window.GLU_DATA = {"meta": {"title": "GLU Study", "student": "Jay-R", "updated": "2026-09-05"}, "courses": [{"id": "ot-survey-1", "code": 50, "title": "Old Testament Survey 1", "status": "complete", "certificateUnlocked": true, "courseTotal": 100, "blurb": "From creation’s aftermath to Solomon’s wisdom — the first sweep of Israel’s story, ready for review and preaching.", "lessons": [{"id": "ot-1", "number": 1, "title": "Introduction to the Old Testament", "topic": "Survey overview of OT structure and themes — the story that prepares the way for Christ.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["The Old Testament is one unfolding story: creation, covenant, failure, and promise — God preparing a people and a Savior.", "It is not a random shelf of books. The church receives sixty-six inspired books; Jesus and the apostles treated the Old Testament as the Word of God.", "When you preach the OT, watch for covenant, sacrifice, kingship, land, and remnant hope. Every one of those roads runs toward Jesus.", "Genesis still preaches: a real creation, a real fall (Eve deceived, Adam choosing), a real flood, and a God who will not abandon the world He made.", "The God of Abraham is not a different God from the Father of our Lord. These pages still form a people for His glory."], "introCard": "Survey doorway: how the Old Testament is put together, what its big themes are, and why the church still needs it. Quiz complete at 100% with exact Moodle wording below.", "quiz": [{"q": "One purpose of this course is to trace the history of God's people from the creation of mankind to the beginning of the New Testament.", "answer": "True", "why": "The survey walks from Eden to the threshold of the New Testament — one people, one story."}, {"q": "The Bible is a collection of 96 books that are recognized as divinely inspired by the Christian Church.", "answer": "False", "why": "The Christian canon is sixty-six books, not ninety-six."}, {"q": "God revealed His Word to ancient Israel over a thousand-year period.", "answer": "True", "why": "Inspiration is not a weekend. God spoke across centuries to form a people."}, {"q": "Jewish tradition affirmed that prophecy ceased in Israel ca. 400 BC after the ministry of Malachi.", "answer": "True", "why": "After Malachi, Jewish tradition heard a long silence until the days of the gospel."}, {"q": "Jesus and the apostles accepted the inspiration of the Old Testament.", "answer": "True", "why": "Jesus and the apostles did not treat the Old Testament as optional background. They received it as the Word of God."}, {"q": "The earliest existing manuscripts of the Old Testament were found in Jerusalem.", "answer": "False", "why": "The oldest copies we have came from the Dead Sea Scrolls near Qumran, not from Jerusalem."}, {"q": "There is great biblical and historical evidence for a pre-Adamic race of humans.", "answer": "False", "why": "Scripture does not furnish a race of humans before Adam. Start with Genesis 1–2, not with speculation."}, {"q": "In the fall temptation, Adam was deceived, but Eve chose to rebel against God.", "answer": "False", "why": "The statement reverses them. Eve was deceived; Adam chose to rebel."}, {"q": "At the fall temptation, Lucifer embodies a snake.", "answer": "True", "why": "The serpent in the garden is not a children’s mascot — Lucifer embodies the snake."}, {"q": "One change which occurred after the universal flood was the increase in life-span.", "answer": "False", "why": "After the flood, life-spans decreased; they did not increase."}], "essays": [{"theme": "Creation in Genesis 1–2 and various theories", "summary": "Genesis 1–2 is a worship text before it is a debate: God speaks, and the world is — form and fullness, then a man and a woman in a garden. Other theories (gap, day-age, theistic evolution, literary framework) try to make peace with extra-biblical clocks. For sermon and review, hold the text first: a real Adam and Eve, a good world, a God who is not competing with matter. Name the theories without letting them steal the pulpit."}, {"theme": "The fall of humanity — results and consequences", "summary": "The snake speaks, Eve is deceived, Adam chooses, and the garden is lost. Results follow at once: shame, blame, pain in childbearing, toil in the ground, death, and exile east of Eden. The damage is personal, relational, and cosmic — yet the first gospel is already spoken: the seed of the woman will crush the serpent’s head. Preach the fall as tragedy with a promise, not as a myth with a moral."}, {"theme": "The argument for the Universal Flood", "summary": "This course reads Genesis 6–9 as a worldwide judgment: the language of covering the earth, the ark, the mountains, and a covenant God makes with the earth itself. Local-flood theories shrink the judgment; the text will not. After the waters, life-spans fall, the nations will scatter, and God hangs a bow in the cloud. For the pulpit: mercy after judgment — not a geology lecture."}], "bigIdeas": ["The Old Testament is one unfolding story: creation, covenant, failure, and promise — God preparing a people and a Savior.", "It is not a random shelf of books. The church receives sixty-six inspired books; Jesus and the apostles treated the Old Testament as the Word of God.", "When you preach the OT, watch for covenant, sacrifice, kingship, land, and remnant hope. Every one of those roads runs toward Jesus.", "Genesis still preaches: a real creation, a real fall (Eve deceived, Adam choosing), a real flood, and a God who will not abandon the world He made.", "The God of Abraham is not a different God from the Father of our Lord. These pages still form a people for His glory."], "summary": "Survey overview of OT structure and themes — the story that prepares the way for Christ. The Old Testament is one unfolding story: creation, covenant, failure, and promise — God preparing a people and a Savior.", "quickReview": ["The Old Testament is one unfolding story: creation, covenant, failure, and promise — God preparing a people…", "It is not a random shelf of books. The church receives sixty-six inspired books; Jesus and the apostles…", "When you preach the OT, watch for covenant, sacrifice, kingship, land, and remnant hope. Every one of those…", "Genesis still preaches: a real creation, a real fall (Eve deceived, Adam choosing), a real flood, and a God…", "The God of Abraham is not a different God from the Father of our Lord. These pages still form a people for…"], "glossary": [{"term": "Creation in Genesis 1–2 and various theories", "meaning": "Genesis 1–2 is a worship text before it is a debate: God speaks, and the world is — form and fullness, then a man and a woman in a garden. Other theories (gap…"}, {"term": "The fall of humanity — results and consequences", "meaning": "The snake speaks, Eve is deceived, Adam chooses, and the garden is lost. Results follow at once: shame, blame, pain in childbearing, toil in the ground, death…"}, {"term": "The argument for the Universal Flood", "meaning": "This course reads Genesis 6–9 as a worldwide judgment: the language of covering the earth, the ark, the mountains, and a covenant God makes with the earth…"}, {"term": "Abraham", "meaning": "Abraham is not a different God from the Father of our Lord"}, {"term": "Covenant", "meaning": "The Old Testament is one unfolding story: creation, covenant, failure, and promise — God preparing a people and a Savior."}, {"term": "Inspiration", "meaning": "Inspiration is not a weekend."}], "outline": ["Creation in Genesis 1–2 and various theories", "The fall of humanity — results and consequences", "The argument for the Universal Flood"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Covenant", "value": "The Old Testament is one unfolding story: creation, covenant, failure, and promise — God preparing a people and a Savior."}, {"label": "Key claim", "value": "It is not a random shelf of books. The church receives sixty-six inspired books; Jesus and the apostles treated the Old Testament as the…"}, {"label": "Covenant", "value": "When you preach the OT, watch for covenant, sacrifice, kingship, land, and remnant hope. Every one of those roads runs toward Jesus."}], "compare": [{"title": "Creation in Genesis 1–2 and various theories", "points": ["gap", "day-age", "theistic evolution", "literary framework"]}], "pulpit": ["When you preach the OT, watch for covenant, sacrifice, kingship, land, and remnant hope.", "Genesis still preaches: a real creation, a real fall (Eve deceived, Adam choosing), a real flood, and a God who will not abandon the world He made.", "For sermon and review, hold the text first: a real Adam and Eve, a good world, a God who is not competing with matter.", "Name the theories without letting them steal the pulpit."]}, {"id": "ot-2", "number": 2, "title": "Noah through Joseph", "topic": "Genesis 7–50: after the flood, through Abraham’s family, to Joseph in Egypt.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Question wording reconstructed from session notes.", "takeaways": ["After the flood, God does not start from nothing — the Noahic covenant continues the Edenic story with new mercy (and a bow in the cloud).", "Babel is judgment and mission at once: confused languages scatter the nations so that one day every tongue will praise the Lord.", "Abraham is called so that all families of the earth will be blessed. Christianity, Judaism, and Islam all look back to him — but the gospel keeps the promise through Isaac, not through our shortcuts.", "Ishmael is a warning for the pulpit: helping God along is not great faith. Waiting on the promise is.", "Isaac and Joseph both preach Christ in type — the beloved son, the one who goes down and is raised up for the saving of many. Rebekah, coming to the son, is a picture of the church.", "Job sits early in this world — older than the Greek tragedies — and teaches us to speak of suffering without cheap answers."], "quiz": [{"q": "The Noahic Covenant was a continuation of the Edenic covenant with added aspects.", "answer": "True", "why": "God does not discard the first story; He carries it forward with new terms of mercy after the flood."}, {"q": "The confusion of languages at the Tower of Babel resulted in the dissemination of people throughout the earth.", "answer": "True", "why": "Judgment scattered the nations — the map of the world begins here."}, {"q": "The Ebla texts, found in Syria and dating to the time of Abraham, indicated that Sodom was a real place.", "answer": "True", "why": "The patriarchal stories sit in real geography, not in myth."}, {"q": "Abraham is identified as the father of three great religions.", "answer": "True", "why": "Judaism, Christianity, and Islam all look back to Abraham — preach the promise with that in view."}, {"q": "When Abraham obeyed God, God gave him the Abrahamic Covenant.", "answer": "True", "why": "The covenant meets a man on the road of obedience, not on the sofa of delay."}, {"q": "The birth of Ishmael showed Abraham’s great faith.", "answer": "False", "why": "Ishmael is the fruit of a shortcut. Great faith waits for Isaac."}, {"q": "Abraham was never outside the will of God.", "answer": "False", "why": "Egypt, Hagar, and half-truths about Sarah are in the record. Grace keeps the promise anyway."}, {"q": "Isaac is a type of the church.", "answer": "False", "why": "Isaac is a type of Christ; Rebekah, coming to him, is a type of the church."}, {"q": "Joseph is a type of the church.", "answer": "False", "why": "Joseph is a type of Christ — rejected, suffered, raised to save many (Genesis 50:20)."}, {"q": "The book of Job was penned soon after the Greek tragedies.", "answer": "False", "why": "Job is earlier — before 1400 BC — not a late echo of Greece."}], "essays": [{"theme": "Abraham’s five tests", "summary": "Walk the tests as a pastoral map: leave, let Lot choose, refuse Sodom’s spoils, send Ishmael, and offer Isaac. Faith is proven on the road, not in the brochure. Each test asks whether the promise is enough."}, {"theme": "Joseph as a type of Christ", "summary": "Beloved of the father, hated by his brothers, sold, falsely accused, raised to the right hand, and the savior of the hungry. Preach the type with a light touch — Joseph points; Jesus fulfills."}, {"theme": "Types in Genesis 24", "summary": "Abraham’s servant seeks a bride for the son. Rebekah leaves her world to meet Isaac. It is a quiet picture of the Father sending, the Spirit seeking, and the church coming to Christ."}], "bigIdeas": ["After the flood, God does not start from nothing — the Noahic covenant continues the Edenic story with new mercy (and a bow in the cloud).", "Babel is judgment and mission at once: confused languages scatter the nations so that one day every tongue will praise the Lord.", "Abraham is called so that all families of the earth will be blessed. Christianity, Judaism, and Islam all look back to him — but the gospel keeps the promise through Isaac, not through our shortcuts.", "Ishmael is a warning for the pulpit: helping God along is not great faith. Waiting on the promise is.", "Isaac and Joseph both preach Christ in type — the beloved son, the one who goes down and is raised up for the saving of many. Rebekah, coming to the son, is a picture of the church.", "Job sits early in this world — older than the Greek tragedies — and teaches us to speak of suffering without cheap answers."], "summary": "Genesis 7–50: after the flood, through Abraham’s family, to Joseph in Egypt. After the flood, God does not start from nothing — the Noahic covenant continues the Edenic story with new mercy (and a bow in the cloud).", "quickReview": ["After the flood, God does not start from nothing — the Noahic covenant continues the Edenic story with new…", "Babel is judgment and mission at once: confused languages scatter the nations so that one day every tongue…", "Abraham is called so that all families of the earth will be blessed. Christianity, Judaism, and Islam all…", "Ishmael is a warning for the pulpit: helping God along is not great faith. Waiting on the promise is.", "Isaac and Joseph both preach Christ in type — the beloved son, the one who goes down and is raised up for the…"], "glossary": [{"term": "Abraham’s five tests", "meaning": "Walk the tests as a pastoral map: leave, let Lot choose, refuse Sodom’s spoils, send Ishmael, and offer Isaac. Faith is proven on the road, not in the…"}, {"term": "Joseph as a type of Christ", "meaning": "Beloved of the father, hated by his brothers, sold, falsely accused, raised to the right hand, and the savior of the hungry. Preach the type with a light touch…"}, {"term": "Types in Genesis 24", "meaning": "Abraham’s servant seeks a bride for the son. Rebekah leaves her world to meet Isaac. It is a quiet picture of the Father sending, the Spirit seeking, and the…"}, {"term": "Babel", "meaning": "Babel is judgment and mission at once: confused languages scatter the nations so that one day every tongue wi"}, {"term": "Abraham", "meaning": "Abraham is called so that all families of the earth will be blessed"}, {"term": "Ishmael", "meaning": "Ishmael is a warning for the pulpit: helping God along is not great faith"}, {"term": "Covenant", "meaning": "After the flood, God does not start from nothing — the Noahic covenant continues the Edenic story with new mercy (and a bow in the cloud)."}], "outline": ["Abraham’s five tests", "Joseph as a type of Christ", "Types in Genesis 24"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Covenant", "value": "After the flood, God does not start from nothing — the Noahic covenant continues the Edenic story with new mercy (and a bow in the cloud)."}, {"label": "Key claim", "value": "Babel is judgment and mission at once: confused languages scatter the nations so that one day every tongue will praise the Lord."}, {"label": "Key claim", "value": "Abraham is called so that all families of the earth will be blessed. Christianity, Judaism, and Islam all look back to him — but the gospel…"}], "pulpit": ["Ishmael is a warning for the pulpit: helping God along is not great faith.", "Isaac and Joseph both preach Christ in type — the beloved son, the one who goes down and is raised up for the saving of many.", "Walk the tests as a pastoral map: leave, let Lot choose, refuse Sodom’s spoils, send Ishmael, and offer Isaac.", "Preach the type with a light touch — Joseph points; Jesus fulfills."], "compare": null}, {"id": "ot-3", "number": 3, "title": "Exodus and the wilderness", "topic": "The call of Moses, the offerings of Leviticus, and Moses’ death on Nebo.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["Exodus 3–4 is a pastor’s mirror: Moses offers five excuses, and God answers with His name, His presence, and His patience — not with a pep talk.", "The five Levitical offerings (burnt, meal, peace, sin, trespass) are not museum pieces. They still preach Christ: whole devotion, daily life, fellowship, guilt, and the wrong we have done to others.", "The wilderness is where redeemed people learn to live. Manna, water, and a lingering God train a complaining church.", "Moses dies on Nebo for Meribah — he struck the rock. Leaders are not above the Word they preach. The promise still stands; the servant still answers to God."], "quiz": [{"q": "The Hyksos ruled in Egypt from 1720-1570 BC.", "answer": "True", "why": "The Hyksos window (1720–1570 BC) is the historical backdrop this course uses for Egypt before the Exodus story."}, {"q": "The early proposed date for the Exodus is 1280-1220 BC.", "answer": "False", "why": "1280–1220 BC is the late date. The early date sits earlier, around 1446 BC."}, {"q": "Moses came from the tribe of Judah.", "answer": "False", "why": "Moses is a Levite, not a son of Judah."}, {"q": "Moses' 40 years in the wilderness was an utter waste of time.", "answer": "False", "why": "Those forty years were a school, not a waste. God was preparing the deliverer."}, {"q": "The ten plagues of Exodus 7-11 were all power encounters with the false gods of Egypt.", "answer": "True", "why": "Each plague is a public contest: the Lord against Egypt’s gods."}, {"q": "When the Israelites ate the first Passover meal, they were already dressed for their journey.", "answer": "True", "why": "Passover is eaten in traveling clothes — redemption is a departure, not a picnic."}, {"q": "The Israelites spent 60 years in the wilderness.", "answer": "False", "why": "Forty years, not sixty. Do not round the wilderness into a different number."}, {"q": "The first of the Ten Commandments was specifically designed to forbid idolatry.", "answer": "False", "why": "The first commandment forbids other gods. Idolatry — carved images — is the second."}, {"q": "The book of Leviticus emphasized sacrifices, priests, and feasts.", "answer": "True", "why": "Leviticus is the worship book: offerings, priests, and the feast calendar of a redeemed people."}, {"q": "The book of Deuteronomy's theme is Unbelief.", "answer": "False", "why": "Unbelief is not Deuteronomy’s banner. Moses’ last book is a charge to remember, love, and obey the Lord."}], "essays": [{"theme": "The call of Moses (Exodus 3–4)", "summary": "The bush burns and is not consumed. God names Himself I AM and sends a reluctant shepherd. Moses offers five excuses — Who am I? Who are You? They will not believe. I am slow of speech. Send someone else — and God answers with His presence, His name, signs, Aaron, and patience. Reluctance is not disqualifying if it ends in obedience. The bush still burns for servants who feel too slow of speech."}, {"theme": "The sacrifices and offerings in Leviticus", "summary": "Leviticus is the worship book of a redeemed people: burnt (whole devotion), grain/meal (daily life offered), peace (fellowship), sin (guilt), and trespass (the wrong done to others). Priests and feasts keep the calendar holy. Use the five offerings to teach worship, fellowship, and atonement — without flattening every detail into an allegory. They still preach Christ."}, {"theme": "Moses’ untimely death — reason and details", "summary": "At Meribah, Moses struck the rock and spoke as if the miracle were his, misrepresenting the Lord before the people. He sees the land from Nebo and dies there; the Lord buries him (Deuteronomy 32; 34). Untimely, because one act of unbelief kept the servant from the promise he had carried. The people still enter; the leader still answers to God. Authority in ministry is a trust, not a trophy."}], "bigIdeas": ["Exodus 3–4 is a pastor’s mirror: Moses offers five excuses, and God answers with His name, His presence, and His patience — not with a pep talk.", "The five Levitical offerings (burnt, meal, peace, sin, trespass) are not museum pieces. They still preach Christ: whole devotion, daily life, fellowship, guilt, and the wrong we have done to others.", "The wilderness is where redeemed people learn to live. Manna, water, and a lingering God train a complaining church.", "Moses dies on Nebo for Meribah — he struck the rock. Leaders are not above the Word they preach. The promise still stands; the servant still answers to God.", "The call of Moses (Exodus 3–4): The bush burns and is not consumed. God names Himself I AM and sends a reluctant shepherd. Moses offers five excuses — Who am I? Who are You? They…", "The sacrifices and offerings in Leviticus: Leviticus is the worship book of a redeemed people: burnt (whole devotion), grain/meal (daily life offered), peace (fellowship), sin (guilt), and…", "Moses’ untimely death — reason and details: At Meribah, Moses struck the rock and spoke as if the miracle were his, misrepresenting the Lord before the people. He sees the land from Nebo and…"], "summary": "The call of Moses, the offerings of Leviticus, and Moses’ death on Nebo. Exodus 3–4 is a pastor’s mirror: Moses offers five excuses, and God answers with His name, His presence, and His patience — not with a pep talk.", "quickReview": ["Exodus 3–4 is a pastor’s mirror: Moses offers five excuses, and God answers with His name, His presence, and…", "The five Levitical offerings (burnt, meal, peace, sin, trespass) are not museum pieces. They still preach…", "The wilderness is where redeemed people learn to live. Manna, water, and a lingering God train a complaining…", "Moses dies on Nebo for Meribah — he struck the rock. Leaders are not above the Word they preach. The promise…", "The Hyksos ruled in Egypt from 1720-1570 BC."], "glossary": [{"term": "The call of Moses (Exodus 3–4)", "meaning": "The bush burns and is not consumed. God names Himself I AM and sends a reluctant shepherd. Moses offers five excuses — Who am I? Who are You? They will not…"}, {"term": "The sacrifices and offerings in Leviticus", "meaning": "Leviticus is the worship book of a redeemed people: burnt (whole devotion), grain/meal (daily life offered), peace (fellowship), sin (guilt), and trespass (the…"}, {"term": "Moses’ untimely death — reason and details", "meaning": "At Meribah, Moses struck the rock and spoke as if the miracle were his, misrepresenting the Lord before the people. He sees the land from Nebo and dies there…"}, {"term": "Leaders", "meaning": "Leaders is not above the Word they preach"}, {"term": "Redemption", "meaning": "Passover is eaten in traveling clothes — redemption is a departure, not a picnic."}, {"term": "Atonement", "meaning": "Use the five offerings to teach worship, fellowship, and atonement — without flattening every detail into an allegory."}], "outline": ["The call of Moses (Exodus 3–4)", "The sacrifices and offerings in Leviticus", "Moses’ untimely death — reason and details"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Exodus 3–4 is a pastor’s mirror: Moses offers five excuses, and God answers with His name, His presence, and His patience — not with a pep…"}, {"label": "Preach", "value": "The five Levitical offerings (burnt, meal, peace, sin, trespass) are not museum pieces. They still preach Christ: whole devotion, daily…"}, {"label": "Key claim", "value": "The wilderness is where redeemed people learn to live. Manna, water, and a lingering God train a complaining church."}], "compare": [{"title": "Clarify", "points": ["Exodus 3–4 is a pastor’s mirror: Moses offers five excuses, and God answers with His name, His presence, and His…", "Not: with a pep talk."]}], "pulpit": ["They still preach Christ: whole devotion, daily life, fellowship, guilt, and the wrong we have done to others.", "Leaders are not above the Word they preach.", "They still preach Christ."]}, {"id": "ot-4", "number": 4, "title": "Joshua and Judges", "topic": "Victory and fulfillment in Joshua; the cycle of compromise in Judges; Ruth’s redemption.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Question wording reconstructed from session notes.", "takeaways": ["Joshua’s theme is fulfillment and victory — God keeping the land-promise. Judges’ theme is the warning against compromise. Do not swap the banners.", "Rahab is spared. Faith can hang a scarlet cord in a collapsing city. The gospel has always made room for unlikely family.", "Caleb asks for Hebron at eighty-five. Age is not a disqualification when the promise still stands.", "The judges are not stained-glass saints. God delivers through imperfect people — and the refrain “everyone did what was right in his own eyes” still preaches.", "Ruth teaches the doctrine of redemption: a kinsman who can, who will, and who pays. Boaz is a window; Christ is the door.", "Incomplete obedience in Joshua becomes next generation’s snare. Finish the work God actually assigned."], "quiz": [{"q": "The theme of Joshua is a warning against compromise.", "answer": "False", "why": "That warning belongs to Judges. Joshua is fulfillment and victory."}, {"q": "Israel entered a death pact of capital punishment.", "answer": "True", "why": "Joshua 1:18 — whoever rebels against the command shall be put to death. The conquest is not casual."}, {"q": "Rahab was executed by stoning.", "answer": "False", "why": "Rahab was spared. Faith brought her into Israel’s story — and into Messiah’s line."}, {"q": "The altar on Mount Ebal was built of precision-cut stone.", "answer": "False", "why": "It was uncut stones. Worship is received, not manufactured to our taste."}, {"q": "Caleb conquered Hebron at the age of 85.", "answer": "True", "why": "A whole heart at eighty-five still takes mountains."}, {"q": "The author of Judges was Moses.", "answer": "False", "why": "Samuel is identified as the author, not Moses."}, {"q": "The judges were all men of uncompromising character.", "answer": "False", "why": "The book’s theme includes their imperfections. God uses cracked vessels."}, {"q": "Gideon was the most inferior of his father’s house.", "answer": "True", "why": "God delights to save through the least, so the glory stays His."}, {"q": "Samson was a Nazarite.", "answer": "True", "why": "Set apart from the womb — and still a warning about wasted strength."}, {"q": "The book of Ruth teaches the doctrine of redemption.", "answer": "True", "why": "The kinsman-redeemer is the pastoral heart of the story."}], "essays": [{"theme": "Ai", "summary": "Jericho’s victory, then Ai’s defeat — hidden sin in the camp, overconfidence, and a God who will not be used. Restoration comes through confession and a second, obedient battle."}, {"theme": "Gideon", "summary": "The least in his house, too many soldiers, a fleece, and a God who reduces the army so Israel cannot boast. Courage is not the absence of fear; it is obedience with trembling."}, {"theme": "Ruth, Boaz, and the kinsman-redeemer", "summary": "Nearness, ability, willingness, and the public price. Preach redemption as personal and costly — then name the greater Boaz."}], "bigIdeas": ["Joshua’s theme is fulfillment and victory — God keeping the land-promise. Judges’ theme is the warning against compromise. Do not swap the banners.", "Rahab is spared. Faith can hang a scarlet cord in a collapsing city. The gospel has always made room for unlikely family.", "Caleb asks for Hebron at eighty-five. Age is not a disqualification when the promise still stands.", "The judges are not stained-glass saints. God delivers through imperfect people — and the refrain “everyone did what was right in his own eyes” still preaches.", "Ruth teaches the doctrine of redemption: a kinsman who can, who will, and who pays. Boaz is a window; Christ is the door.", "Incomplete obedience in Joshua becomes next generation’s snare. Finish the work God actually assigned."], "summary": "Victory and fulfillment in Joshua; the cycle of compromise in Judges; Ruth’s redemption. Joshua’s theme is fulfillment and victory — God keeping the land-promise. Judges’ theme is the warning against compromise. Do not swap the banners.", "quickReview": ["Joshua’s theme is fulfillment and victory — God keeping the land-promise. Judges’ theme is the warning…", "Rahab is spared. Faith can hang a scarlet cord in a collapsing city. The gospel has always made room for…", "Caleb asks for Hebron at eighty-five. Age is not a disqualification when the promise still stands.", "The judges are not stained-glass saints. God delivers through imperfect people — and the refrain “everyone…", "Ruth teaches the doctrine of redemption: a kinsman who can, who will, and who pays. Boaz is a window; Christ…"], "glossary": [{"term": "Gideon", "meaning": "The least in his house, too many soldiers, a fleece, and a God who reduces the army so Israel cannot boast. Courage is not the absence of fear; it is obedience…"}, {"term": "Ruth, Boaz, and the kinsman-redeemer", "meaning": "Nearness, ability, willingness, and the public price. Preach redemption as personal and costly — then name the greater Boaz."}, {"term": "Age", "meaning": "Age is not a disqualification when the promise still stands"}, {"term": "Boaz", "meaning": "Boaz is a window; Christ is the door"}, {"term": "Redemption", "meaning": "Ruth teaches the doctrine of redemption: a kinsman who can, who will, and who pays."}], "outline": ["Ai", "Gideon", "Ruth, Boaz, and the kinsman-redeemer"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Joshua’s theme is fulfillment and victory — God keeping the land-promise. Judges’ theme is the warning against compromise. Do not swap the…"}, {"label": "Key claim", "value": "Rahab is spared. Faith can hang a scarlet cord in a collapsing city. The gospel has always made room for unlikely family."}, {"label": "Key claim", "value": "Caleb asks for Hebron at eighty-five. Age is not a disqualification when the promise still stands."}], "pulpit": ["God delivers through imperfect people — and the refrain “everyone did what was right in his own eyes” still preaches.", "Preach redemption as personal and costly — then name the greater Boaz."], "compare": null}, {"id": "ot-5", "number": 5, "title": "Saul and David", "topic": "From failing judges to a king like the nations — then a shepherd after God’s heart.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Question wording reconstructed from session notes.", "takeaways": ["The line of the judges grows weaker while the oppressors grow stronger. When leadership thins, God’s people start asking for a king like everybody else.", "Samuel is prophet, priest, and judge — not king. Keep the offices straight when you preach 1 Samuel.", "Saul looks the part and lives by excuses. Appearance is not anointing. A congregation can want a tall king and still miss God’s man.", "David is anointed long before Saul dies. God’s choice often runs ahead of the public calendar.", "David ruled forty years — and he sinned. Greatness in Scripture includes repentance, not a clean press kit. The Davidic covenant still points to a forever King.", "The witch of Endor is not a curiosity for Halloween sermons. It is a man at the end of himself, and even the darkness shrieks."], "quiz": [{"q": "Each judge became weaker, while the oppressors became stronger.", "answer": "True", "why": "The book winds down; the need for a true king winds up."}, {"q": "Eli was a strong, disciplined leader.", "answer": "False", "why": "Eli’s house is a study in indulgence, not discipline."}, {"q": "Samuel was prophet, priest, and king.", "answer": "False", "why": "Prophet, priest, and judge — not king. The crown is not his."}, {"q": "Israel wanted a king so they could be like the other nations.", "answer": "True", "why": "The motive is conformity, not covenant. That still preaches."}, {"q": "Saul had many excuses.", "answer": "True", "why": "Blame-shifting is the soundtrack of a rejected king."}, {"q": "Whether Saul was saved or lost is debated.", "answer": "True", "why": "Hold the debate humbly; do not build a whole system on a silence."}, {"q": "David was anointed as soon as Saul died.", "answer": "False", "why": "David was anointed earlier, while Saul still sat on the throne."}, {"q": "The witch of Endor was delighted.", "answer": "False", "why": "She shrieked. This is terror, not a séance souvenir."}, {"q": "David ruled for 40 years.", "answer": "True", "why": "Forty years of real reign — triumph, sin, and covenant mercy."}, {"q": "David never sinned.", "answer": "False", "why": "Bathsheba, Uriah, the census — and a psalm of repentance. Preach the whole man."}], "essays": [{"theme": "Samuel", "summary": "The last judge, a praying prophet, a disappointed mentor to Saul, and the anointer of David. Leadership that listens to God outlasts leadership that listens to the crowd."}, {"theme": "Was Saul saved or lost?", "summary": "The text leaves room for debate. Use it to teach holy caution: fruit, obedience, and the danger of a heart that will not return — without pretending we sit in the final chair of judgment."}, {"theme": "David’s greatness and the Davidic covenant", "summary": "A shepherd, a singer, a sinner, a king. 2 Samuel 7 is sermon gold: God builds the house. The forever throne is not David’s achievement; it is God’s promise, kept in Christ."}], "bigIdeas": ["The line of the judges grows weaker while the oppressors grow stronger. When leadership thins, God’s people start asking for a king like everybody else.", "Samuel is prophet, priest, and judge — not king. Keep the offices straight when you preach 1 Samuel.", "Saul looks the part and lives by excuses. Appearance is not anointing. A congregation can want a tall king and still miss God’s man.", "David is anointed long before Saul dies. God’s choice often runs ahead of the public calendar.", "David ruled forty years — and he sinned. Greatness in Scripture includes repentance, not a clean press kit. The Davidic covenant still points to a forever King.", "The witch of Endor is not a curiosity for Halloween sermons. It is a man at the end of himself, and even the darkness shrieks."], "summary": "From failing judges to a king like the nations — then a shepherd after God’s heart. The line of the judges grows weaker while the oppressors grow stronger. When leadership thins, God’s people start asking for a king like everybody else.", "quickReview": ["The line of the judges grows weaker while the oppressors grow stronger. When leadership thins, God’s people…", "Samuel is prophet, priest, and judge — not king. Keep the offices straight when you preach 1 Samuel.", "Saul looks the part and lives by excuses. Appearance is not anointing. A congregation can want a tall king…", "David is anointed long before Saul dies. God’s choice often runs ahead of the public calendar.", "David ruled forty years — and he sinned. Greatness in Scripture includes repentance, not a clean press kit…"], "glossary": [{"term": "Samuel", "meaning": "The last judge, a praying prophet, a disappointed mentor to Saul, and the anointer of David. Leadership that listens to God outlasts leadership that listens to…"}, {"term": "Was Saul saved or lost?", "meaning": "The text leaves room for debate. Use it to teach holy caution: fruit, obedience, and the danger of a heart that will not return — without pretending we sit in…"}, {"term": "David’s greatness and the Davidic covenant", "meaning": "A shepherd, a singer, a sinner, a king. 2 Samuel 7 is sermon gold: God builds the house. The forever throne is not David’s achievement; it is God’s promise…"}, {"term": "Appearance", "meaning": "Appearance is not anointing"}, {"term": "David", "meaning": "David is anointed long before Saul dies"}, {"term": "Endor", "meaning": "Endor is not a curiosity for Halloween sermons"}, {"term": "Covenant", "meaning": "The Davidic covenant still points to a forever King."}], "outline": ["Samuel", "Was Saul saved or lost?", "David’s greatness and the Davidic covenant"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "The line of the judges grows weaker while the oppressors grow stronger. When leadership thins, God’s people start asking for a king like…"}, {"label": "Preach", "value": "Samuel is prophet, priest, and judge — not king. Keep the offices straight when you preach 1 Samuel."}, {"label": "Key claim", "value": "Saul looks the part and lives by excuses. Appearance is not anointing. A congregation can want a tall king and still miss God’s man."}], "compare": [{"title": "Clarify", "points": ["Samuel is prophet, priest, and judge", "Not: king. Keep the offices straight when you preach 1 Samuel."]}], "pulpit": ["Keep the offices straight when you preach 1 Samuel.", "The witch of Endor is not a curiosity for Halloween sermons.", "2 Samuel 7 is sermon gold: God builds the house."]}, {"id": "ot-6", "number": 6, "title": "Solomon and the poetic books", "topic": "Wisdom on the throne, a temple raised, and the poetry that teaches us to live and to pray.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Question wording reconstructed from session notes.", "takeaways": ["God offered Solomon anything in a dream — and wisdom was the right ask. Gifts still reveal what we think a throne is for.", "Solomon wrote three books and still drifted. A divided heart can preach Proverbs in the morning and gather horses by night.", "Job asks what suffering is for. Psalms give the church a voice. Proverbs is skill for ordinary Tuesdays. Ecclesiastes says life without God is vanity. Song of Solomon is communion, not Ecclesiastes wearing cologne.", "Not all the Psalms are David’s, and their themes walk in step with the Torah’s movement. Use that when you plan a series.", "There is more than one kind of biblical poetry. Read laments as laments, wisdom as wisdom, and love songs as love songs.", "Adonijah’s rebellion and death are a hard footnote: the kingdom is not seized; it is given."], "quiz": [{"q": "Job explains the purpose of suffering.", "answer": "True", "why": "Not every why is answered, but the book will not let suffering be meaningless or cruelly simple."}, {"q": "Ecclesiastes explains communion with God.", "answer": "False", "why": "Communion is the Song of Solomon. Ecclesiastes asks about purpose — and finds vanity under the sun."}, {"q": "There is more than one type of poetry in the Bible.", "answer": "True", "why": "The course names four types. Do not flatten the Psalter into one mood."}, {"q": "All of the Psalms were written by David.", "answer": "False", "why": "David wrote many, not all. Asaph, the sons of Korah, Moses, and others also sing."}, {"q": "The themes of the Psalms reflect the progression of the Torah.", "answer": "True", "why": "The five books of Psalms walk with the five books of Moses — a gift for series preaching."}, {"q": "God offered Solomon anything in a dream.", "answer": "True", "why": "1 Kings 3. What we would ask still reveals us."}, {"q": "Adonijah was executed for rebellion.", "answer": "True", "why": "The kingdom is not taken by a feast and a claim."}, {"q": "Solomon wrote three books.", "answer": "True", "why": "Proverbs, Ecclesiastes, and Song of Songs — wisdom’s three notes."}, {"q": "Proverbs emphasizes principles for everyday life.", "answer": "True", "why": "Street-level holiness: tongue, work, friends, anger, and the fear of the Lord."}, {"q": "Ecclesiastes teaches that life without God is vanity, and the search is endless.", "answer": "True", "why": "Under the sun, the well is empty. Preach it to restless people, then walk them back to the fear of God."}], "essays": [{"theme": "Four types of poetry", "summary": "Name the kinds and read each on its own terms — so a lament is not preached as a pep talk, and a proverb is not treated like a legal promise."}, {"theme": "Psalms and the Torah in parallel", "summary": "Five movements matching five books. Creation and walk, deliverance, holiness, wilderness, and homecoming — a ready skeleton for a Psalter series."}, {"theme": "Solomon: greatness, strengths, and weaknesses", "summary": "Wisdom, temple, international glory — and multiplied horses, wives, and a heart turned. Gifts without a guarded heart become a slow funeral. Christ is the greater Son of David who does not drift."}], "bigIdeas": ["God offered Solomon anything in a dream — and wisdom was the right ask. Gifts still reveal what we think a throne is for.", "Solomon wrote three books and still drifted. A divided heart can preach Proverbs in the morning and gather horses by night.", "Job asks what suffering is for. Psalms give the church a voice. Proverbs is skill for ordinary Tuesdays. Ecclesiastes says life without God is vanity. Song of Solomon is communion, not Ecclesiastes wearing cologne.", "Not all the Psalms are David’s, and their themes walk in step with the Torah’s movement. Use that when you plan a series.", "There is more than one kind of biblical poetry. Read laments as laments, wisdom as wisdom, and love songs as love songs.", "Adonijah’s rebellion and death are a hard footnote: the kingdom is not seized; it is given."], "summary": "Wisdom on the throne, a temple raised, and the poetry that teaches us to live and to pray. God offered Solomon anything in a dream — and wisdom was the right ask. Gifts still reveal what we think a throne is for.", "quickReview": ["God offered Solomon anything in a dream — and wisdom was the right ask. Gifts still reveal what we think a…", "Solomon wrote three books and still drifted. A divided heart can preach Proverbs in the morning and gather…", "Job asks what suffering is for. Psalms give the church a voice. Proverbs is skill for ordinary Tuesdays…", "Not all the Psalms are David’s, and their themes walk in step with the Torah’s movement. Use that when you…", "There is more than one kind of biblical poetry. Read laments as laments, wisdom as wisdom, and love songs as…"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "God offered Solomon anything in a dream — and wisdom was the right ask. Gifts still reveal what we think a throne is for."}, {"label": "Preach", "value": "Solomon wrote three books and still drifted. A divided heart can preach Proverbs in the morning and gather horses by night."}, {"label": "Key claim", "value": "Job asks what suffering is for. Psalms give the church a voice. Proverbs is skill for ordinary Tuesdays. Ecclesiastes says life without God…"}], "glossary": [{"term": "Four types of poetry", "meaning": "Name the kinds and read each on its own terms — so a lament is not preached as a pep talk, and a proverb is not treated like a legal promise."}, {"term": "Psalms and the Torah in parallel", "meaning": "Five movements matching five books. Creation and walk, deliverance, holiness, wilderness, and homecoming — a ready skeleton for a Psalter series."}, {"term": "Solomon: greatness, strengths, and weaknesses", "meaning": "Wisdom, temple, international glory — and multiplied horses, wives, and a heart turned. Gifts without a guarded heart become a slow funeral. Christ is the…"}, {"term": "Proverbs", "meaning": "Proverbs is skill for ordinary Tuesdays"}, {"term": "Solomon", "meaning": "Solomon is communion, not Ecclesiastes wearing cologne"}, {"term": "Psalms", "meaning": "Psalms is David’s, and their themes walk in step with the Torah’s movement"}, {"term": "There", "meaning": "There is more than one kind of biblical poetry"}], "outline": ["Four types of poetry", "Psalms and the Torah in parallel", "Solomon: greatness, strengths, and weaknesses"], "pulpit": ["A divided heart can preach Proverbs in the morning and gather horses by night.", "Name the kinds and read each on its own terms — so a lament is not preached as a pep talk, and a proverb is not treated like a legal promise."], "compare": null}]}, {"id": "theology-1", "code": 52, "title": "Survey of Theology 1", "status": "complete", "certificateUnlocked": true, "courseTotal": 100, "blurb": "From prolegomena to the Person of Christ — doctrine that helps a pastor worship, preach, and care for the flock.", "lessons": [{"id": "th-1", "number": 1, "title": "Introduction — belief about God / prolegomena", "topic": "The Bible’s story, what doctrine is for, and the blueprint that goes before the rest of theology.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["The Bible is 66 books, many authors, about 1,600 years — and one story: God revealing Himself and redeeming people (Hebrews 1:1–2). Christianity is Jesus Christ.", "Doctrine is not a cold hobby. It is teaching that meets people at the point of need — a wrench that actually turns, not a trophy on the shelf.", "The gospel is good news as a proposition (Christ died, was buried, rose — 1 Corinthians 15) and as a Person received (John 1:12). Do not separate relationship from truth.", "Prolegomena means “the word that goes before” — the blueprint. We assume God exists and speaks, that truth does not contradict itself, and that the last step of communication is worship (John 4:24).", "Test doctrine by consistency, correspondence, relevance, Christ’s centrality, and thoroughness. Towns maps eleven divisions, not twenty-two."], "quiz": [{"q": "The Bible is made up of 77 books.", "answer": "False", "why": "Sixty-six books. Do not let a number error become a pulpit error."}, {"q": "Christian doctrine speaks to the point of need.", "answer": "True", "why": "Theology that never lands in a life is not yet ready to preach."}, {"q": "God’s greatest way to communicate was through His Son.", "answer": "True", "why": "Hebrews 1 — the final Word is a Person."}, {"q": "The first step in communication between God and man is worship.", "answer": "False", "why": "Worship is the final step, not the first. We hear, then we bow."}, {"q": "The content of Christian doctrine is God’s good news.", "answer": "True", "why": "Doctrine carries the gospel; it is not a rival to the gospel."}, {"q": "Prolegomena means “to go before.”", "answer": "True", "why": "It is the porch of the house — what must be said before the rooms."}, {"q": "A presupposition is a self-evident truth.", "answer": "True", "why": "We all start somewhere. Name your starting place honestly."}, {"q": "The first presupposition is that there is a God who has revealed Himself.", "answer": "True", "why": "We do not guess God into being; He speaks."}, {"q": "The first test used to verify doctrine is reliable eyewitnesses.", "answer": "False", "why": "The first test is consistency. Eyewitnesses matter, but they are not the first sieve here."}, {"q": "Dr. Towns sees 22 divisions of theology and doctrine.", "answer": "False", "why": "Eleven divisions: from prolegomena through eschatology."}], "essays": [{"theme": "Prolegomena", "summary": "The word that goes before: God exists and reveals Himself; laws are constant; we can know what we observe; truth does not contradict itself; the mind receives what is logical. Build the house on that porch."}, {"theme": "Five tests of doctrine", "summary": "Consistency, correspondence to reality, relevance to need, centrality of Christ, and thoroughness. A sermon can be clever and still fail these tests."}, {"theme": "Eleven divisions of theology", "summary": "Prolegomena, bibliology, theology proper, Christology, pneumatology, anthropology, hamartiology, soteriology, angelology, ecclesiology, eschatology — a map so you do not preach only your favorite room."}], "bigIdeas": ["The Bible is 66 books, many authors, about 1,600 years — and one story: God revealing Himself and redeeming people (Hebrews 1:1–2). Christianity is Jesus Christ.", "Doctrine is not a cold hobby. It is teaching that meets people at the point of need — a wrench that actually turns, not a trophy on the shelf.", "The gospel is good news as a proposition (Christ died, was buried, rose — 1 Corinthians 15) and as a Person received (John 1:12). Do not separate relationship from truth.", "Prolegomena means “the word that goes before” — the blueprint. We assume God exists and speaks, that truth does not contradict itself, and that the last step of communication is worship (John 4:24).", "Test doctrine by consistency, correspondence, relevance, Christ’s centrality, and thoroughness. Towns maps eleven divisions, not twenty-two."], "summary": "The Bible’s story, what doctrine is for, and the blueprint that goes before the rest of theology. The Bible is 66 books, many authors, about 1,600 years — and one story: God revealing Himself and redeeming people (Hebrews 1:1–2). Christianity is Jesus Christ.", "quickReview": ["The Bible is 66 books, many authors, about 1,600 years — and one story: God revealing Himself and redeeming…", "Doctrine is not a cold hobby. It is teaching that meets people at the point of need — a wrench that actually…", "The gospel is good news as a proposition (Christ died, was buried, rose — 1 Corinthians 15) and as a Person…", "Prolegomena means “the word that goes before” — the blueprint. We assume God exists and speaks, that truth…", "Test doctrine by consistency, correspondence, relevance, Christ’s centrality, and thoroughness. Towns maps…"], "glossary": [{"term": "The word that goes before", "meaning": "the blueprint"}, {"term": "Prolegomena", "meaning": "The word that goes before: God exists and reveals Himself; laws are constant; we can know what we observe; truth does not contradict itself; the mind receives…"}, {"term": "Five tests of doctrine", "meaning": "Consistency, correspondence to reality, relevance to need, centrality of Christ, and thoroughness. A sermon can be clever and still fail these tests."}, {"term": "Eleven divisions of theology", "meaning": "Prolegomena, bibliology, theology proper, Christology, pneumatology, anthropology, hamartiology, soteriology, angelology, ecclesiology, eschatology — a map so…"}, {"term": "The Bible", "meaning": "The Bible is 66 books, many authors, about 1,600 years — and one story: God revealing Himself and redeeming peopl"}, {"term": "Christianity", "meaning": "Christianity is Jesus Christ"}, {"term": "Doctrine", "meaning": "Doctrine is not a cold hobby"}], "outline": ["Prolegomena", "Five tests of doctrine", "Eleven divisions of theology"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "The Bible is 66 books, many authors, about 1,600 years — and one story: God revealing Himself and redeeming people (Hebrews 1:1–2)…"}, {"label": "Key claim", "value": "Doctrine is not a cold hobby. It is teaching that meets people at the point of need — a wrench that actually turns, not a trophy on the…"}, {"label": "Key claim", "value": "The gospel is good news as a proposition (Christ died, was buried, rose — 1 Corinthians 15) and as a Person received (John 1:12). Do not…"}], "pulpit": ["A sermon can be clever and still fail these tests.", "Prolegomena, bibliology, theology proper, Christology, pneumatology, anthropology, hamartiology, soteriology, angelology, ecclesiology, eschatology — a map so…"], "compare": null}, {"id": "th-2", "number": 2, "title": "Contents of the Bible", "topic": "Revelation, inspiration, inerrancy, and the eight words for how we handle Scripture.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Question wording reconstructed from session notes.", "takeaways": ["Eight words keep a pastor honest with the Book: revelation, inspiration, inerrancy, preservation, canonicity, illumination, interpretation, application.", "Revelation is God unveiling Himself — not merely handing us ideas. General revelation (nature, conscience, history) and special revelation (Scripture and Christ) both matter, and they are not the same gift.", "Inspiration (theopneustos, God-breathed) is the Spirit guiding the writing. Revelation gives the truth; inspiration guards the writing. Mix them up and you will preach fog.", "We trust this Book because it uniquely reveals Christ, says “Thus saith the Lord” more than a thousand times, carries fulfilled prophecy (the Dead Sea Scrolls still preach), converts sinners, and tells the truth about its heroes’ sins.", "Illumination is the Spirit helping us understand; application is actually doing the Word (James 1:22). Interpretation without obedience is unfinished discipleship."], "quiz": [{"q": "The redemption message meets the needs of sinful men.", "answer": "True", "why": "The Bible is not a riddle for the clever; it is rescue for the guilty."}, {"q": "Inerrancy means the Bible is accurate, reliable, authoritative, and without error.", "answer": "True", "why": "A high view of Scripture is a pastoral comfort, not a hobbyhorse."}, {"q": "The Bible is essentially a story of thoughts about God.", "answer": "False", "why": "It is a record of God’s acts — He does, then He speaks."}, {"q": "Revelation means God unveils Himself to His people.", "answer": "True", "why": "God is not a puzzle we invented; He pulls back the veil."}, {"q": "There is general revelation and special (specific) revelation.", "answer": "True", "why": "The sky preaches; the Son and the Scriptures save and specify."}, {"q": "The Bible is God’s Word because of the unique revelation of Christ.", "answer": "True", "why": "The Book’s center is a Person."}, {"q": "God’s truthfulness would demand that He remain incognito.", "answer": "False", "why": "Because He is true, He reveals Himself. Hiddenness is not His last word."}, {"q": "Over 1,000 times the authors claim the message is from God.", "answer": "True", "why": "“Thus saith the Lord” is not a decoration; it is a claim."}, {"q": "The Dead Sea Scrolls show that prophecies pre-date their fulfillment.", "answer": "True", "why": "The promise was written before the empty tomb, not after."}, {"q": "Each book was written by a human author guided by the Holy Spirit.", "answer": "True", "why": "Real men, real style, one divine Author."}], "essays": [{"theme": "Fourteen methods of revelation", "summary": "Visions, dreams, nature, biography, sermons, face to face, writing on stone, object lessons, parables, inner compulsion, history, angels, research, and Jesus Himself — God is not limited to one microphone."}, {"theme": "The unity of Scripture despite many authors", "summary": "About forty writers across about 1,600 years, and one story. That unity is itself a reason to trust, and a reason to preach the whole counsel."}, {"theme": "Christ’s deity claims — liar, lunatic, or Lord", "summary": "He does not leave us the option of a merely nice teacher. The claims force a decision; the pulpit should too."}], "bigIdeas": ["Eight words keep a pastor honest with the Book: revelation, inspiration, inerrancy, preservation, canonicity, illumination, interpretation, application.", "Revelation is God unveiling Himself — not merely handing us ideas. General revelation (nature, conscience, history) and special revelation (Scripture and Christ) both matter, and they are not the same gift.", "Inspiration (theopneustos, God-breathed) is the Spirit guiding the writing. Revelation gives the truth; inspiration guards the writing. Mix them up and you will preach fog.", "We trust this Book because it uniquely reveals Christ, says “Thus saith the Lord” more than a thousand times, carries fulfilled prophecy (the Dead Sea Scrolls still preach), converts sinners, and tells the truth about its heroes’ sins.", "Illumination is the Spirit helping us understand; application is actually doing the Word (James 1:22). Interpretation without obedience is unfinished discipleship."], "summary": "Revelation, inspiration, inerrancy, and the eight words for how we handle Scripture. Eight words keep a pastor honest with the Book: revelation, inspiration, inerrancy, preservation, canonicity, illumination, interpretation, application.", "quickReview": ["Eight words keep a pastor honest with the Book: revelation, inspiration, inerrancy, preservation, canonicity…", "Revelation is God unveiling Himself — not merely handing us ideas. General revelation (nature, conscience…", "Inspiration (theopneustos, God-breathed) is the Spirit guiding the writing. Revelation gives the truth…", "We trust this Book because it uniquely reveals Christ, says “Thus saith the Lord” more than a thousand times…", "Illumination is the Spirit helping us understand; application is actually doing the Word (James 1:22)…"], "glossary": [{"term": "Thus saith the Lord", "meaning": "We trust this Book because it uniquely reveals Christ, says “Thus saith the Lord” more than a thousand times, carries fulfilled prophecy (the Dead Sea Scrolls…"}, {"term": "Fourteen methods of revelation", "meaning": "Visions, dreams, nature, biography, sermons, face to face, writing on stone, object lessons, parables, inner compulsion, history, angels, research, and Jesus…"}, {"term": "The unity of Scripture despite many authors", "meaning": "About forty writers across about 1,600 years, and one story. That unity is itself a reason to trust, and a reason to preach the whole counsel."}, {"term": "Christ’s deity claims — liar, lunatic, or Lord", "meaning": "He does not leave us the option of a merely nice teacher. The claims force a decision; the pulpit should too."}, {"term": "Revelation", "meaning": "Revelation is God unveiling Himself — not merely handing us ideas"}, {"term": "Illumination", "meaning": "Illumination is the Spirit helping us understand; application is actually doing the Word (James 1:22)"}, {"term": "Inspiration", "meaning": "Eight words keep a pastor honest with the Book: revelation, inspiration, inerrancy, preservation, canonicity, illumination, interpretation, application."}], "outline": ["Fourteen methods of revelation", "The unity of Scripture despite many authors", "Christ’s deity claims — liar, lunatic, or Lord"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Eight words keep a pastor honest with the Book: revelation, inspiration, inerrancy, preservation, canonicity, illumination, interpretation…"}, {"label": "Key claim", "value": "Revelation is God unveiling Himself — not merely handing us ideas. General revelation (nature, conscience, history) and special revelation…"}, {"label": "Preach", "value": "Inspiration (theopneustos, God-breathed) is the Spirit guiding the writing. Revelation gives the truth; inspiration guards the writing. Mix…"}], "compare": [{"title": "Clarify", "points": ["Revelation is God unveiling Himself", "Not: merely handing us ideas. General revelation (nature, conscience, history) and special revelation (Scripture and Christ)…"]}], "pulpit": ["Mix them up and you will preach fog.", "We trust this Book because it uniquely reveals Christ, says “Thus saith the Lord” more than a thousand times, carries fulfilled prophecy (the Dead Sea Scrolls…", "Visions, dreams, nature, biography, sermons, face to face, writing on stone, object lessons, parables, inner compulsion, history, angels, research, and Jesus…", "That unity is itself a reason to trust, and a reason to preach the whole counsel."]}, {"id": "th-3", "number": 3, "title": "Accuracy and inspiration of Scripture", "topic": "God-breathed words, inerrancy, faulty theories, and a closed canon.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Question wording reconstructed from session notes.", "takeaways": ["Inspiration is the Spirit’s superintending work so that writers wrote what God wanted, without error. Theopneustos in 2 Timothy 3:16 means God-breathed — life in the words.", "Four qualities to keep straight: inspired men (borne along, 2 Peter 1:21), inspired writers (God used personality and style), inspired words (verbal, not ideas only), inspired results (inerrancy and authority).", "Name the faulty views so you can smell them in a conversation: intuition, conceptual, illumination-only, partial, limited (“only the religious bits”), dictation, and KJV-only inspiration of a translation.", "We hold inerrancy because Scripture claims it, Jesus treated it as final truth (“It is written”), and God cannot lie. Reliability is also backed by history, archaeology, and prophecy.", "The autographs are gone; thousands of manuscripts remain. Textual criticism, rightly used, aims to recover the original wording — not to unseat the Word."], "quiz": [{"q": "The word theopneustos appears in 2 Timothy 3:16.", "answer": "True", "why": "God-breathed. That one word carries a pulpit’s confidence."}, {"q": "The author was guided to write what God wanted.", "answer": "True", "why": "Superintendence, not religious guesswork."}, {"q": "God gave the thoughts but not the words.", "answer": "False", "why": "Verbal inspiration: the words matter, not only the vibe."}, {"q": "Conceptual inspiration means God inspired the ideas.", "answer": "True", "why": "That is a real view — and a faulty one. Ideas without words will not hold a church."}, {"q": "Limited inspiration means Scripture is authoritative only in religious dogma.", "answer": "True", "why": "George Eldon Ladd’s kind of limit. It carves the Bible into “safe” and “skippable.”"}, {"q": "Some dismiss passages as morally objectionable.", "answer": "True", "why": "People still edit God. The pastor’s job is not to help them."}, {"q": "The prophets never claimed to speak the words of God.", "answer": "False", "why": "They claimed it constantly. That is why “thus saith the Lord” lands with weight."}, {"q": "Jesus appealed to the authority of the Word as final truth.", "answer": "True", "why": "“It is written” is how the Lord Himself argued."}, {"q": "Parts of Daniel are in Chaldean.", "answer": "True", "why": "The Book is at home in history and language, not in a fog."}, {"q": "Textual criticism aims to recover the wording of the autographs.", "answer": "True", "why": "A servant task: get back to what was written, not replace it."}], "essays": [{"theme": "Definition and four qualities of inspiration", "summary": "Men borne along, writers as themselves, words as God’s, results as inerrant and authoritative. Keep all four or the doctrine tilts."}, {"theme": "The Bible’s own arguments for inerrancy", "summary": "Self-witness, the character of God, and the Lord’s own use of Scripture. We do not prop the Book up with mood; it claims what it is."}, {"theme": "How Jesus treated Scripture", "summary": "He quoted it as final, lived under it, and fulfilled it. A church that shrugs at the Book is not following this Jesus."}], "bigIdeas": ["Inspiration is the Spirit’s superintending work so that writers wrote what God wanted, without error. Theopneustos in 2 Timothy 3:16 means God-breathed — life in the words.", "Four qualities to keep straight: inspired men (borne along, 2 Peter 1:21), inspired writers (God used personality and style), inspired words (verbal, not ideas only), inspired results (inerrancy and authority).", "Name the faulty views so you can smell them in a conversation: intuition, conceptual, illumination-only, partial, limited (“only the religious bits”), dictation, and KJV-only inspiration of a translation.", "We hold inerrancy because Scripture claims it, Jesus treated it as final truth (“It is written”), and God cannot lie. Reliability is also backed by history, archaeology, and prophecy.", "The autographs are gone; thousands of manuscripts remain. Textual criticism, rightly used, aims to recover the original wording — not to unseat the Word."], "summary": "God-breathed words, inerrancy, faulty theories, and a closed canon. Inspiration is the Spirit’s superintending work so that writers wrote what God wanted, without error. Theopneustos in 2 Timothy 3:16 means God-breathed — life in the words.", "quickReview": ["Inspiration is the Spirit’s superintending work so that writers wrote what God wanted, without error…", "Four qualities to keep straight: inspired men (borne along, 2 Peter 1:21), inspired writers (God used…", "Name the faulty views so you can smell them in a conversation: intuition, conceptual, illumination-only…", "We hold inerrancy because Scripture claims it, Jesus treated it as final truth (“It is written”), and God…", "The autographs are gone; thousands of manuscripts remain. Textual criticism, rightly used, aims to recover…"], "glossary": [{"term": "Only the religious bits", "meaning": "Name the faulty views so you can smell them in a conversation: intuition, conceptual, illumination-only, partial, limited (“only the religious bits”)…"}, {"term": "It is written", "meaning": "We hold inerrancy because Scripture claims it, Jesus treated it as final truth (“It is written”), and God cannot lie."}, {"term": "Safe", "meaning": "It carves the Bible into “safe” and “skippable.” People still edit God."}, {"term": "Skippable", "meaning": "It carves the Bible into “safe” and “skippable.” People still edit God."}, {"term": "Thus saith the Lord", "meaning": "That is why “thus saith the Lord” lands with weight."}, {"term": "Definition and four qualities of inspiration", "meaning": "Men borne along, writers as themselves, words as God’s, results as inerrant and authoritative. Keep all four or the doctrine tilts."}, {"term": "The Bible’s own arguments for inerrancy", "meaning": "Self-witness, the character of God, and the Lord’s own use of Scripture. We do not prop the Book up with mood; it claims what it is."}, {"term": "How Jesus treated Scripture", "meaning": "He quoted it as final, lived under it, and fulfilled it. A church that shrugs at the Book is not following this Jesus."}], "outline": ["Definition and four qualities of inspiration", "The Bible’s own arguments for inerrancy", "How Jesus treated Scripture"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Inspiration is the Spirit’s superintending work so that writers wrote what God wanted, without error. Theopneustos in 2 Timothy 3:16 means…"}, {"label": "Key claim", "value": "Four qualities to keep straight: inspired men (borne along, 2 Peter 1:21), inspired writers (God used personality and style), inspired…"}, {"label": "Key claim", "value": "Name the faulty views so you can smell them in a conversation: intuition, conceptual, illumination-only, partial, limited (“only the…"}], "compare": [{"title": "Four qualities to keep straight", "points": ["inspired men (borne along", "2 Peter 1:21)", "inspired writers (God used personality", "style)", "inspired words (verbal", "not ideas only)", "inspired results (inerrancy", "authority)"]}, {"title": "Clarify", "points": ["The autographs are gone; thousands of manuscripts remain. Textual criticism, rightly used, aims to recover the original…", "Not: to unseat the Word."]}], "pulpit": ["Four qualities to keep straight: inspired men (borne along, 2 Peter 1:21), inspired writers (God used personality and style)…", "Name the faulty views so you can smell them in a conversation: intuition, conceptual, illumination-only, partial, limited (“only…", "We hold inerrancy because Scripture claims it, Jesus treated it as final truth (“It is written”), and God cannot lie. Reliability…"]}, {"id": "th-4", "number": 4, "title": "Nature of God", "topic": "God’s nature and attributes — and the wrong views that quietly wreck a Christian life.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["A wrong view of God always multiplies problems in daily Christian living (Tozer). What you believe about God will leak into prayer, marriage, money, and preaching.", "Nature is who God is; attributes are the rays of that sun. Do not preach attributes as spare parts you can rearrange.", "Seven terms for His nature: Spirit, Person, Life, self-existent, immutable, unlimited by time and space, and unity — one God. The Trinity is not three gods.", "Holiness, love, and goodness are absolute attributes (God alone in that fullness). Omniscience, omnipresence, and omnipotence are comparative — we have a drop; He has the sea.", "God has never learned. He is present everywhere at all times. Omnipotence still has limits of character: He cannot lie, sin, or stop being who He is.", "Most religions paint God as an impersonal force. The gospel gives us a living Lord with intellect, emotion, and will."], "quiz": [{"q": "The wrong view of God will always cause a multitude of problems in the daily life of a Christian.", "answer": "True", "why": "Theology leaks. Bad doctrine makes anxious disciples."}, {"q": "While the nature of God defines His existence, the attributes of God reflect His nature.", "answer": "True", "why": "The sun and its light — do not confuse them, and do not divide them."}, {"q": "The term “personal” when used to define God means that He is immaterial, incorporeal, and invisible.", "answer": "False", "why": "That describes God as Spirit. Personal means intellect, emotion, and will."}, {"q": "Most religions of the world portray God as an impersonal being or force.", "answer": "True", "why": "The gospel is startling: God speaks, loves, and comes near."}, {"q": "God is the source of all life.", "answer": "True", "why": "We do not lend Him breath; He lends us ours."}, {"q": "God is limited in space and time.", "answer": "False", "why": "He is not a larger creature. He fills heaven and earth."}, {"q": "Holiness, love, and goodness are comparative attributes of God.", "answer": "False", "why": "They are absolute. Comparative attributes are omniscience, omnipresence, omnipotence."}, {"q": "Love is the opposite of selfishness.", "answer": "True", "why": "Preach love as holy self-giving, not as sentiment."}, {"q": "God has never learned.", "answer": "True", "why": "Omniscience is not a good student; it is a perfect mind."}, {"q": "God is present everywhere at all times.", "answer": "True", "why": "Omnipresence is comfort for the hospital room and warning for the secret sin."}], "essays": [{"theme": "God is Spirit", "summary": "Immaterial, invisible, living. We worship in spirit and truth because He is not a statue and not a mood."}, {"theme": "Eleven erroneous views of God", "summary": "Atheism, agnosticism, materialism, animism, polytheism, henotheism, tritheism, dualism, pantheism, idealism, deism — a pastoral checklist for the ideas already sitting in the pews."}, {"theme": "Six principal attributes", "summary": "Absolute: holiness, love, goodness. Comparative: omniscience, omnipresence, omnipotence. Keep the pairs straight when you teach."}], "bigIdeas": ["A wrong view of God always multiplies problems in daily Christian living (Tozer). What you believe about God will leak into prayer, marriage, money, and preaching.", "Nature is who God is; attributes are the rays of that sun. Do not preach attributes as spare parts you can rearrange.", "Seven terms for His nature: Spirit, Person, Life, self-existent, immutable, unlimited by time and space, and unity — one God. The Trinity is not three gods.", "Holiness, love, and goodness are absolute attributes (God alone in that fullness). Omniscience, omnipresence, and omnipotence are comparative — we have a drop; He has the sea.", "God has never learned. He is present everywhere at all times. Omnipotence still has limits of character: He cannot lie, sin, or stop being who He is.", "Most religions paint God as an impersonal force. The gospel gives us a living Lord with intellect, emotion, and will."], "summary": "God’s nature and attributes — and the wrong views that quietly wreck a Christian life. A wrong view of God always multiplies problems in daily Christian living (Tozer). What you believe about God will leak into prayer, marriage, money, and preaching.", "quickReview": ["A wrong view of God always multiplies problems in daily Christian living (Tozer). What you believe about God…", "Nature is who God is; attributes are the rays of that sun. Do not preach attributes as spare parts you can…", "Seven terms for His nature: Spirit, Person, Life, self-existent, immutable, unlimited by time and space, and…", "Holiness, love, and goodness are absolute attributes (God alone in that fullness). Omniscience, omnipresence…", "God has never learned. He is present everywhere at all times. Omnipotence still has limits of character: He…"], "glossary": [{"term": "God is Spirit", "meaning": "Immaterial, invisible, living. We worship in spirit and truth because He is not a statue and not a mood."}, {"term": "Eleven erroneous views of God", "meaning": "Atheism, agnosticism, materialism, animism, polytheism, henotheism, tritheism, dualism, pantheism, idealism, deism — a pastoral checklist for the ideas already…"}, {"term": "Six principal attributes", "meaning": "Absolute: holiness, love, goodness. Comparative: omniscience, omnipresence, omnipotence. Keep the pairs straight when you teach."}, {"term": "Nature", "meaning": "Nature is who God is; attributes are the rays of that sun"}, {"term": "The Trinity", "meaning": "The Trinity is not three gods"}, {"term": "Trinity", "meaning": "The Trinity is not three gods."}], "outline": ["God is Spirit", "Eleven erroneous views of God", "Six principal attributes"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Preach", "value": "A wrong view of God always multiplies problems in daily Christian living (Tozer). What you believe about God will leak into prayer…"}, {"label": "Preach", "value": "Nature is who God is; attributes are the rays of that sun. Do not preach attributes as spare parts you can rearrange."}, {"label": "Key claim", "value": "Seven terms for His nature: Spirit, Person, Life, self-existent, immutable, unlimited by time and space, and unity — one God. The Trinity…"}], "pulpit": ["What you believe about God will leak into prayer, marriage, money, and preaching.", "Do not preach attributes as spare parts you can rearrange.", "Atheism, agnosticism, materialism, animism, polytheism, henotheism, tritheism, dualism, pantheism, idealism, deism — a pastoral checklist for the ideas already…", "Keep the pairs straight when you teach."], "compare": [{"title": "Seven terms for His nature", "points": ["Spirit", "Person", "Life", "self-existent", "immutable", "unlimited by time", "space", "and unity — one God"]}]}, {"id": "th-5", "number": 5, "title": "The Trinity and the works of God", "topic": "One God in three Persons, the law of God, decrees, and the three primary names.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["The members of the Trinity are equal in nature, distinct in person, and subordinate in duties. We worship one God, not three. Tritheism and modalism both miss the glory.", "The word Trinity is not in the Bible; the truth is. The Old Testament points (Elohim, “let Us,” holy-holy-holy). The New Testament shows it in the open at Jesus’ baptism.", "Works that only God can do involve all three Persons — creation, the cross, the resurrection, inspiration, indwelling. Never preach a Lone Ranger God.", "The law reflects God’s attributes. The rule of law presupposes objective truth. Pantheism turns God into an inanimate force in nature; Scripture will not.", "God has revealed three primary names in the Old Testament, not six: Elohim, Jehovah (Yahweh), and Adonai. Names are revelation, not nicknames.", "Calvinistic language about decrees stresses that they are all-encompassing. Handle the mystery with worship: God rules, and we remain accountable."], "quiz": [{"q": "The members of the Trinity are equal in nature, distinct in person, and subordinate in duties.", "answer": "True", "why": "Equal in deity; distinct in person; ordered in mission. Hold all three lines."}, {"q": "The Trinity means three Gods.", "answer": "False", "why": "Christians are monotheists. Hear, O Israel: the LORD is one."}, {"q": "The Old Testament points to the Trinity.", "answer": "True", "why": "Hints and plural unity — not a full Nicene paragraph, but not silence either."}, {"q": "The Trinity was revealed at the baptism of Jesus.", "answer": "True", "why": "The Son in the water, the Spirit as a dove, the Father’s voice. Go to the Jordan."}, {"q": "All three persons of divinity are involved in works that only God can do.", "answer": "True", "why": "Creation, Calvary, and new birth are triune works."}, {"q": "The law is a reflection of God’s attributes.", "answer": "True", "why": "Holy, just, and good — because He is."}, {"q": "The “rule of law,” by its very nature, presupposes objective truth for it to be reliable to rightly order society.", "answer": "True", "why": "If law is only power, the strongest always wins."}, {"q": "Pantheism is the ideology teaching that God is an inanimate force within nature and controls all things through the laws of nature.", "answer": "True", "why": "Pantheism dissolves the distinction between Creator and creation."}, {"q": "The Calvinistic understanding of decrees teaches that they are all-encompassing because they control everything that comes to pass.", "answer": "True", "why": "That is the claim of that tradition. Teach it accurately even when you linger over the mystery."}, {"q": "God has revealed His six primary names in the Old Testament.", "answer": "False", "why": "Three primary names: Elohim, Jehovah, Adonai."}], "essays": [{"theme": "What is the Trinity?", "summary": "One divine nature, three real Persons — Father, Son, and Spirit — neither confounding the persons nor dividing the substance. Use the baptism, the benediction, and the Great Commission."}, {"theme": "Biblical words for decree", "summary": "Predestine, foreknowledge, elect, call, purpose, will, counsel, good pleasure. The vocabulary is worship language before it is a debate team."}, {"theme": "Three primary names", "summary": "Elohim (the strong God, plural majesty), Jehovah/Yahweh (I AM, the covenant Name), Adonai (Master). Capitalization in the KJV is a preaching tool if you explain it."}], "bigIdeas": ["The members of the Trinity are equal in nature, distinct in person, and subordinate in duties. We worship one God, not three. Tritheism and modalism both miss the glory.", "The word Trinity is not in the Bible; the truth is. The Old Testament points (Elohim, “let Us,” holy-holy-holy). The New Testament shows it in the open at Jesus’ baptism.", "Works that only God can do involve all three Persons — creation, the cross, the resurrection, inspiration, indwelling. Never preach a Lone Ranger God.", "The law reflects God’s attributes. The rule of law presupposes objective truth. Pantheism turns God into an inanimate force in nature; Scripture will not.", "God has revealed three primary names in the Old Testament, not six: Elohim, Jehovah (Yahweh), and Adonai. Names are revelation, not nicknames.", "Calvinistic language about decrees stresses that they are all-encompassing. Handle the mystery with worship: God rules, and we remain accountable."], "summary": "One God in three Persons, the law of God, decrees, and the three primary names. The members of the Trinity are equal in nature, distinct in person, and subordinate in duties. We worship one God, not three. Tritheism and modalism both miss the glory.", "quickReview": ["The members of the Trinity are equal in nature, distinct in person, and subordinate in duties. We worship one…", "The word Trinity is not in the Bible; the truth is. The Old Testament points (Elohim, “let Us,”…", "Works that only God can do involve all three Persons — creation, the cross, the resurrection, inspiration…", "The law reflects God’s attributes. The rule of law presupposes objective truth. Pantheism turns God into an…", "God has revealed three primary names in the Old Testament, not six: Elohim, Jehovah (Yahweh), and Adonai…"], "glossary": [{"term": "Let Us,", "meaning": "The Old Testament points (Elohim, “let Us,” holy-holy-holy)."}, {"term": "The Trinity?", "meaning": "One divine nature, three real Persons — Father, Son, and Spirit — neither confounding the persons nor dividing the substance. Use the baptism, the benediction…"}, {"term": "Biblical words for decree", "meaning": "Predestine, foreknowledge, elect, call, purpose, will, counsel, good pleasure. The vocabulary is worship language before it is a debate team."}, {"term": "Three primary names", "meaning": "Elohim (the strong God, plural majesty), Jehovah/Yahweh (I AM, the covenant Name), Adonai (Master). Capitalization in the KJV is a preaching tool if you…"}, {"term": "Trinity", "meaning": "Trinity is equal in nature, distinct in person, and subordinate in duties"}, {"term": "Names", "meaning": "Names is revelation, not nicknames"}, {"term": "Covenant", "meaning": "Three primary names Elohim (the strong God, plural majesty), Jehovah/Yahweh (I AM, the covenant Name), Adonai (Master)."}, {"term": "Inspiration", "meaning": "Works that only God can do involve all three Persons — creation, the cross, the resurrection, inspiration, indwelling."}], "outline": ["What is the Trinity?", "Biblical words for decree", "Three primary names"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "The members of the Trinity are equal in nature, distinct in person, and subordinate in duties. We worship one God, not three. Tritheism and…"}, {"label": "Key claim", "value": "The word Trinity is not in the Bible; the truth is. The Old Testament points (Elohim, “let Us,” holy-holy-holy). The New Testament shows it…"}, {"label": "Preach", "value": "Works that only God can do involve all three Persons — creation, the cross, the resurrection, inspiration, indwelling. Never preach a Lone…"}], "pulpit": ["Never preach a Lone Ranger God.", "Capitalization in the KJV is a preaching tool if you explain it."], "compare": null}, {"id": "th-6", "number": 6, "title": "The Person of Christ", "topic": "The Son’s deity, eternal generation, offices, virgin birth, kenosis, and hypostatic union.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["Jesus is the second Person of the Trinity — equal with the Father in essence, subordinate in office as the Sent One. He accepted worship. The New Testament ascribes creation to Him.", "Eternal generation: He has always been the Son. He did not become Son at baptism or resurrection. Christophanies are pre-incarnate appearances (the Angel of the LORD).", "Three anointed offices: Prophet (speaks), Priest (sacrifice and intercession), King. Oil pictures the Spirit; Christ means Anointed One. Do not give the priest’s work to the prophet.", "The virgin birth is necessary for His sinlessness (Genesis 3:15; Isaiah 7:14). Liberal theology does not require it; the gospel does. Joseph was not His biological father.", "Kenosis (Philippians 2:7) is self-emptying: veiled glory, accepted human limits, surrendered independent use of comparative attributes — not a surrender of deity.", "Hypostatic union (Chalcedon): one Person, two natures, fully God and fully man, without mixture or separation. Tempted for real, yet without sin. That is the Christ we preach."], "quiz": [{"q": "Jesus never allowed people to worship Him.", "answer": "False", "why": "He received worship. A mere rabbi would have stopped it."}, {"q": "The New Testament authors ascribe the work of creation to Christ.", "answer": "True", "why": "John 1:3; Colossians 1:16 — the carpenter is the Maker."}, {"q": "Jesus has always been the Son of God.", "answer": "True", "why": "Eternal Sonship. The manger is not His beginning."}, {"q": "A Christophany was a pre-incarnate appearance of Jesus Christ.", "answer": "True", "why": "The Angel of the LORD is not a footnote; it is the Son before Bethlehem."}, {"q": "The three anointed offices of Jesus Christ are prophet, priest, and king.", "answer": "True", "why": "Speak, sacrifice, reign — the whole Christ for the whole church."}, {"q": "The prophet fulfilled his office by offering sacrifices and making intercession.", "answer": "False", "why": "That is the priest. Keep the offices clean in the pulpit."}, {"q": "Even those embracing a liberal theological posture affirm the absolute necessity of believing in the virgin birth of Jesus Christ.", "answer": "False", "why": "Liberalism often shrugs. We cannot."}, {"q": "Jesus was the biological son of his father, Joseph.", "answer": "False", "why": "Joseph is legal father, not biological. The conception is of the Holy Spirit."}, {"q": "Part of Jesus’ self-emptying was His surrender of the independent use of His comparative attributes.", "answer": "True", "why": "Kenosis is veiling and dependence, not subtraction of deity."}, {"q": "Jesus is totally God and totally human at the same time.", "answer": "True", "why": "One Person, two natures. If either is lost, so is our salvation."}], "essays": [{"theme": "Threefold offices", "summary": "Prophet to our ignorance, Priest to our guilt, King to our rebellion. Preach all three or the congregation gets a partial Jesus."}, {"theme": "False views of kenosis", "summary": "He did not empty Himself of being God. He veiled glory, took servant form, and refused independent use of attributes that are His by nature."}, {"theme": "Biblical testimony for the virgin birth", "summary": "Genesis 3:15, Isaiah 7:14, the infancy narratives, and the need for a sinless last Adam. This is gospel structure, not seasonal decoration."}], "bigIdeas": ["Jesus is the second Person of the Trinity — equal with the Father in essence, subordinate in office as the Sent One. He accepted worship. The New Testament ascribes creation to Him.", "Eternal generation: He has always been the Son. He did not become Son at baptism or resurrection. Christophanies are pre-incarnate appearances (the Angel of the LORD).", "Three anointed offices: Prophet (speaks), Priest (sacrifice and intercession), King. Oil pictures the Spirit; Christ means Anointed One. Do not give the priest’s work to the prophet.", "The virgin birth is necessary for His sinlessness (Genesis 3:15; Isaiah 7:14). Liberal theology does not require it; the gospel does. Joseph was not His biological father.", "Kenosis (Philippians 2:7) is self-emptying: veiled glory, accepted human limits, surrendered independent use of comparative attributes — not a surrender of deity.", "Hypostatic union (Chalcedon): one Person, two natures, fully God and fully man, without mixture or separation. Tempted for real, yet without sin. That is the Christ we preach."], "summary": "The Son’s deity, eternal generation, offices, virgin birth, kenosis, and hypostatic union. Jesus is the second Person of the Trinity — equal with the Father in essence, subordinate in office as the Sent One. He accepted worship. The New Testament ascribes creation to Him.", "quickReview": ["Jesus is the second Person of the Trinity — equal with the Father in essence, subordinate in office as the…", "Eternal generation: He has always been the Son. He did not become Son at baptism or resurrection…", "Three anointed offices: Prophet (speaks), Priest (sacrifice and intercession), King. Oil pictures the Spirit…", "The virgin birth is necessary for His sinlessness (Genesis 3:15; Isaiah 7:14). Liberal theology does not…", "Kenosis (Philippians 2:7) is self-emptying: veiled glory, accepted human limits, surrendered independent use…"], "glossary": [{"term": "Threefold offices", "meaning": "Prophet to our ignorance, Priest to our guilt, King to our rebellion. Preach all three or the congregation gets a partial Jesus."}, {"term": "False views of kenosis", "meaning": "He did not empty Himself of being God. He veiled glory, took servant form, and refused independent use of attributes that are His by nature."}, {"term": "Biblical testimony for the virgin birth", "meaning": "Genesis 3:15, Isaiah 7:14, the infancy narratives, and the need for a sinless last Adam. This is gospel structure, not seasonal decoration."}, {"term": "Christophanies", "meaning": "Christophanies is pre-incarnate appearances (the Angel of the LORD)"}, {"term": "Joseph", "meaning": "Joseph is not His biological father"}, {"term": "Trinity", "meaning": "Jesus is the second Person of the Trinity — equal with the Father in essence, subordinate in office as the Sent One."}], "outline": ["Threefold offices", "False views of kenosis", "Biblical testimony for the virgin birth"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Jesus is the second Person of the Trinity — equal with the Father in essence, subordinate in office as the Sent One. He accepted worship…"}, {"label": "Key claim", "value": "Eternal generation: He has always been the Son. He did not become Son at baptism or resurrection. Christophanies are pre-incarnate…"}, {"label": "Key claim", "value": "Three anointed offices: Prophet (speaks), Priest (sacrifice and intercession), King. Oil pictures the Spirit; Christ means Anointed One. Do…"}], "compare": [{"title": "Three anointed offices", "points": ["Prophet (speaks)", "Priest (sacrifice", "intercession)", "King"]}, {"title": "Clarify", "points": ["Kenosis (Philippians 2:7) is self-emptying: veiled glory, accepted human limits, surrendered independent use of…", "Not: a surrender of deity."]}], "pulpit": ["That is the Christ we preach.", "Preach all three or the congregation gets a partial Jesus."]}]}, {"id": "nt-survey-1", "code": 51, "title": "New Testament Survey 1", "status": "complete", "certificateUnlocked": true, "blurb": "Silent years to Acts — four portraits of one Lord, and the church on mission. Certificate unlocked. Course total 99%.", "lessons": [{"id": "nt-1", "number": 1, "title": "Introduction to the New Testament", "topic": "Four Gospels at a glance, the 400 silent years, and a world prepared for the Savior.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["The Old Testament is the New Testament concealed; the New Testament is the Old Testament revealed. Everything points to Christ (Luke 24:44).", "Gospel means good news. The four Gospels are persuasive histories written by the evangelists — Jesus did not write them, and we do not need Him to have written them in order to trust them.", "Matthew: tax collector, Jew, apostle — to the Jews — Christ as King — key word Kingdom — Lion. Mark: with Peter — to Romans — Christ as Servant — immediately — Ox. Luke: physician, Greek, with Paul — to Greeks — perfect Man — Son of Man — Man. John: fisherman, apostle — to the whole world — Christ is God — believe and life — Eagle.", "The 400 silent years were not empty years: Babylon, Persia, Greece (Septuagint, 285 BC, Hebrew into Greek), Maccabees, Rome. Herod was crowned by Julius Caesar. Pax Romana paved roads for preachers.", "Pharisees (“to separate”) and Sadducees stood opposite each other. It was the Sadducees who denied the supernatural — a detail that still saves you from mixing the parties in a sermon."], "figure": {"caption": "Four Gospels at a glance", "headers": ["Gospel", "Author", "Audience", "Theme", "Key word", "Symbol"], "rows": [["Matthew", "Tax collector, Jew, apostle", "Jews", "Christ as King", "Kingdom", "Lion"], ["Mark", "Jew/Roman, with Peter", "Romans", "Christ as Servant", "immediately", "Ox"], ["Luke", "Physician, Greek, with Paul", "Greeks", "Christ as perfect Man", "Son of Man", "Man"], ["John", "Fisherman, Jew, apostle", "Whole world", "Christ is God", "believe / life", "Eagle"]]}, "quiz": [{"q": "Jesus wrote the New Testament.", "answer": "False", "why": "The evangelists wrote the Gospels. Jesus is the subject, not the scribe."}, {"q": "Everything in the Gospels points to Jesus.", "answer": "True", "why": "Luke 24:44 — law, prophets, and psalms find their yes in Him."}, {"q": "Matthew was a doctor.", "answer": "False", "why": "Luke is the beloved physician. Matthew was a tax collector."}, {"q": "The key word in Matthew is Kingdom.", "answer": "True", "why": "The King and His kingdom — that is Matthew’s drumbeat."}, {"q": "John was written to the entire world.", "answer": "True", "why": "Not a house newsletter. “Whoever believes” is the horizon."}, {"q": "John includes the greatest number of parables.", "answer": "False", "why": "John has none of the Synoptic parables. Luke has the most."}, {"q": "Luke is the most Jewish-oriented Gospel.", "answer": "False", "why": "Matthew is the most Jewish Gospel. Luke writes with Greeks in view."}, {"q": "The Septuagint is the Hebrew Bible translated into Greek.", "answer": "True", "why": "About 285 BC — God preparing a Greek-speaking world for a Greek New Testament."}, {"q": "Herod was crowned by Julius Caesar.", "answer": "True", "why": "Rome’s politics become the cradle of the nativity story."}, {"q": "The Pharisees denied the supernatural.", "answer": "False", "why": "The Sadducees denied the supernatural. Keep the parties straight."}], "essays": [{"theme": "Four authors and their audiences", "summary": "Matthew to Jews (King), Mark to Romans (Servant), Luke to Greeks (perfect Man), John to the world (God the Son). Audience shapes emphasis without splitting Jesus into four."}, {"theme": "Key word, verse, symbol, and emphasis compared", "summary": "Kingdom / Lion; immediately / Ox; Son of Man / Man; believe and life / Eagle. One Lord, four faithful portraits — preach them as harmony, not as rivals."}, {"theme": "Seven course objectives", "summary": "A survey’s aim: know the lay of the land, the writers, the silent years, and how each book serves Christ and the church. Use the objectives as a checklist when you review."}], "bigIdeas": ["The Old Testament is the New Testament concealed; the New Testament is the Old Testament revealed. Everything points to Christ (Luke 24:44).", "Gospel means good news. The four Gospels are persuasive histories written by the evangelists — Jesus did not write them, and we do not need Him to have written them in order to trust them.", "Matthew: tax collector, Jew, apostle — to the Jews — Christ as King — key word Kingdom — Lion. Mark: with Peter — to Romans — Christ as Servant — immediately — Ox. Luke: physician, Greek, with Paul — to Greeks — perfect Man — Son of Man — Man. John: fisherman, apostle — to the whole world — Christ is God — believe and life — Eagle.", "The 400 silent years were not empty years: Babylon, Persia, Greece (Septuagint, 285 BC, Hebrew into Greek), Maccabees, Rome. Herod was crowned by Julius Caesar. Pax Romana paved roads for preachers.", "Pharisees (“to separate”) and Sadducees stood opposite each other. It was the Sadducees who denied the supernatural — a detail that still saves you from mixing the parties in a sermon."], "summary": "Four Gospels at a glance, the 400 silent years, and a world prepared for the Savior. The Old Testament is the New Testament concealed; the New Testament is the Old Testament revealed. Everything points to Christ (Luke 24:44).", "quickReview": ["The Old Testament is the New Testament concealed; the New Testament is the Old Testament revealed. Everything…", "Gospel means good news. The four Gospels are persuasive histories written by the evangelists — Jesus did not…", "Matthew: tax collector, Jew, apostle — to the Jews — Christ as King — key word Kingdom — Lion. Mark: with…", "The 400 silent years were not empty years: Babylon, Persia, Greece (Septuagint, 285 BC, Hebrew into Greek)…", "Pharisees (“to separate”) and Sadducees stood opposite each other. It was the Sadducees who denied the…"], "glossary": [{"term": "Four authors and their audiences", "meaning": "Matthew to Jews (King), Mark to Romans (Servant), Luke to Greeks (perfect Man), John to the world (God the Son). Audience shapes emphasis without splitting…"}, {"term": "Key word, verse, symbol, and emphasis compared", "meaning": "Kingdom / Lion; immediately / Ox; Son of Man / Man; believe and life / Eagle. One Lord, four faithful portraits — preach them as harmony, not as rivals."}, {"term": "Seven course objectives", "meaning": "A survey’s aim: know the lay of the land, the writers, the silent years, and how each book serves Christ and the church. Use the objectives as a checklist when…"}, {"term": "Herod", "meaning": "Herod is crowned by Julius Caesar"}], "outline": ["Four authors and their audiences", "Key word, verse, symbol, and emphasis compared", "Seven course objectives"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Author", "value": "the evangelists — Jesus did not write them, and we do not need Him to h"}, {"label": "Audience", "value": "shapes emphasis without splitting Jesus into four"}, {"label": "Date", "value": "285 BC, Hebrew into Greek), Maccabee"}, {"label": "Purpose", "value": "know the lay of the land, the writers, the silent years, and how each book serves Christ a"}, {"label": "Key word", "value": "Kingdom — Lion"}, {"label": "Portrait", "value": "King"}, {"label": "Key claim", "value": "The Old Testament is the New Testament concealed; the New Testament is the Old Testament revealed. Everything points to Christ (Luke 24:44)."}], "compare": [{"title": "Four Gospels at a glance", "points": ["Matthew: tax collector, Jew, apostle — to the Jews — Christ as King — key word Kingdom — Lion", "Mark: with Peter — to Romans — Christ as Servant — immediately — Ox", "Luke: physician, Greek, with Paul — to Greeks — perfect Man — Son of Man — Man", "John: fisherman, apostle — to the whole world — Christ is God — believe and life — Eagle"]}, {"title": "Pharisees and Sadducees", "points": ["Pharisees (“to separate”) and Sadducees stood opposite each other.", "Pharisees (“to separate”) and Sadducees stood opposite each other."]}], "pulpit": ["Pax Romana paved roads for preachers.", "It was the Sadducees who denied the supernatural — a detail that still saves you from mixing the parties in a sermon.", "One Lord, four faithful portraits — preach them as harmony, not as rivals."]}, {"id": "nt-2", "number": 2, "title": "Matthew", "topic": "The most Jewish Gospel: Jesus the predicted King, the Baptist, the Mount, and the road to the cross.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["Matthew, the former tax collector, writes the most Jewish Gospel: Jesus is the promised King and Messiah. Key verse: Matthew 2:2 — “Where is He who has been born King of the Jews?”", "The wise men’s request threatened Herod. History has never agreed on the star. You can preach the worship without pretending the astronomy is settled.", "John the Baptist fulfills Isaiah. The high point of his ministry is baptizing Jesus — the Trinity at the Jordan, not the biggest crowd.", "Matthew’s own call was immediate and influenced others. Following Jesus in public still makes room for other feet.", "The Sermon on the Mount travels across culture and time. To bless is to add value to another’s life. The believer’s ultimate authority is God’s planned purpose — not mood, not majority.", "Expect opposition (Matthew 10). Jesus predicted His death and resurrection about twenty times, not three. The cross was not a surprise ending."], "quiz": [{"q": "The wise men’s request to see the baby born “King of the Jews” threatened Herod.", "answer": "True", "why": "A rival king in Bethlehem is a political emergency in Jerusalem."}, {"q": "History has been in total agreement concerning the star which guided the worshippers to Jesus.", "answer": "False", "why": "The star’s identity is disputed. Worship is not. Hold the story with honesty."}, {"q": "John the Baptist’s preaching fulfilled an Old Testament prediction.", "answer": "True", "why": "Isaiah’s voice in the wilderness becomes flesh and locusts."}, {"q": "The high point of John the Baptist’s ministry was baptizing Jesus.", "answer": "True", "why": "He must increase. The Jordan, not the crowds, is the peak."}, {"q": "Matthew’s willingness to follow Jesus influenced others to do the same.", "answer": "True", "why": "Obedience is contagious. So is delay."}, {"q": "The Sermon on the Mount contains principles that can be applied across culture and across time.", "answer": "True", "why": "Amazement, authority, and real happiness — not a first-century museum."}, {"q": "To “bless” means to add value to another’s life.", "answer": "True", "why": "Blessing is not thin words; it is real good done to a real neighbor."}, {"q": "The planned purpose of God is the believer’s ultimate authority for life.", "answer": "True", "why": "Not the loudest opinion in the room."}, {"q": "It is easier to endure when we are unaware of the opposition to our faith.", "answer": "False", "why": "Jesus tells the truth about opposition so we can stand, not so we can nap."}, {"q": "Jesus only predicted His death and resurrection three times before He was actually crucified.", "answer": "False", "why": "About twenty times — the cross was announced, not improvised."}], "essays": [{"theme": "Who was John the Baptist?", "summary": "Wilderness prophet, Isaiah’s voice, forerunner, and the man who got to lower the King into the water. His joy was to decrease."}, {"theme": "Seven questions and three principles from the Sermon on the Mount", "summary": "The sermon still asks how we live before the Father who sees in secret. Carry amazement at Jesus’ authority, the shape of true happiness, and a life aimed at God’s purpose."}, {"theme": "Eight insights from Matthew 10", "summary": "Mission is not a picnic. Jesus prepares disciples for opposition, dependence, and courage. Negative preparation is still love."}], "bigIdeas": ["Matthew, the former tax collector, writes the most Jewish Gospel: Jesus is the promised King and Messiah. Key verse: Matthew 2:2 — “Where is He who has been born King of the Jews?”", "The wise men’s request threatened Herod. History has never agreed on the star. You can preach the worship without pretending the astronomy is settled.", "John the Baptist fulfills Isaiah. The high point of his ministry is baptizing Jesus — the Trinity at the Jordan, not the biggest crowd.", "Matthew’s own call was immediate and influenced others. Following Jesus in public still makes room for other feet.", "The Sermon on the Mount travels across culture and time. To bless is to add value to another’s life. The believer’s ultimate authority is God’s planned purpose — not mood, not majority.", "Expect opposition (Matthew 10). Jesus predicted His death and resurrection about twenty times, not three. The cross was not a surprise ending."], "summary": "The most Jewish Gospel: Jesus the predicted King, the Baptist, the Mount, and the road to the cross. Matthew, the former tax collector, writes the most Jewish Gospel: Jesus is the promised King and Messiah. Key verse: Matthew 2:2 — “Where is He who has been born King of the Jews?”.", "quickReview": ["Matthew, the former tax collector, writes the most Jewish Gospel: Jesus is the promised King and Messiah. Key…", "The wise men’s request threatened Herod. History has never agreed on the star. You can preach the worship…", "John the Baptist fulfills Isaiah. The high point of his ministry is baptizing Jesus — the Trinity at the…", "Matthew’s own call was immediate and influenced others. Following Jesus in public still makes room for other…", "The Sermon on the Mount travels across culture and time. To bless is to add value to another’s life. The…"], "glossary": [{"term": "John the Baptist?", "meaning": "Wilderness prophet, Isaiah’s voice, forerunner, and the man who got to lower the King into the water. His joy was to decrease."}, {"term": "Seven questions and three principles from the Sermon on", "meaning": "The sermon still asks how we live before the Father who sees in secret. Carry amazement at Jesus’ authority, the shape of true happiness, and a life aimed at…"}, {"term": "Eight insights from Matthew 10", "meaning": "Mission is not a picnic. Jesus prepares disciples for opposition, dependence, and courage. Negative preparation is still love."}, {"term": "Where", "meaning": "Where is He who has been born King of the Jews?”"}, {"term": "Trinity", "meaning": "The high point of his ministry is baptizing Jesus — the Trinity at the Jordan, not the biggest crowd."}], "outline": ["Who was John the Baptist?", "Seven questions and three principles from the Sermon on the Mount", "Eight insights from Matthew 10"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Matthew, the former tax collector, writes the most Jewish Gospel: Jesus is the promised King and Messiah. Key verse: Matthew 2:2 — “Where…"}, {"label": "Preach", "value": "The wise men’s request threatened Herod. History has never agreed on the star. You can preach the worship without pretending the astronomy…"}, {"label": "Key claim", "value": "John the Baptist fulfills Isaiah. The high point of his ministry is baptizing Jesus — the Trinity at the Jordan, not the biggest crowd."}], "compare": [{"title": "Clarify", "points": ["The Sermon on the Mount travels across culture and time. To bless is to add value to another’s life. The believer’s…", "Not: mood, not majority."]}], "pulpit": ["You can preach the worship without pretending the astronomy is settled.", "The Sermon on the Mount travels across culture and time.", "The sermon still asks how we live before the Father who sees in secret."]}, {"id": "nt-3", "number": 3, "title": "Mark", "topic": "John Mark, Peter’s interpreter, and the gospel of the Servant — immediately.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["Mark (John Marcus), Barnabas’ nephew, likely the young man who fled naked, wrote from Peter’s testimony. A restored helper can still write Scripture’s shortest Gospel.", "Mark presents Jesus as Servant in a gospel of deeds. Key verse: Mark 10:45. Key word: immediately. No genealogy, no birth narrative — a servant does not hand you a résumé.", "The “Long Day” (Mark 3:12–5:43) is packed with about ten events. It shows Jesus’ humanity and weariness. He is in control of Himself, not always of His circumstances.", "During that long day He preached a sermon with eight parables. His family did not demonstrate total support. Ministry can be lonely in your own house.", "The day ends with two contrasting miracles: the woman with the issue of blood and Jairus’ daughter — a long hemorrhage and a short life, both met by the Servant.", "Mark 4’s soils still preach: wayside, stony, thorns, good ground. The issue is not the Sower’s skill only; it is the heart that hears."], "quiz": [{"q": "Mark, only a boy during the ministry of Christ, wrote from the testimony of Peter.", "answer": "True", "why": "Peter’s interpreter. Eyewitness preaching becomes written Gospel."}, {"q": "Mark was Barnabas’ nephew.", "answer": "True", "why": "Family, failure at Perga, and later restoration — a pastoral subplot."}, {"q": "The book of Mark presents Jesus as a servant in a gospel of deeds.", "answer": "True", "why": "Action more than speech. The Servant is busy with the Father’s will."}, {"q": "The key word in Mark is “immediately.”", "answer": "True", "why": "Urgency is not hurry for its own sake; it is a Lord on the move."}, {"q": "The favorite name of the devil/demons for deity is “The Holy One of God.”", "answer": "True", "why": "Hell knows His name. The question is whether the church will."}, {"q": "The “Long Day” in Mark demonstrated that Jesus was tireless.", "answer": "False", "why": "It shows His humanity. He grew weary. That is good news for tired pastors."}, {"q": "Mark points out that Jesus was in control of Himself, but not necessarily His circumstances.", "answer": "True", "why": "Self-control under pressure is holiness, not passivity."}, {"q": "During the “Long Day,” Jesus preached a sermon with eight parables.", "answer": "True", "why": "Teaching packed into a crushing schedule — the Servant still opens His mouth."}, {"q": "During the “Long Day,” Jesus’ family demonstrated total support.", "answer": "False", "why": "They misunderstood Him. Faithfulness is not always applauded at home."}, {"q": "The “Long Day” concludes with miracles where Jesus healed two people with two contrasting problems.", "answer": "True", "why": "A twelve-year hemorrhage and a twelve-year-old girl — one Lord for both."}], "essays": [{"theme": "The emphasis of Mark", "summary": "Jesus the Servant, deeds over pedigree, immediately, Mark 10:45 as the spine. Preach a Christ who came not to be served but to serve, and to give His life as a ransom."}, {"theme": "Ten events of the Long Day", "summary": "A crushing sequence from confrontation to parables to storm to tombs to two healings. Use it to show both the press of need and the real humanity of Jesus."}, {"theme": "The parables of Mark 4", "summary": "Four soils, and the company of kingdom parables. Hearing is not automatic. Ask the congregation which soil they are this week."}], "bigIdeas": ["Mark (John Marcus), Barnabas’ nephew, likely the young man who fled naked, wrote from Peter’s testimony. A restored helper can still write Scripture’s shortest Gospel.", "Mark presents Jesus as Servant in a gospel of deeds. Key verse: Mark 10:45. Key word: immediately. No genealogy, no birth narrative — a servant does not hand you a résumé.", "The “Long Day” (Mark 3:12–5:43) is packed with about ten events. It shows Jesus’ humanity and weariness. He is in control of Himself, not always of His circumstances.", "During that long day He preached a sermon with eight parables. His family did not demonstrate total support. Ministry can be lonely in your own house.", "The day ends with two contrasting miracles: the woman with the issue of blood and Jairus’ daughter — a long hemorrhage and a short life, both met by the Servant.", "Mark 4’s soils still preach: wayside, stony, thorns, good ground. The issue is not the Sower’s skill only; it is the heart that hears."], "summary": "John Mark, Peter’s interpreter, and the gospel of the Servant — immediately. Mark (John Marcus), Barnabas’ nephew, likely the young man who fled naked, wrote from Peter’s testimony. A restored helper can still write Scripture’s shortest Gospel.", "quickReview": ["Mark (John Marcus), Barnabas’ nephew, likely the young man who fled naked, wrote from Peter’s testimony. A…", "Mark presents Jesus as Servant in a gospel of deeds. Key verse: Mark 10:45. Key word: immediately. No…", "The “Long Day” (Mark 3:12–5:43) is packed with about ten events. It shows Jesus’ humanity and weariness. He…", "During that long day He preached a sermon with eight parables. His family did not demonstrate total support…", "The day ends with two contrasting miracles: the woman with the issue of blood and Jairus’ daughter — a long…"], "glossary": [{"term": "Long Day", "meaning": "Mark 3:12–5:43"}, {"term": "The emphasis of Mark", "meaning": "Jesus the Servant, deeds over pedigree, immediately, Mark 10:45 as the spine. Preach a Christ who came not to be served but to serve, and to give His life as a…"}, {"term": "Ten events of the Long Day", "meaning": "A crushing sequence from confrontation to parables to storm to tombs to two healings. Use it to show both the press of need and the real humanity of Jesus."}, {"term": "The parables of Mark 4", "meaning": "Four soils, and the company of kingdom parables. Hearing is not automatic. Ask the congregation which soil they are this week."}], "outline": ["The emphasis of Mark", "Ten events of the Long Day", "The parables of Mark 4"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key word", "value": "immediately"}, {"label": "Key claim", "value": "Mark (John Marcus), Barnabas’ nephew, likely the young man who fled naked, wrote from Peter’s testimony. A restored helper can still write…"}, {"label": "Key claim", "value": "Mark presents Jesus as Servant in a gospel of deeds. Key verse: Mark 10:45. Key word: immediately. No genealogy, no birth narrative — a…"}, {"label": "Key claim", "value": "The “Long Day” (Mark 3:12–5:43) is packed with about ten events. It shows Jesus’ humanity and weariness. He is in control of Himself, not…"}], "pulpit": ["During that long day He preached a sermon with eight parables.", "Mark 4’s soils still preach: wayside, stony, thorns, good ground.", "Preach a Christ who came not to be served but to serve, and to give His life as a ransom."], "compare": null}, {"id": "nt-4", "number": 4, "title": "Luke", "topic": "The beloved physician, the Son of Man, parables, prayer, and the Savior of the overlooked.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["Luke, “the beloved physician” (Colossians 4:14), likely a Gentile, writes careful history to Theophilus. Key word: Son of Man. Key verse: Luke 19:10 — the Son of Man came to seek and to save the lost.", "Zacharias and Elizabeth were righteous and still carried the stigma of childlessness. Gabriel (not Michael) announced both John and Jesus. God sees the quiet shame in a good home.", "Luke has more parables than any other Gospel. A parable is an earthly story with a heavenly meaning: one interpretation, many applications. Do not turn every detail into an allegory.", "Each parable has its own lesson. Miracle is truth in action; parable is truth in story. Use both in the pulpit without confusing them.", "The disciples asked to be taught to pray. The Lord’s Prayer is a pattern, not a spell. Prayer in Luke is a school, not a performance.", "Luke loves the outsider, the poor, women, and the lost. If your preaching never sounds like that, you are not yet preaching Luke."], "quiz": [{"q": "Luke’s vocation was that he was a rabbi.", "answer": "False", "why": "He was a physician, not a rabbi. Colossians 4:14 still introduces him."}, {"q": "The key word (term) in Luke is “Son of Man.”", "answer": "True", "why": "The human nature of the God-Man is Luke’s open secret."}, {"q": "Elizabeth had a stigma because she was childless.", "answer": "True", "why": "Righteous and still carrying cultural shame. God writes John into that ache."}, {"q": "The angel Michael told Mary about the coming of Jesus.", "answer": "False", "why": "It was Gabriel. Keep the messengers straight."}, {"q": "There are more parables in Luke than in any other Gospel.", "answer": "True", "why": "Luke is a treasure chest for story-shaped preaching."}, {"q": "A parable is an earthly story with a heavenly meaning.", "answer": "True", "why": "Down-to-earth, aimed at heaven — that is the form."}, {"q": "Each parable has its own lesson.", "answer": "True", "why": "Do not mash them into one vague moral."}, {"q": "A parable has one interpretation, but many applications.", "answer": "True", "why": "One center, many landing places. That frees the preacher and guards the text."}, {"q": "Jesus’ disciples asked Him to teach them to pray.", "answer": "True", "why": "They did not ask first to preach. That should humble our seminaries and our Sundays."}, {"q": "The Lord’s Prayer is considered a model or pattern for praying.", "answer": "True", "why": "A pattern to enter, not a formula to mutter."}], "essays": [{"theme": "John’s birth in Luke", "summary": "Barren Elizabeth, doubting Zacharias, Gabriel’s word, muteness, and a boy set apart. God begins the Gospel in a priestly home that had stopped expecting."}, {"theme": "Towns on parables", "summary": "Earthly story, heavenly meaning; one interpretation, many applications; don’t over-allegorize. A parable is a servant of one main truth."}, {"theme": "The circumstances of Jesus’ birth", "summary": "Nazareth unlikely, census under Quirinius, manger, Simeon, growth in four areas (Luke 2:52), and the first recorded words at twelve. The Son of Man enters our mess without a palace."}], "bigIdeas": ["Luke, “the beloved physician” (Colossians 4:14), likely a Gentile, writes careful history to Theophilus. Key word: Son of Man. Key verse: Luke 19:10 — the Son of Man came to seek and to save the lost.", "Zacharias and Elizabeth were righteous and still carried the stigma of childlessness. Gabriel (not Michael) announced both John and Jesus. God sees the quiet shame in a good home.", "Luke has more parables than any other Gospel. A parable is an earthly story with a heavenly meaning: one interpretation, many applications. Do not turn every detail into an allegory.", "Each parable has its own lesson. Miracle is truth in action; parable is truth in story. Use both in the pulpit without confusing them.", "The disciples asked to be taught to pray. The Lord’s Prayer is a pattern, not a spell. Prayer in Luke is a school, not a performance.", "Luke loves the outsider, the poor, women, and the lost. If your preaching never sounds like that, you are not yet preaching Luke."], "summary": "The beloved physician, the Son of Man, parables, prayer, and the Savior of the overlooked. Luke, “the beloved physician” (Colossians 4:14), likely a Gentile, writes careful history to Theophilus. Key word: Son of Man. Key verse: Luke 19:10 — the Son of Man came to seek and to save the lost.", "quickReview": ["Luke, “the beloved physician” (Colossians 4:14), likely a Gentile, writes careful history to Theophilus. Key…", "Zacharias and Elizabeth were righteous and still carried the stigma of childlessness. Gabriel (not Michael)…", "Luke has more parables than any other Gospel. A parable is an earthly story with a heavenly meaning: one…", "Each parable has its own lesson. Miracle is truth in action; parable is truth in story. Use both in the…", "The disciples asked to be taught to pray. The Lord’s Prayer is a pattern, not a spell. Prayer in Luke is a…"], "glossary": [{"term": "The beloved physician", "meaning": "Colossians 4:14"}, {"term": "John’s birth in Luke", "meaning": "Barren Elizabeth, doubting Zacharias, Gabriel’s word, muteness, and a boy set apart. God begins the Gospel in a priestly home that had stopped expecting."}, {"term": "Towns on parables", "meaning": "Earthly story, heavenly meaning; one interpretation, many applications; don’t over-allegorize. A parable is a servant of one main truth."}, {"term": "The circumstances of Jesus’ birth", "meaning": "Nazareth unlikely, census under Quirinius, manger, Simeon, growth in four areas (Luke 2:52), and the first recorded words at twelve. The Son of Man enters our…"}, {"term": "Miracle", "meaning": "Miracle is truth in action; parable is truth in story"}, {"term": "Prayer", "meaning": "Prayer is a pattern, not a spell"}, {"term": "Luke", "meaning": "Luke is a school, not a performance"}], "outline": ["John’s birth in Luke", "Towns on parables", "The circumstances of Jesus’ birth"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key word", "value": "Son of Man"}, {"label": "Key claim", "value": "Luke, “the beloved physician” (Colossians 4:14), likely a Gentile, writes careful history to Theophilus. Key word: Son of Man. Key verse…"}, {"label": "Key claim", "value": "Zacharias and Elizabeth were righteous and still carried the stigma of childlessness. Gabriel (not Michael) announced both John and Jesus…"}, {"label": "Key claim", "value": "Luke has more parables than any other Gospel. A parable is an earthly story with a heavenly meaning: one interpretation, many applications…"}], "pulpit": ["Use both in the pulpit without confusing them.", "If your preaching never sounds like that, you are not yet preaching Luke."], "compare": null}, {"id": "nt-5", "number": 5, "title": "The Gospel According to John", "topic": "Holy of Holies of the four Gospels — believe, and live.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "takeaways": ["Philip Schaff called John the Holy of Holies of the four Gospels — the greatest of the four, the golden sunset of inspiration. Preach it with that reverence: this is not a fourth rerun of the same story; it is the inner room.", "The author is John son of Zebedee, the Beloved Disciple. Written late, about 90–100 AD, traditionally from Ephesus. The Rylands Fragment (about 135 AD) already carries this Gospel into the next generation — the book was traveling while the church was young.", "John 20:30–31 is the purpose sentence and a preaching commission: these signs are written so that you may believe Jesus is the Christ, the Son of God, and that by believing you may have life. The two key words are believe and life — not grace and faith as a pair.", "Seven I Ams (bread of life; light of the world; the door; the good shepherd; the resurrection and the life; the way, the truth, and the life; the true vine) and seven miracles plus one more in chapter 21. The number 7 signals completeness and perfection of Christ’s revelation — that is the pastoral takeaway, not a hunt for mysticism.", "About 90% of John is new beside the Synoptics. He omits genealogy, birth, temptation, transfiguration, parables, the ascension, and the Great Commission. He adds the prologue, Lazarus, Peter restored, and the Spirit discourses. Four portraits, one Lord — do not mash them into a blur.", "Jesus cleansed the Temple at the beginning and at the end of His public ministry. John 2:20 (“forty-six years this temple has been in building”) points toward about 26 AD for that first cleansing — history sitting inside the sign.", "Nicodemus must be born anothen — from above. “Water and the Spirit” is Hebrew parallelism: natural birth and spiritual birth, not baptismal regeneration. Do not preach John 3 as a requirement to get wet in order to be saved."], "quiz": [{"q": "According to Phillip Schaff, the church considers John the greatest of the four Gospels.", "answer": "True", "why": "Schaff called it the Holy of Holies, the golden sunset of inspiration."}, {"q": "John was known as the 'Beloved Disciple.'", "answer": "True", "why": "John son of Zebedee is the disciple Jesus loved. That is how the church has known him."}, {"q": "The two key words in John are 'grace' and 'faith.'", "answer": "False", "why": "The two key words are believe and life, not grace and faith."}, {"q": "John emphasizes the full deity of Jesus.", "answer": "True", "why": "From the prologue onward: the Word was God. John will not let you keep a merely human Jesus."}, {"q": "John's use of the number 7, suggests his strong commitment to Jewish mysticism.", "answer": "True", "why": "Moodle marks this True. Jay-R missed it (9/10). The workbook is ambiguous here; 7 also simply signals completeness and perfection of Christ’s revelation. Review the miss — do not treat mysticism as the pastoral takeaway."}, {"q": "Approximately 90% of John's material is supplemental to the Synoptics.", "answer": "True", "why": "Nearly all of John is new beside Matthew, Mark, and Luke. Read it as a complement, not a rerun."}, {"q": "All of John's recorded miracles are found in the other Gospels..", "answer": "False", "why": "Most of John’s signs are his own. Lazarus, Cana, and the rest are not a Synoptic reprint."}, {"q": "Tradition suggests that John's Gospel was penned in Ephesus.", "answer": "True", "why": "Tradition places the writing in Ephesus, late in the first century."}, {"q": "Jesus cleansed the Temple both at the beginning and the end of His public ministry.", "answer": "True", "why": "John opens with a cleansing; the Synoptics close with one. Two visits, one holy zeal."}, {"q": "To say that one must be born of water and the Spirit means that one must be baptized in order to be saved.", "answer": "False", "why": "Anothen means from above. Water and Spirit is Hebrew parallelism (natural vs spiritual birth), not baptismal regeneration."}], "essays": [{"theme": "The seven I Am statements", "summary": "I am the bread of life; the light of the world; the door; the good shepherd; the resurrection and the life; the way, the truth, and the life; the true vine. Each is a sermon in a sentence — hunger, darkness, belonging, care, death, lostness, fruitlessness — and Christ names Himself as the answer. Preach them as revelation, not as slogans."}, {"theme": "John beside the Synoptics", "summary": "About 90% of John is supplemental. He omits genealogy, birth, temptation, transfiguration, parables, the ascension, and the Great Commission. He adds the Word-made-flesh prologue, Lazarus raised, Peter restored, and the long Spirit discourses. Four portraits, one Lord — do not flatten them."}, {"theme": "Insights from Nicodemus", "summary": "Anothen means from above (and again). Water and Spirit is Hebrew parallelism: the birth that is of flesh and the birth that is of the Spirit, not a formula that baptism regenerates. Nicodemus comes at night with questions; Jesus answers with new birth. Preach the conversation, not a sacrament as the savior."}], "bigIdeas": ["Philip Schaff called John the Holy of Holies of the four Gospels — the greatest of the four, the golden sunset of inspiration. Preach it with that reverence: this is not a fourth rerun of the same story; it is the inner room.", "The author is John son of Zebedee, the Beloved Disciple. Written late, about 90–100 AD, traditionally from Ephesus. The Rylands Fragment (about 135 AD) already carries this Gospel into the next generation — the book was traveling while the church was young.", "John 20:30–31 is the purpose sentence and a preaching commission: these signs are written so that you may believe Jesus is the Christ, the Son of God, and that by believing you may have life. The two key words are believe and life — not grace and faith as a pair.", "Seven I Ams (bread of life; light of the world; the door; the good shepherd; the resurrection and the life; the way, the truth, and the life; the true vine) and seven miracles plus one more in chapter 21. The number 7 signals completeness and perfection of Christ’s revelation — that is the pastoral takeaway, not a hunt for mysticism.", "About 90% of John is new beside the Synoptics. He omits genealogy, birth, temptation, transfiguration, parables, the ascension, and the Great Commission. He adds the prologue, Lazarus, Peter restored, and the Spirit discourses. Four portraits, one Lord — do not mash them into a blur.", "Jesus cleansed the Temple at the beginning and at the end of His public ministry. John 2:20 (“forty-six years this temple has been in building”) points toward about 26 AD for that first cleansing — history sitting inside the sign.", "Nicodemus must be born anothen — from above. “Water and the Spirit” is Hebrew parallelism: natural birth and spiritual birth, not baptismal regeneration. Do not preach John 3 as a requirement to get wet in order to be saved."], "summary": "Holy of Holies of the four Gospels — believe, and live. Philip Schaff called John the Holy of Holies of the four Gospels — the greatest of the four, the golden sunset of inspiration. Preach it with that reverence: this is not a fourth rerun of the same story; it is the inner room.", "quickReview": ["Philip Schaff called John the Holy of Holies of the four Gospels — the greatest of the four, the golden…", "The author is John son of Zebedee, the Beloved Disciple. Written late, about 90–100 AD, traditionally from…", "John 20:30–31 is the purpose sentence and a preaching commission: these signs are written so that you may…", "Seven I Ams (bread of life; light of the world; the door; the good shepherd; the resurrection and the life…", "About 90% of John is new beside the Synoptics. He omits genealogy, birth, temptation, transfiguration…"], "glossary": [{"term": "Water and the Spirit", "meaning": "“Water and the Spirit” is Hebrew parallelism: natural birth and spiritual birth, not baptismal regeneration."}, {"term": "The seven I Am statements", "meaning": "I am the bread of life; the light of the world; the door; the good shepherd; the resurrection and the life; the way, the truth, and the life; the true vine…"}, {"term": "John beside the Synoptics", "meaning": "About 90% of John is supplemental. He omits genealogy, birth, temptation, transfiguration, parables, the ascension, and the Great Commission. He adds the…"}, {"term": "Insights from Nicodemus", "meaning": "Anothen means from above (and again). Water and Spirit is Hebrew parallelism: the birth that is of flesh and the birth that is of the Spirit, not a formula…"}, {"term": "John", "meaning": "John is new beside the Synoptics"}, {"term": "Regeneration", "meaning": "“Water and the Spirit” is Hebrew parallelism: natural birth and spiritual birth, not baptismal regeneration."}, {"term": "Inspiration", "meaning": "Philip Schaff called John the Holy of Holies of the four Gospels — the greatest of the four, the golden sunset of inspiration."}], "outline": ["The seven I Am statements", "John beside the Synoptics", "Insights from Nicodemus"], "mustKnow": [{"label": "Quiz score", "value": "90% (1 attempt)"}, {"label": "Author", "value": "John son of Zebedee, the Beloved Disciple"}, {"label": "Date", "value": "100 AD, traditionally from Ephesus"}, {"label": "Key word", "value": "s are believe and life — not grace and f"}, {"label": "Preach", "value": "Philip Schaff called John the Holy of Holies of the four Gospels — the greatest of the four, the golden sunset of inspiration. Preach it…"}, {"label": "Key claim", "value": "The author is John son of Zebedee, the Beloved Disciple. Written late, about 90–100 AD, traditionally from Ephesus. The Rylands Fragment…"}, {"label": "Preach", "value": "John 20:30–31 is the purpose sentence and a preaching commission: these signs are written so that you may believe Jesus is the Christ, the…"}], "compare": [{"title": "Clarify", "points": ["John 20:30–31 is the purpose sentence and a preaching commission: these signs are written so that you may believe Jesus…", "Not: grace and faith as a pair."]}], "pulpit": ["Preach it with that reverence: this is not a fourth rerun of the same story; it is the inner room.", "John 20:30–31 is the purpose sentence and a preaching commission: these signs are written so that you may believe Jesus is the Christ, the Son of God, and that…", "The number 7 signals completeness and perfection of Christ’s revelation — that is the pastoral takeaway, not a hunt for mysticism.", "Do not preach John 3 as a requirement to get wet in order to be saved."]}, {"id": "nt-6", "number": 6, "title": "The Acts of the Apostles", "topic": "The ascended Christ, the Spirit, and the church on mission to Rome.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["Acts can be titled as the work of the ascended, glorified Christ — the story of the early church to about 63 AD, and just as truly the Acts of the Holy Spirit. The Lord who went up is still at work.", "Luke the beloved physician wrote Acts, not Mark. The “we” sections cover about a third of the book and match the voice of Luke’s Gospel — careful history from a companion on the road.", "Six purposes sit in this volume: fulfill the Great Commission; vindicate Paul’s writings and ministry; trace the gospel’s geography to Rome; show fair treatment by civil authorities; record Jewish opposition and rejection; and display the presence of the Holy Spirit.", "Forty days after the resurrection, Jesus ascended. About 120 waited in the upper room. Ten days later came Pentecost. When lots were cast for Judas’s place, the apostles chose Matthias — not Paul.", "Pentecost tongues were known languages, not unknown speech. Wind, fire, and tongues preach the Spirit’s arrival. The church grows 120 to 3,000 to 5,000 even as persecution escalates. Acts 4:12 still stands: there is no other name for salvation.", "The risen Lord appeared many times after Easter. Those first-day appearances help explain why the church gathers on the Lord’s Day — Sunday is resurrection day, not a leftover Sabbath.", "The map of Acts runs toward Rome. The gospel is not a Jerusalem secret; it travels, suffers, and lands in the capital because Christ is Lord of all."], "quiz": [{"q": "Acts can be described as the account of the work of the ascended, glorified Christ.", "answer": "True", "why": "This book is not merely church history; it is the ascended Lord still working through His people."}, {"q": "The human author of Acts was Mark.", "answer": "False", "why": "Luke the beloved physician wrote Acts. Mark is another Gospel, not this volume."}, {"q": "One purpose of Acts was to fulfill the Great Commission.", "answer": "True", "why": "Luke shows the Commission actually going out — from Jerusalem toward the nations."}, {"q": "Another purpose of Acts was to vindicate the writings and ministry of Paul.", "answer": "True", "why": "Acts stands beside the letters so Paul’s ministry is not a rumor but a record."}, {"q": "The time between Jesus' resurrection and ascension was 10 days.", "answer": "False", "why": "Forty days, not ten. The ten days are from the ascension to Pentecost."}, {"q": "The promise of the angels at the ascension of Christ was that He would visibly and physically come again.", "answer": "True", "why": "The same Jesus who went up will come again — visible and physical, not a mere idea."}, {"q": "Approximately 20 people prayed in the upper room waiting for Pentecost to come.", "answer": "False", "why": "About 120 waited and prayed, not twenty. The church begins as a room, not a crowd of twenty."}, {"q": "When the lots were cast in order to select Judas Iscariot's replacement, the Apostles selected Paul.", "answer": "False", "why": "The lot fell to Matthias. Paul is called later, on the Damascus road — not by lot."}, {"q": "The 'tongues phenomenon' described on Pentecost was an unknown language.", "answer": "False", "why": "Pentecost tongues were known languages the nations could hear, not unknown speech."}, {"q": "According to Acts, there are many ways to get to Heaven.", "answer": "False", "why": "Acts 4:12: there is no other name under heaven given among men by which we must be saved."}], "essays": [{"theme": "Eye-witness post-resurrection appearances", "summary": "The risen Lord appeared many times after Easter. Those first-day appearances help explain the Lord’s Day — the church gathers on Sunday because that is resurrection day, not a leftover Sabbath."}, {"theme": "Six purposes of Acts", "summary": "Fulfill the Great Commission; vindicate Paul’s writings and ministry; trace geographical development to Rome; record fair treatment by civil authorities; show Jewish opposition and rejection; and display the presence of the Holy Spirit."}, {"theme": "Authorship of Acts", "summary": "Luke the beloved physician wrote Acts, not Mark. The we-sections (about a third of the book) match Luke’s Gospel — a companion’s careful history, not another hand."}], "bigIdeas": ["Acts can be titled as the work of the ascended, glorified Christ — the story of the early church to about 63 AD, and just as truly the Acts of the Holy Spirit. The Lord who went up is still at work.", "Luke the beloved physician wrote Acts, not Mark. The “we” sections cover about a third of the book and match the voice of Luke’s Gospel — careful history from a companion on the road.", "Six purposes sit in this volume: fulfill the Great Commission; vindicate Paul’s writings and ministry; trace the gospel’s geography to Rome; show fair treatment by civil authorities; record Jewish opposition and rejection; and display the presence of the Holy Spirit.", "Forty days after the resurrection, Jesus ascended. About 120 waited in the upper room. Ten days later came Pentecost. When lots were cast for Judas’s place, the apostles chose Matthias — not Paul.", "Pentecost tongues were known languages, not unknown speech. Wind, fire, and tongues preach the Spirit’s arrival. The church grows 120 to 3,000 to 5,000 even as persecution escalates. Acts 4:12 still stands: there is no other name for salvation.", "The risen Lord appeared many times after Easter. Those first-day appearances help explain why the church gathers on the Lord’s Day — Sunday is resurrection day, not a leftover Sabbath.", "The map of Acts runs toward Rome. The gospel is not a Jerusalem secret; it travels, suffers, and lands in the capital because Christ is Lord of all."], "summary": "The ascended Christ, the Spirit, and the church on mission to Rome. Acts can be titled as the work of the ascended, glorified Christ — the story of the early church to about 63 AD, and just as truly the Acts of the Holy Spirit. The Lord who went up is still at work.", "quickReview": ["Acts can be titled as the work of the ascended, glorified Christ — the story of the early church to about 63…", "Luke the beloved physician wrote Acts, not Mark. The “we” sections cover about a third of the book and match…", "Six purposes sit in this volume: fulfill the Great Commission; vindicate Paul’s writings and ministry; trace…", "Forty days after the resurrection, Jesus ascended. About 120 waited in the upper room. Ten days later came…", "Pentecost tongues were known languages, not unknown speech. Wind, fire, and tongues preach the Spirit’s…"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Date", "value": "63 AD, and just as truly the Acts o"}, {"label": "Key claim", "value": "Acts can be titled as the work of the ascended, glorified Christ — the story of the early church to about 63 AD, and just as truly the Acts…"}, {"label": "Key claim", "value": "Luke the beloved physician wrote Acts, not Mark. The “we” sections cover about a third of the book and match the voice of Luke’s Gospel —…"}, {"label": "Reject", "value": "Six purposes sit in this volume: fulfill the Great Commission; vindicate Paul’s writings and ministry; trace the gospel’s geography to…"}], "glossary": [{"term": "Eye-witness post-resurrection appearances", "meaning": "The risen Lord appeared many times after Easter. Those first-day appearances help explain the Lord’s Day — the church gathers on Sunday because that is…"}, {"term": "Six purposes of Acts", "meaning": "Fulfill the Great Commission; vindicate Paul’s writings and ministry; trace geographical development to Rome; record fair treatment by civil authorities; show…"}, {"term": "Authorship of Acts", "meaning": "Luke the beloved physician wrote Acts, not Mark. The we-sections (about a third of the book) match Luke’s Gospel — a companion’s careful history, not another…"}, {"term": "Sunday", "meaning": "Sunday is resurrection day, not a leftover Sabbath"}], "outline": ["Eye-witness post-resurrection appearances", "Six purposes of Acts", "Authorship of Acts"], "compare": [{"title": "Six purposes sit in this volume", "points": ["fulfill the Great Commission; vindicate Paul’s writings", "ministry; trace the gospel’s geography to Rome; show fair treatment by civil authorities; record Jewish opposition", "rejection;", "display the presence of the Holy Spirit"]}, {"title": "Clarify", "points": ["Forty days after the resurrection, Jesus ascended. About 120 waited in the upper room. Ten days later came Pentecost…", "Not: Paul."]}], "pulpit": ["Wind, fire, and tongues preach the Spirit’s arrival.", "Acts can be titled as the work of the ascended, glorified Christ — the story of the early church to about 63 AD, and just as…", "Luke the beloved physician wrote Acts, not Mark. The “we” sections cover about a third of the book and match the voice of Luke’s…"]}], "courseTotal": 99, "quizzesTotal": 98}, {"id": "ot-survey-2", "code": 54, "title": "Old Testament Survey 2", "status": "complete", "certificateUnlocked": true, "courseTotal": 99, "blurb": "From the divided kingdom through the return — Lessons 7–12 complete. Certificate unlocked. Course total 99%.", "lessons": [{"id": "ot2-7", "number": 7, "title": "The Division of the Kingdom", "topic": "931 BC to the return — the split, the sin of Jeroboam, and hope after exile.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["The kingdom splits in 931 BC. Ahijah’s word names Jeroboam over ten tribes; Rehoboam takes the young men’s tax advice at Shechem; Shemaiah stops a civil war. God can tear a throne in a single assembly.", "Jeroboam’s “pastoral” solution is calves at Bethel and Dan, a homemade feast, and priests who are not Levites. That counterfeit worship is called the sin of Jeroboam — and it lasts until Samaria falls in 722 BC.", "Judah is not innocent. Rehoboam leads apostasy; Shishak of Egypt strips the temple. A southern address does not make a faithful king.", "Asa tastes revival, then fails. A good start is not the same as a guarded heart. Preach the whole reign, not the highlight reel.", "The north runs Nadab, Baasha, Elah, Zimri, Omri (who builds Samaria), then Ahab and Jezebel — with Elijah standing in the way. Thrones change; the calves stay.", "Captivity has four reasons. Assyria and Babylon are the rod; the Lord is the One who swung it. Judgment is covenant love that will not share a people with other gods.", "Hope after the night: Cyrus sends them home; Zerubbabel raises the Second Temple by 515 BC. After restoration they cling to Torah, gather in synagogue, and (at last) put away the idols."], "quiz": [{"q": "Jeroboam was humanly responsible for splitting the Kingdom.", "answer": "True", "why": "Ahijah named him, and Rehoboam’s folly at Shechem opened the door — Jeroboam took the ten tribes. God split it; a man still bears the human share."}, {"q": "Ahab and Jezebel were known as two of Israel's godliest leaders.", "answer": "False", "why": "They are the opposite — Baal, Naboth’s vineyard, and a throne that hunted prophets. Elijah stands against them, not with them."}, {"q": "Rehoboam was a great leader of revival.", "answer": "False", "why": "Revival is Asa’s word, not Rehoboam’s. He took the young men’s tax advice, then led Judah into apostasy until Shishak came."}, {"q": "Jehoshaphat was known for his wise choice of allies.", "answer": "False", "why": "He is remembered for joining himself to Ahab. Unequal alliance is not wisdom; it nearly cost him the kingdom."}, {"q": "Uzziah's reign was one of the briefest in Judah's history.", "answer": "False", "why": "Uzziah (Azariah) reigned fifty-two years — one of the longest, not the briefest. Pride in the temple is the warning, not a short calendar."}, {"q": "Josiah was known for his rampant immorality.", "answer": "False", "why": "Josiah is the boy-king of the book — he tore down the high places. Immorality is not his headline; repentance is."}, {"q": "Daniel lived most of his life in Babylon.", "answer": "True", "why": "Taken young, he stayed through empires. Faithfulness is not always a ticket home; sometimes it is a long obedience in a foreign court."}, {"q": "The captives returned to Jerusalem during the reign of Persia's King Cyrus.", "answer": "True", "why": "Isaiah named him; Ezra records the decree. The Lord stirs a pagan king so a remnant can go home."}, {"q": "The builder of the Second Temple was Zerubbabel.", "answer": "True", "why": "Zerubbabel laid the house that stood until Herod and until Christ walked its courts — finished about 515 BC."}, {"q": "Ahab's closest advisor was Elijah.", "answer": "False", "why": "Elijah was Ahab’s antagonist, not his counselor. Jezebel is the voice in that palace; the prophet is the voice against it."}], "essays": [{"theme": "Four reasons for Captivity", "summary": "The exile is not an accident of empire. This lesson names four reasons the people went into captivity: they would not quit idolatry (the calves and the Baals); they would not keep the covenant word; they would not hear the prophets God sent; and they would not give the land its Sabbath rest. Assyria and Babylon are the rod — the Lord is the One who swung it. Preach captivity as holy love that will not let a people keep two gods."}, {"theme": "Jeroboam's apostasy", "summary": "Fear dressed as policy: if they go up to Jerusalem, they may return to Rehoboam. So Jeroboam sets calves at Bethel and Dan, invents a feast, and ordains priests who are not Levites. Convenient worship is still rebellion. Kings keep changing; this sin keeps its name until Samaria falls in 722 BC. A church can copy it — a more local god, a more flexible calendar, and leaders we chose ourselves."}, {"theme": "Israel after Restoration", "summary": "Cyrus sends them home. Zerubbabel raises the Second Temple by 515 BC. After the return they cling to Torah, gather in synagogue, and — at last — put away the idols that had cost them the land. Exile taught what sermons had not. Hope is not a new empire; it is a remnant, a book, and a house of prayer until Messiah comes."}], "bigIdeas": ["The kingdom splits in 931 BC. Ahijah’s word names Jeroboam over ten tribes; Rehoboam takes the young men’s tax advice at Shechem; Shemaiah stops a civil war. God can tear a throne in a single assembly.", "Jeroboam’s “pastoral” solution is calves at Bethel and Dan, a homemade feast, and priests who are not Levites. That counterfeit worship is called the sin of Jeroboam — and it lasts until Samaria falls in 722 BC.", "Judah is not innocent. Rehoboam leads apostasy; Shishak of Egypt strips the temple. A southern address does not make a faithful king.", "Asa tastes revival, then fails. A good start is not the same as a guarded heart. Preach the whole reign, not the highlight reel.", "The north runs Nadab, Baasha, Elah, Zimri, Omri (who builds Samaria), then Ahab and Jezebel — with Elijah standing in the way. Thrones change; the calves stay.", "Captivity has four reasons. Assyria and Babylon are the rod; the Lord is the One who swung it. Judgment is covenant love that will not share a people with other gods.", "Hope after the night: Cyrus sends them home; Zerubbabel raises the Second Temple by 515 BC. After restoration they cling to Torah, gather in synagogue, and (at last) put away the idols."], "summary": "931 BC to the return — the split, the sin of Jeroboam, and hope after exile. The kingdom splits in 931 BC. Ahijah’s word names Jeroboam over ten tribes; Rehoboam takes the young men’s tax advice at Shechem; Shemaiah stops a civil war. God can tear a throne in a single assembly.", "quickReview": ["The kingdom splits in 931 BC. Ahijah’s word names Jeroboam over ten tribes; Rehoboam takes the young men’s…", "Jeroboam’s “pastoral” solution is calves at Bethel and Dan, a homemade feast, and priests who are not…", "Judah is not innocent. Rehoboam leads apostasy; Shishak of Egypt strips the temple. A southern address does…", "Asa tastes revival, then fails. A good start is not the same as a guarded heart. Preach the whole reign, not…", "The north runs Nadab, Baasha, Elah, Zimri, Omri (who builds Samaria), then Ahab and Jezebel — with Elijah…"], "glossary": [{"term": "Pastoral", "meaning": "Jeroboam’s “pastoral” solution is calves at Bethel and Dan, a homemade feast, and priests who are not Levites."}, {"term": "Four reasons for Captivity", "meaning": "The exile is not an accident of empire. This lesson names four reasons the people went into captivity: they would not quit idolatry (the calves and the Baals)…"}, {"term": "Jeroboam's apostasy", "meaning": "Fear dressed as policy: if they go up to Jerusalem, they may return to Rehoboam. So Jeroboam sets calves at Bethel and Dan, invents a feast, and ordains…"}, {"term": "Israel after Restoration", "meaning": "Cyrus sends them home. Zerubbabel raises the Second Temple by 515 BC. After the return they cling to Torah, gather in synagogue, and — at last — put away the…"}, {"term": "Judah", "meaning": "Judah is not innocent"}, {"term": "Babylon", "meaning": "Babylon is the rod; the Lord is the One who swung it"}, {"term": "Judgment", "meaning": "Judgment is covenant love that will not share a people with other gods"}, {"term": "Covenant", "meaning": "Judgment is covenant love that will not share a people with other gods."}], "outline": ["Four reasons for Captivity", "Jeroboam's apostasy", "Israel after Restoration"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Date", "value": "931 BC"}, {"label": "Key claim", "value": "The kingdom splits in 931 BC. Ahijah’s word names Jeroboam over ten tribes; Rehoboam takes the young men’s tax advice at Shechem; Shemaiah…"}, {"label": "Key claim", "value": "Jeroboam’s “pastoral” solution is calves at Bethel and Dan, a homemade feast, and priests who are not Levites. That counterfeit worship is…"}, {"label": "Key claim", "value": "Judah is not innocent. Rehoboam leads apostasy; Shishak of Egypt strips the temple. A southern address does not make a faithful king."}], "pulpit": ["Jeroboam’s “pastoral” solution is calves at Bethel and Dan, a homemade feast, and priests who are not Levites.", "Preach the whole reign, not the highlight reel.", "Preach captivity as holy love that will not let a people keep two gods.", "Exile taught what sermons had not."], "compare": null}, {"id": "ot2-8", "number": 8, "title": "The Prophets: Elijah, Elisha and Isaiah", "topic": "forth-tell and foretell — Carmel to the virgin birth promise.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["The prophets are the last section of the Old Testament. After law and history, God still has a voice — not a sideshow, but the Lord preaching to a people who already have a temple.", "Forth-tell and foretell: the prophet speaks for God. Most of the work is preaching — calling kings and people back — not a calendar of tomorrow. Foretelling is real; it is not the main diet.", "True-prophet marks sit in Deuteronomy 18 and 13: the word comes to pass, and it never leads you after other gods. A sign that sells idolatry is still a lie. Test the fruit, not the fireworks.", "Elijah on Carmel: fire falls, Baal is silent, and the people cry that the Lord is God. Then the prophet runs, sits under a broom tree, and asks to die. Victory does not vaccinate a servant against discouragement.", "Jezebel threatened him; she did not kill him. Elijah is translated — chariots, not a queen’s sword. Seven miracles mark his ministry, including raising the dead. God finishes a prophet’s story on His own terms.", "Elisha asked for a double portion and saw fourteen miracles — twice Elijah’s seven. The mantle is not a souvenir; it is a call to more of the same God.", "Isaiah is the prince of prophets. Chapter 6 is the call — holy, holy, holy, and a coal on the lips. Hold the book as one; and 7:14 already names the virgin birth of Jesus."], "quiz": [{"q": "The study of the Prophets constitutes the last section of the Old Testament.", "answer": "True", "why": "Law, history, then the prophets — this is the last sweep of the Old Testament. The office still speaks after the kings have their say."}, {"q": "Most of the prophets in the Bible are focused on foretelling the future.", "answer": "False", "why": "Forth-telling is the main work: preaching God’s word to the people in front of them. Foretelling is real, but it is not most of the diet."}, {"q": "Ahab's great adversary was Elisha the prophet.", "answer": "False", "why": "Ahab’s great adversary is Elijah — Carmel, the drought, Naboth’s vineyard. Elisha wears the mantle after him."}, {"q": "Elijah was known as the prophet who had raised the dead.", "answer": "True", "why": "The widow’s son at Zarephath lives again. Among Elijah’s seven miracles, raising the dead is not a rumor."}, {"q": "Baal was known as the sun god and fertility god.", "answer": "True", "why": "That is the rival on Carmel — sun and fertility, fire and rain promised, and not a spark when the true God answers."}, {"q": "Elijah suffered from discouragement.", "answer": "True", "why": "After Carmel he runs from Jezebel, sits under a broom tree, and asks to die. A prophet can be faithful and still be spent."}, {"q": "Elijah suffered a cruel and untimely death at the hand of Jezebel.", "answer": "False", "why": "Jezebel threatened him; she did not kill him. Elijah is translated — taken up, not cut down."}, {"q": "Elisha saw twice the number of miracles that Elijah did.", "answer": "True", "why": "Elijah seven; Elisha fourteen — the double portion he asked for when the mantle fell."}, {"q": "Isaiah is called the prince of prophets.", "answer": "True", "why": "That is his title in this survey: the prince of prophets, called in chapter 6, still preaching Christ."}, {"q": "Isaiah foretold the virgin birth of Jesus Christ.", "answer": "True", "why": "Isaiah 7:14 — Immanuel, born of a virgin. The gospel does not invent that promise; it names the Child."}], "essays": [{"theme": "Office, methods, and marks of a prophet", "summary": "The prophetic office is the last section of the Old Testament: God still has a voice after law and kings. Methods are forth-telling and foretelling — speaking for God, and sometimes speaking of what is yet to come. Most of the work is preaching, not a calendar of tomorrow. Marks of a true prophet sit in Deuteronomy 18 and 13: the word comes to pass, and it never leads the people after other gods. A sign that sells idolatry is still a lie. For the pulpit: test the fruit, not the fireworks, and keep the office as a preacher’s call before it is a seer’s."}, {"theme": "Elijah's discouragement resolved", "summary": "Carmel is fire, rain, and a nation crying that the Lord is God — then Jezebel’s threat, a broom tree, and a prophet who asks to die. Discouragement is not unbelief in this story; it is a spent servant after a public victory. God meets him: food, sleep, a still small voice, and a reminder that he is not the only one left. Jezebel does not get the last word; Elijah is translated, not murdered. Preach this to pastors who won on Sunday and cannot get out of bed on Monday — the Lord still knows how to find a prophet in the wilderness."}, {"theme": "Unity of Isaiah authorship", "summary": "This course holds Isaiah as one book and one prophet — the prince of prophets, called in chapter 6 with a coal on his lips. Critics split him into two or three voices because the later chapters see exile and return; the church does not have to. The same holy God who sends the seraphim can name Cyrus and the virgin-born Immanuel (7:14) before either arrives. For sermon and review: do not farm the book out to anonymous disciples. Let Isaiah preach Christ from one mouth."}], "bigIdeas": ["The prophets are the last section of the Old Testament. After law and history, God still has a voice — not a sideshow, but the Lord preaching to a people who already have a temple.", "Forth-tell and foretell: the prophet speaks for God. Most of the work is preaching — calling kings and people back — not a calendar of tomorrow. Foretelling is real; it is not the main diet.", "True-prophet marks sit in Deuteronomy 18 and 13: the word comes to pass, and it never leads you after other gods. A sign that sells idolatry is still a lie. Test the fruit, not the fireworks.", "Elijah on Carmel: fire falls, Baal is silent, and the people cry that the Lord is God. Then the prophet runs, sits under a broom tree, and asks to die. Victory does not vaccinate a servant against discouragement.", "Jezebel threatened him; she did not kill him. Elijah is translated — chariots, not a queen’s sword. Seven miracles mark his ministry, including raising the dead. God finishes a prophet’s story on His own terms.", "Elisha asked for a double portion and saw fourteen miracles — twice Elijah’s seven. The mantle is not a souvenir; it is a call to more of the same God.", "Isaiah is the prince of prophets. Chapter 6 is the call — holy, holy, holy, and a coal on the lips. Hold the book as one; and 7:14 already names the virgin birth of Jesus."], "summary": "forth-tell and foretell — Carmel to the virgin birth promise. The prophets are the last section of the Old Testament. After law and history, God still has a voice — not a sideshow, but the Lord preaching to a people who already have a temple.", "quickReview": ["The prophets are the last section of the Old Testament. After law and history, God still has a voice — not a…", "Forth-tell and foretell: the prophet speaks for God. Most of the work is preaching — calling kings and people…", "True-prophet marks sit in Deuteronomy 18 and 13: the word comes to pass, and it never leads you after other…", "Elijah on Carmel: fire falls, Baal is silent, and the people cry that the Lord is God. Then the prophet runs…", "Jezebel threatened him; she did not kill him. Elijah is translated — chariots, not a queen’s sword. Seven…"], "glossary": [{"term": "Office, methods, and marks of a prophet", "meaning": "The prophetic office is the last section of the Old Testament: God still has a voice after law and kings. Methods are forth-telling and foretelling — speaking…"}, {"term": "Elijah's discouragement resolved", "meaning": "Carmel is fire, rain, and a nation crying that the Lord is God — then Jezebel’s threat, a broom tree, and a prophet who asks to die. Discouragement is not…"}, {"term": "Unity of Isaiah authorship", "meaning": "This course holds Isaiah as one book and one prophet — the prince of prophets, called in chapter 6 with a coal on his lips. Critics split him into two or three…"}, {"term": "Foretelling", "meaning": "Foretelling is real; it is not the main diet"}, {"term": "Baal", "meaning": "Baal is silent, and the people cry that the Lord is God"}, {"term": "Elijah", "meaning": "Elijah is translated — chariots, not a queen’s sword"}, {"term": "Isaiah", "meaning": "Isaiah is the prince of prophets"}], "outline": ["Office, methods, and marks of a prophet", "Elijah's discouragement resolved", "Unity of Isaiah authorship"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Preach", "value": "The prophets are the last section of the Old Testament. After law and history, God still has a voice — not a sideshow, but the Lord…"}, {"label": "Preach", "value": "Forth-tell and foretell: the prophet speaks for God. Most of the work is preaching — calling kings and people back — not a calendar of…"}, {"label": "Key claim", "value": "True-prophet marks sit in Deuteronomy 18 and 13: the word comes to pass, and it never leads you after other gods. A sign that sells…"}], "compare": [{"title": "Clarify", "points": ["The prophets are the last section of the Old Testament. After law and history, God still has a voice", "Not: a sideshow, but the Lord preaching to a people who already have a temple."]}], "pulpit": ["After law and history, God still has a voice — not a sideshow, but the Lord preaching to a people who already have a temple.", "Most of the work is preaching — calling kings and people back — not a calendar of tomorrow.", "Most of the work is preaching, not a calendar of tomorrow.", "For the pulpit: test the fruit, not the fireworks, and keep the office as a preacher’s call before it is a seer’s."]}, {"id": "ot2-9", "number": 9, "title": "Minor Prophets", "topic": "The Twelve — decline, hope, and the Redeemer.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["The Twelve belong together. God raised these prophets in days of decline and apostasy — not a golden age. When the nation is sliding, the Lord still sends a voice.", "Five-fold emphases mark the books: the word is local, it addresses Israel, it names the Gentiles (often as tools of chastisement), it is predictive near and far, and it points to a promised Redeemer.", "Jonah is the Lord’s sovereignty and a universal offer of salvation. Gentiles are not outside His mercy — the same God who uses the nations as a rod also calls them to live.", "Amos is not a sophisticated businessman; he is a herdsman of Tekoa. Hosea and Gomer are not an ideal marriage. God picks the man, and sometimes the prophet’s home is the sermon.", "Joel preaches the Day of the Lord and the outpouring of the Spirit. He and Elisha were contemporaries — the later writing prophets stand in the same stream as the earlier voices.", "Micah 5:2 names Bethlehem as the Messiah’s birthplace. Keep that text close: the Savior’s town is not a Christmas decoration; it is predictive prophecy of the Redeemer.", "Nahum explains God’s judgment on Nineveh, Assyria. Habakkuk 2:4 still stands. Zephaniah is of Hezekiah’s line — great-great grandson. Judgment and hope sit in one family tree."], "quiz": [{"q": "The Minor Prophets were raised up during times of decline and apostasy.", "answer": "True", "why": "The Twelve are not a golden-age choir. God raises them when the nation is sliding — decline and apostasy are the soil, not the exception."}, {"q": "In the Minor Prophets, the Gentiles were often identified as tools of chastisement against Israel.", "answer": "True", "why": "Assyria, Babylon, and the nations around them are the rod. The Lord uses Gentiles to chasten His people — and still has a word for those nations too."}, {"q": "Predictive prophecy relates to a promised redeemer.", "answer": "True", "why": "Near and far, the predictive word is not a parlor trick. It relates to a promised Redeemer — hope with a name, not only a calendar."}, {"q": "In Jonah, we find a universal offer of salvation.", "answer": "True", "why": "Nineveh hears and lives. Jonah is sovereignty plus a wide door: salvation is not Israel’s private stock."}, {"q": "Amos was known as a sophisticated businessman.", "answer": "False", "why": "Amos is a herdsman of Tekoa. God picks the man; the résumé does not have to look like the palace."}, {"q": "Hosea and Gomer were known as a couple with an ideal marriage.", "answer": "False", "why": "The marriage is the sermon, not the postcard. Unfaithful Gomer, faithful Hosea — a living picture of Israel and the Lord."}, {"q": "Joel and Elisha were contemporaries.", "answer": "True", "why": "The pack sets them in the same stretch of history. Joel’s Day of the Lord sits beside the earlier prophetic stream, not after it."}, {"q": "Micah's prophetic book predicts the birthplace of the Savior (Messiah).", "answer": "True", "why": "Micah 5:2 — Bethlehem. The Messiah’s town is named in the Twelve; Advent does not invent it."}, {"q": "Nahum was written to explain God's judgment on Ninevah, Assyria.", "answer": "True", "why": "That is the book’s burden: Nineveh (Ninevah in the quiz) under the Lord’s sentence. Assyria is not too big for judgment."}, {"q": "Zephaniah was the great-great grandson of Hezekiah.", "answer": "True", "why": "He stands in Hezekiah’s line — great-great grandson. Royal blood does not cancel a prophet’s call to preach judgment and hope."}], "essays": [{"theme": "Five-fold emphases of the Minor Prophets", "summary": "The Twelve preach with five emphases, not twelve unrelated hobbies. First, the word is local — it lands on the people standing in front of the prophet. Second, it addresses Israel: covenant people under a covenant God. Third, it names the Gentiles, often as tools of chastisement against Israel, and sometimes as hearers of mercy. Fourth, it is predictive, near and far — what is at the gate, and what is still over the horizon. Fifth, it relates to a promised Redeemer. For the pulpit: do not reduce the Minor Prophets to weather reports. Preach the local word, the nation’s sin, the nations as rod and audience, the near and far horizon, and Christ."}, {"theme": "Major movements in Jonah", "summary": "Jonah’s major movements are the Lord’s, not the fish’s. The prophet is sent; he runs; the Sovereign still has him. Then the word is preached, and a Gentile city lives — a universal offer of salvation in the mouth of a reluctant Israelite. The last movement is the argument over mercy: Jonah wants Nineveh judged; God has compassion and the last word. Sovereignty and a wide door sit in one short book. Preach it that way: the Lord overrules the flight, offers life to the nations, and will not let His servant shrink the gospel to one people."}, {"theme": "Who Micah was / most important message (Bethlehem / Messiah)", "summary": "Micah is one of The Twelve, raised in the same decline as the rest. His most important message is not a catalog of woes; it is the birthplace of the Savior. Micah 5:2 names Bethlehem as the Messiah’s town — predictive prophecy of the Redeemer, near enough to locate and far enough to wait. When you preach Advent or the incarnation, start here: the Minor Prophets already knew the village. Hope has an address. Hold Micah as a preacher of judgment who still points to the Child."}], "bigIdeas": ["The Twelve belong together. God raised these prophets in days of decline and apostasy — not a golden age. When the nation is sliding, the Lord still sends a voice.", "Five-fold emphases mark the books: the word is local, it addresses Israel, it names the Gentiles (often as tools of chastisement), it is predictive near and far, and it points to a promised Redeemer.", "Jonah is the Lord’s sovereignty and a universal offer of salvation. Gentiles are not outside His mercy — the same God who uses the nations as a rod also calls them to live.", "Amos is not a sophisticated businessman; he is a herdsman of Tekoa. Hosea and Gomer are not an ideal marriage. God picks the man, and sometimes the prophet’s home is the sermon.", "Joel preaches the Day of the Lord and the outpouring of the Spirit. He and Elisha were contemporaries — the later writing prophets stand in the same stream as the earlier voices.", "Micah 5:2 names Bethlehem as the Messiah’s birthplace. Keep that text close: the Savior’s town is not a Christmas decoration; it is predictive prophecy of the Redeemer.", "Nahum explains God’s judgment on Nineveh, Assyria. Habakkuk 2:4 still stands. Zephaniah is of Hezekiah’s line — great-great grandson. Judgment and hope sit in one family tree."], "summary": "The Twelve — decline, hope, and the Redeemer. The Twelve belong together. God raised these prophets in days of decline and apostasy — not a golden age. When the nation is sliding, the Lord still sends a voice.", "quickReview": ["The Twelve belong together. God raised these prophets in days of decline and apostasy — not a golden age…", "Five-fold emphases mark the books: the word is local, it addresses Israel, it names the Gentiles (often as…", "Jonah is the Lord’s sovereignty and a universal offer of salvation. Gentiles are not outside His mercy — the…", "Amos is not a sophisticated businessman; he is a herdsman of Tekoa. Hosea and Gomer are not an ideal…", "Joel preaches the Day of the Lord and the outpouring of the Spirit. He and Elisha were contemporaries — the…"], "glossary": [{"term": "Five-fold emphases of the Minor Prophets", "meaning": "The Twelve preach with five emphases, not twelve unrelated hobbies. First, the word is local — it lands on the people standing in front of the prophet. Second…"}, {"term": "Major movements in Jonah", "meaning": "Jonah’s major movements are the Lord’s, not the fish’s. The prophet is sent; he runs; the Sovereign still has him. Then the word is preached, and a Gentile…"}, {"term": "Who Micah was / most important message (Bethlehem / Mes", "meaning": "Micah is one of The Twelve, raised in the same decline as the rest. His most important message is not a catalog of woes; it is the birthplace of the Savior…"}, {"term": "Jonah", "meaning": "Jonah is the Lord’s sovereignty and a universal offer of salvation"}, {"term": "Gentiles", "meaning": "Gentiles is not outside His mercy — the same God who uses the nations as a rod also calls them to live"}, {"term": "Amos", "meaning": "Amos is not a sophisticated businessman; he is a herdsman of Tekoa"}, {"term": "Gomer", "meaning": "Gomer is not an ideal marriage"}, {"term": "Zephaniah", "meaning": "Zephaniah is of Hezekiah’s line — great-great grandson"}], "outline": ["Five-fold emphases of the Minor Prophets", "Major movements in Jonah", "Who Micah was / most important message (Bethlehem / Messiah)"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "The Twelve belong together. God raised these prophets in days of decline and apostasy — not a golden age. When the nation is sliding, the…"}, {"label": "Key claim", "value": "Five-fold emphases mark the books: the word is local, it addresses Israel, it names the Gentiles (often as tools of chastisement), it is…"}, {"label": "Key claim", "value": "Jonah is the Lord’s sovereignty and a universal offer of salvation. Gentiles are not outside His mercy — the same God who uses the nations…"}], "compare": [{"title": "Clarify", "points": ["The Twelve belong together. God raised these prophets in days of decline and apostasy", "Not: a golden age. When the nation is sliding, the Lord still sends a voice."]}], "pulpit": ["God picks the man, and sometimes the prophet’s home is the sermon.", "Joel preaches the Day of the Lord and the outpouring of the Spirit.", "The Twelve preach with five emphases, not twelve unrelated hobbies.", "For the pulpit: do not reduce the Minor Prophets to weather reports."]}, {"id": "ot2-10", "number": 10, "title": "Jeremiah and Ezekiel", "topic": "Priest-prophets at the fall of Jerusalem — Branch, New Covenant, dry bones.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "takeaways": ["Jeremiah is a priest-prophet from Anathoth. His work sits in 626–586 BC — the last decades before Jerusalem falls. The pulpit is not a court job; it is a priest with a hard word.", "His message is repent, and submit to Babylon. That is the Lord’s sentence, not cowardice. Fight the wrong empire and you fight the God who sent it.", "Lamentations is the grief that follows the sermon. The city falls, and the prophet weeps. Preach both: the warning and the tears.", "Jeremiah did not die of old age in Babylon. He died in Egypt. Do not tidy the ending to match the exile stories you already know.", "Three key prophecies still preach: seventy years of captivity, a righteous Branch, and a New Covenant. Daniel and Ezra take up Jeremiah’s word; the New Testament quotes him more than once.", "Ezekiel is taken in 597 BC — after Daniel’s 605, not ten years before him. He writes to explain why God allowed the Temple and the city of Jerusalem to be destroyed.", "Watch the glory leave: Ezekiel 8–11, the Shekinah departing because of four idolatries, including 25 men worshiping the sun. Then Ezekiel 37 — the valley of dry bones, a prophetic picture of Israel’s future restoration."], "quiz": [{"q": "Jeremiah was quoted by both Daniel and Ezra.", "answer": "True", "why": "Daniel and Ezra both take up Jeremiah’s word. The seventy-year captivity he named is the calendar they preach and live under."}, {"q": "Jeremiah's father was a priest.", "answer": "True", "why": "Jeremiah is a priest-prophet from Anathoth. The call sits on a priest’s son, not a professional court speaker."}, {"q": "Two evil Kings who provide an historical background to Jeremiah's book are Hezekiah and Josiah.", "answer": "False", "why": "Hezekiah and Josiah were good kings, not evil. Do not smear the reformers to fill in Jeremiah’s background."}, {"q": "Nebuchadnezzar told his army to release Jeremiah because of Jeremiah's prophesies.", "answer": "True", "why": "The Babylonian king knew the prophet’s word. Jeremiah had said submit to Babylon — and the army was told to let him go."}, {"q": "Jeremiah died of old age in Babylon.", "answer": "False", "why": "He died in Egypt, not Babylon. The exile did not become his gravesite; Egypt did."}, {"q": "Jeremiah was quoted multiple times in the New Testament.", "answer": "True", "why": "The New Testament takes up Jeremiah more than once. The Branch and the New Covenant do not stay in one book."}, {"q": "Ezekiel wrote to explain why God allowed the destruction of the Temple and the city of Jerusalem.", "answer": "True", "why": "That is the burden of the book. Ezekiel is not only visions; he is the why behind the rubble."}, {"q": "Ezekiel arrived in Babylon 10 years before Daniel.", "answer": "False", "why": "Daniel went first (605). Ezekiel is taken in 597 — after Daniel, not a decade before him."}, {"q": "Ezekiel recounts that one reason for the glory of God departing the Temple was due to the false worship of the sun by 25 men.", "answer": "True", "why": "Ezekiel 8–11: four idolatries, including 25 men worshiping the sun. The Shekinah leaves because the house is already defiled."}, {"q": "The Vision of the Valley of Dry Bones in Ezekiel 37 was a prophetic picture of the future restoration of Israel.", "answer": "True", "why": "Dry bones live. The vision is not a funeral; it is Israel’s future restoration in picture form."}], "essays": [{"theme": "Jeremiah’s three key prophecies (70yr, Branch, New Covenant)", "summary": "Hold three words from Jeremiah, not a pile of woes. First, seventy years of captivity: the exile has a term. Daniel and Ezra both take up that calendar — the Lord named the length before the gates fell. Second, a righteous Branch: hope is not a policy; it is a Person from David’s line when the throne looks dead. Third, a New Covenant: the law written on the heart, not only on stone, after the old arrangements have been broken. The New Testament quotes Jeremiah more than once because these last two do not stay in one book. For the pulpit: preach the numbered exile, the Branch, and the new heart. Do not leave the people with only the tears of Lamentations."}, {"theme": "Ezekiel 37 dry bones", "summary": "The valley of dry bones is a prophetic picture of the future restoration of Israel — not a private mysticism and not a funeral. The bones are very dry; the people are finished as far as human strength can tell. Then the word is preached, breath comes, and a vast army stands. Ezekiel has already explained the destruction; chapter 37 is the other half of the sermon: God can raise what He judged. Preach it that way. Restoration is the Lord’s work on a dead nation, not Israel’s self-rescue."}, {"theme": "Shekinah departure / temple destruction", "summary": "Ezekiel writes to explain why God allowed the destruction of the Temple and the city of Jerusalem. The glory does not slip out by accident. In Ezekiel 8–11 the prophet is shown four idolatries in the house, including 25 men with their backs to the sanctuary, worshiping the sun. The Shekinah departs because the Temple is already defiled. Babylon is the tool; the cause is false worship. For the pulpit: if the glory leaves, ask what was already being bowed to. The rubble is the sentence; the sun-worshipers are the reason."}], "bigIdeas": ["Jeremiah is a priest-prophet from Anathoth. His work sits in 626–586 BC — the last decades before Jerusalem falls. The pulpit is not a court job; it is a priest with a hard word.", "His message is repent, and submit to Babylon. That is the Lord’s sentence, not cowardice. Fight the wrong empire and you fight the God who sent it.", "Lamentations is the grief that follows the sermon. The city falls, and the prophet weeps. Preach both: the warning and the tears.", "Jeremiah did not die of old age in Babylon. He died in Egypt. Do not tidy the ending to match the exile stories you already know.", "Three key prophecies still preach: seventy years of captivity, a righteous Branch, and a New Covenant. Daniel and Ezra take up Jeremiah’s word; the New Testament quotes him more than once.", "Ezekiel is taken in 597 BC — after Daniel’s 605, not ten years before him. He writes to explain why God allowed the Temple and the city of Jerusalem to be destroyed.", "Watch the glory leave: Ezekiel 8–11, the Shekinah departing because of four idolatries, including 25 men worshiping the sun. Then Ezekiel 37 — the valley of dry bones, a prophetic picture of Israel’s future restoration."], "summary": "Priest-prophets at the fall of Jerusalem — Branch, New Covenant, dry bones. Jeremiah is a priest-prophet from Anathoth. His work sits in 626–586 BC — the last decades before Jerusalem falls. The pulpit is not a court job; it is a priest with a hard word.", "quickReview": ["Jeremiah is a priest-prophet from Anathoth. His work sits in 626–586 BC — the last decades before Jerusalem…", "His message is repent, and submit to Babylon. That is the Lord’s sentence, not cowardice. Fight the wrong…", "Lamentations is the grief that follows the sermon. The city falls, and the prophet weeps. Preach both: the…", "Jeremiah did not die of old age in Babylon. He died in Egypt. Do not tidy the ending to match the exile…", "Three key prophecies still preach: seventy years of captivity, a righteous Branch, and a New Covenant. Daniel…"], "glossary": [{"term": "Jeremiah’s three key prophecies (70yr, Branch, New Cove", "meaning": "Hold three words from Jeremiah, not a pile of woes. First, seventy years of captivity: the exile has a term. Daniel and Ezra both take up that calendar — the…"}, {"term": "Ezekiel 37 dry bones", "meaning": "The valley of dry bones is a prophetic picture of the future restoration of Israel — not a private mysticism and not a funeral. The bones are very dry; the…"}, {"term": "Shekinah departure / temple destruction", "meaning": "Ezekiel writes to explain why God allowed the destruction of the Temple and the city of Jerusalem. The glory does not slip out by accident. In Ezekiel 8–11 the…"}, {"term": "Jeremiah", "meaning": "Jeremiah is a priest-prophet from Anathoth"}, {"term": "Lamentations", "meaning": "Lamentations is the grief that follows the sermon"}, {"term": "Ezekiel", "meaning": "Ezekiel is taken in 597 BC — after Daniel’s 605, not ten years before him"}, {"term": "Covenant", "meaning": "Three key prophecies still preach: seventy years of captivity, a righteous Branch, and a New Covenant."}], "outline": ["Jeremiah’s three key prophecies (70yr, Branch, New Covenant)", "Ezekiel 37 dry bones", "Shekinah departure / temple destruction"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Date", "value": "586 BC — the last decades before Jer"}, {"label": "Key claim", "value": "Jeremiah is a priest-prophet from Anathoth. His work sits in 626–586 BC — the last decades before Jerusalem falls. The pulpit is not a…"}, {"label": "Key claim", "value": "His message is repent, and submit to Babylon. That is the Lord’s sentence, not cowardice. Fight the wrong empire and you fight the God who…"}, {"label": "Preach", "value": "Lamentations is the grief that follows the sermon. The city falls, and the prophet weeps. Preach both: the warning and the tears."}], "pulpit": ["The pulpit is not a court job; it is a priest with a hard word.", "Lamentations is the grief that follows the sermon.", "Preach both: the warning and the tears.", "Three key prophecies still preach: seventy years of captivity, a righteous Branch, and a New Covenant."], "compare": [{"title": "Three key prophecies still preach", "points": ["seventy years of captivity", "a righteous Branch", "and a New Covenant"]}]}, {"id": "ot2-11", "number": 11, "title": "Daniel and Esther", "topic": "Captive prophet and hidden providence — kingdoms, seventy weeks, and Purim.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 9/10. Essays not graded yet — final may rise when marked. One attempt only; do not reattempt.", "takeaways": ["Daniel is taken captive about 605 BC at fifteen. He is the last of the Major Prophets in influence and sequence. In many ways his life is like Joseph’s: no recorded sin, a Gentile court, political leaders who listen, moral purity, and a rise from obscurity to national recognition.", "The book is bilingual — Hebrew in 1:1–2:4 and 8:1–12:13, Aramaic in 2:5–7:28 — written 605–535 BC in Babylon. A captive prophet speaking the language of the court and the language of the covenant.", "Critics put Daniel late, unknown, even first-century. The answer is earlier Aramaic, early Jewish acceptance (Baruch, Josephus, the LXX, Ezekiel), and Jesus recognizing Daniel as both prophet and author.", "Chapters 1–6 are history you can preach: new names (Belteshazzar, Shadrach, Meshach, Abednego); the king’s food refused; the image dream; the ninety-foot idol and the fourth Man in the fire; Nebuchadnezzar’s seven years of pride; Belshazzar’s MENE, TEKEL, PERES; Darius and the lions’ den.", "Daniel 2 and 7 run in parallel: Babylon (gold / winged lion), Medo-Persia (silver / bear / ram), Greece (brass / leopard with four heads — Alexander’s generals), Rome (iron / dreadful beast), then revived Rome (iron and clay / little horn). The Stone is Christ’s kingdom. The key to world history here is God’s program with the Jews — so Daniel is not mapping China or the Aztecs.", "Daniel 9: seventy weeks are 490 years of Jewish prophetic history. The decree to Nehemiah is about 454 BC; sixty-nine weeks (483 years) run to Messiah cut off (~AD 29). Then a gap. The seventieth week is the seven-year tribulation.", "Esther (~450 BC) is hidden providence in the diaspora. God’s name never appears in the open text; it is hidden in five acrostics (1:20; 5:4; 5:13; 7:5; 7:7). “For such a time as this.” Haman is hanged on his own gallows; Mordecai becomes Prime Minister. The victory is remembered in the Feast of Purim."], "quiz": [{"q": "Jeroboam was humanly responsible for splitting the Kingdom.", "answer": "True", "why": "Carryover stem from earlier material. Jeroboam led the ten tribes’ revolt — that is the human split of the kingdom."}, {"q": "Daniel is the last of the Minor Prophets in influence and sequence.", "answer": "False", "why": "He is the last of the Major Prophets in influence and sequence, not the Twelve."}, {"q": "In many ways, Daniel's life was like Joseph's.", "answer": "True", "why": "Five listed parallels: no recorded sin, a Gentile nation, influence on political leaders, moral purity, obscurity to national recognition."}, {"q": "Jesus recognized Daniel as both a prophet and an author.", "answer": "True", "why": "That is the workbook’s answer to the critical view. Jesus treats Daniel as prophet and as the one who wrote."}, {"q": "Daniel predicted coming world powers including the Chinese and Aztecs.", "answer": "False", "why": "The key to world history in Daniel is God’s program with the Jews — not a catalog of every empire on the map."}, {"q": "Daniel's wild beasts in chapter 7 were actually nations.", "answer": "True", "why": "Lion = Babylon, bear = Medo-Persia, leopard = Greece, dreadful beast = Rome. The beasts are empires."}, {"q": "Daniel understood everything he wrote in his prophetic book.", "answer": "False", "why": "Daniel knows what is said, writes it down, but does not understand everything he wrote."}, {"q": "The name of God is mentioned only five times in the book of Esther.", "answer": "False", "why": "The one lost mark (Jay-R chose True). God’s name is never openly mentioned in Esther; it is only hidden in five acrostics. “Mentioned five times” is therefore false."}, {"q": "Esther's victory is commemorated in the Feast of Purim.", "answer": "True", "why": "Purim is the feast that remembers Esther’s victory and the Jews’ deliverance."}, {"q": "Eventually, Haman became the Prime Minister in Esther's story.", "answer": "False", "why": "Mordecai became Prime Minister. Haman was hanged on his own gallows."}], "essays": [{"theme": "Daniel 7 refers to four wild beasts. Explain what this chapter means.", "summary": "Daniel 7 is a night vision (about 553 BC, Belshazzar’s first year): four wild beasts come up from the sea — the sea standing for the Gentile nations. They parallel the metals of chapter 2. The winged lion is Babylon; the bear is Medo-Persia; the leopard with four heads is Greece (Alexander’s four generals); the dreadful beast is Rome. A little horn rises among ten kings — the antichrist of a revived Rome. Then the Stone: Christ’s kingdom that crushes the image and fills the earth. Preach the empires, the horn, and the Stone. Do not turn the beasts into a private puzzle."}, {"theme": "Explain the significance of Daniel's 70 weeks.", "summary": "Seventy weeks are 490 years of Jewish prophetic history, not a riddle for its own sake. The decree that starts the clock is the word to Nehemiah, about 454 BC. Sixty-nine weeks (483 years) run to Messiah cut off — about AD 29. Then a gap (an intercalation). The seventieth week is the seven-year tribulation still ahead. Hold the calendar: 490, 454, 69 weeks to the cross, a gap, then the last seven years. That is the significance Daniel 9 puts in your hand."}, {"theme": "Explain briefly the major message of Esther.", "summary": "Esther’s major message is hidden providence over the Jews in the diaspora. God’s name never appears in the open text; it is hidden in five acrostics. Mordecai’s word still preaches: you have come to the kingdom “for such a time as this.” Haman is hanged; a second decree answers an irrevocable law; Purim remembers the victory. Even outside the Promised Land, when His name is not spoken, His hand is with His people."}], "bigIdeas": ["Daniel is taken captive about 605 BC at fifteen. He is the last of the Major Prophets in influence and sequence. In many ways his life is like Joseph’s: no recorded sin, a Gentile court, political leaders who listen, moral purity, and a rise from obscurity to national recognition.", "The book is bilingual — Hebrew in 1:1–2:4 and 8:1–12:13, Aramaic in 2:5–7:28 — written 605–535 BC in Babylon. A captive prophet speaking the language of the court and the language of the covenant.", "Critics put Daniel late, unknown, even first-century. The answer is earlier Aramaic, early Jewish acceptance (Baruch, Josephus, the LXX, Ezekiel), and Jesus recognizing Daniel as both prophet and author.", "Chapters 1–6 are history you can preach: new names (Belteshazzar, Shadrach, Meshach, Abednego); the king’s food refused; the image dream; the ninety-foot idol and the fourth Man in the fire; Nebuchadnezzar’s seven years of pride; Belshazzar’s MENE, TEKEL, PERES; Darius and the lions’ den.", "Daniel 2 and 7 run in parallel: Babylon (gold / winged lion), Medo-Persia (silver / bear / ram), Greece (brass / leopard with four heads — Alexander’s generals), Rome (iron / dreadful beast), then revived Rome (iron and clay / little horn). The Stone is Christ’s kingdom. The key to world history here is God’s program with the Jews — so Daniel is not mapping China or the Aztecs.", "Daniel 9: seventy weeks are 490 years of Jewish prophetic history. The decree to Nehemiah is about 454 BC; sixty-nine weeks (483 years) run to Messiah cut off (~AD 29). Then a gap. The seventieth week is the seven-year tribulation.", "Esther (~450 BC) is hidden providence in the diaspora. God’s name never appears in the open text; it is hidden in five acrostics (1:20; 5:4; 5:13; 7:5; 7:7). “For such a time as this.” Haman is hanged on his own gallows; Mordecai becomes Prime Minister. The victory is remembered in the Feast of Purim."], "summary": "Captive prophet and hidden providence — kingdoms, seventy weeks, and Purim. Daniel is taken captive about 605 BC at fifteen. He is the last of the Major Prophets in influence and sequence. In many ways his life is like Joseph’s: no recorded sin, a Gentile…", "quickReview": ["Daniel is taken captive about 605 BC at fifteen. He is the last of the Major Prophets in influence and…", "The book is bilingual — Hebrew in 1:1–2:4 and 8:1–12:13, Aramaic in 2:5–7:28 — written 605–535 BC in Babylon…", "Critics put Daniel late, unknown, even first-century. The answer is earlier Aramaic, early Jewish acceptance…", "Chapters 1–6 are history you can preach: new names (Belteshazzar, Shadrach, Meshach, Abednego); the king’s…", "Daniel 2 and 7 run in parallel: Babylon (gold / winged lion), Medo-Persia (silver / bear / ram), Greece…"], "glossary": [{"term": "For such a time as this", "meaning": "“For such a time as this.” Haman is hanged on his own gallows; Mordecai becomes Prime Minister."}, {"term": "Mentioned five times", "meaning": "“Mentioned five times” is therefore false."}, {"term": "Daniel 7 refers to four wild beasts. Explain what this", "meaning": "Daniel 7 is a night vision (about 553 BC, Belshazzar’s first year): four wild beasts come up from the sea — the sea standing for the Gentile nations. They…"}, {"term": "The significance of Daniel's 70 weeks", "meaning": "Seventy weeks are 490 years of Jewish prophetic history, not a riddle for its own sake. The decree that starts the clock is the word to Nehemiah, about 454 BC…"}, {"term": "Briefly the major message of Esther", "meaning": "Esther’s major message is hidden providence over the Jews in the diaspora. God’s name never appears in the open text; it is hidden in five acrostics…"}, {"term": "Lion", "meaning": "Babylon"}, {"term": "Daniel", "meaning": "Daniel is taken captive about 605 BC at fifteen"}], "outline": ["Daniel 7 refers to four wild beasts. Explain what this chapter means.", "Explain the significance of Daniel's 70 weeks.", "Explain briefly the major message of Esther."], "mustKnow": [{"label": "Quiz score", "value": "90% (1 attempt)"}, {"label": "Date", "value": "605 BC at fifteen"}, {"label": "Key claim", "value": "Daniel is taken captive about 605 BC at fifteen. He is the last of the Major Prophets in influence and sequence. In many ways his life is…"}, {"label": "Covenant", "value": "The book is bilingual — Hebrew in 1:1–2:4 and 8:1–12:13, Aramaic in 2:5–7:28 — written 605–535 BC in Babylon. A captive prophet speaking…"}, {"label": "Key claim", "value": "Critics put Daniel late, unknown, even first-century. The answer is earlier Aramaic, early Jewish acceptance (Baruch, Josephus, the LXX…"}], "pulpit": ["Chapters 1–6 are history you can preach: new names (Belteshazzar, Shadrach, Meshach, Abednego); the king’s food refused; the image dream; the ninety-foot idol…", "Preach the empires, the horn, and the Stone.", "Mordecai’s word still preaches: you have come to the kingdom “for such a time as this.” Haman is hanged; a second decree answers an irrevocable law; Purim…"], "compare": null}, {"id": "ot2-12", "number": 12, "title": "Ezra, Haggai, Zechariah, Nehemiah and Malachi", "topic": "Five leaders after the exile — temple, people, wall, and the last OT word.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10. Essays not graded yet. One attempt only.", "takeaways": ["Ezra is post-exile, 458–433 BC. The book is written to encourage those who returned to be faithful. Two halves: restoration of the Temple (Ezra 1–6), then reformation of the nation (7–10). Worship first, then the people.", "Cyrus took Babylon in 539 BC and decreed the return the next year (2 Chron. 36:23; Ezra 1:2–3). Isaiah 45:1 named him; the Cylinder of Cyrus matches the policy. About 50,000 came home with Zerubbabel (Sheshbazzar — legal heir of David’s throne, Matt. 1:12) and Jeshua the high priest. The road home still sings in the Psalms of Ascents, 120–134.", "They built the altar first and kept the Feast of Tabernacles. The foundation went down in the second month of the second year — mixed weeping and shouting (Ezra 3:8–13). Samaritan help was refused; opposition followed; the work stopped sixteen years (Ezra 4:23).", "Haggai (520 BC, second year of Darius I) is the “most successful prophet”: thirty-eight verses, five messages, one theme — the unfinished Temple. “Lord of Hosts” piles up here (Haggai 14×, Zechariah 50×, Malachi 25×). The house is finished 516 BC (Ezra 6:15; the workbook also says 515). Passover in Jerusalem for the first time in seventy years.", "Zechariah (520–500 BC), a Levite, son of Iddo, writes two advents. Rejected: 9:9 on an ass; 11:12 thirty pieces; 12:10 pierced; 13:6 wounds in the hands. Reigning: 14:2 the nations; 14:4–6 the Mount of Olives splits; 14:8 living waters; 14:16 the Feast of Tabernacles.", "Nehemiah (438–433 BC) is the last historical book of the Old Testament. Cupbearer to Artaxerxes in Shushan. Sanballat, Tobiah, and Geshem oppose him. The wall is finished in fifty-two days (6:15). The decree of Nehemiah’s day starts Daniel’s seventy weeks (Dan. 9:25). Ezra’s reading of the Word brings revival.", "Malachi (435–430 BC) means “messenger.” His burden is covenant violation — dishonor, maimed offerings, broken marriage vows, unpaid tithes. Elijah is John the Baptist (3:1; 4:5). The last word of the Old Testament is “curse.”", "Hold the three builders: Zerubbabel builds the temple, Ezra builds the people and the worship, Nehemiah builds the wall."], "quiz": [{"q": "Ezra was written to encourage those who returned from captivity to be faithful to the Lord.", "answer": "True", "why": "That is the purpose Towns names — encourage the remnant who came home to stay faithful."}, {"q": "Ezra recorded the restoration of temple worship.", "answer": "True", "why": "Chapters 1–6 restore the Temple; that is the first half of the book."}, {"q": "Ezra recorded the preservation of the line of the Messiah", "answer": "True", "why": "Towns: Ezra records the preservation of the Messianic line (Zerubbabel / Sheshbazzar in David’s throne, Matt. 1:12)."}, {"q": "Haggai was a contemporary of Zechariah.", "answer": "True", "why": "Both preached about 520 BC under Darius I. Haggai and Zechariah together got the work moving again."}, {"q": "Zechariah wrote of the two advents of the Messiah.", "answer": "True", "why": "First advent: rejected (9:9; 11:12; 12:10; 13:6). Second: reigning (ch. 14)."}, {"q": "Nehemiah is the last historical book of the Old Testament.", "answer": "True", "why": "After Nehemiah the historical books of the OT close. Malachi is prophecy, not history."}, {"q": "Nehemiah's task was to restore the broken down walls as well as the dignity of Jerusalem.", "answer": "True", "why": "Broken walls and burned gates — and the shame of the people. He restored both."}, {"q": "Nehemiah faced considerable opposition to his objective yet worked on undeterred.", "answer": "True", "why": "Sanballat, Tobiah, and Geshem mocked, threatened, and tried to lure him down. He would not come down."}, {"q": "Malachi means \"messenger.\"", "answer": "True", "why": "The name itself is “messenger.” Elijah / John (3:1; 4:5) is the messenger still ahead."}, {"q": "Malachi's burden was to redress the issues related to the \"Covenant Violation\".", "answer": "True", "why": "His burden is covenant violation — dishonor, maimed offerings, broken vows, unpaid tithes."}], "essays": [{"theme": "Summarize the major message of Ezra's book.", "summary": "Ezra’s main message is that God kept His word and brought a remnant of the Jews back home after the seventy years in Babylon. Cyrus of Persia signed the decree in 538 BC, and about 50,000 came back with Zerubbabel the governor and Jeshua the high priest. First they built the altar, started the sacrifices, and kept the Feast of Tabernacles; then they laid the temple foundation. The work stopped sixteen years because of the Samaritans — discouragement and letters to the king — until Haggai and Zechariah preached and the people started again. The temple was finished in 516 BC under Darius. Later Ezra himself came in 458 BC with about 1,500 people; his work was reformation, teaching the law and dealing with the sin of the people. So the book records the restoration of temple worship and the preservation of the line of the Messiah. The lesson is simple: God is faithful even when His people are only a small remnant."}, {"theme": "What does Zechariah tell us about the two advents of the Messiah?", "summary": "Zechariah preached with Haggai around 520–500 BC, but his message went farther than the temple. He wrote about the Messiah coming two times. In the first coming He is rejected: Zechariah 9:9, the king comes lowly riding upon an ass; 11:12, they weighed for my price thirty pieces of silver; 12:10, they shall look upon me whom they have pierced; 13:6, what are these wounds in thine hands, wounded in the house of my friends. All of that was fulfilled in Jesus at the cross. In the second coming He is reigning. Chapters 12–14 tell how the Lord will gather all nations against Jerusalem; His feet shall stand on the Mount of Olives and it will split in half and make a great valley. Living waters will go out of Jerusalem, and everyone will come up year by year to worship the King, the Lord of Hosts, and keep the Feast of Tabernacles. The same Messiah who was rejected the first time will come back as King."}, {"theme": "Describe Nehemiah's life from the time he hears of Jerusalem's sad condition until the time the walls and gates of Jerusalem are rebuilt.", "summary": "Nehemiah was in Shushan palace as cupbearer to king Artaxerxes. His brother and some men came from Judah with the news: the wall of Jerusalem broken down, the gates burned, the people in trouble and shame. Nehemiah sat down and wept, then he fasted and prayed. He confessed the sin of the nation and asked God for mercy before the king. When the king saw his sad face and asked what he wanted, Nehemiah prayed again quickly and asked to be sent to rebuild the city. The king gave him letters and timber, and Nehemiah said the good hand of God was upon him. When he arrived he told nobody at first; he went out by night and inspected the walls himself, then called the people and said, let us build — and they said, let us rise up and build. Every family worked on the part of the wall near where they lived. Opposition came at once: Sanballat of Samaria, Tobiah the Ammonite, and Geshem the Arabian first mocked, then grew angry and planned to fight, then tried to compromise and call Nehemiah to the plain of Ono, and even hired a false prophet to make him afraid and hide in the temple. Inside there were problems too — much rubbish, fear of the enemy, and usury charged by rich Jews on their own brothers. Nehemiah answered all of it: a guard day and night, half the men working and half holding weapons, the workers building with one hand and a weapon in the other, the nobles made to stop the usury. He kept praying, he kept working, and he would not come down. The wall was finished in fifty-two days, and even the enemies perceived that this work was done of God. After that Ezra read the law to the people at the water gate; they stood up and said amen and wept, and there was revival in the city."}], "bigIdeas": ["Ezra is post-exile, 458–433 BC. The book is written to encourage those who returned to be faithful. Two halves: restoration of the Temple (Ezra 1–6), then reformation of the nation (7–10). Worship first, then the people.", "Cyrus took Babylon in 539 BC and decreed the return the next year (2 Chron. 36:23; Ezra 1:2–3). Isaiah 45:1 named him; the Cylinder of Cyrus matches the policy. About 50,000 came home with Zerubbabel (Sheshbazzar — legal heir of David’s throne, Matt. 1:12) and Jeshua the high priest. The road home still sings in the Psalms of Ascents, 120–134.", "They built the altar first and kept the Feast of Tabernacles. The foundation went down in the second month of the second year — mixed weeping and shouting (Ezra 3:8–13). Samaritan help was refused; opposition followed; the work stopped sixteen years (Ezra 4:23).", "Haggai (520 BC, second year of Darius I) is the “most successful prophet”: thirty-eight verses, five messages, one theme — the unfinished Temple. “Lord of Hosts” piles up here (Haggai 14×, Zechariah 50×, Malachi 25×). The house is finished 516 BC (Ezra 6:15; the workbook also says 515). Passover in Jerusalem for the first time in seventy years.", "Zechariah (520–500 BC), a Levite, son of Iddo, writes two advents. Rejected: 9:9 on an ass; 11:12 thirty pieces; 12:10 pierced; 13:6 wounds in the hands. Reigning: 14:2 the nations; 14:4–6 the Mount of Olives splits; 14:8 living waters; 14:16 the Feast of Tabernacles.", "Nehemiah (438–433 BC) is the last historical book of the Old Testament. Cupbearer to Artaxerxes in Shushan. Sanballat, Tobiah, and Geshem oppose him. The wall is finished in fifty-two days (6:15). The decree of Nehemiah’s day starts Daniel’s seventy weeks (Dan. 9:25). Ezra’s reading of the Word brings revival.", "Malachi (435–430 BC) means “messenger.” His burden is covenant violation — dishonor, maimed offerings, broken marriage vows, unpaid tithes. Elijah is John the Baptist (3:1; 4:5). The last word of the Old Testament is “curse.”", "Hold the three builders: Zerubbabel builds the temple, Ezra builds the people and the worship, Nehemiah builds the wall."], "summary": "Five leaders after the exile — temple, people, wall, and the last OT word. Ezra is post-exile, 458–433 BC. The book is written to encourage those who returned to be faithful. Two halves: restoration of the Temple (Ezra 1–6), then reformation of the nation (7–10). Worship first, then the people. Essay work covers Summarize the major message of Ezra's book.; What does Zechariah tell us about the two advents of the Messiah?; Describe Nehemiah's life from the time he hears of Jerusalem's sad condition until the time the walls and gates of Jerusalem are rebuilt..", "quickReview": ["Ezra is post-exile, 458–433 BC. The book is written to encourage those who returned to be faithful. Two…", "Cyrus took Babylon in 539 BC and decreed the return the next year (2 Chron. 36:23; Ezra 1:2–3). Isaiah 45:1…", "They built the altar first and kept the Feast of Tabernacles. The foundation went down in the second month of…", "Haggai (520 BC, second year of Darius I) is the “most successful prophet”: thirty-eight verses, five…", "Zechariah (520–500 BC), a Levite, son of Iddo, writes two advents. Rejected: 9:9 on an ass; 11:12 thirty…"], "glossary": [{"term": "Most successful prophet", "meaning": "Haggai (520 BC, second year of Darius I) is the “most successful prophet”: thirty-eight verses, five messages, one theme — the unfinished Temple."}, {"term": "Lord of Hosts", "meaning": "“Lord of Hosts” piles up here (Haggai 14×, Zechariah 50×, Malachi 25×)."}, {"term": "Messenger", "meaning": "Malachi (435–430 BC) means “messenger.” His burden is covenant violation — dishonor, maimed offerings, broken marriage vows, unpaid tithes."}, {"term": "Curse", "meaning": "The last word of the Old Testament is “curse.” Hold the three builders: Zerubbabel builds the temple, Ezra builds the people and the worship, Nehemiah builds…"}, {"term": "Summarize the major message of Ezra's book", "meaning": "Ezra’s main message is that God kept His word and brought a remnant of the Jews back home after the seventy years in Babylon. Cyrus of Persia signed the decree…"}, {"term": "What does Zechariah tell us about the two advents of th", "meaning": "Zechariah preached with Haggai around 520–500 BC, but his message went farther than the temple. He wrote about the Messiah coming two times. In the first…"}, {"term": "Describe Nehemiah's life from the time he hears of Jeru", "meaning": "Nehemiah was in Shushan palace as cupbearer to king Artaxerxes. His brother and some men came from Judah with the news: the wall of Jerusalem broken down, the…"}, {"term": "Ezra", "meaning": "Ezra is post-exile, 458–433 BC"}], "outline": ["Summarize the major message of Ezra's book.", "What does Zechariah tell us about the two advents of the Messiah?", "Describe Nehemiah's life from the time he hears of Jerusalem's sad condition until the time the walls and gates of Jerusalem are rebuilt."], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Audience", "value": "encourage those who returned to be faithful"}, {"label": "Date", "value": "433 BC"}, {"label": "Key claim", "value": "Ezra is post-exile, 458–433 BC. The book is written to encourage those who returned to be faithful. Two halves: restoration of the Temple…"}, {"label": "Key claim", "value": "Cyrus took Babylon in 539 BC and decreed the return the next year (2 Chron. 36:23; Ezra 1:2–3). Isaiah 45:1 named him; the Cylinder of…"}, {"label": "Key claim", "value": "They built the altar first and kept the Feast of Tabernacles. The foundation went down in the second month of the second year — mixed…"}], "compare": null, "pulpit": ["The work stopped sixteen years because of the Samaritans — discouragement and letters to the king — until Haggai and Zechariah preached and the people started…", "Zechariah preached with Haggai around 520–500 BC, but his message went farther than the temple."]}]}, {"id": "nt-survey-2", "code": 55, "title": "New Testament Survey 2", "status": "complete", "certificateUnlocked": false, "blurb": "Acts continued through Revelation — Lessons 7–12 complete. Course total 94%. (No certificate module.)", "lessons": [{"id": "nt2-7", "number": 7, "title": "Acts Continued", "topic": "Saul’s conversion, Cornelius, and the first missionary journey.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10. Essays not graded yet. One attempt only. Workbook only (no separate Reading doc).", "takeaways": ["Paul’s background has nine traits God later used: Jew of Benjamin (Phil. 3:5); Pharisee, blameless in the law; educated at Gamaliel’s feet (Acts 22:3); free-born Roman (Acts 22:27–28); a zealous persecutor; he voted for believers’ deaths (Acts 26:10); he stood at Stephen’s stoning (Acts 7:58); he carried letters to Damascus (Acts 22:5); and he most likely saw Christ in the flesh (2 Cor. 5:16).", "Conversion on the Damascus road is light, voice, and command. A supernatural light blinded him three days; a supernatural voice said, I am Jesus whom you are persecuting; and the command was, go into the city. Faithfulness in that first task is often the sign of long-range usefulness. Companions heard a noise, not the words — spoken in Hebrew (Acts 22:9).", "Ananias yielded three times: to the call, to the objection, and to the ministry. He laid hands on Saul and said, Brother Saul. That word “brother” is the gospel in one greeting. Saul then becomes the pattern new believer — healed, filled, baptized, strengthened, preaching, with hearers amazed (Acts 9:17–20).", "Paul’s desert years are Arabia, not a footnote in Philippians. Galatians 1:15–24 says God taught him, separate from men. Then the persecutor becomes the hunted — disciples let him down the Damascus wall in a basket (Acts 9:23–25; 2 Cor. 11:32–33).", "With Cornelius, God opens the doorway of salvation to the Gentiles. An honest seeker; an angel who does not preach but sends him to Peter; a sheet lowered three times — what God has cleansed do not call common (Acts 10). Gentiles receive the Spirit and baptism (Acts 10:44–48); Peter defends it in Acts 11.", "Oikos evangelism is reaching people for Christ through existing relationships — household, kin, the people already in the house. Cornelius’s house is the picture: the gospel walks in through a door God already opened.", "The first missionary journey begins about 45 A.D. from Antioch. The Spirit says, Separate Barnabas and Saul. The church fasts, prays, lays hands, and sends. They go Seleucia → Cyprus → Salamis, preaching in the synagogues, John Mark as helper. Foreign mission work begins with prayer and fasting — and John Mark does not stay to the finish."], "quiz": [{"q": "Paul was both Jewish and a Roman citizen.", "answer": "True", "why": "Jew of Benjamin and free-born Roman (Acts 22:27–28). God used both passports for the gospel."}, {"q": "For new believers, faithfulness in their first task is often indicative of long range usefulness.", "answer": "True", "why": "The first command was go into the city. Faithfulness in that first task often marks long-range usefulness."}, {"q": "Paul's desert experience is described in the book of Philippians.", "answer": "False", "why": "The desert years are Arabia, recorded in Galatians 1 — not Philippians. God taught him apart from men."}, {"q": "With Cornelius, God was opening the doorway of salvation to the Gentiles.", "answer": "True", "why": "Acts 10–11 is the open door. Cornelius’s house is Gentiles receiving the Spirit and baptism."}, {"q": "Angels do not preach, but serve as God's messengers.", "answer": "True", "why": "An angel sent Cornelius to Peter. Angels serve as messengers; they do not preach the gospel."}, {"q": "People are tested in respect to their obedience to God's will.", "answer": "True", "why": "Ananias, Peter, and Cornelius all had to obey. People are tested by whether they will do God’s will."}, {"q": "Oikos evangelism is reaching people for Christ through existing relationships.", "answer": "True", "why": "Oikos is household and existing relationships — the gospel through the people already in the house."}, {"q": "Foreign mission work begins with prayer and fasting.", "answer": "True", "why": "Antioch fasted, prayed, laid hands, and sent (Acts 13:1–3). Foreign mission work begins there, not with a map."}, {"q": "Paul was a natural leader.", "answer": "True", "why": "The lesson names him a natural leader. The same drive that hunted the church later planted it."}, {"q": "John Mark accompanied Paul and Barnabas on the first missionary journey from start to finish.", "answer": "False", "why": "John Mark went as helper from Antioch and Cyprus, then left. He did not stay from start to finish."}], "essays": [{"theme": "Nine characteristics of Paul's background", "summary": "Paul’s background has nine parts from the workbook. He was a Jew by birth — circumcised the eighth day, of Israel, of Benjamin, a Hebrew of the Hebrews (Phil. 3:5). He was a Pharisee, blameless as touching the righteousness of the law (Phil. 3:5–6). He was well educated, brought up in Jerusalem at the feet of Gamaliel (Acts 22:3). He was a free-born Roman citizen (Acts 22:27–28). Zeal made him persecute the church (Phil. 3:6). He voted for believers’ deaths — “I gave my voice against them” (Acts 26:10). He was there at Stephen’s stoning; the witnesses laid their clothes at the feet of the young man Saul (Acts 7:58). He was an official persecutor, taking letters to Damascus to bring believers bound to Jerusalem (Acts 22:5). And he most likely saw Jesus in the flesh, for he said we have known Christ according to the flesh (2 Cor. 5:16). All of this God later used for His glory after Saul met Christ on the road."}, {"theme": "What Acts teaches about the First Missionary Journey", "summary": "Acts 13–14 show how the first missionary journey began and what it teaches. It started around 45 A.D. from Antioch. While Barnabas, Simeon called Niger, Lucius of Cyrene, Manaen, and Saul ministered to the Lord and fasted, the Holy Spirit said, Separate Barnabas and Saul for the work I have called them to (Acts 13:1–2). Mission work starts with the Spirit’s call, not mere human planning. The local church confirmed it: they fasted, prayed, laid hands on them, and sent them away (Acts 13:3). The sending church has a real part. They had a strategy — Seleucia, then Cyprus; at Salamis they preached the word of God in the synagogues of the Jews, with John Mark as helper (Acts 13:4–5). They began where people already knew the Scriptures, then moved toward Gentile cities. Their authority was the Great Commission and the Spirit’s leading. They went as a team, not alone; and John Mark later left them — mission work is not easy, and it needs faithful workers."}, {"theme": "Paul's conversion — before, during, and after", "summary": "Before conversion, Saul was a zealous Pharisee who hated the church. He stood at Stephen’s stoning, voted against believers when they were put to death, and took letters to Damascus to arrest them and bring them bound to Jerusalem (Acts 7:58; 26:10; 22:5). He thought he was serving God. During the Damascus-road meeting, three things came together: a supernatural light from heaven — and he was blind three days (Acts 9:3, 9); a supernatural voice — “I am Jesus, whom you are persecuting” (Acts 9:5); and a command — go into the city, and you will be told what you must do (Acts 9:6). Conversion here is conviction, faith in Christ, and surrender: Lord, what do You want me to do? The men with him heard a noise but not the words; the Lord spoke to Saul in Hebrew. Afterward Ananias came, called him Brother Saul, and laid hands on him. Scales fell from his eyes; he was filled with the Holy Spirit, baptized, strengthened with food, and immediately preached Christ in the synagogues — that He is the Son of God (Acts 9:17–20). Hearers were amazed: this was the man who had destroyed those who called on that name. He then had a desert time in Arabia, taught by the Lord and separated from men before public work (Gal. 1:16–18). Later the persecutor became the persecuted, and the disciples let him down the wall in a basket (Acts 9:23–25). Saul is the pattern of a new believer: cleansed, filled, baptized, witnessing, and growing."}], "bigIdeas": ["Paul’s background has nine traits God later used: Jew of Benjamin (Phil. 3:5); Pharisee, blameless in the law; educated at Gamaliel’s feet (Acts 22:3); free-born Roman (Acts 22:27–28); a zealous persecutor; he voted for believers’ deaths (Acts 26:10); he stood at Stephen’s stoning (Acts 7:58); he carried letters to Damascus (Acts 22:5); and he most likely saw Christ in the flesh (2 Cor. 5:16).", "Conversion on the Damascus road is light, voice, and command. A supernatural light blinded him three days; a supernatural voice said, I am Jesus whom you are persecuting; and the command was, go into the city. Faithfulness in that first task is often the sign of long-range usefulness. Companions heard a noise, not the words — spoken in Hebrew (Acts 22:9).", "Ananias yielded three times: to the call, to the objection, and to the ministry. He laid hands on Saul and said, Brother Saul. That word “brother” is the gospel in one greeting. Saul then becomes the pattern new believer — healed, filled, baptized, strengthened, preaching, with hearers amazed (Acts 9:17–20).", "Paul’s desert years are Arabia, not a footnote in Philippians. Galatians 1:15–24 says God taught him, separate from men. Then the persecutor becomes the hunted — disciples let him down the Damascus wall in a basket (Acts 9:23–25; 2 Cor. 11:32–33).", "With Cornelius, God opens the doorway of salvation to the Gentiles. An honest seeker; an angel who does not preach but sends him to Peter; a sheet lowered three times — what God has cleansed do not call common (Acts 10). Gentiles receive the Spirit and baptism (Acts 10:44–48); Peter defends it in Acts 11.", "Oikos evangelism is reaching people for Christ through existing relationships — household, kin, the people already in the house. Cornelius’s house is the picture: the gospel walks in through a door God already opened.", "The first missionary journey begins about 45 A.D. from Antioch. The Spirit says, Separate Barnabas and Saul. The church fasts, prays, lays hands, and sends. They go Seleucia → Cyprus → Salamis, preaching in the synagogues, John Mark as helper. Foreign mission work begins with prayer and fasting — and John Mark does not stay to the finish."], "summary": "Saul’s conversion, Cornelius, and the first missionary journey. Paul’s background has nine traits God later used: Jew of Benjamin (Phil. 3:5); Pharisee, blameless in the law; educated at Gamaliel’s feet (Acts 22:3); free-born Roman (Acts…", "quickReview": ["Paul’s background has nine traits God later used: Jew of Benjamin (Phil. 3:5); Pharisee, blameless in the…", "Conversion on the Damascus road is light, voice, and command. A supernatural light blinded him three days; a…", "Ananias yielded three times: to the call, to the objection, and to the ministry. He laid hands on Saul and…", "Paul’s desert years are Arabia, not a footnote in Philippians. Galatians 1:15–24 says God taught him…", "With Cornelius, God opens the doorway of salvation to the Gentiles. An honest seeker; an angel who does not…"], "glossary": [{"term": "Brother", "meaning": "That word “brother” is the gospel in one greeting."}, {"term": "I gave my voice against them", "meaning": "Acts 26:10"}, {"term": "I am Jesus, whom you are persecuting", "meaning": "Acts 9:5"}, {"term": "Nine characteristics of Paul's background", "meaning": "Paul’s background has nine parts from the workbook. He was a Jew by birth — circumcised the eighth day, of Israel, of Benjamin, a Hebrew of the Hebrews (Phil…"}, {"term": "What Acts teaches about the First Missionary Journey", "meaning": "Acts 13–14 show how the first missionary journey began and what it teaches. It started around 45 A.D. from Antioch. While Barnabas, Simeon called Niger, Lucius…"}, {"term": "Paul's conversion — before, during, and after", "meaning": "Before conversion, Saul was a zealous Pharisee who hated the church. He stood at Stephen’s stoning, voted against believers when they were put to death, and…"}], "outline": ["Nine characteristics of Paul's background", "What Acts teaches about the First Missionary Journey", "Paul's conversion — before, during, and after"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Date", "value": "45 A.D. from Antioch"}, {"label": "Key claim", "value": "Paul’s background has nine traits God later used: Jew of Benjamin (Phil. 3:5); Pharisee, blameless in the law; educated at Gamaliel’s feet…"}, {"label": "Key claim", "value": "Conversion on the Damascus road is light, voice, and command. A supernatural light blinded him three days; a supernatural voice said, I am…"}, {"label": "Preach", "value": "Ananias yielded three times: to the call, to the objection, and to the ministry. He laid hands on Saul and said, Brother Saul. That word…"}], "pulpit": ["Saul then becomes the pattern new believer — healed, filled, baptized, strengthened, preaching, with hearers amazed (Acts 9:17–20).", "An honest seeker; an angel who does not preach but sends him to Peter; a sheet lowered three times — what God has cleansed do not call common (Acts 10).", "They go Seleucia → Cyprus → Salamis, preaching in the synagogues, John Mark as helper.", "They had a strategy — Seleucia, then Cyprus; at Salamis they preached the word of God in the synagogues of the Jews, with John Mark as helper (Acts 13:4–5)."], "compare": null}, {"id": "nt2-8", "number": 8, "title": "Acts Continued", "topic": "Jerusalem Council, Galatians, second journey, Spirit-led ministry, Athens, and Romans.", "quizScore": 100, "quizAttempts": 2, "status": "complete", "introCard": "Auto-graded 10/10 on authorized attempt 2 (attempt 101217). Attempt 1 was a blank stall at 0% — ignore for study content. Essays not graded yet. Attempts used: 2 of 3.", "takeaways": ["The Jerusalem Council rejected requiring Gentiles to become Jews first. Salvation is by grace through faith. Gentiles were asked to abstain from idolatry-related food, blood and strangled meat, and sexual immorality.", "Galatians contrasts law and faith. It was written to the churches in the Roman province of Galatia.", "On the second missionary journey, Paul took Silas while Barnabas took John Mark. The split did not stop the work — two teams went out.", "Paul discipled Timothy through Scripture, example, shared ministry, and practical prep. He circumcised Timothy so he could minister among the Jews — ministry access, not salvation or a forced Jewish identity.", "Spirit-led ministry includes planning, goals, strategy, open and closed doors, patience, visions, support, hindsight, and confirming circumstances. The Macedonia vision redirected them to Europe.", "Lydia was the first convert in Europe; the Philippian jailer came later. Prayer and praise still work under oppression.", "In Athens, begin where they are. Paul used the unknown God as a point of contact, then still preached the Creator, repentance, resurrection, and judgment.", "Romans teaches that sin is a universal problem for both the pagan and the religious person — justification by faith, and victory in the struggle."], "quiz": [{"q": "James, the human brother of Jesus, was the leader of the Jerusalem Church", "answer": "True", "why": "James, the human brother of Jesus, led the Jerusalem Church when the Council met."}, {"q": "Galatians was written to the churches in the Roman province of Galatia.", "answer": "True", "why": "Galatians is a letter to the churches in the Roman province of Galatia — law set against faith."}, {"q": "The Jerusalem Council concluded that new believers must first become Jews before they can be followers of Jesus.", "answer": "False", "why": "The Council rejected that. Salvation is by grace through faith, not by becoming a Jew first."}, {"q": "On the Second Missionary Journey, Paul took John Mark, while Barnabas took Silas.", "answer": "False", "why": "Paul took Silas; Barnabas took John Mark. Two teams went out after the split."}, {"q": "Paul circumcised Timothy in order to force him to have a Jewish identity.", "answer": "False", "why": "Circumcision was for ministry access among Jews, not salvation or a forced Jewish identity."}, {"q": "Hindsight helps us understand and interpret God's plan for our life", "answer": "True", "why": "One of the Spirit-led principles in Acts 16: hindsight helps us put the pieces together."}, {"q": "Sometimes circumstances confirm we are being led of the Spirit.", "answer": "True", "why": "Circumstances can confirm the Spirit’s leading — the trip to Neapolis and what followed."}, {"q": "The first convert in Europe was the Philippian jailer.", "answer": "False", "why": "Lydia was the first convert in Europe. The Philippian jailer came later."}, {"q": "When preaching to a secular crowd, we must begin where they are. (", "answer": "True", "why": "Athens: begin where they are. Paul used the unknown God as a point of contact."}, {"q": "Romans teaches that sin is a universal problem for both the pagan and religious person.", "answer": "True", "why": "Romans: sin is universal — for the pagan and the religious person alike."}], "essays": [{"theme": "How Paul discipled Timothy", "summary": "Paul found Timothy in Derbe and Lystra — a young man with a good testimony among the believers. His mother Eunice was a Jewess who believed, and his father was a Greek. Grandmother Lois and mother Eunice had taught him the Holy Scriptures and given him a sincere faith. Timothy had also seen Paul suffer when Paul was stoned at Lystra. After John Mark left, Paul invited Timothy to travel and minister with him. Paul had Timothy circumcised, not to save him or force a Jewish identity, but so the Jews would not be offended and Timothy could minister among them. Paul gave him the decrees from the Jerusalem church and trained him by serving beside him. Timothy became Paul’s son in the faith and a trusted helper. Through his help the churches were strengthened in the faith and increased in number."}, {"theme": "Ten principles on how to be led of the Spirit (Acts 16:6-11)", "summary": "The ten principles in Acts 16:6–11 are these: (1) Make a plan to carry out God’s work, but be willing for the Spirit to change it. (2) Have a clear goal of what you want to accomplish — Paul wanted to preach the Word. (3) Have a strategy. Paul planted churches in large cities, looked for places with a Jewish population, and looked for responsive people first. (4) Follow both open doors and closed doors. God can lead by giving an opportunity or by forbidding a way. (5) When the way is not clear, obey the last clear direction and wait on God instead of forcing a door. (6) Go as far as you can go. Paul continued to Troas, the farthest point he could reach. (7) God may lead by an unusual event or vision. Paul received the vision of the Macedonian man. (8) Take others with you for support. Luke, Timothy, Silas, and Paul went together, and the passage changes to “we.” (9) Hindsight helps us put the pieces together and understand God’s plan. (10) Circumstances can confirm the Spirit’s leading. The quick, straight trip to Neapolis and the events that followed confirmed the direction. Being led by the Spirit includes prayerful planning, obedience, patience, and checking our direction against God’s work."}, {"theme": "Paul’s experience in Athens (Acts 17:15-34)", "summary": "Paul’s experience in Athens teaches us to begin with people where they are. Athens was full of idols, and the people liked to discuss new ideas. Paul was troubled by the idols, but he still spoke respectfully. He reasoned with the Jews and Gentile worshipers in the synagogue, then spoke daily in the marketplace. He used the altar to the unknown God as a point of contact. He did not approve their idols; he used what they knew to explain the true God who made the world and is Lord of heaven and earth. He taught that God is near, that people must turn to Him, and that God will judge the world through the Man He raised from the dead. When Paul mentioned the resurrection, some mocked him, but others believed. This is contextualization: making contact with unsaved people and helping them give an honest hearing to the Gospel. Meet people where they are and lift them to the truth. Paul did not change the Gospel even though some called his approach a compromise."}], "bigIdeas": ["The Jerusalem Council rejected requiring Gentiles to become Jews first. Salvation is by grace through faith. Gentiles were asked to abstain from idolatry-related food, blood and strangled meat, and sexual immorality.", "Galatians contrasts law and faith. It was written to the churches in the Roman province of Galatia.", "On the second missionary journey, Paul took Silas while Barnabas took John Mark. The split did not stop the work — two teams went out.", "Paul discipled Timothy through Scripture, example, shared ministry, and practical prep. He circumcised Timothy so he could minister among the Jews — ministry access, not salvation or a forced Jewish identity.", "Spirit-led ministry includes planning, goals, strategy, open and closed doors, patience, visions, support, hindsight, and confirming circumstances. The Macedonia vision redirected them to Europe.", "Lydia was the first convert in Europe; the Philippian jailer came later. Prayer and praise still work under oppression.", "In Athens, begin where they are. Paul used the unknown God as a point of contact, then still preached the Creator, repentance, resurrection, and judgment.", "Romans teaches that sin is a universal problem for both the pagan and the religious person — justification by faith, and victory in the struggle."], "summary": "Jerusalem Council, Galatians, second journey, Spirit-led ministry, Athens, and Romans. The Jerusalem Council rejected requiring Gentiles to become Jews first. Salvation is by grace through faith. Gentiles were asked to abstain from idolatry-related food, blood and strangled meat, and sexual immorality.", "quickReview": ["The Jerusalem Council rejected requiring Gentiles to become Jews first. Salvation is by grace through faith…", "Galatians contrasts law and faith. It was written to the churches in the Roman province of Galatia.", "On the second missionary journey, Paul took Silas while Barnabas took John Mark. The split did not stop the…", "Paul discipled Timothy through Scripture, example, shared ministry, and practical prep. He circumcised…", "Spirit-led ministry includes planning, goals, strategy, open and closed doors, patience, visions, support…"], "glossary": [{"term": "How Paul discipled Timothy", "meaning": "Paul found Timothy in Derbe and Lystra — a young man with a good testimony among the believers. His mother Eunice was a Jewess who believed, and his father was…"}, {"term": "Ten principles on how to be led of the Spirit (Acts 16:", "meaning": "The ten principles in Acts 16:6–11 are these: (1) Make a plan to carry out God’s work, but be willing for the Spirit to change it. (2) Have a clear goal of…"}, {"term": "Paul’s experience in Athens (Acts 17:15-34)", "meaning": "Paul’s experience in Athens teaches us to begin with people where they are. Athens was full of idols, and the people liked to discuss new ideas. Paul was…"}, {"term": "Salvation", "meaning": "Salvation is by grace through faith"}, {"term": "Lydia", "meaning": "Lydia is the first convert in Europe; the Philippian jailer came later"}, {"term": "Justification", "meaning": "Romans teaches that sin is a universal problem for both the pagan and the religious person — justification by faith, and victory in the struggle."}], "outline": ["How Paul discipled Timothy", "Ten principles on how to be led of the Spirit (Acts 16:6-11)", "Paul’s experience in Athens (Acts 17:15-34)"], "mustKnow": [{"label": "Quiz score", "value": "100% (2 attempts)"}, {"label": "Audience", "value": "churches in the Roman province of Galatia"}, {"label": "Reject", "value": "The Jerusalem Council rejected requiring Gentiles to become Jews first. Salvation is by grace through faith. Gentiles were asked to abstain…"}, {"label": "Key claim", "value": "Galatians contrasts law and faith. It was written to the churches in the Roman province of Galatia."}, {"label": "Key claim", "value": "On the second missionary journey, Paul took Silas while Barnabas took John Mark. The split did not stop the work — two teams went out."}], "pulpit": ["Paul used the unknown God as a point of contact, then still preached the Creator, repentance, resurrection, and judgment.", "(2) Have a clear goal of what you want to accomplish — Paul wanted to preach the Word."], "compare": null}, {"id": "nt2-9", "number": 9, "title": "Acts Continued", "topic": "Vow in the Temple, Felix–Festus–Agrippa, Rome, and the Prison/Pastoral letters.", "quizScore": 60, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 6/10 on attempt 1. Essays not graded yet. Attempts used: 1 of 3 — a second attempt is not assumed. Review the four misses below before any retry.", "takeaways": ["In Jerusalem Paul delivered a financial gift so large it took a wagon, then paid the purification expenses of four men and took a vow with them. He used freedom with wisdom to quiet the rumor that he taught Jews to forsake Moses — without changing the gospel.", "It is wise not to become a martyr when it is not necessary. Paul spoke to the commander in Greek, to the crowd in Hebrew, and claimed Roman citizenship before they could scourge an uncondemned man (Acts 22:25).", "Before the Sanhedrin, High Priest Ananias had Paul struck. This was not their first meeting. Paul then divided Pharisees and Sadducees over the resurrection, and the Lord promised he would also witness in Rome.", "Paul was held in prison under Felix, Festus, and Agrippa. Felix delayed — “when I have a convenient time.” Festus wanted favor with the Jews, so Paul appealed to Caesar. Agrippa said, “You almost persuade me to become a Christian.”", "In Rome Paul was considered a political prisoner: house arrest with a soldier, two years in his own rented house, preaching the kingdom with confidence, no one forbidding him. Acts ends unfinished — the gospel still moving toward the uttermost part of the earth.", "Prison letters from Rome (about 62 A.D.): Ephesians was meant to be circulated among churches; Philippi’s problem was not doctrinal error but disunity; Colossians was written while Paul was a prisoner; Philemon was a rich Christian master, not a poor slave — Onesimus was the runaway.", "The Pastoral Epistles (1–2 Timothy, Titus) train young ministers in doctrine, church order, and godly character. Second Timothy is Paul’s last letter from his last imprisonment: preach the Word; endure hardship; come soon."], "quiz": [{"q": "Paul's financial gift to the church was so large, it took a wagon to deliver it.", "answer": "True", "why": "Miss — Jay-R chose False. The workbook: the gift was so large it took a wagon. Moodle correct is True."}, {"q": "It is wise not to become a martyr when it is not necessary.", "answer": "True", "why": "Paul claimed Roman citizenship before the scourge (Acts 22:25). The principle: do not become a martyr when it is not necessary."}, {"q": "When Paul stood before the Sanhedrin, he met the High Priest, Ananias, for the first time.", "answer": "False", "why": "Miss — Jay-R chose True. Moodle: False. This was not a first meeting. Paul said he did not realize the man who ordered him struck was the high priest (Acts 23:5) — that is not a first introduction."}, {"q": "Paul was held in prison under Felix, Festus, and Agrippa.", "answer": "True", "why": "Miss — Jay-R chose False. The lesson walks the hearings under Felix, Festus, and Agrippa while Paul remained a prisoner. Moodle correct is True."}, {"q": "In Rome, Paul was considered a political prisoner.", "answer": "True", "why": "Miss — Jay-R chose False. The workbook: he was a political prisoner — permitted to dwell by himself with the soldier who guarded him (Acts 28:16). Moodle correct is True."}, {"q": "The book of Ephesians was intended to be circulated and read among churches.", "answer": "True", "why": "Ephesians is a circular letter (Col. 4:16) — no personal references, no one local problem. Written to be read among the churches."}, {"q": "The big problem in Philippi, was doctrinal error.", "answer": "False", "why": "Philippians has no serious doctrinal or lifestyle problem. The issue was disunity (Phil. 4:2–3)."}, {"q": "The book of Colossians was written while Paul was a prisoner in Rome.", "answer": "True", "why": "Colossians is a prison epistle, written from Rome about 62 A.D. and delivered with Ephesians and Philemon."}, {"q": "Philemon was a poor Christian slave.", "answer": "False", "why": "Philemon was a rich Christian who owned slaves; the church met in his home. Onesimus was the runaway slave."}, {"q": "Second Timothy was Paul's last letter written from his last imprisonment.", "answer": "True", "why": "The workbook heading: Paul writes his last letter from his last imprisonment. 2 Timothy is that letter."}], "essays": [{"theme": "Paul's vow in the Temple", "summary": "Paul’s vow shows that Christian freedom should be used with wisdom and love. He was willing to follow a Jewish purification custom and pay the expenses for four men, even though the gospel did not depend on that custom. He tried to remove a needless offense and keep peace with Jewish believers. At the same time, he did not change his message about Christ or earn salvation by the vow. We also learn not to seek suffering or become a martyr when it is not necessary. Serve people and witness faithfully, and trust God when suffering really comes."}, {"theme": "Five lessons from Paul's ministry in Rome", "summary": "Five lessons from Paul’s ministry in Rome: (1) Paul continued serving while under house arrest, with only a soldier guarding him. (2) He met with the Jewish leaders and explained God’s kingdom and Jesus from morning until evening. (3) There was no proven accusation from Judea against him. (4) His ministry was not stopped by chains; he received people in his rented house and preached with confidence. (5) Acts ends with the gospel still moving toward the uttermost part of the earth, so the church’s mission continues."}, {"theme": "Pastoral Epistles (1–2 Timothy, Titus)", "summary": "Dr. Towns teaches that the Pastoral Epistles are Paul’s letters about church leadership and the work of young ministers. First Timothy was written to Timothy at Ephesus, Paul’s true son in the faith. Paul gave him authority to correct false teachers, teach sound doctrine, and lead the church. Titus was sent to Crete to set the churches in order, appoint elders, and teach believers how to live. The letters speak about the qualifications and conduct of pastors and the good works expected from God’s people. Second Timothy was Paul’s last letter, written from his final imprisonment in Rome. Paul encouraged Timothy to endure hardship, keep preaching the Word, and come soon, bringing his cloak, books, and parchments. Together these letters call a pastor to faithful doctrine, godly character, and perseverance in ministry."}], "bigIdeas": ["In Jerusalem Paul delivered a financial gift so large it took a wagon, then paid the purification expenses of four men and took a vow with them. He used freedom with wisdom to quiet the rumor that he taught Jews to forsake Moses — without changing the gospel.", "It is wise not to become a martyr when it is not necessary. Paul spoke to the commander in Greek, to the crowd in Hebrew, and claimed Roman citizenship before they could scourge an uncondemned man (Acts 22:25).", "Before the Sanhedrin, High Priest Ananias had Paul struck. This was not their first meeting. Paul then divided Pharisees and Sadducees over the resurrection, and the Lord promised he would also witness in Rome.", "Paul was held in prison under Felix, Festus, and Agrippa. Felix delayed — “when I have a convenient time.” Festus wanted favor with the Jews, so Paul appealed to Caesar. Agrippa said, “You almost persuade me to become a Christian.”", "In Rome Paul was considered a political prisoner: house arrest with a soldier, two years in his own rented house, preaching the kingdom with confidence, no one forbidding him. Acts ends unfinished — the gospel still moving toward the uttermost part of the earth.", "Prison letters from Rome (about 62 A.D.): Ephesians was meant to be circulated among churches; Philippi’s problem was not doctrinal error but disunity; Colossians was written while Paul was a prisoner; Philemon was a rich Christian master, not a poor slave — Onesimus was the runaway.", "The Pastoral Epistles (1–2 Timothy, Titus) train young ministers in doctrine, church order, and godly character. Second Timothy is Paul’s last letter from his last imprisonment: preach the Word; endure hardship; come soon."], "summary": "Vow in the Temple, Felix–Festus–Agrippa, Rome, and the Prison/Pastoral letters. In Jerusalem Paul delivered a financial gift so large it took a wagon, then paid the purification expenses of four men and took a vow with them. He used freedom with wisdom to…", "quickReview": ["Miss: True — Paul's financial gift to the church was so large, it took a wagon to deliver it.", "Miss: False — When Paul stood before the Sanhedrin, he met the High Priest, Ananias, for the first time.", "Miss: True — Paul was held in prison under Felix, Festus, and Agrippa.", "Miss: True — In Rome, Paul was considered a political prisoner.", "In Jerusalem Paul delivered a financial gift so large it took a wagon, then paid the purification expenses of…"], "glossary": [{"term": "When I have a convenient time", "meaning": "Felix delayed — “when I have a convenient time.” Festus wanted favor with the Jews, so Paul appealed to Caesar."}, {"term": "Paul's vow in the Temple", "meaning": "Paul’s vow shows that Christian freedom should be used with wisdom and love. He was willing to follow a Jewish purification custom and pay the expenses for…"}, {"term": "Five lessons from Paul's ministry in Rome", "meaning": "Five lessons from Paul’s ministry in Rome: (1) Paul continued serving while under house arrest, with only a soldier guarding him. (2) He met with the Jewish…"}, {"term": "Pastoral Epistles (1–2 Timothy, Titus)", "meaning": "Dr. Towns teaches that the Pastoral Epistles are Paul’s letters about church leadership and the work of young ministers. First Timothy was written to Timothy…"}, {"term": "Paul", "meaning": "Paul is held in prison under Felix, Festus, and Agrippa"}, {"term": "Rome Paul", "meaning": "Rome Paul is considered a political prisoner: house arrest with a soldier, two years in his own rented house, pre"}, {"term": "Ephesians", "meaning": "Ephesians is meant to be circulated among churches; Philippi’s problem was not doctrinal error but disunity; Colo"}], "outline": ["Paul's vow in the Temple", "Five lessons from Paul's ministry in Rome", "Pastoral Epistles (1–2 Timothy, Titus)"], "mustKnow": [{"label": "Quiz score", "value": "60% (1 attempt)"}, {"label": "Audience", "value": "Timothy at Ephesus, Paul’s true son in the faith"}, {"label": "Date", "value": "62 A.D.): Ephesians was meant to be c"}, {"label": "Key claim", "value": "In Jerusalem Paul delivered a financial gift so large it took a wagon, then paid the purification expenses of four men and took a vow with…"}, {"label": "Key claim", "value": "It is wise not to become a martyr when it is not necessary. Paul spoke to the commander in Greek, to the crowd in Hebrew, and claimed Roman…"}, {"label": "Key claim", "value": "Before the Sanhedrin, High Priest Ananias had Paul struck. This was not their first meeting. Paul then divided Pharisees and Sadducees over…"}, {"label": "Miss drill 1", "value": "True: Paul's financial gift to the church was so large, it took a wagon to deliver it. — Miss — Jay-R chose False. The workbook: the gift was so large it took…"}, {"label": "Miss drill 2", "value": "False: When Paul stood before the Sanhedrin, he met the High Priest, Ananias, for the first time. — Miss — Jay-R chose True. Moodle: False. This was not a…"}], "pulpit": ["In Rome Paul was considered a political prisoner: house arrest with a soldier, two years in his own rented house, preaching the kingdom with confidence, no one…", "The Pastoral Epistles (1–2 Timothy, Titus) train young ministers in doctrine, church order, and godly character.", "Second Timothy is Paul’s last letter from his last imprisonment: preach the Word; endure hardship; come soon.", "(4) His ministry was not stopped by chains; he received people in his rented house and preached with confidence."], "compare": [{"title": "Pharisees and Sadducees", "points": ["Paul then divided Pharisees and Sadducees over the resurrection, and the Lord promised he would also witness in Rome.", "Paul then divided Pharisees and Sadducees over the resurrection, and the Lord promised he would also witness in Rome."]}]}, {"id": "nt2-10", "number": 10, "title": "The Book of Hebrews", "topic": "Christ superior — hold fast; with James and Peter on faith, works, and suffering.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 9/10 on attempt 1. Essays not graded yet. Attempts used: 1 of 3 — no retry planned unless Jay-R asks. One miss: Q4.", "takeaways": ["The authorship of Hebrews is disputed. The lesson does not say everyone knows Paul wrote it. The letter still preaches Christ as better, and the church still reads it as Scripture.", "Hebrews was written to Jewish Christians involved in Temple worship. A constant temptation existed for them to return to Old Testament ways — so the call is to hold fast to Christ, not go back.", "Christ is superior: better Son and message, better High Priest, better sacrifice, better covenant, better promises, better mediator. Preach Him; do not send people back to the old system.", "Six dangers of turning back (not twelve): neglect of so great salvation, unbelief and a hardened heart, disobedience, falling away after much light, willful sin, and refusing God’s voice from heaven.", "James is the brother of Jesus and a leader of the church in Jerusalem — not John’s brother among the twelve. His letter is practical: real faith shows itself in works and daily conduct.", "Peter was considered the apostle to the Jews (Paul to the Gentiles) and the leader of the apostles. Some traditions contend that he went to England. Second Peter warns against false teachers; 2 Timothy and 2 Peter share some themes.", "Peter teaches suffering under persecution: it is not strange; faith is tested like gold; suffer for righteousness without shame; follow Christ’s example; glorify God; commit your soul to the faithful Creator and keep doing good; hope for the coming glory."], "quiz": [{"q": "Everyone knows without a doubt that Paul wrote Hebrews.", "answer": "False", "why": "Authorship is disputed. The lesson does not treat Pauline authorship as certain."}, {"q": "Hebrews was written to Jewish Christians who were involved in Temple worship.", "answer": "True", "why": "The workbook: written to Jewish Christians involved in Temple worship."}, {"q": "A constant temptation existed for the Jewish believers to return to the Old Testament ways.", "answer": "True", "why": "Jewish believers were tempted to go back to Old Testament ways; Hebrews calls them to hold fast."}, {"q": "Twelve times in Hebrews believers are warned against turning back.", "answer": "False", "why": "Miss — Jay-R chose True. Workbook: six warning passages, not twelve. Moodle correct is False."}, {"q": "The author of James was John's brother, one of the twelve.", "answer": "False", "why": "The author is James the brother of Jesus, a Jerusalem leader — not James the brother of John, one of the twelve."}, {"q": "Peter was considered the apostle to the Jews while Paul was considered the apostle to the Gentiles.", "answer": "True", "why": "Peter was considered the apostle to the Jews; Paul the apostle to the Gentiles."}, {"q": "Peter was considered the leader of the apostles.", "answer": "True", "why": "The workbook treats Peter as the leader of the apostles."}, {"q": "Some traditions contend that Peter went to England.", "answer": "True", "why": "Some traditions contend that Peter went to England."}, {"q": "Peter's second letter was written to warn against false teachers", "answer": "True", "why": "2 Peter was written to warn against false teachers."}, {"q": "2 Timothy and 2 Peter are similar in some of their themes.", "answer": "True", "why": "The lesson notes that 2 Timothy and 2 Peter share some themes."}], "essays": [{"theme": "Hebrews' six dangers of returning to the OT", "summary": "Hebrews gives six serious dangers of turning back from Christ to the Old Testament system: (1) neglecting the great salvation Christ has provided; (2) unbelief and a hardened heart, so a person does not enter God’s rest; (3) failing to grow and falling away after receiving much light; (4) treating Christ’s sacrifice as common and choosing willful sin; (5) drawing back when persecution comes instead of holding fast; (6) refusing God’s voice and grace, which brings His judgment. These warnings show that the old covenant could not save us. Look to Jesus, our perfect High Priest, and continue in faith."}, {"theme": "Introductory material of James", "summary": "James introduces himself as a servant of God and of the Lord Jesus Christ. He writes to the twelve tribes scattered abroad — Jewish believers living in different places. The writer is James, the brother of Jesus and a leader of the church in Jerusalem, not James the brother of John who was one of the twelve. The letter is practical: trials, wisdom, hearing and doing the Word, caring for the poor, controlling the tongue, humility, prayer, and faith that shows itself by works. Real faith should be seen in daily Christian conduct."}, {"theme": "Peter's seven teachings on suffering during persecution", "summary": "Peter’s seven teachings for believers who suffer during persecution: (1) suffering for Christ is not strange — it can be part of the Christian calling; (2) trials test and prove the genuineness of faith like fire tests gold; (3) suffering for righteousness is a blessing, not a reason for shame; (4) follow Christ’s example — He suffered without sin and did not answer evil with evil; (5) do not be ashamed to bear Christ’s name, but glorify God in it; (6) commit your souls to the faithful Creator and keep doing what is right; (7) rejoice in hope, trust God’s care, and look for the coming glory — God will judge rightly and restore His people. Stay humble, faithful, and prayerful instead of giving up."}], "bigIdeas": ["The authorship of Hebrews is disputed. The lesson does not say everyone knows Paul wrote it. The letter still preaches Christ as better, and the church still reads it as Scripture.", "Hebrews was written to Jewish Christians involved in Temple worship. A constant temptation existed for them to return to Old Testament ways — so the call is to hold fast to Christ, not go back.", "Christ is superior: better Son and message, better High Priest, better sacrifice, better covenant, better promises, better mediator. Preach Him; do not send people back to the old system.", "Six dangers of turning back (not twelve): neglect of so great salvation, unbelief and a hardened heart, disobedience, falling away after much light, willful sin, and refusing God’s voice from heaven.", "James is the brother of Jesus and a leader of the church in Jerusalem — not John’s brother among the twelve. His letter is practical: real faith shows itself in works and daily conduct.", "Peter was considered the apostle to the Jews (Paul to the Gentiles) and the leader of the apostles. Some traditions contend that he went to England. Second Peter warns against false teachers; 2 Timothy and 2 Peter share some themes.", "Peter teaches suffering under persecution: it is not strange; faith is tested like gold; suffer for righteousness without shame; follow Christ’s example; glorify God; commit your soul to the faithful Creator and keep doing good; hope for the coming glory."], "summary": "Christ superior — hold fast; with James and Peter on faith, works, and suffering. The authorship of Hebrews is disputed. The lesson does not say everyone knows Paul wrote it. The letter still preaches Christ as better, and the church still reads it as Scripture.", "quickReview": ["Miss: False — Twelve times in Hebrews believers are warned against turning back.", "The authorship of Hebrews is disputed. The lesson does not say everyone knows Paul wrote it. The letter still…", "Hebrews was written to Jewish Christians involved in Temple worship. A constant temptation existed for them…", "Christ is superior: better Son and message, better High Priest, better sacrifice, better covenant, better…", "Six dangers of turning back (not twelve): neglect of so great salvation, unbelief and a hardened heart…"], "glossary": [{"term": "Hebrews' six dangers of returning to the OT", "meaning": "Hebrews gives six serious dangers of turning back from Christ to the Old Testament system: (1) neglecting the great salvation Christ has provided; (2) unbelief…"}, {"term": "Introductory material of James", "meaning": "James introduces himself as a servant of God and of the Lord Jesus Christ. He writes to the twelve tribes scattered abroad — Jewish believers living in…"}, {"term": "Peter's seven teachings on suffering during persecution", "meaning": "Peter’s seven teachings for believers who suffer during persecution: (1) suffering for Christ is not strange — it can be part of the Christian calling; (2)…"}, {"term": "Hebrews", "meaning": "Hebrews is disputed"}, {"term": "James", "meaning": "James is the brother of Jesus and a leader of the church in Jerusalem — not John’s brother among the twelve"}, {"term": "Peter", "meaning": "Peter is considered the apostle to the Jews (Paul to the Gentiles) and the leader of the apostles"}, {"term": "Covenant", "meaning": "Christ is superior: better Son and message, better High Priest, better sacrifice, better covenant, better promises, better mediator."}], "outline": ["Hebrews' six dangers of returning to the OT", "Introductory material of James", "Peter's seven teachings on suffering during persecution"], "mustKnow": [{"label": "Quiz score", "value": "90% (1 attempt)"}, {"label": "Audience", "value": "Jewish Christians involved in Temple worship"}, {"label": "Portrait", "value": "better"}, {"label": "Preach", "value": "The authorship of Hebrews is disputed. The lesson does not say everyone knows Paul wrote it. The letter still preaches Christ as better…"}, {"label": "Key claim", "value": "Hebrews was written to Jewish Christians involved in Temple worship. A constant temptation existed for them to return to Old Testament ways…"}, {"label": "Covenant", "value": "Christ is superior: better Son and message, better High Priest, better sacrifice, better covenant, better promises, better mediator. Preach…"}, {"label": "Miss drill 1", "value": "False: Twelve times in Hebrews believers are warned against turning back. — Miss — Jay-R chose True. Workbook: six warning passages, not twelve. Moodle correct…"}], "compare": [{"title": "Six dangers of turning back (not twelve)", "points": ["neglect of so great salvation", "unbelief", "a hardened heart", "disobedience", "falling away after much light", "willful sin", "and refusing God’s voice from heaven"]}, {"title": "Clarify", "points": ["James is the brother of Jesus and a leader of the church in Jerusalem", "Not: John’s brother among the twelve. His letter is practical: real faith shows itself in works and daily conduct."]}], "pulpit": ["The letter still preaches Christ as better, and the church still reads it as Scripture.", "Preach Him; do not send people back to the old system."]}, {"id": "nt2-11", "number": 11, "title": "The Book of 1-3 John and Jude", "topic": "Fellowship, assurance, and a short warning against apostasy.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 9/10 on attempt 1. Essays not graded yet. Attempts used: 1 of 3. One miss: Q2 (key word is not \"Believe\").", "takeaways": ["John writes as one who knew Jesus intimately — heard, seen, and handled Him — at a time when he appears to have been the only surviving apostle.", "The key word in 1 John is not “Believe.” Moodle marked that claim False. The letter’s burden is fellowship, walking in the light, and confessing that Christ has come in the flesh.", "1 John combats Gnostic/Docetic heresy: teachers who treated matter as evil, denied that Christ truly came in the flesh, claimed special knowledge, and separated from the church.", "In 1 John, sin is treated as a child’s offense against his father: do not practice sin, do not sin, know we are sinners, confess, and receive the Father’s immediate forgiveness and cleansing.", "A person can know they are saved in more than two ways. The foundation for true doctrine is a proper understanding of Jesus Christ.", "3 John condemns those who destroy the faith with struggles for supremacy in the church and earthly pride.", "Jude’s message is a warning against immorality and apostasy — not directed only to believers in Jerusalem. The letter begins and ends with assurance."], "quiz": [{"q": "The writer of 1 John knew Jesus intimately.", "answer": "True", "why": "John writes as an eyewitness who knew Jesus intimately."}, {"q": "The key word in 1 John is \"Believe.\"", "answer": "False", "why": "Miss — Jay-R chose True. Moodle: the key word is not \"Believe.\" Correct answer is False."}, {"q": "1 John was written in a time when John appears to have been the only surviving apostle.", "answer": "True", "why": "The lesson places 1 John when John appears to have been the only surviving apostle."}, {"q": "In 1 John, sin is to be treated as a child's offense against his father.", "answer": "True", "why": "The workbook treats sin as a child’s offense against his father, not a stranger’s crime."}, {"q": "1 John provides only two reasons of how a person can know they are saved.", "answer": "False", "why": "There are more than two ways a person can know they are saved."}, {"q": "The foundation for true doctrine is a proper understanding of Jesus Christ", "answer": "True", "why": "True doctrine rests on a proper understanding of Jesus Christ."}, {"q": "3 John condemns those who destroy the faith with struggles for supremacy in the church and earthly pride.", "answer": "True", "why": "3 John condemns struggles for supremacy and earthly pride that destroy the faith."}, {"q": "Jude's message was a warning against immorality and apostasy.", "answer": "True", "why": "Jude warns the church against immorality and apostasy."}, {"q": "Jude's message was directed specifically and only to believers in Jerusalem", "answer": "False", "why": "Jude is not directed specifically and only to believers in Jerusalem."}, {"q": "Jude begins and ends with assurance.", "answer": "True", "why": "Jude opens and closes with assurance for the saints."}], "essays": [{"theme": "Heresy combated by 1 John (Gnostic/Docetic)", "summary": "1 John combats early Gnostic teaching — the claim that spirit is good but matter is evil, and that Christ did not truly come in the flesh. Some denied the reality of Jesus’ body (Docetism); others denied His true humanity; others separated the divine Christ from the human Jesus. These teachers claimed special knowledge and separated from the church. John answers with apostolic eyewitness: Jesus was heard, seen, and handled. Believers must confess that Jesus Christ has come in the flesh. He calls the church to walk in the light, in righteousness, in love, and in fellowship, so that those who believe can know they have eternal life and live in victorious fellowship with God."}, {"theme": "Five ways 1 John treats sin as a child's offense against his father", "summary": "1 John treats sin as a child’s offense against his father in five ways: (1) He expects the believer not to practice sin — whoever has been born of God does not live in a settled pattern of sin (1 John 3:9). (2) He expects us not to sin: “My little children, these things I write to you, that you may not sin” (2:1). (3) He knows we are sinners, both by nature and by sinful acts; denying this deceives us and means God’s Word is not in us (1:8, 10). (4) He expects us to confess our sins (1:9). (5) When we walk in the light and confess, God immediately forgives and cleanses our sin through the blood of Jesus Christ (1:7, 9)."}, {"theme": "Seven ways/proofs of assurance of salvation", "summary": "1 John gives seven proofs that can give a person confidence they are saved: (1) Have a Savior — having the Son means having life; without the Son there is no life (1 John 5:12). (2) Have the witness of God, especially the testimony God has given of His Son (5:9-10). (3) Walk in the light: a saved person turns from darkness and lives honestly before God (1:7). (4) Obey God’s commandments: keeping His word shows that we know Him (2:3-5). (5) Love other Christians: love for the brethren is evidence that we have passed from death to life (3:14). (6) Believe that Jesus is the Christ and that He came in the flesh; faith in the Son gives eternal life (4:2; 5:1, 12). (7) Have the Spirit’s witness and confidence in prayer: the Holy Spirit confirms that we belong to God, and we can come to Him knowing He hears us (3:24; 5:14-15). These proofs are not a claim of being perfect. They give a believer confidence while he continues to walk with Christ."}], "bigIdeas": ["John writes as one who knew Jesus intimately — heard, seen, and handled Him — at a time when he appears to have been the only surviving apostle.", "The key word in 1 John is not “Believe.” Moodle marked that claim False. The letter’s burden is fellowship, walking in the light, and confessing that Christ has come in the flesh.", "1 John combats Gnostic/Docetic heresy: teachers who treated matter as evil, denied that Christ truly came in the flesh, claimed special knowledge, and separated from the church.", "In 1 John, sin is treated as a child’s offense against his father: do not practice sin, do not sin, know we are sinners, confess, and receive the Father’s immediate forgiveness and cleansing.", "A person can know they are saved in more than two ways. The foundation for true doctrine is a proper understanding of Jesus Christ.", "3 John condemns those who destroy the faith with struggles for supremacy in the church and earthly pride.", "Jude’s message is a warning against immorality and apostasy — not directed only to believers in Jerusalem. The letter begins and ends with assurance."], "summary": "Fellowship, assurance, and a short warning against apostasy. John writes as one who knew Jesus intimately — heard, seen, and handled Him — at a time when he appears to have been the only surviving apostle.", "quickReview": ["Miss: False — The key word in 1 John is \"Believe.\"", "John writes as one who knew Jesus intimately — heard, seen, and handled Him — at a time when he appears to…", "The key word in 1 John is not “Believe.” Moodle marked that claim False. The letter’s burden is fellowship…", "1 John combats Gnostic/Docetic heresy: teachers who treated matter as evil, denied that Christ truly came in…", "In 1 John, sin is treated as a child’s offense against his father: do not practice sin, do not sin, know we…"], "glossary": [{"term": "Believe", "meaning": "The key word in 1 John is not “Believe.” Moodle marked that claim False."}, {"term": "Heresy combated by 1 John (Gnostic/Docetic)", "meaning": "1 John combats early Gnostic teaching — the claim that spirit is good but matter is evil, and that Christ did not truly come in the flesh. Some denied the…"}, {"term": "Five ways 1 John treats sin as a child's offense agains", "meaning": "1 John treats sin as a child’s offense against his father in five ways: (1) He expects the believer not to practice sin — whoever has been born of God does not…"}, {"term": "Seven ways/proofs of assurance of salvation", "meaning": "1 John gives seven proofs that can give a person confidence they are saved: (1) Have a Savior — having the Son means having life; without the Son there is no…"}, {"term": "John", "meaning": "John is not “Believe"}], "outline": ["Heresy combated by 1 John (Gnostic/Docetic)", "Five ways 1 John treats sin as a child's offense against his father", "Seven ways/proofs of assurance of salvation"], "mustKnow": [{"label": "Quiz score", "value": "90% (1 attempt)"}, {"label": "Key word", "value": "in 1 John is not “Believe"}, {"label": "Key claim", "value": "John writes as one who knew Jesus intimately — heard, seen, and handled Him — at a time when he appears to have been the only surviving…"}, {"label": "Reject", "value": "The key word in 1 John is not “Believe.” Moodle marked that claim False. The letter’s burden is fellowship, walking in the light, and…"}, {"label": "Key claim", "value": "1 John combats Gnostic/Docetic heresy: teachers who treated matter as evil, denied that Christ truly came in the flesh, claimed special…"}, {"label": "Miss drill 1", "value": "False: The key word in 1 John is \"Believe.\" — Miss — Jay-R chose True. Moodle: the key word is not \"Believe.\" Correct answer is False."}], "compare": [{"title": "Clarify", "points": ["Jude’s message is a warning against immorality and apostasy", "Not: directed only to believers in Jerusalem. The letter begins and ends with assurance."]}], "pulpit": ["The key word in 1 John is not “Believe.” Moodle marked that claim False. The letter’s burden is fellowship, walking in the light…", "1 John combats Gnostic/Docetic heresy: teachers who treated matter as evil, denied that Christ truly came in the flesh, claimed…", "In 1 John, sin is treated as a child’s offense against his father: do not practice sin, do not sin, know we are sinners, confess…"]}, {"id": "nt2-12", "number": 12, "title": "The Book of Revelation", "topic": "The unveiling — churches, Rapture, Tribulation, Millennium, and the last Heaven.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10 on attempt 1. Essays not graded yet. Attempts used: 1 of 3. Course total 94%.", "takeaways": ["The key word in Revelation is “Revelation” — the unveiling of Jesus Christ. Chapters 2–3 send messages to seven churches and give a picture of church history.", "Before Jesus returns: deception (false Christs and date-setters), wars and rumors of wars, natural disasters that shake politics, a church that grows cold and compromises (not stronger in evangelism), sin treated as normal, exploding knowledge, Jews returning, Israel re-established with Jerusalem as capital, and accelerating apostasy.", "At the Rapture, Christ appears in the air with a shout and trumpet; the church is caught up; the living are transformed into Christ’s likeness; the dead in Christ rise; God’s restraint against sin is removed; those left behind believe a lie.", "After the Rapture, all believers will see the throne and God — a settled hope for the church caught up.", "The World Ruler launches a “substitute church” with signs and wonders (including a counterfeit resurrection), forms an unholy trinity with Satan and the False Prophet, demands a mark, and the Anti-Christ makes a covenant with Israel.", "The Great Tribulation is not three and a half weeks. The Millennium is a thousand years of Christ’s reign on earth.", "In the fourth (future) Heaven there will be no more temple, sun, tears, death, or night — God Himself is the light and the dwelling."], "quiz": [{"q": "The key word in Revelation is \"Revelation.\"", "answer": "True", "why": "The book’s key word is Revelation — the unveiling of Jesus Christ."}, {"q": "In chapters 2 and 3, seven churches receive messages from Jesus.", "answer": "True", "why": "Revelation 2–3: seven churches receive messages from Jesus; a picture of church history."}, {"q": "Prior to Jesus' return, the church will grow stronger in evangelism.", "answer": "False", "why": "Workbook: the church grows cold and compromises — not stronger in evangelism. Moodle UI truncated the stem."}, {"q": "Saved people at the time of the Rapture will be transformed into the likeness of Christ.", "answer": "True", "why": "At the Rapture the living saved are transformed into Christ’s likeness. Moodle UI truncated the stem."}, {"q": "After the Rapture, all believers will see the throne and God.", "answer": "True", "why": "After the Rapture, all believers will see the throne and God."}, {"q": "After the Rapture, the world ruler will,launch his \"substitute church.\"", "answer": "True", "why": "Moodle’s comma typo kept (will,launch). After the Rapture the world ruler launches his substitute church with signs and wonders."}, {"q": "After the Rapture, the Anti-Christ will make a covenant with Israel.", "answer": "True", "why": "After the Rapture the Anti-Christ makes a covenant with Israel."}, {"q": "The Great Tribulation will last for three and a half weeks.", "answer": "False", "why": "The Great Tribulation is not three and a half weeks."}, {"q": "The Millennium will last a thousand years.", "answer": "True", "why": "The Millennium is a thousand-year reign of Christ."}, {"q": "In the fourth Heaven, there will be no more temple, sun, tears, death, or night.", "answer": "True", "why": "In the fourth (future) Heaven: no temple, sun, tears, death, or night."}], "essays": [{"theme": "What will the world be like right before Jesus returns?", "summary": "Right before Jesus returns, deception will increase as false Christs and date-setters arise. Wars and rumors of wars and their stressful problems will intensify, and natural disasters will affect political stability. The New Testament church will grow cold to spiritual things, compromise its moral belief, and become less effective in influencing cultures. People will become accustomed to sin, knowledge will explode, Jews will return to Palestine, Israel will be re-established as a nation, Jerusalem will again be the capital of Israel, and apostasy will accelerate. It is a gathering storm: we cannot say when, but we know it is coming."}, {"theme": "What will happen at the moment of the Rapture?", "summary": "At the Rapture, Jesus Christ will appear in the air with a shout and the sound of a trumpet, and the church will be caught up. Saved people will be transformed into the likeness of Jesus Christ, and Christians who died in the church age will be resurrected. God will remove His restraining influence against sin, and those remaining behind will be deceived so that they believe a lie."}, {"theme": "After the Rapture, how will the World Ruler launch his \"Substitute Church?\"", "summary": "The World Ruler will launch a substitute church through signs and wonders that mimic Jesus Christ, especially a counterfeit resurrection. He will operate as part of an unholy trinity with Satan and the False Prophet, demand an outward mark, and lead people to worship him. With persuasive and blasphemous speech and satanic power, he will rally the world against the saints and reorganize the natural forces of the ancient Roman Empire through demonic influence."}], "bigIdeas": ["The key word in Revelation is “Revelation” — the unveiling of Jesus Christ. Chapters 2–3 send messages to seven churches and give a picture of church history.", "Before Jesus returns: deception (false Christs and date-setters), wars and rumors of wars, natural disasters that shake politics, a church that grows cold and compromises (not stronger in evangelism), sin treated as normal, exploding knowledge, Jews returning, Israel re-established with Jerusalem as capital, and accelerating apostasy.", "At the Rapture, Christ appears in the air with a shout and trumpet; the church is caught up; the living are transformed into Christ’s likeness; the dead in Christ rise; God’s restraint against sin is removed; those left behind believe a lie.", "After the Rapture, all believers will see the throne and God — a settled hope for the church caught up.", "The World Ruler launches a “substitute church” with signs and wonders (including a counterfeit resurrection), forms an unholy trinity with Satan and the False Prophet, demands a mark, and the Anti-Christ makes a covenant with Israel.", "The Great Tribulation is not three and a half weeks. The Millennium is a thousand years of Christ’s reign on earth.", "In the fourth (future) Heaven there will be no more temple, sun, tears, death, or night — God Himself is the light and the dwelling."], "summary": "The unveiling — churches, Rapture, Tribulation, Millennium, and the last Heaven. The key word in Revelation is “Revelation” — the unveiling of Jesus Christ. Chapters 2–3 send messages to seven churches and give a picture of church history.", "quickReview": ["The key word in Revelation is “Revelation” — the unveiling of Jesus Christ. Chapters 2–3 send messages to…", "Before Jesus returns: deception (false Christs and date-setters), wars and rumors of wars, natural disasters…", "At the Rapture, Christ appears in the air with a shout and trumpet; the church is caught up; the living are…", "After the Rapture, all believers will see the throne and God — a settled hope for the church caught up.", "The World Ruler launches a “substitute church” with signs and wonders (including a counterfeit resurrection)…"], "glossary": [{"term": "Revelation", "meaning": "the unveiling of Jesus Christ"}, {"term": "Substitute church", "meaning": "The World Ruler launches a “substitute church” with signs and wonders (including a counterfeit resurrection), forms an unholy trinity with Satan and the False…"}, {"term": "Substitute Church?", "meaning": "After the Rapture, how will the World Ruler launch his \"Substitute Church?\" The World Ruler will launch a substitute church through signs and wonders that…"}, {"term": "What will the world be like right before Jesus returns?", "meaning": "Right before Jesus returns, deception will increase as false Christs and date-setters arise. Wars and rumors of wars and their stressful problems will…"}, {"term": "What will happen at the moment of the Rapture?", "meaning": "At the Rapture, Jesus Christ will appear in the air with a shout and the sound of a trumpet, and the church will be caught up. Saved people will be transformed…"}, {"term": "After the Rapture, how will the World Ruler launch his", "meaning": "The World Ruler will launch a substitute church through signs and wonders that mimic Jesus Christ, especially a counterfeit resurrection. He will operate as…"}, {"term": "Great Tribulation", "meaning": "Great Tribulation is not three and a half weeks"}, {"term": "The Millennium", "meaning": "The Millennium is a thousand years of Christ’s reign on earth"}], "outline": ["What will the world be like right before Jesus returns?", "What will happen at the moment of the Rapture?", "After the Rapture, how will the World Ruler launch his \"Substitute Church?\""], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key word", "value": "in Revelation is “Revelation"}, {"label": "Key claim", "value": "The key word in Revelation is “Revelation” — the unveiling of Jesus Christ. Chapters 2–3 send messages to seven churches and give a picture…"}, {"label": "Reject", "value": "Before Jesus returns: deception (false Christs and date-setters), wars and rumors of wars, natural disasters that shake politics, a church…"}, {"label": "Key claim", "value": "At the Rapture, Christ appears in the air with a shout and trumpet; the church is caught up; the living are transformed into Christ’s…"}], "pulpit": ["After the Rapture, all believers will see the throne and God — a settled hope for the church caught up.", "The key word in Revelation is “Revelation” — the unveiling of Jesus Christ. Chapters 2–3 send messages to seven churches and give…", "Before Jesus returns: deception (false Christs and date-setters), wars and rumors of wars, natural disasters that shake politics…"], "compare": null}], "courseTotal": 94}, {"id": "theology-2", "code": 56, "title": "Survey of Theology 2", "status": "complete", "certificateUnlocked": true, "blurb": "Death of Christ through Demons — Lessons 7–12 complete. Certificate unlocked. Course total 96% (L7 100, L8 100, L9 90, L10 80, L11 100, L12 90).", "lessons": [{"id": "th2-7", "number": 7, "title": "What We Believe About the Death of Christ", "topic": "Historical, voluntary, substitutionary — redemption by blood.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10 on attempt 1. Essays not graded yet. Attempts used: 1 of 3.", "takeaways": ["Christ’s death is historical, voluntary, substitutionary, and part of God’s sovereign purpose — not an accident and not a surprise to the Father.", "Walk the chronology: Last Supper, Gethsemane, arrest, trials, crucifixion, burial, resurrection. The story has a shape; preach it in order.", "Seven sayings from the cross: forgiveness, acceptance, human responsibility, separation, suffering, victory, and completion.", "The cross provides redemption by blood, propitiation, reconciliation, satisfaction of the law, and the judgment of Satan.", "Reject the false theories: accident, recapitulation, ransom-to-Satan, Anselm’s satisfaction, mystical, moral-influence, governmental, and modern-liberal. They minimize or deny substitution by blood."], "quiz": [{"q": "The Father took no responsibility for His son's death on the cross.", "answer": "False", "why": "The cross is the Father’s purpose and the Son’s willing obedience — not the Father stepping aside."}, {"q": "The substitutionary work of Christ is the vicarious nature of His death.", "answer": "True", "why": "He died in the sinner’s place — that is substitution."}, {"q": "The word for \"redemption\" comes from a word meaning \"to buy back.\" .", "answer": "True", "why": "Moodle punctuation kept. Redemption is to buy back."}, {"q": "Propitiation signifies the turning away of wrath by an offering.", "answer": "True", "why": "Wrath turned aside by the offering of Christ."}, {"q": "Reconciliation has the root meaning, \"to restore divine favor.\"", "answer": "True", "why": "Enemies restored to favor through the cross."}, {"q": "Judicial and personal guilt are two terms for the same reality.", "answer": "False", "why": "They are related but not identical categories in the lesson."}, {"q": "When someone sins, the circle of confession should always be the entire church.", "answer": "False", "why": "Confession matches the circle of the offense — not always the whole church."}, {"q": "The death of Jesus is the basis of the eventual national salvation of Israel.", "answer": "True", "why": "Israel’s hope rests on the same finished work."}, {"q": "The death of Jesus judged Satan.", "answer": "True", "why": "The cross judged the devil and broke his claim."}, {"q": "As long as Christians keep sinning, Christ has to remain on the cross to deal with their sin.", "answer": "False", "why": "It is finished. He is not still hanging there for ongoing sins."}], "essays": [{"theme": "Who was responsible for Christ's death on the cross?", "summary": "Human responsibility and God’s sovereign purpose meet at Calvary. Judas, leaders, Pilate, soldiers, and the crowd acted wickedly; our sin made the cross necessary. Yet Jesus willingly submitted, and the Father’s purpose was not thwarted. Sinful people are responsible for the act; God gave His Son in love, and Christ laid down His life voluntarily."}, {"theme": "Explain the concept of \"Redemption by Blood.\"", "summary": "Release from sin and judgment comes through Christ’s sacrificial death. The Passover lamb pointed forward to Jesus, the Lamb whose blood satisfies God’s justice, meets the law’s demand, defeats Satan’s works, and opens forgiveness and eternal life. We receive this by trusting Christ, not by our works."}, {"theme": "Review the false theories concerning the Atonement.", "summary": "Rejected theories: accident; recapitulation; ransom-to-Satan; Anselm’s satisfaction (extra merit transferable); mystical (Aquinas/sacraments); moral influence (Abelard); governmental (Grotius); modern liberal (example only). They minimize or deny that Christ willingly died in the sinner’s place, satisfied holy justice, and provided redemption by His blood."}], "bigIdeas": ["Christ’s death is historical, voluntary, substitutionary, and part of God’s sovereign purpose — not an accident and not a surprise to the Father.", "Walk the chronology: Last Supper, Gethsemane, arrest, trials, crucifixion, burial, resurrection. The story has a shape; preach it in order.", "Seven sayings from the cross: forgiveness, acceptance, human responsibility, separation, suffering, victory, and completion.", "The cross provides redemption by blood, propitiation, reconciliation, satisfaction of the law, and the judgment of Satan.", "Reject the false theories: accident, recapitulation, ransom-to-Satan, Anselm’s satisfaction, mystical, moral-influence, governmental, and modern-liberal. They minimize or deny substitution by blood."], "summary": "Historical, voluntary, substitutionary — redemption by blood. Christ’s death is historical, voluntary, substitutionary, and part of God’s sovereign purpose — not an accident and not a surprise to the Father.", "quickReview": ["Christ’s death is historical, voluntary, substitutionary, and part of God’s sovereign purpose — not an…", "Walk the chronology: Last Supper, Gethsemane, arrest, trials, crucifixion, burial, resurrection. The story…", "Seven sayings from the cross: forgiveness, acceptance, human responsibility, separation, suffering, victory…", "The cross provides redemption by blood, propitiation, reconciliation, satisfaction of the law, and the…", "Reject the false theories: accident, recapitulation, ransom-to-Satan, Anselm’s satisfaction, mystical…"], "outline": ["Last Supper", "Gethsemane", "Arrest", "Trials", "Crucifixion", "Burial", "Resurrection"], "glossary": [{"term": "Redemption by Blood", "meaning": "Explain the concept of \"Redemption by Blood.\" Release from sin and judgment comes through Christ’s sacrificial death."}, {"term": "Responsibility for Christ's death", "meaning": "Human responsibility and God’s sovereign purpose meet at Calvary. Judas, leaders, Pilate, soldiers, and the crowd acted wickedly; our sin made the cross…"}, {"term": "False theories of the Atonement", "meaning": "Rejected theories: accident; recapitulation; ransom-to-Satan; Anselm’s satisfaction (extra merit transferable); mystical (Aquinas/sacraments); moral influence…"}, {"term": "Propitiation", "meaning": "The cross provides redemption by blood, propitiation, reconciliation, satisfaction of the law, and the judgment of Satan."}, {"term": "Redemption", "meaning": "The cross provides redemption by blood, propitiation, reconciliation, satisfaction of the law, and the judgment of Satan."}, {"term": "Reconciliation", "meaning": "The cross provides redemption by blood, propitiation, reconciliation, satisfaction of the law, and the judgment of Satan."}, {"term": "Atonement", "meaning": "Review the false theories concerning the Atonement."}, {"term": "Substitution", "meaning": "They minimize or deny substitution by blood."}], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Christ’s death is historical, voluntary, substitutionary, and part of God’s sovereign purpose — not an accident and not a surprise to the…"}, {"label": "Preach", "value": "Walk the chronology: Last Supper, Gethsemane, arrest, trials, crucifixion, burial, resurrection. The story has a shape; preach it in order."}, {"label": "Key claim", "value": "Seven sayings from the cross: forgiveness, acceptance, human responsibility, separation, suffering, victory, and completion."}], "compare": [{"title": "Clarify", "points": ["Christ’s death is historical, voluntary, substitutionary, and part of God’s sovereign purpose", "Not: an accident and not a surprise to the Father."]}, {"title": "Seven sayings from the cross", "points": ["forgiveness", "acceptance", "human responsibility", "separation", "suffering", "victory", "and completion"]}, {"title": "Review the false theories concerning the Atonement.", "points": ["accident", "recapitulation", "ransom-to-Satan", "Anselm’s satisfaction (extra merit transferable)", "mystical (Aquinas/sacraments)", "moral influence (Abelard)", "governmental (Grotius)", "modern liberal (example only)"]}], "pulpit": ["The story has a shape; preach it in order.", "Christ’s death is historical, voluntary, substitutionary, and part of God’s sovereign purpose — not an accident and not a…", "Walk the chronology: Last Supper, Gethsemane, arrest, trials, crucifixion, burial, resurrection. The story has a shape; preach it…"]}, {"id": "th2-8", "number": 8, "title": "What We Believe About the Resurrection", "topic": "Empty tomb to the right hand — Christianity’s central historical truth.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10 (9/9 objective) on attempt 1. Essays not graded yet. Attempts used: 1 of 3. Quiz has 9 true/false items plus 3 essays.", "takeaways": ["The resurrection is Christianity’s central historical truth: empty tomb, eyewitnesses, transformed disciples, and the church’s emergence.", "It means renewed life, reunion of body and spirit, victory over death, new glory, spiritual life for believers, and a glorified body.", "The ascended Christ ministers now as intercessor and advocate at the Father’s right hand.", "Opposing theories to reject: stolen body, swoon, wrong tomb/Passover Plot, non-historical eschatological, Bultmann demythologizing, excited imagination, and Keim’s mystical vision.", "The Christian lives in two worlds — already raised with Christ in standing, still walking in this age until He comes."], "quiz": [{"q": "The resurrection is the fundamental truth of Christianity.", "answer": "True", "why": "Without it, preaching is empty. With it, everything holds."}, {"q": "Rudolf Bultmann was a strong proponent of the reality of the physical resurrection of Jesus Christ.", "answer": "False", "why": "Bultmann demythologized — he did not champion a physical resurrection."}, {"q": "The first proof of the resurrection was the empty tomb.", "answer": "True", "why": "The tomb was empty — the first public fact."}, {"q": "A major proof of the resurrection was the numerous post-resurrection appearances of Jesus.", "answer": "True", "why": "Many appearances to many witnesses."}, {"q": "At the crucifixion, the disciples were fully expecting to see the resurrected Christ.", "answer": "False", "why": "They were shattered, not expecting Him."}, {"q": "When Jesus was raised from the dead, His resurrection body was identical in every way to the body that had been crucified.", "answer": "False", "why": "Same essential body, but glorified — not identical in every way."}, {"q": "The Christian actually lives in two worlds. .", "answer": "True", "why": "Moodle punctuation kept. Already raised with Christ, still in this age."}, {"q": "At this time, Christ is actually seated at the right hand of the Father.", "answer": "True", "why": "Ascended and seated — ruling and representing."}, {"q": "In Jesus' present ministry, He is our intercessor and advocate.", "answer": "True", "why": "He prays for us and advocates for us now."}], "essays": [{"theme": "What are some of the historical theories opposing the resurrection?", "summary": "Stolen-body; swoon; wrong-tomb / Passover Plot; resurrection as non-historical eschatological event; Bultmann’s demythologizing / subjective vision; excited imagination; Keim’s mystical-message vision. All refuse a literal bodily rising."}, {"theme": "List proofs that the literal physical resurrection of Jesus Christ actually occurred.", "summary": "Empty tomb; grave clothes; agreeing eyewitnesses; transformed disciples; rapid church; group and individual appearances; James’s conversion; Paul’s living testimony; OT correlation; NT purpose/cause/results; enemies unable to produce a body; shift to first-day worship; early testimony (e.g. Ignatius). Converging evidence for a literal physical resurrection."}, {"theme": "List and explain the six elements of a definition of the resurrection of Jesus Christ.", "summary": "1) Renewed life — truly died, truly rose. 2) Reunion of body and spirit. 3) Victory over death’s power. 4) New glory — former glory restored plus intercessor/advocate ministry. 5) Spiritual life for believers who share His resurrection. 6) Glorified body — identifiable wounds, able to eat and walk, yet transformed beyond ordinary limits."}], "bigIdeas": ["The resurrection is Christianity’s central historical truth: empty tomb, eyewitnesses, transformed disciples, and the church’s emergence.", "It means renewed life, reunion of body and spirit, victory over death, new glory, spiritual life for believers, and a glorified body.", "The ascended Christ ministers now as intercessor and advocate at the Father’s right hand.", "Opposing theories to reject: stolen body, swoon, wrong tomb/Passover Plot, non-historical eschatological, Bultmann demythologizing, excited imagination, and Keim’s mystical vision.", "The Christian lives in two worlds — already raised with Christ in standing, still walking in this age until He comes."], "summary": "Empty tomb to the right hand — Christianity’s central historical truth. The resurrection is Christianity’s central historical truth: empty tomb, eyewitnesses, transformed disciples, and the church’s emergence.", "quickReview": ["The resurrection is Christianity’s central historical truth: empty tomb, eyewitnesses, transformed disciples…", "It means renewed life, reunion of body and spirit, victory over death, new glory, spiritual life for…", "The ascended Christ ministers now as intercessor and advocate at the Father’s right hand.", "Opposing theories to reject: stolen body, swoon, wrong tomb/Passover Plot, non-historical eschatological…", "The Christian lives in two worlds — already raised with Christ in standing, still walking in this age until…"], "glossary": [{"term": "some of the historical theories opposing the r", "meaning": "Stolen-body; swoon; wrong-tomb / Passover Plot; resurrection as non-historical eschatological event; Bultmann’s demythologizing / subjective vision; excited…"}, {"term": "List proofs that the literal physical resurrection of J", "meaning": "Empty tomb; grave clothes; agreeing eyewitnesses; transformed disciples; rapid church; group and individual appearances; James’s conversion; Paul’s living…"}, {"term": "List and explain the six elements of a definition of th", "meaning": "1) Renewed life — truly died, truly rose. 2) Reunion of body and spirit. 3) Victory over death’s power. 4) New glory — former glory restored plus…"}], "outline": ["What are some of the historical theories opposing the resurrection?", "List proofs that the literal physical resurrection of Jesus Christ actually occurred.", "List and explain the six elements of a definition of the resurrection of Jesus Christ."], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "The resurrection is Christianity’s central historical truth: empty tomb, eyewitnesses, transformed disciples, and the church’s emergence."}, {"label": "Key claim", "value": "It means renewed life, reunion of body and spirit, victory over death, new glory, spiritual life for believers, and a glorified body."}, {"label": "Key claim", "value": "The ascended Christ ministers now as intercessor and advocate at the Father’s right hand."}], "compare": null, "pulpit": ["The resurrection is Christianity’s central historical truth: empty tomb, eyewitnesses, transformed disciples, and the church’s…", "The ascended Christ ministers now as intercessor and advocate at the Father’s right hand.", "Opposing theories to reject: stolen body, swoon, wrong tomb/Passover Plot, non-historical eschatological, Bultmann…"]}, {"id": "th2-9", "number": 9, "title": "What We Believe About the Person of the Holy Spirit", "topic": "The Spirit is a divine Person: intellect, emotion, will — God in us.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 9/10 (90%) on attempt 1. Miss: Holy Anointing Oil as emblem (Q7, chose False; Moodle True). Essays not graded yet. Attempts used: 1 of 3. Quiz has 10 true/false items plus 3 essays.", "takeaways": ["The Holy Spirit is a divine Person — intellect, emotion, and will — identified as God. He is “God in us.”", "Extensive research on the Spirit is more modern; it was not a major field before the twentieth century.", "The Council of Nicea (325) did not first issue the “proceedeth from the Father” decree (Moodle: False).", "Emblems include the dove, seal, anointing oil, fire, rain, wind, rivers, dew, water, clothing, and earnest — each picturing a facet of His character or work.", "Ministry words (Towns): convict, restraint, regeneration, baptism, indwelling, illumination, sealing, prayer, fullness, sanctification, fruit, gifts.", "Before the incarnation His ministry was not merely “manifestation.” He participated in creation, and He convicts before conversion."], "quiz": [{"q": "Prior to the Twentieth-century, extensive research had been done on the person and work of the Holy Spirit.", "answer": "False", "why": "Serious, extensive study of the Spirit is largely a modern (twentieth-century) development."}, {"q": "The Holy Spirit has intellect, emotion, and volition (will).", "answer": "True", "why": "He knows, He loves, He wills — Person, not force."}, {"q": "In Scripture, the Holy Spirit is identified as God.", "answer": "True", "why": "Scripture names Him God and ascribes divine works to Him."}, {"q": "“God in us” is the Holy Spirit.", "answer": "True", "why": "Moodle punctuation kept. The indwelling Spirit is God with us, in us."}, {"q": "The Council of Nicea in 325 AD first issued the decree that recognized the Holy Spirit ‘who proceedeth from the Father.’", "answer": "False", "why": "Nicea 325 is not where that procession language first lands. Moodle: False."}, {"q": "One emblematic representative of the Spirit is the dove.", "answer": "True", "why": "The dove pictures the purity of the Spirit’s character (baptism of Jesus)."}, {"q": "The Holy Anointing Oil is emblematic of the Holy Spirit's blessing.", "answer": "True", "why": "Miss — Jay-R chose False. Moodle: True. The Holy Anointing Oil pictures the Spirit’s blessing (holiness / His presence on a person)."}, {"q": "The Holy Spirit had no part in the creation of the universe.", "answer": "False", "why": "He participated in creation. Moodle: False."}, {"q": "Before Christ's incarnation, the Spirit's ministry was one of manifestation.", "answer": "False", "why": "Moodle: False. His pre-incarnation work was more than mere manifestation."}, {"q": "Prior to conversion, the Holy Spirit convicts people of their sin.", "answer": "True", "why": "Reprove/convict comes before conversion — sin, righteousness, and judgment."}], "essays": [{"theme": "Briefly describe the proofs that the Holy Spirit is a person.", "summary": "He has intellect, emotion, and will (1 Cor 2:11; Rom 15:30; 1 Cor 12:11). He teaches, testifies, guides, speaks, enlightens, strives, commands, intercedes, sends, calls, comforts, and works. People can obey, lie to, resist, grieve, and blaspheme Him. Scripture uses masculine pronouns. Person, not force."}, {"theme": "List the emblems describing the Holy Spirit and provide the brief meaning for each.", "summary": "Dove — purity. Seal — security and proprietorship. Holy Anointing Oil — holiness. Act of anointing — His presence on a person. Oil — divine qualification. Fire — visible operations. Rain — fullness of supply. Atmosphere — spiritual worship. Wind — winnowing/searching. Rivers — abundant grace. Dew — refreshing and fruitfulness. Water — spiritual life. Clothing — equipment and strength. Earnest — sample of promised glory."}, {"theme": "List and explain the 12 words that describe the Holy Spirit's ministry according to Dr. Towns.", "summary": "1) Reprove/convict — sin, righteousness, judgment before conversion. 2) Restraint — holds back evil. 3) Regeneration — new life. 4) Baptism — places believers into the one body. 5) Indwelling — the body as temple. 6) Illumination — understanding truth. 7) Sealing — mark and keep. 8) Prayer — helps and intercedes. 9) Fullness — fill and control. 10) Sanctification — into Christ’s image. 11) Fruit — Christlike character. 12) Gifts — abilities for ministry."}], "bigIdeas": ["The Holy Spirit is a divine Person — intellect, emotion, and will — identified as God. He is “God in us.”", "Extensive research on the Spirit is more modern; it was not a major field before the twentieth century.", "The Council of Nicea (325) did not first issue the “proceedeth from the Father” decree (Moodle: False).", "Emblems include the dove, seal, anointing oil, fire, rain, wind, rivers, dew, water, clothing, and earnest — each picturing a facet of His character or work.", "Ministry words (Towns): convict, restraint, regeneration, baptism, indwelling, illumination, sealing, prayer, fullness, sanctification, fruit, gifts.", "Before the incarnation His ministry was not merely “manifestation.” He participated in creation, and He convicts before conversion."], "summary": "The Spirit is a divine Person: intellect, emotion, will — God in us. The Holy Spirit is a divine Person — intellect, emotion, and will — identified as God. He is “God in us.”.", "quickReview": ["Miss: True — The Holy Anointing Oil is emblematic of the Holy Spirit's blessing.", "The Holy Spirit is a divine Person — intellect, emotion, and will — identified as God. He is “God in us.”", "Extensive research on the Spirit is more modern; it was not a major field before the twentieth century.", "The Council of Nicea (325) did not first issue the “proceedeth from the Father” decree (Moodle: False).", "Emblems include the dove, seal, anointing oil, fire, rain, wind, rivers, dew, water, clothing, and earnest —…"], "glossary": [{"term": "God in us", "meaning": "He is “God in us.” Extensive research on the Spirit is more modern; it was not a major field before the twentieth century."}, {"term": "Proceedeth from the Father", "meaning": "The Council of Nicea (325) did not first issue the “proceedeth from the Father” decree (Moodle: False)."}, {"term": "Manifestation", "meaning": "Before the incarnation His ministry was not merely “manifestation.” He participated in creation, and He convicts before conversion."}, {"term": "Briefly describe the proofs that the Holy Spirit is a p", "meaning": "He has intellect, emotion, and will (1 Cor 2:11; Rom 15:30; 1 Cor 12:11). He teaches, testifies, guides, speaks, enlightens, strives, commands, intercedes…"}, {"term": "emblems describing the Holy Spirit and provide the brie", "meaning": "Dove — purity. Seal — security and proprietorship. Holy Anointing Oil — holiness. Act of anointing — His presence on a person. Oil — divine qualification. Fire…"}, {"term": "List and explain the 12 words that describe the Holy Sp", "meaning": "1) Reprove/convict — sin, righteousness, judgment before conversion. 2) Restraint — holds back evil. 3) Regeneration — new life. 4) Baptism — places believers…"}, {"term": "Holy Spirit", "meaning": "Holy Spirit is a divine Person — intellect, emotion, and will — identified as God"}], "outline": ["Briefly describe the proofs that the Holy Spirit is a person.", "List the emblems describing the Holy Spirit and provide the brief meaning for each.", "List and explain the 12 words that describe the Holy Spirit's ministry according to Dr. Towns."], "mustKnow": [{"label": "Quiz score", "value": "90% (1 attempt)"}, {"label": "Key claim", "value": "The Holy Spirit is a divine Person — intellect, emotion, and will — identified as God. He is “God in us.”"}, {"label": "Key claim", "value": "Extensive research on the Spirit is more modern; it was not a major field before the twentieth century."}, {"label": "Reject", "value": "The Council of Nicea (325) did not first issue the “proceedeth from the Father” decree (Moodle: False)."}, {"label": "Miss drill 1", "value": "True: The Holy Anointing Oil is emblematic of the Holy Spirit's blessing. — Miss — Jay-R chose False. Moodle: True. The Holy Anointing Oil pictures the…"}], "pulpit": ["Keep this lesson’s center clear for the people: The Spirit is a divine Person: intellect, emotion, will — God in us.", "The Holy Spirit is a divine Person — intellect, emotion, and will — identified as God. He is “God in us.”"], "compare": null}, {"id": "th2-10", "number": 10, "title": "What We Believe About the Holy Spirit’s Ministry", "topic": "Restrain, regenerate, baptize, indwell, seal, fill, illuminate, and gift — one Spirit, many works.", "quizScore": 80, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 8/10 (80%) on attempt 1. Misses: Q3 regeneration/Luther (chose True; Moodle False) and Q7 illumination as subtraction (chose False; Moodle True). Essays not graded yet. Attempts used: 1 of 3. No retry unless Jay-R asks. Quiz has 10 true/false items plus 3 essays.", "takeaways": ["The Spirit restrains sin — the Church is one instrument — and prevents the complete corruption of the world.", "Baptism of the Spirit is a one-time work at conversion that places the believer into the body of Christ (1 Cor 12:13). It is not a second blessing and not water baptism.", "Indwelling is permanent from conversion. Filling is repeated control; believers are commanded to be filled. Filling is not getting more of God; it is yielding more of yourself.", "The seal is the presence of God in the believer. Illumination is a ministry of subtraction: the Spirit removes spiritual blindness.", "Sign gifts do not vastly outnumber serving gifts. The unpardonable sin is the final rejection of Christ through unbelief.", "Character is habitually knowing and doing the right thing in the right way. Fullness does not mean immerse. Regeneration was not emphasized by Luther (Moodle: False)."], "quiz": [{"q": "The presence of the Holy Spirit prevents the complete corruption of the world.", "answer": "True", "why": "His restraining work keeps the world from total collapse into evil."}, {"q": "One instrument used by the Spirit to restrain sin is the Church.", "answer": "True", "why": "The Church is one of the Spirit’s tools for restraint in the world."}, {"q": "Regeneration was emphasized by Martin Luther.", "answer": "False", "why": "Miss — Jay-R chose True. Moodle: False. Luther’s emphasis is justification by faith, not regeneration as the headline doctrine."}, {"q": "Fullness means to immerse.", "answer": "False", "why": "Immerse belongs to baptism imagery, not fullness. Filling is control, not dunking."}, {"q": "The seal signifies the Holy Spirit is the presence of God in the believer", "answer": "True", "why": "Moodle punctuation kept (no period). The seal is God present in the believer."}, {"q": "Believers are commanded to live lives filled with the Spirit.", "answer": "True", "why": "Ephesians 5:18 is a command — be filled, continuously."}, {"q": "When the Spirit illuminates the mind, it is essentially a ministry of subtraction by the removal of spiritual blindness.", "answer": "True", "why": "Miss — Jay-R chose False. Moodle: True. Illumination is subtraction: He takes the blindness off so we can see."}, {"q": "Character is habitually knowing and doing the right thing in the right way.", "answer": "True", "why": "Character is the settled habit of right knowing and right doing."}, {"q": "Sign gifts vastly out number serving gifts.", "answer": "False", "why": "Moodle spelling kept (“out number”). Sign gifts do not vastly outnumber serving gifts."}, {"q": "The unpardonable sin is the final rejection of Christ through unbelief.", "answer": "True", "why": "Final, settled unbelief — rejecting Christ — is the unpardonable sin in this lesson."}], "essays": [{"theme": "Explain what is meant by the term, \"the baptism of the Holy Spirit.\"", "summary": "One-time work at conversion: the Spirit places the person who receives Christ into the body of Christ (1 Cor 12:13). Not a second blessing to seek, and not water baptism. Historically at Pentecost for the church; personally at new birth."}, {"theme": "Explain the Filling of the Spirit. How does it differ from the Indwelling of the Spirit?", "summary": "Filling is repeated control and power for living and service (Eph 5:18) as we yield, confess, and obey. Indwelling is the Spirit’s permanent presence from conversion (1 Cor 6:19; Rom 8:9). Every believer is indwelt; not every believer is always filled. Filling is not getting more of God; it is letting Him have more of you."}, {"theme": "List and explain the serving gifts of the Holy Spirit.", "summary": "Prophecy — proclaim God’s message. Teaching — explain and apply truth. Exhortation — encourage and challenge. Shepherding — care, guide, protect. Word of knowledge — communicate spiritual knowledge. Ministering — practical service. Giving — generous sharing. Ruling — diligent leadership. Evangelist — proclaim the gospel. (Submitted Q13 accidentally repeated the filling/indwelling paragraph; that extra copy is omitted here.)"}], "bigIdeas": ["The Spirit restrains sin — the Church is one instrument — and prevents the complete corruption of the world.", "Baptism of the Spirit is a one-time work at conversion that places the believer into the body of Christ (1 Cor 12:13). It is not a second blessing and not water baptism.", "Indwelling is permanent from conversion. Filling is repeated control; believers are commanded to be filled. Filling is not getting more of God; it is yielding more of yourself.", "The seal is the presence of God in the believer. Illumination is a ministry of subtraction: the Spirit removes spiritual blindness.", "Sign gifts do not vastly outnumber serving gifts. The unpardonable sin is the final rejection of Christ through unbelief.", "Character is habitually knowing and doing the right thing in the right way. Fullness does not mean immerse. Regeneration was not emphasized by Luther (Moodle: False)."], "summary": "Restrain, regenerate, baptize, indwell, seal, fill, illuminate, and gift — one Spirit, many works. The Spirit restrains sin — the Church is one instrument — and prevents the complete corruption of the world.", "quickReview": ["Miss: False — Regeneration was emphasized by Martin Luther.", "Miss: True — When the Spirit illuminates the mind, it is essentially a ministry of subtraction by the removal of…", "The Spirit restrains sin — the Church is one instrument — and prevents the complete corruption of the world.", "Baptism of the Spirit is a one-time work at conversion that places the believer into the body of Christ (1…", "Indwelling is permanent from conversion. Filling is repeated control; believers are commanded to be filled…"], "glossary": [{"term": "The baptism of the Holy Spirit", "meaning": "Explain what is meant by the term, \"the baptism of the Holy Spirit.\" One-time work at conversion: the Spirit places the person who receives Christ into the…"}, {"term": "Out number", "meaning": "Moodle spelling kept (“out number”)."}, {"term": "meant by the term, \"the baptism of the Holy Spi", "meaning": "One-time work at conversion: the Spirit places the person who receives Christ into the body of Christ (1 Cor 12:13). Not a second blessing to seek, and not…"}, {"term": "the Filling of the Spirit. How does it differ from the", "meaning": "Filling is repeated control and power for living and service (Eph 5:18) as we yield, confess, and obey. Indwelling is the Spirit’s permanent presence from…"}, {"term": "List and explain the serving gifts of the Holy Spirit", "meaning": "Prophecy — proclaim God’s message. Teaching — explain and apply truth. Exhortation — encourage and challenge. Shepherding — care, guide, protect. Word of…"}, {"term": "Indwelling", "meaning": "Indwelling is permanent from conversion"}, {"term": "Filling", "meaning": "Filling is repeated control; believers are commanded to be filled"}], "outline": ["Explain what is meant by the term, \"the baptism of the Holy Spirit.\"", "Explain the Filling of the Spirit. How does it differ from the Indwelling of the Spirit?", "List and explain the serving gifts of the Holy Spirit."], "mustKnow": [{"label": "Quiz score", "value": "80% (1 attempt)"}, {"label": "Key claim", "value": "The Spirit restrains sin — the Church is one instrument — and prevents the complete corruption of the world."}, {"label": "Key claim", "value": "Baptism of the Spirit is a one-time work at conversion that places the believer into the body of Christ (1 Cor 12:13). It is not a second…"}, {"label": "Key claim", "value": "Indwelling is permanent from conversion. Filling is repeated control; believers are commanded to be filled. Filling is not getting more of…"}, {"label": "Miss drill 1", "value": "False: Regeneration was emphasized by Martin Luther. — Miss — Jay-R chose True. Moodle: False. Luther’s emphasis is justification by faith, not regeneration as…"}, {"label": "Miss drill 2", "value": "True: When the Spirit illuminates the mind, it is essentially a ministry of subtraction by the removal of spiritual blindness. — Miss — Jay-R chose False…"}], "pulpit": ["Historically at Pentecost for the church; personally at new birth.", "The Spirit restrains sin — the Church is one instrument — and prevents the complete corruption of the world.", "Baptism of the Spirit is a one-time work at conversion that places the believer into the body of Christ (1 Cor 12:13). It is not…"], "compare": null}, {"id": "th2-11", "number": 11, "title": "What We Believe About Angels", "topic": "Messengers of God — created, holy, powerful — and Satan’s threefold work against them.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10 (100%) on attempt 1. Essays not graded yet. Attempts used: 1 of 3. Quiz has 10 true/false items plus 3 essays.", "takeaways": ["Angel means messenger. They are created, incorporeal, holy, personal, deathless, unseen, and organized — powerful, but not omnipotent or omniscient.", "Lucifer originally held a high place in heaven. Gabriel’s name does not mean “who is like The Lord?” — that is Michael.", "Scripture is the primary source of correct information about Satan. Adam and Eve were not created with a sin nature.", "Satan is not “incapable of doing good”; he can appear to do good by imitation. His threefold work is opposition, imitation, and destruction.", "Believers are commanded to resist the devil. Overcome him by caution, separation, resistance, and watchfulness with prayer."], "quiz": [{"q": "The word \"angel\" means messenger.", "answer": "True", "why": "Messenger is the basic meaning of the word."}, {"q": "Angels are deathless beings.", "answer": "True", "why": "They do not die. Created, they remain."}, {"q": "Lucifer originally possessed a high place in heaven.", "answer": "True", "why": "He was high before the fall."}, {"q": "Gabriel's name means \"who is like The Lord?\"", "answer": "False", "why": "That meaning belongs to Michael, not Gabriel."}, {"q": "Angels are known for their strength.", "answer": "True", "why": "Powerful — but still not omnipotent."}, {"q": "The primary source of correct information about Satan is Scripture.", "answer": "True", "why": "Not folklore, not movies — Scripture."}, {"q": "Like all humans, Adam and Eve were created with a sin nature.", "answer": "False", "why": "They were created good. Sin nature entered after the fall."}, {"q": "Satan is incapable of doing good.", "answer": "False", "why": "He can appear to do good by imitation — even as an angel of light. Moodle: False."}, {"q": "Satan's threefold work has to do with opposition, imitation, and destruction.", "answer": "True", "why": "Oppose God, counterfeit God’s work, destroy what is good."}, {"q": "Christians are commanded to resist the devil.", "answer": "True", "why": "Submit to God, then resist — and he will flee."}], "essays": [{"theme": "Describe the ten distinct works of the angels.", "summary": "1) Transportation — carry the believer at death. 2) Revelation — deliver messages (never replacing Scripture or the Spirit). 3) Protection — encamp around those who fear God. 4) Liberation — open prison doors. 5) Military assistance — God’s host, the legions. 6) Influence — outward circumstances (Spirit works within). 7) Ministry — serve heirs of salvation. 8) Worship and praise. 9) Judgment — execute God’s punishment. 10) Appearance — visible when God has a special purpose. Strong, yet humble and obedient."}, {"theme": "List and explain the three-fold works of Satan.", "summary": "1) Opposition — resists God and seeks to destroy the race God loves. 2) Imitation — counterfeits God’s work; can appear as an angel of light. 3) Destruction — steal, kill, destroy; deceive nations, blind unbelievers, tempt and accuse believers. Real schemes, still subject to God."}, {"theme": "List and explain the four principles involved in believers overcoming Satan.", "summary": "1) Caution — do not play with satanic power or treat evil as entertainment. 2) Separation — abstain from the appearance of evil; reject false teaching. 3) Resistance — submit to God first, then resist the devil in the faith. 4) Watchfulness and prayer — watch and pray; put on the whole armor of God. Depend on God, not on personal strength."}], "bigIdeas": ["Angel means messenger. They are created, incorporeal, holy, personal, deathless, unseen, and organized — powerful, but not omnipotent or omniscient.", "Lucifer originally held a high place in heaven. Gabriel’s name does not mean “who is like The Lord?” — that is Michael.", "Scripture is the primary source of correct information about Satan. Adam and Eve were not created with a sin nature.", "Satan is not “incapable of doing good”; he can appear to do good by imitation. His threefold work is opposition, imitation, and destruction.", "Believers are commanded to resist the devil. Overcome him by caution, separation, resistance, and watchfulness with prayer."], "summary": "Messengers of God — created, holy, powerful — and Satan’s threefold work against them. Angel means messenger. They are created, incorporeal, holy, personal, deathless, unseen, and organized — powerful, but not omnipotent or omniscient.", "quickReview": ["Angel means messenger. They are created, incorporeal, holy, personal, deathless, unseen, and organized —…", "Lucifer originally held a high place in heaven. Gabriel’s name does not mean “who is like The Lord?” — that…", "Scripture is the primary source of correct information about Satan. Adam and Eve were not created with a sin…", "Satan is not “incapable of doing good”; he can appear to do good by imitation. His threefold work is…", "Believers are commanded to resist the devil. Overcome him by caution, separation, resistance, and…"], "glossary": [{"term": "Who is like The Lord?", "meaning": "that is Michael"}, {"term": "Incapable of doing good", "meaning": "Satan is not “incapable of doing good”; he can appear to do good by imitation."}, {"term": "Describe the ten distinct works of the angels", "meaning": "1) Transportation — carry the believer at death. 2) Revelation — deliver messages (never replacing Scripture or the Spirit). 3) Protection — encamp around…"}, {"term": "List and explain the three-fold works of Satan", "meaning": "1) Opposition — resists God and seeks to destroy the race God loves. 2) Imitation — counterfeits God’s work; can appear as an angel of light. 3) Destruction —…"}, {"term": "List and explain the four principles involved in believ", "meaning": "1) Caution — do not play with satanic power or treat evil as entertainment. 2) Separation — abstain from the appearance of evil; reject false teaching. 3)…"}, {"term": "They", "meaning": "They is created, incorporeal, holy, personal, deathless, unseen, and organized — powerful, but not omnipoten"}, {"term": "Satan", "meaning": "Satan is not “incapable of doing good”; he can appear to do good by imitation"}], "outline": ["Describe the ten distinct works of the angels.", "List and explain the three-fold works of Satan.", "List and explain the four principles involved in believers overcoming Satan."], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Angel means messenger. They are created, incorporeal, holy, personal, deathless, unseen, and organized — powerful, but not omnipotent or…"}, {"label": "Key claim", "value": "Lucifer originally held a high place in heaven. Gabriel’s name does not mean “who is like The Lord?” — that is Michael."}, {"label": "Key claim", "value": "Scripture is the primary source of correct information about Satan. Adam and Eve were not created with a sin nature."}], "pulpit": ["Lucifer originally held a high place in heaven. Gabriel’s name does not mean “who is like The Lord?” — that is Michael.", "Believers are commanded to resist the devil. Overcome him by caution, separation, resistance, and watchfulness with prayer."], "compare": null}, {"id": "th2-12", "number": 12, "title": "What We Believe About Demons", "topic": "Fallen angels — limited, organized, and opposed to God — and how deliverance actually works.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 9/10 (90%) on attempt 1. Miss: Q6 Hallucination Theory vs Mystical Theory. Essays not graded yet. Attempts used: 1 of 3. Quiz has 10 true/false items plus 3 essays. Course certificate unlocked.", "takeaways": ["Demons are fallen angels: personal, nonmaterial, intelligent, immoral, powerful but limited.", "They oppose God through temptation, deception, false teaching, affliction, and spiritual warfare.", "Demon worship includes divination, necromancy, magic (white and black), sorcery, and witchcraft — all drawing power apart from God.", "God can use even a demon to accomplish His will. Some demons are confined until the Tribulation.", "Deliverance depends on God’s power, faith, Scripture, and a spiritually mature counselor — not the counselor’s personal power.", "The Hallucination Theory is not “a vivid symbol of the prevalence of evil” — that is the Mystical Theory. Review that miss."], "quiz": [{"q": "Most likely demons are fallen angels who rebelled against God.", "answer": "True", "why": "The lesson’s best account: fallen angels in rebellion."}, {"q": "Demons are pure spirits.", "answer": "True", "why": "Nonmaterial spirit beings — not flesh."}, {"q": "Some demons are confined until the Tribulation.", "answer": "True", "why": "Not all are free to roam now."}, {"q": "One famous work of fiction describing the efforts of a demon to hinder a person in his walk with God is The Screwtape Letters.", "answer": "True", "why": "Lewis’s Screwtape Letters is the famous fictional picture."}, {"q": "God would never use a demon to accomplish His will.", "answer": "False", "why": "God remains sovereign. He can even use a demon to accomplish His will."}, {"q": "The Hallucination Theory of demon possession argues that demon possession is but a vivid symbol of the prevalence of evil in the world.", "answer": "False", "why": "Miss — Jay-R chose True. That description is the Mystical Theory, not the Hallucination Theory. Moodle: False."}, {"q": "John Nevius was a Baptist missionary in India who wrote a classic book, Demon Possession, in the first part of the twenty-first century.", "answer": "False", "why": "Moodle: False. The stacked details (Baptist, India, twenty-first century) do not match Nevius."}, {"q": "Necromancy is the effort to communicate with and interrogate the dead.", "answer": "True", "why": "Scripture calls it an abomination. The dead are separated from the living."}, {"q": "Both white and black magic find their source and strength in demon power.", "answer": "True", "why": "White and black both draw on demon power — not sleight of hand."}, {"q": "The whole notion of exorcism is just nonsense.", "answer": "False", "why": "Exorcism is not nonsense. God delivers; the counselor points to Christ."}], "essays": [{"theme": "Please explain Dr. Towns' nine-point description of demons.", "summary": "1) Spirit nature — nonmaterial, can indwell, sometimes appear. 2) Unity — organized under Satan. 3) Fear of judgment — they know Christ’s authority. 4) Essence — immortal, powerful, but intellect and morals corrupted. 5) Power — great strength, limited by God. 6) Intellectual — accumulated knowledge, false doctrine, no saving faith. 7) Personality — desire, emotion, will (the swine). 8) Moral — evil, reprobate, unclean, no repentance. 9) Number — about one-third of the angels fell with Satan."}, {"theme": "List and describe the five characteristics of demon worship.", "summary": "1) Divination — illegitimate attempt to know God’s will or the future (e.g. examining an animal’s liver). 2) Necromancy — interrogating the dead; an abomination. 3) Magic — white and black both from demon power; not parlor tricks. 4) Sorcery — calling on demons for supernatural effects. 5) Witchcraft — magic and sorcery to do Satan’s will (Deut 18:10). All seek power apart from God."}, {"theme": "List and explain the three qualifications of an exorcist.", "summary": "1) Spiritual — born of the Spirit, obedient, Spirit-controlled. 2) Scriptural — knows what the Bible teaches about God, Satan, and demons; uses God’s armor; convinced of Christ’s victory. 3) Special — medical/psychiatric training when possible; a mature Christian with experience is preferred. God delivers. The counselor has no personal power; he points the person to Christ, Scripture, faith, confession, and a willing follow."}], "bigIdeas": ["Demons are fallen angels: personal, nonmaterial, intelligent, immoral, powerful but limited.", "They oppose God through temptation, deception, false teaching, affliction, and spiritual warfare.", "Demon worship includes divination, necromancy, magic (white and black), sorcery, and witchcraft — all drawing power apart from God.", "God can use even a demon to accomplish His will. Some demons are confined until the Tribulation.", "Deliverance depends on God’s power, faith, Scripture, and a spiritually mature counselor — not the counselor’s personal power.", "The Hallucination Theory is not “a vivid symbol of the prevalence of evil” — that is the Mystical Theory. Review that miss."], "summary": "Fallen angels — limited, organized, and opposed to God — and how deliverance actually works. Demons are fallen angels: personal, nonmaterial, intelligent, immoral, powerful but limited.", "quickReview": ["Miss: False — The Hallucination Theory of demon possession argues that demon possession is but a vivid symbol of the…", "Demons are fallen angels: personal, nonmaterial, intelligent, immoral, powerful but limited.", "They oppose God through temptation, deception, false teaching, affliction, and spiritual warfare.", "Demon worship includes divination, necromancy, magic (white and black), sorcery, and witchcraft — all drawing…", "God can use even a demon to accomplish His will. Some demons are confined until the Tribulation."], "glossary": [{"term": "a vivid symbol of the prevalence of evil", "meaning": "that is the Mystical Theory"}, {"term": "Please explain Dr. Towns' nine-point description of dem", "meaning": "1) Spirit nature — nonmaterial, can indwell, sometimes appear. 2) Unity — organized under Satan. 3) Fear of judgment — they know Christ’s authority. 4) Essence…"}, {"term": "List and describe the five characteristics of demon wor", "meaning": "1) Divination — illegitimate attempt to know God’s will or the future (e.g. examining an animal’s liver). 2) Necromancy — interrogating the dead; an…"}, {"term": "List and explain the three qualifications of an exorcis", "meaning": "1) Spiritual — born of the Spirit, obedient, Spirit-controlled. 2) Scriptural — knows what the Bible teaches about God, Satan, and demons; uses God’s armor…"}, {"term": "Demons", "meaning": "Demons is fallen angels: personal, nonmaterial, intelligent, immoral, powerful but limited"}, {"term": "Hallucination Theory", "meaning": "Hallucination Theory is not “a vivid symbol of the prevalence of evil” — that is the Mystical Theory"}], "outline": ["Please explain Dr. Towns' nine-point description of demons.", "List and describe the five characteristics of demon worship.", "List and explain the three qualifications of an exorcist."], "mustKnow": [{"label": "Quiz score", "value": "90% (1 attempt)"}, {"label": "Key claim", "value": "Demons are fallen angels: personal, nonmaterial, intelligent, immoral, powerful but limited."}, {"label": "Reject", "value": "They oppose God through temptation, deception, false teaching, affliction, and spiritual warfare."}, {"label": "Key claim", "value": "Demon worship includes divination, necromancy, magic (white and black), sorcery, and witchcraft — all drawing power apart from God."}, {"label": "Miss drill 1", "value": "False: The Hallucination Theory of demon possession argues that demon possession is but a vivid symbol of the prevalence of evil in the world. — Miss — Jay-R…"}], "compare": [{"title": "Clarify", "points": ["Deliverance depends on God’s power, faith, Scripture, and a spiritually mature counselor", "Not: the counselor’s personal power."]}], "pulpit": ["Deliverance depends on God’s power, faith, Scripture, and a spiritually mature counselor — not the counselor’s personal power.", "Keep this lesson’s center clear for the people: Fallen angels — limited, organized, and opposed to God — and how deliverance actually works.", "Demons are fallen angels: personal, nonmaterial, intelligent, immoral, powerful but limited."]}], "courseTotal": 96}, {"id": "basic-life-2", "code": 59, "title": "Survey of Basic Christian Life 2", "status": "complete", "certificateUnlocked": true, "blurb": "Learning Faith through Examination of Leadership — Lessons 7–12 complete. Certificate unlocked. Course total 100%.", "lessons": [{"id": "bl2-7", "number": 7, "title": "Learning Faith", "topic": "Faith is a confident relationship with God that leads to obedience and action — not mere awareness or feeling.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10 (100%) on attempt 1. Essays not graded yet. Attempts used: 1 of 3. Quiz has 10 true/false items plus 3 essays.", "takeaways": ["Faith is more than mental awareness or emotion. It is a confident relationship with God that leads to obedience and action.", "Faith grows through Scripture, prayer, trust, obedience, and opportunities to act. It is biblical to pray for faith.", "Doubt commonly comes from ignorance, fear, or rebellion.", "Love is shown by giving and sacrifice. Hope comes through Christ’s presence, God’s providence, Heaven, and Christ’s return.", "Six expressions: doctrinal, saving, justifying, indwelling, sanctifying, and the gift of faith. They are not all the same.", "Three views of the gift of faith: instrumental, insight, and interventional. Interventional faith goes beyond the normal tools God gives."], "quiz": [{"q": "Bill Bright was co-founder of Thomas Road Baptist Church with Jerry Falwell.", "answer": "False", "why": "Bright founded Campus Crusade (Cru), not Thomas Road with Falwell."}, {"q": "There are three views of the gift of faith: instrumental, insight, and intervention.", "answer": "True", "why": "Moodle wording kept (“intervention”). The three views: instrumental, insight, interventional."}, {"q": "Saving faith and justifying faith are both non-experiential.", "answer": "False", "why": "Justifying faith is God’s non-experiential act. Saving faith involves knowledge, will, and emotion."}, {"q": "Indwelling faith and doctrinal faith are the same.", "answer": "False", "why": "Doctrinal faith is the objective faith delivered to the saints. Indwelling faith is Christ’s faith in us."}, {"q": "Developing faith involves the mind, will, and emotions.", "answer": "True", "why": "Growing faith is whole-person: mind, will, and heart."}, {"q": "It is never biblical to pray for faith.", "answer": "False", "why": "The disciples asked, “Increase our faith.” It is biblical to pray for it."}, {"q": "Interventional faith grows out of using faith as a vision and uses faith as an instrument.", "answer": "True", "why": "It grows from vision-faith and still uses faith as an instrument."}, {"q": "Interventional faith goes beyond the normal tools God gives to serve Him.", "answer": "True", "why": "Beyond ordinary methods — divine certainty for a biblical purpose."}, {"q": "Interventional faith is not based on the person having exact biblical knowledge or mature doctrine.", "answer": "True", "why": "God’s power, not the person’s doctrinal maturity, is the ground of it."}, {"q": "Interventional faith is more than living by faith.", "answer": "True", "why": "Living by faith is sanctifying faith. Interventional faith is more than that."}], "essays": [{"theme": "List and discuss the six expressions of faith.", "summary": "Doctrinal — the faith delivered to the saints, an objective statement of belief. Saving — an act of the will based on knowledge, with emotional expression. Justifying — God’s non-experiential act of declaring us righteous. Indwelling — Christ’s faith in us, leading to a deeper-life experience. Sanctifying — living by the principles of the Bible. Gift of faith — an ability God gives a believer to do His work."}, {"theme": "Discuss the three different understandings and explanations of the gift of faith.", "summary": "Instrumental — God is source, vision, and power; available to all. Insight — also from God with His power, but a particular vision for ministry; for chosen people. Interventional — the person’s initiative and vision, God supplies power and accomplishment; for chosen people; beyond normal tools; divine certainty for a biblical purpose. God is the source, the person is the vehicle, results are supernatural."}, {"theme": "Discuss the eight conclusions about growing and using faith.", "summary": "Faith is a primary influence on ministry. Growing faith and growing ministries travel together. Leaders can grow ministries through the gift of faith and can develop that gift. Those without the gift can still use other means God provides and work with people who have it. Leaders can increase a gift’s effectiveness. Ministry grows as the leader goes from faith to faith. The gift can intervene in church crises or remove growth-hindering problems. Leaders need not express faith the same way to influence the church."}], "bigIdeas": ["Faith is more than mental awareness or emotion. It is a confident relationship with God that leads to obedience and action.", "Faith grows through Scripture, prayer, trust, obedience, and opportunities to act. It is biblical to pray for faith.", "Doubt commonly comes from ignorance, fear, or rebellion.", "Love is shown by giving and sacrifice. Hope comes through Christ’s presence, God’s providence, Heaven, and Christ’s return.", "Six expressions: doctrinal, saving, justifying, indwelling, sanctifying, and the gift of faith. They are not all the same.", "Three views of the gift of faith: instrumental, insight, and interventional. Interventional faith goes beyond the normal tools God gives."], "summary": "Faith is a confident relationship with God that leads to obedience and action — not mere awareness or feeling. Faith is more than mental awareness or emotion. It is a confident relationship with God that leads to obedience and action.", "quickReview": ["Faith is more than mental awareness or emotion. It is a confident relationship with God that leads to…", "Faith grows through Scripture, prayer, trust, obedience, and opportunities to act. It is biblical to pray for…", "Doubt commonly comes from ignorance, fear, or rebellion.", "Love is shown by giving and sacrifice. Hope comes through Christ’s presence, God’s providence, Heaven, and…", "Six expressions: doctrinal, saving, justifying, indwelling, sanctifying, and the gift of faith. They are not…"], "glossary": [{"term": "Six expressions of faith", "meaning": "Doctrinal — the faith delivered to the saints, an objective statement of belief. Saving — an act of the will based on knowledge, with emotional expression…"}, {"term": "eight conclusions about growing and using faith", "meaning": "Faith is a primary influence on ministry. Growing faith and growing ministries travel together. Leaders can grow ministries through the gift of faith and can…"}, {"term": "Faith", "meaning": "Faith is more than mental awareness or emotion"}, {"term": "Love", "meaning": "Love is shown by giving and sacrifice"}], "outline": ["List and discuss the six expressions of faith.", "Discuss the three different understandings and explanations of the gift of faith.", "Discuss the eight conclusions about growing and using faith."], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Faith is more than mental awareness or emotion. It is a confident relationship with God that leads to obedience and action."}, {"label": "Key claim", "value": "Faith grows through Scripture, prayer, trust, obedience, and opportunities to act. It is biblical to pray for faith."}, {"label": "Key claim", "value": "Doubt commonly comes from ignorance, fear, or rebellion."}], "compare": [{"title": "Six expressions", "points": ["doctrinal", "saving", "justifying", "indwelling", "sanctifying", "and the gift of faith"]}, {"title": "Three views of the gift of faith", "points": ["instrumental", "insight", "and interventional"]}], "pulpit": ["Faith is more than mental awareness or emotion. It is a confident relationship with God that leads to obedience and action.", "Faith grows through Scripture, prayer, trust, obedience, and opportunities to act. It is biblical to pray for faith.", "Love is shown by giving and sacrifice. Hope comes through Christ’s presence, God’s providence, Heaven, and Christ’s return."]}, {"id": "bl2-8", "number": 8, "title": "Dealing with Trials", "topic": "A winter’s night is meant to prepare you, not destroy you — trials that build faith.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10 (100%) on attempt 1. Essays not graded yet. Attempts used: 1 of 3. Quiz has 10 true/false items plus 3 essays.", "takeaways": ["Trials build faith, reveal weaknesses, correct sin or wrong direction, and prepare believers for God’s work.", "Loneliness is unwanted isolation. Solitude is chosen time with God.", "Scripture, effective prayer, Christian friends, and meaningful relationships help us through difficulty.", "Usually the deeper the winter’s night, the greater the preparation for future usefulness. God allows frustration and pain to move us closer to Him.", "Most of God’s great servants went through great trials — including Paul. Before God uses people in a mighty way, He often allows a long, dark, lonely night to build mighty faith.", "A winter’s night may come from limited understanding, unconfessed sin, a wrong direction, or a need to learn patience for a new vision."], "quiz": [{"q": "During a time of testing a person learns his/her weaknesses or failures", "answer": "True", "why": "Moodle punctuation kept (no period). Testing exposes weakness so it can be healed."}, {"q": "In times of testing, we wrestle with our faulty self-perception to learn to see ourselves as God sees us.", "answer": "True", "why": "The test is also a mirror — God’s view, not ours."}, {"q": "Usually the deeper the winter's night, the greater preparation for future usefulness.", "answer": "True", "why": "Deep night, deep preparation."}, {"q": "It is not enough to yield to God. He tests us to determine our dedication to do His will.", "answer": "True", "why": "Yielding is the start. Testing proves dedication."}, {"q": "Jerry Falwell first said, \"The world has yet to see what God can do with a person fully dedicated to Him.\"", "answer": "False", "why": "Moodle: False. Falwell did not first say it."}, {"q": "God allows frustration and pain to move us closer to Him.", "answer": "True", "why": "Pain that draws, not pain that merely hurts."}, {"q": "Samson was blind to what God was doing.", "answer": "True", "why": "He failed the test by being blind to God’s work — then literally blind."}, {"q": "Joseph was isolated in Egypt's slavery and prison before God used him to feed a starving world.", "answer": "True", "why": "The pit and the prison came before the palace."}, {"q": "Most of God's great servants went through great trials, except Saul of Tarsus (Paul) who learned from his life in Judaism.", "answer": "False", "why": "Paul is not the exception. He suffered greatly. Moodle: False."}, {"q": "Before God uses people in a mighty way, He allows them to suffer in a long, dark, lonely night to build in them mighty faith.", "answer": "True", "why": "Mighty faith is often forged in a long night."}], "essays": [{"theme": "What prompts a winter's night? Discuss the four answers.", "summary": "1) Limited understanding — God teaches truth for a greater task. 2) Sin that needs confession and correction. 3) Wrong direction — see it and turn back. 4) Need to learn patience and wait for a new vision. These times prepare; they are not meant to destroy."}, {"theme": "What is the prescription to get through a dark night?", "summary": "Know the spiritual purpose of the frustration; do not let it destroy self-worth. Use loneliness to draw closer to Christ. Look for what God wants to give. Let your loneliness become ministry to others with the same problem. Study biblical relationships, pray for a meaningful friendship, turn negative thoughts inside out, do something useful, and add friends to your prayer list."}, {"theme": "What do we learn from those who failed their time of testing?", "summary": "Samson was blind to what God was doing. Others gave in to evil desire. Demas loved this present world and lost sight of God’s purpose. Saul would not wait or obey — he intruded into the priest’s office and later gave incomplete obedience concerning Amalek. Stay humble, resist temptation, keep God’s purpose in view, and obey fully."}], "bigIdeas": ["Trials build faith, reveal weaknesses, correct sin or wrong direction, and prepare believers for God’s work.", "Loneliness is unwanted isolation. Solitude is chosen time with God.", "Scripture, effective prayer, Christian friends, and meaningful relationships help us through difficulty.", "Usually the deeper the winter’s night, the greater the preparation for future usefulness. God allows frustration and pain to move us closer to Him.", "Most of God’s great servants went through great trials — including Paul. Before God uses people in a mighty way, He often allows a long, dark, lonely night to build mighty faith.", "A winter’s night may come from limited understanding, unconfessed sin, a wrong direction, or a need to learn patience for a new vision."], "summary": "A winter’s night is meant to prepare you, not destroy you — trials that build faith. Trials build faith, reveal weaknesses, correct sin or wrong direction, and prepare believers for God’s work.", "quickReview": ["Trials build faith, reveal weaknesses, correct sin or wrong direction, and prepare believers for God’s work.", "Loneliness is unwanted isolation. Solitude is chosen time with God.", "Scripture, effective prayer, Christian friends, and meaningful relationships help us through difficulty.", "Usually the deeper the winter’s night, the greater the preparation for future usefulness. God allows…", "Most of God’s great servants went through great trials — including Paul. Before God uses people in a mighty…"], "glossary": [{"term": "What prompts a winter's night? Discuss the four answers", "meaning": "1) Limited understanding — God teaches truth for a greater task. 2) Sin that needs confession and correction. 3) Wrong direction — see it and turn back. 4)…"}, {"term": "the prescription to get through a dark night?", "meaning": "Know the spiritual purpose of the frustration; do not let it destroy self-worth. Use loneliness to draw closer to Christ. Look for what God wants to give. Let…"}, {"term": "What do we learn from those who failed their time of te", "meaning": "Samson was blind to what God was doing. Others gave in to evil desire. Demas loved this present world and lost sight of God’s purpose. Saul would not wait or…"}, {"term": "Loneliness", "meaning": "Loneliness is unwanted isolation"}, {"term": "Solitude", "meaning": "Solitude is chosen time with God"}], "outline": ["What prompts a winter's night? Discuss the four answers.", "What is the prescription to get through a dark night?", "What do we learn from those who failed their time of testing?"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Trials build faith, reveal weaknesses, correct sin or wrong direction, and prepare believers for God’s work."}, {"label": "Key claim", "value": "Loneliness is unwanted isolation. Solitude is chosen time with God."}, {"label": "Key claim", "value": "Scripture, effective prayer, Christian friends, and meaningful relationships help us through difficulty."}], "pulpit": ["Trials build faith, reveal weaknesses, correct sin or wrong direction, and prepare believers for God’s work.", "Scripture, effective prayer, Christian friends, and meaningful relationships help us through difficulty.", "Most of God’s great servants went through great trials — including Paul. Before God uses people in a mighty way, He often allows…"], "compare": null}, {"id": "bl2-9", "number": 9, "title": "What Is the Call of God?", "topic": "Three calls — salvation, sanctification, and full-time service — and how a ministry call is recognized.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10 (100%) on attempt 1. Essays not graded yet. Attempts used: 1 of 3. Quiz has 10 true/false items plus 3 essays.", "takeaways": ["The three calls of God are salvation, sanctification, and full-time Christian service.", "A ministry call involves burden, conviction, desire, preparation, fruit, church confirmation, and an inner assurance from God.", "A genuine call gains strength through time and testing; it does not lose its urgency.", "The call is not always instantaneous. God may repeat the call if it is first rejected. Not every Christian is called to full-time ministry.", "Ordain in the original language means “to lay hands on.” At ordination the candidate must give evidence of a burden to serve God full time.", "The call includes God’s call for the servant to prepare. It involves a rigid self-examination."], "quiz": [{"q": "There are three calls of God: to salvation, to sanctification, and to full time service.", "answer": "True", "why": "Moodle spelling kept (“full time”). Three calls, not one."}, {"q": "God's call to service includes God's call for the servant to prepare himself/herself.", "answer": "True", "why": "The call includes the call to prepare, not only the call to go."}, {"q": "If a person rejects the call to ministry the first time, God will not repeat Himself with a second opportunity.", "answer": "False", "why": "God may call again. Rejection the first time is not the last word."}, {"q": "The word \"ordain\" in the original language means \"to lay hands on.\"", "answer": "True", "why": "Laying on of hands is the original sense of ordain here."}, {"q": "The call of God to full time ministry usually begins with a burden to work for God.", "answer": "True", "why": "Burden first — then the rest of the call’s marks."}, {"q": "The call of God to ministry always comes instantaneously, not a gradual awareness over a period of time.", "answer": "False", "why": "It is often gradual, not always a single moment."}, {"q": "The call of God to ministry involves a rigid-self examination.", "answer": "True", "why": "Moodle hyphen kept. Motives, fruit, competence — examine them honestly."}, {"q": "Every Christian will have an opportunity to serve God in a full time capacity, but must turn it down.", "answer": "False", "why": "Not all are called. Towns: the greatest part of mankind is not called."}, {"q": "If the call is real, it will gain strength over time, not lose its urgency.", "answer": "True", "why": "Time and testing strengthen a real call."}, {"q": "At an ordination service, the candidate must give evidence of a burden to serve God full time.", "answer": "True", "why": "Burden to serve full time is part of the evidence at ordination."}], "essays": [{"theme": "Discuss the three calls of God.", "summary": "Salvation — Jesus invites a person to come and be saved. Sanctification — fellowship with Christ and growth in a holy life. Full-time Christian service — God’s call to win souls, build churches, teach the Bible, and serve His people."}, {"theme": "How does a person recognize the call of God for full time ministry?", "summary": "Inner burden and conviction from God, not merely a job desire. The Spirit’s work and God’s providence. Honest examination of motives. The judgment of Christian friends and the will of the church. Ability to preach and teach, and people willing to listen. Christian life, fruit, competence, love for people, and preparation. The call grows stronger with time and testing."}, {"theme": "What are Dr. Towns' eight insights into being called by God to full time Christian ministry?", "summary": "1) All are not called. 2) God alone can call anyone. 3) The greatest part of mankind is not called. 4) Scripture requires every minister in God’s house to be called by the Lord. 5) It is a great and undeserved honor. 6) The honor does not puff up a good man. 7) Some bad men have entered the ministry. 8) If a call is real, it will gain strength by time and test."}], "bigIdeas": ["The three calls of God are salvation, sanctification, and full-time Christian service.", "A ministry call involves burden, conviction, desire, preparation, fruit, church confirmation, and an inner assurance from God.", "A genuine call gains strength through time and testing; it does not lose its urgency.", "The call is not always instantaneous. God may repeat the call if it is first rejected. Not every Christian is called to full-time ministry.", "Ordain in the original language means “to lay hands on.” At ordination the candidate must give evidence of a burden to serve God full time.", "The call includes God’s call for the servant to prepare. It involves a rigid self-examination."], "summary": "Three calls — salvation, sanctification, and full-time service — and how a ministry call is recognized. The three calls of God are salvation, sanctification, and full-time Christian service.", "quickReview": ["The three calls of God are salvation, sanctification, and full-time Christian service.", "A ministry call involves burden, conviction, desire, preparation, fruit, church confirmation, and an inner…", "A genuine call gains strength through time and testing; it does not lose its urgency.", "The call is not always instantaneous. God may repeat the call if it is first rejected. Not every Christian is…", "Ordain in the original language means “to lay hands on.” At ordination the candidate must give evidence of a…"], "glossary": [{"term": "To lay hands on", "meaning": "Ordain in the original language means “to lay hands on.” At ordination the candidate must give evidence of a burden to serve God full time."}, {"term": "Full time", "meaning": "Moodle spelling kept (“full time”)."}, {"term": "Three calls of God", "meaning": "Salvation — Jesus invites a person to come and be saved. Sanctification — fellowship with Christ and growth in a holy life. Full-time Christian service — God’s…"}, {"term": "How does a person recognize the call of God for full ti", "meaning": "Inner burden and conviction from God, not merely a job desire. The Spirit’s work and God’s providence. Honest examination of motives. The judgment of Christian…"}, {"term": "Dr. Towns' eight insights into being called by", "meaning": "1) All are not called. 2) God alone can call anyone. 3) The greatest part of mankind is not called. 4) Scripture requires every minister in God’s house to be…"}, {"term": "Christian", "meaning": "Christian is called to full-time ministry"}, {"term": "Sanctification", "meaning": "The three calls of God are salvation, sanctification, and full-time Christian service."}], "outline": ["Discuss the three calls of God.", "How does a person recognize the call of God for full time ministry?", "What are Dr. Towns' eight insights into being called by God to full time Christian ministry?"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "The three calls of God are salvation, sanctification, and full-time Christian service."}, {"label": "Key claim", "value": "A ministry call involves burden, conviction, desire, preparation, fruit, church confirmation, and an inner assurance from God."}, {"label": "Key claim", "value": "A genuine call gains strength through time and testing; it does not lose its urgency."}], "pulpit": ["Ability to preach and teach, and people willing to listen.", "The three calls of God are salvation, sanctification, and full-time Christian service.", "A genuine call gains strength through time and testing; it does not lose its urgency."], "compare": null}, {"id": "bl2-10", "number": 10, "title": "The Great Commission", "topic": "Five commissions — send, preach, make disciples, proclaim repentance, and go in the Spirit’s power.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10 (100%) on attempt 1. Essays not graded yet. Attempts used: 1 of 3. Quiz has 10 true/false items plus 3 essays.", "takeaways": ["The Great Commission is given five times, emphasizing sending, global evangelism, discipleship, repentance and forgiveness, Spirit-empowered witnessing, and geographical expansion.", "Church planting is central to evangelism and multiplication. A church reproduces after its kind.", "Disciples commit to Christ, the church, Scripture, fellow believers, and bearing fruit.", "Witnessing shares personal experience. Soul-winning clearly presents the gospel and seeks a response.", "The primary purpose of a New Testament church is evangelism. Multiply converts and congregations.", "“Go” is not a one-time stop-action. Following Jesus includes commitment to His church."], "quiz": [{"q": "The primary purpose of a New Testament church is evangelism.", "answer": "True", "why": "Evangelism is the church’s primary purpose in this lesson."}, {"q": "The a great Commission included taking the gospel to all people groups in the entire world.", "answer": "True", "why": "Moodle wording kept (“The a great Commission”). All peoples, the whole world."}, {"q": "Jesus only gave the Great Commission one time and that is enough to tell each church what it must do.", "answer": "False", "why": "He gave it five times, with different settings and emphases."}, {"q": "There were 10 disciples in the Upper Room on Resurrection Day when Jesus first gave the Great Commission.", "answer": "True", "why": "John 20:21 — ten in the Upper Room (Thomas absent)."}, {"q": "Jesus never told His disciples what to preach, he just told them to go and preach and make disciples.", "answer": "False", "why": "Luke 24 gives the content: repentance and forgiveness of sins."}, {"q": "The Great Commission includes producing and reproducing Christians, and reproducing churches.", "answer": "True", "why": "Disciples who make disciples, churches that plant churches."}, {"q": "Christians must focus on multiplying converts and congregations as the strategic principle.", "answer": "True", "why": "Multiplication of people and of churches is the strategy."}, {"q": "The word \"go\" in the King James Bible is a participle, and means stop action; everyone must go evangelize at least once in their life.", "answer": "False", "why": "A participle is ongoing, not a one-time stop. Moodle: False."}, {"q": "To be a disciple means you have made a commitment to Jesus Christ to follow Him.", "answer": "True", "why": "Disciple = committed follower of Jesus."}, {"q": "To follow Jesus Christ does not mean one is committed to the church.", "answer": "False", "why": "Following Christ includes commitment to His church."}], "essays": [{"theme": "Discuss the five Bible passages containing the Great Commission. How are they similar and how do they differ?", "summary": "All send the disciples as witnesses to the world. They differ in setting, timing, number, and emphasis. John 20:21 (Upper Room, resurrection day, ten) — as the Father sent Me, I send you. Mark 16:15 (~a week later, eleven) — all the world, every creature. Matthew 28:19-20 (Galilee mountain) — make disciples, baptize, teach; authority and presence. Luke 24:46-48 (Jerusalem, day 40) — repentance and forgiveness to all nations, beginning at Jerusalem. Acts 1:8 (Olivet, day 40) — Spirit’s power; Jerusalem, Judea, Samaria, uttermost earth."}, {"theme": "What do we know about the relationship between the Great Commission and church planting? Explain.", "summary": "They belong together. God’s primary method of evangelizing an area is planting a New Testament church. Making disciples includes winning, teaching, encouraging. Baptism brings the believer into the church. Teaching Christ’s commands is church work. A church reproduces after its kind — sending missionaries who plant churches that send more. The local church should reproduce in another neighborhood, town, or village. Only existing churches can be perfected and teach new believers."}, {"theme": "Discuss the five commitments of a disciple.", "summary": "1) Jesus Christ — follow, take up the cross, put Him first. 2) The church — fellowship and gathering. 3) The Word — abide in His word and obey it, not merely know it. 4) Love for other believers — the mark Jesus named. 5) Bearing much fruit — spiritual fruit and helping others follow Jesus. Discipleship is a continuing life of following, learning, loving, and serving."}], "bigIdeas": ["The Great Commission is given five times, emphasizing sending, global evangelism, discipleship, repentance and forgiveness, Spirit-empowered witnessing, and geographical expansion.", "Church planting is central to evangelism and multiplication. A church reproduces after its kind.", "Disciples commit to Christ, the church, Scripture, fellow believers, and bearing fruit.", "Witnessing shares personal experience. Soul-winning clearly presents the gospel and seeks a response.", "The primary purpose of a New Testament church is evangelism. Multiply converts and congregations.", "“Go” is not a one-time stop-action. Following Jesus includes commitment to His church."], "summary": "Five commissions — send, preach, make disciples, proclaim repentance, and go in the Spirit’s power. The Great Commission is given five times, emphasizing sending, global evangelism, discipleship, repentance and forgiveness, Spirit-empowered witnessing, and geographical expansion.", "quickReview": ["The Great Commission is given five times, emphasizing sending, global evangelism, discipleship, repentance…", "Church planting is central to evangelism and multiplication. A church reproduces after its kind.", "Disciples commit to Christ, the church, Scripture, fellow believers, and bearing fruit.", "Witnessing shares personal experience. Soul-winning clearly presents the gospel and seeks a response.", "The primary purpose of a New Testament church is evangelism. Multiply converts and congregations."], "glossary": [{"term": "The a great Commission", "meaning": "Moodle wording kept (“The a great Commission”)."}, {"term": "five Bible passages containing the Great Commission. Ho", "meaning": "All send the disciples as witnesses to the world. They differ in setting, timing, number, and emphasis. John 20:21 (Upper Room, resurrection day, ten) — as the…"}, {"term": "What do we know about the relationship between the Grea", "meaning": "They belong together. God’s primary method of evangelizing an area is planting a New Testament church. Making disciples includes winning, teaching…"}, {"term": "Five commitments of a disciple", "meaning": "1) Jesus Christ — follow, take up the cross, put Him first. 2) The church — fellowship and gathering. 3) The Word — abide in His word and obey it, not merely…"}, {"term": "Disciple", "meaning": "committed follower of Jesus"}, {"term": "Great Commission", "meaning": "Great Commission is given five times, emphasizing sending, global evangelism, discipleship, repentance and forgiveness,"}], "outline": ["Discuss the five Bible passages containing the Great Commission. How are they similar and how do they differ?", "What do we know about the relationship between the Great Commission and church planting? Explain.", "Discuss the five commitments of a disciple."], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "The Great Commission is given five times, emphasizing sending, global evangelism, discipleship, repentance and forgiveness…"}, {"label": "Key claim", "value": "Church planting is central to evangelism and multiplication. A church reproduces after its kind."}, {"label": "Key claim", "value": "Disciples commit to Christ, the church, Scripture, fellow believers, and bearing fruit."}], "pulpit": ["Disciples commit to Christ, the church, Scripture, fellow believers, and bearing fruit.", "Witnessing shares personal experience. Soul-winning clearly presents the gospel and seeks a response.", "The primary purpose of a New Testament church is evangelism. Multiply converts and congregations."], "compare": null}, {"id": "bl2-11", "number": 11, "title": "Leading through Spiritual Gifts", "topic": "Every believer has a gift — discover it, use it, and let it serve the body.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10 (100%) on attempt 1. Essays not graded yet. Attempts used: 1 of 3. Quiz has 10 true/false items plus 3 essays.", "takeaways": ["Every Christian has at least one spiritual gift and should discover and use it. Lack of a gift is not an excuse to sit out.", "A spiritual gift is a Holy Spirit-given ability for serving the body of Christ. Gifts are usually given embryonically and mature as they are exercised.", "Discovery involves Scripture study, inventory, trial and error, Spirit-led service, and counsel from mature believers.", "Gifts help communicate the gospel, meet needs, develop ministry, and build church unity. Success in ministry: calling, gifts, and platform.", "Abuses include ignorance, blindness, imposing, gravitation, colonization, coveting, assimilation, intrusion, manipulation, imitation, immaturity, and obsession.", "Five biblical words: Pneumatikon (spiritual character), Charismata (gracious bestowal), Diakonia (service), Energema (God’s activating power), Phanerosis (visible manifestation)."], "quiz": [{"q": "Not every Christian has one or more spiritual gifts, but they can pray to receive it/them.", "answer": "False", "why": "Every Christian has at least one gift. You do not wait to pray one into existence."}, {"q": "It is not important for a Christian to know his/her spiritual gift(s).", "answer": "False", "why": "Knowing the gift matters so it can be used, not left unidentified."}, {"q": "A spiritual gift is a special ability given by the Holy Spirit to enable Christians to perform spiritual service in the body of Christ.", "answer": "True", "why": "Spirit-given ability for body service — that is the definition."}, {"q": "Spiritual gifts are usually given embryonically and mature as they grow or they are exercised.", "answer": "True", "why": "Given in seed form, matured by use."}, {"q": "Ministry is described in this chapter as communicating the gospel to people at their point of need.", "answer": "True", "why": "Gospel + need = ministry in this chapter."}, {"q": "Gift manipulation is a Christian forcing himself/herself to attempt to use a spiritual ability he/she does not have.", "answer": "True", "why": "Forcing a gift you do not have is manipulation."}, {"q": "Gift colonization happens when people with the same gift expression gather together in a church or Christian organization.", "answer": "True", "why": "Same-gift clustering is colonization — the body needs variety."}, {"q": "This chapter teaches that if a person does not have a spiritual gift, they may use that as an excuse and not try to serve The Lord.", "answer": "False", "why": "Moodle capitalization kept (“The Lord”). No gift-excuse. Everyone has a gift and everyone serves."}, {"q": "Three things give success in ministry: our calling, our spiritual gifts, and our platform for ministry", "answer": "True", "why": "Moodle punctuation kept (no period). Calling, gifts, platform."}, {"q": "Gift obsession is when a person becomes obsessed with the doctrine of spiritual gifts to the exclusion of other doctrines.", "answer": "True", "why": "Gifts as the only doctrine is obsession."}], "essays": [{"theme": "What are spiritual gifts and how might a believer go about discovering what gift(s) she/he possesses?", "summary": "Special abilities from the Holy Spirit for productive service in the body. Discover by studying Scripture, taking an inventory, serving in different areas (trial and error), asking mature believers for counsel, and listening to the Spirit where God gives fruit, desire, and usefulness. Use the gift — do not only name it."}, {"theme": "Discuss the relationship between spiritual gifts and ministry.", "summary": "Gifts are the channels of ministry: they enable believers to communicate the gospel and meet people at their point of need. Used well, they establish a basis for leadership. Ministry builds people; leadership builds the church. A wise pastor delegates ministry but retains leadership. Different gifts help the body work in unity."}, {"theme": "Discuss the five biblical words used to identify spiritual gifts. What is unique about each?", "summary": "Pneumatikon — spiritual in character; the Spirit is the source. Charismata — from charis (grace); freely given, not earned. Diakonia — ministry/service; an opportunity to serve people. Energema — operation, God’s energy activating the ministry, more than natural ability. Phanerosis — manifestation; an evident work of God made visible through the believer."}], "bigIdeas": ["Every Christian has at least one spiritual gift and should discover and use it. Lack of a gift is not an excuse to sit out.", "A spiritual gift is a Holy Spirit-given ability for serving the body of Christ. Gifts are usually given embryonically and mature as they are exercised.", "Discovery involves Scripture study, inventory, trial and error, Spirit-led service, and counsel from mature believers.", "Gifts help communicate the gospel, meet needs, develop ministry, and build church unity. Success in ministry: calling, gifts, and platform.", "Abuses include ignorance, blindness, imposing, gravitation, colonization, coveting, assimilation, intrusion, manipulation, imitation, immaturity, and obsession.", "Five biblical words: Pneumatikon (spiritual character), Charismata (gracious bestowal), Diakonia (service), Energema (God’s activating power), Phanerosis (visible manifestation)."], "summary": "Every believer has a gift — discover it, use it, and let it serve the body. Every Christian has at least one spiritual gift and should discover and use it. Lack of a gift is not an excuse to sit out.", "quickReview": ["Every Christian has at least one spiritual gift and should discover and use it. Lack of a gift is not an…", "A spiritual gift is a Holy Spirit-given ability for serving the body of Christ. Gifts are usually given…", "Discovery involves Scripture study, inventory, trial and error, Spirit-led service, and counsel from mature…", "Gifts help communicate the gospel, meet needs, develop ministry, and build church unity. Success in ministry…", "Abuses include ignorance, blindness, imposing, gravitation, colonization, coveting, assimilation, intrusion…"], "glossary": [{"term": "The Lord", "meaning": "Moodle capitalization kept (“The Lord”)."}, {"term": "spiritual gifts and how might a believer go ab", "meaning": "Special abilities from the Holy Spirit for productive service in the body. Discover by studying Scripture, taking an inventory, serving in different areas…"}, {"term": "Relationship between spiritual gifts and ministry", "meaning": "Gifts are the channels of ministry: they enable believers to communicate the gospel and meet people at their point of need. Used well, they establish a basis…"}, {"term": "five biblical words used to identify spiritual gifts. W", "meaning": "Pneumatikon — spiritual in character; the Spirit is the source. Charismata — from charis (grace); freely given, not earned. Diakonia — ministry/service; an…"}, {"term": "Gifts", "meaning": "Gifts is usually given embryonically and mature as they are exercised"}], "outline": ["What are spiritual gifts and how might a believer go about discovering what gift(s) she/he possesses?", "Discuss the relationship between spiritual gifts and ministry.", "Discuss the five biblical words used to identify spiritual gifts. What is unique about each?"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Every Christian has at least one spiritual gift and should discover and use it. Lack of a gift is not an excuse to sit out."}, {"label": "Key claim", "value": "A spiritual gift is a Holy Spirit-given ability for serving the body of Christ. Gifts are usually given embryonically and mature as they…"}, {"label": "Key claim", "value": "Discovery involves Scripture study, inventory, trial and error, Spirit-led service, and counsel from mature believers."}], "pulpit": ["Every Christian has at least one spiritual gift and should discover and use it. Lack of a gift is not an excuse to sit out.", "A spiritual gift is a Holy Spirit-given ability for serving the body of Christ. Gifts are usually given embryonically and mature…", "Gifts help communicate the gospel, meet needs, develop ministry, and build church unity. Success in ministry: calling, gifts, and…"], "compare": [{"title": "Five biblical words", "points": ["Pneumatikon (spiritual character)", "Charismata (gracious bestowal)", "Diakonia (service)", "Energema (God’s activating power)", "Phanerosis (visible manifestation)"]}]}, {"id": "bl2-12", "number": 12, "title": "Examination of Leadership", "topic": "Leadership is influence — direction, followers, and a journey they actually take with you.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Auto-graded 10/10 (100%) on attempt 1. Essays not graded yet. Attempts used: 1 of 3. Quiz has 10 true/false items plus 3 essays. Course certificate unlocked.", "takeaways": ["Leadership is influence — not making people do what you tell them. It requires direction, followers, credibility, communication, accountability, motivation, problem-solving, and decision-making.", "If the followers are not with the leader on the journey, both are just taking a walk.", "Spiritual gifts and temperaments shape leadership strengths and weaknesses. The primary gift of leadership is not “helps.”", "Biblical models: Moses’ delegation, Joshua’s mentoring, Jesus’ servant leadership, Peter’s growth after failure, and Paul’s strategic planning and disciple-making.", "Joseph planned long-range. Solomon was a transitional leader. Esther led through hostility and crisis.", "People look up to leaders. Leaders look down to followers. Leadership implies both movement and direction."], "quiz": [{"q": "The primary definition of leadership in this chapter is making people do what you tell them.", "answer": "False", "why": "That is command, not this chapter’s definition. Leadership is influence."}, {"q": "The primary definition in this chapter is \"leadership is influence.\"", "answer": "True", "why": "Influence is the headline definition."}, {"q": "People look up to leaders. Leaders look down to followers.", "answer": "True", "why": "Look up / look down — the chapter’s picture of the relationship."}, {"q": "Leadership implies both movement and direction", "answer": "True", "why": "Moodle punctuation kept (no period). Not standing still, and not wandering."}, {"q": "The primary spiritual gift of leadership is \"helps,\" because they must do service-oriented ministry for God.", "answer": "False", "why": "Helps is a serving gift. It is not the primary gift of leadership."}, {"q": "The spiritual gift of exhortation is the special ability to communicate to others and positively motivate them to follow God.", "answer": "True", "why": "Exhortation communicates and motivates toward God."}, {"q": "Joseph is an example of a leader with long-range planning ability for his ministry in Egypt.", "answer": "True", "why": "The seven years of plenty and famine — long-range planning."}, {"q": "Solomon is an example of a transitional leader when he followed principles assuming the throne of his father David.", "answer": "True", "why": "He took the throne by principle, not by novelty — a transitional leader."}, {"q": "Esther is an example of a leader who led the people through times of hostility and crisis.", "answer": "True", "why": "For such a time as this — crisis leadership."}, {"q": "If the followers are not with the leader on the journey, then both are just taking a walk.", "answer": "True", "why": "No followers on the journey = a walk, not leadership."}], "essays": [{"theme": "How might the four temperaments influence our leadership style?", "summary": "Sanguine — friendly, lively, motivating; can be weak-willed and disorganized. Choleric — independent, active, decisive; can be bossy and lack compassion. Melancholy — analytical, gifted, sensitive, faithful; may be pessimistic, fearful, moody. Phlegmatic — calm, dependable, peacemaking; may stay a spectator and avoid leading. Know the strengths and weaknesses; do not mainly work from the weak side."}, {"theme": "What can we learn about leadership from Moses and Joshua?", "summary": "Moses: charismatic and clear about God’s call, and he must delegate — judges, a team for administration and conflict. Joshua: mentored by Moses, prepared others, moved from victory to victory in military and diplomatic work. Together: vision, delegation, mentoring, and learning in the situation God gives."}, {"theme": "What can we learn about leadership from Jesus, Peter, and Paul?", "summary": "Jesus — servant leadership and shepherd leadership: serve, mentor, give His life for the sheep; credibility is ministry to others. Peter — self-correcting: failed, learned, became a respected leader. Paul — strategic planning and disciple-making: planned the work and trained other leaders so the work would continue after him."}], "bigIdeas": ["Leadership is influence — not making people do what you tell them. It requires direction, followers, credibility, communication, accountability, motivation, problem-solving, and decision-making.", "If the followers are not with the leader on the journey, both are just taking a walk.", "Spiritual gifts and temperaments shape leadership strengths and weaknesses. The primary gift of leadership is not “helps.”", "Biblical models: Moses’ delegation, Joshua’s mentoring, Jesus’ servant leadership, Peter’s growth after failure, and Paul’s strategic planning and disciple-making.", "Joseph planned long-range. Solomon was a transitional leader. Esther led through hostility and crisis.", "People look up to leaders. Leaders look down to followers. Leadership implies both movement and direction."], "summary": "Leadership is influence — direction, followers, and a journey they actually take with you. Leadership is influence — not making people do what you tell them. It requires direction, followers, credibility, communication, accountability, motivation, problem-solving, and decision-making. Essay work covers How might the four temperaments influence our leadership style?; What can we learn about leadership from Moses and Joshua?; What can we learn about leadership from Jesus, Peter, and Paul?.", "quickReview": ["Leadership is influence — not making people do what you tell them. It requires direction, followers…", "If the followers are not with the leader on the journey, both are just taking a walk.", "Spiritual gifts and temperaments shape leadership strengths and weaknesses. The primary gift of leadership is…", "Biblical models: Moses’ delegation, Joshua’s mentoring, Jesus’ servant leadership, Peter’s growth after…", "Joseph planned long-range. Solomon was a transitional leader. Esther led through hostility and crisis."], "glossary": [{"term": "Helps", "meaning": "The primary gift of leadership is not “helps.” Biblical models: Moses’ delegation, Joshua’s mentoring, Jesus’ servant leadership, Peter’s growth after failure…"}, {"term": "How might the four temperaments influence our leadershi", "meaning": "Sanguine — friendly, lively, motivating; can be weak-willed and disorganized. Choleric — independent, active, decisive; can be bossy and lack compassion…"}, {"term": "What can we learn about leadership from Moses and Joshu", "meaning": "Moses: charismatic and clear about God’s call, and he must delegate — judges, a team for administration and conflict. Joshua: mentored by Moses, prepared…"}, {"term": "What can we learn about leadership from Jesus, Peter, a", "meaning": "Jesus — servant leadership and shepherd leadership: serve, mentor, give His life for the sheep; credibility is ministry to others. Peter — self-correcting…"}, {"term": "No followers on the journey", "meaning": "a walk"}, {"term": "Leadership", "meaning": "Leadership is influence — not making people do what you tell them"}, {"term": "Solomon", "meaning": "Solomon is a transitional leader"}], "outline": ["How might the four temperaments influence our leadership style?", "What can we learn about leadership from Moses and Joshua?", "What can we learn about leadership from Jesus, Peter, and Paul?"], "mustKnow": [{"label": "Quiz score", "value": "100% (1 attempt)"}, {"label": "Key claim", "value": "Leadership is influence — not making people do what you tell them. It requires direction, followers, credibility, communication…"}, {"label": "Key claim", "value": "If the followers are not with the leader on the journey, both are just taking a walk."}, {"label": "Key claim", "value": "Spiritual gifts and temperaments shape leadership strengths and weaknesses. The primary gift of leadership is not “helps.”"}], "compare": [{"title": "Clarify", "points": ["Leadership is influence", "Not: making people do what you tell them. It requires direction, followers, credibility, communication, accountability…"]}], "pulpit": ["If the followers are not with the leader on the journey, both are just taking a walk.", "Keep this lesson’s center clear for the people: Leadership is influence — direction, followers, and a journey they actually take with you.", "Leadership is influence — not making people do what you tell them. It requires direction, followers, credibility, communication, accountability…"]}], "courseTotal": 100}, {"id": "four-gospels", "code": 64, "title": "The Four Gospels", "status": "complete", "certificateUnlocked": false, "blurb": "Lessons 1-5 and the Final Exam complete (exam 93.89%). Lesson 6 Reading Reports skipped. Course total 94%. No certificate module.", "lessons": [{"id": "fg-1", "number": 1, "title": "Introduction to the Gospels", "topic": "Four portraits of one Lord — synoptics, reliability, and how each Gospel answers who Jesus is.", "quizScore": 93, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Lesson 1 is complete: section quizzes 1.1–1.4 plus the Cumulative Test. No essays.", "introCard": "Quiz 1.1 100% (8/8). Quiz 1.2 87.5% (7/8) — miss: early writings treated the four as genuine (True). Quiz 1.3 90% (4.5/5) — extra “Messiah would never die…” option was incorrect. Quiz 1.4 100% (5/5). Cumulative 93% (28/30) with three partials flagged below.", "essayEmpty": "No essays in Lesson 1", "essayEmptyDetail": "Section quizzes and the cumulative test had no essays. Nothing is invented.", "takeaways": ["The Gospels are historical narratives in the Old Testament pattern, with some Greco-Roman biography features. They are generally chronological, but may arrange things logically, topically, or geographically.", "Intended audience: the Christian community. Cultural orientation: the Jewish culture of the Old Testament.", "Reliability: theological conviction to record the real Jesus, historical corroboration, the Holy Spirit, candid disciple failures, and distinct access (Matthew and John as eyewitnesses; Mark with Peter; Luke with Paul and other witnesses). The Talmud mentions Jesus; first-century Greco-Roman writers do too.", "Synoptics = Matthew, Mark, Luke (“seen together”). They cover mostly the same material, often with the same words. John includes many events the others omit. Majority view: Mark first; Matthew and Luke used Mark.", "Who is Jesus: Matthew — Messianic King; Mark — Suffering Conqueror; Luke — Compassionate Savior; John — Eternal Son of God. Follow Him from the heart, willing to suffer, with compassion on the needy, loved by God and loving others.", "Jesus the true King: power over demons, authority to forgive sins, power to heal and resurrect. Kurios = Lord. Euangelion = good news. Kingdom language outweighs “gospel/evangelize.”", "Early church: the four were received as genuine NT documents. Eusebius: John approved the synoptics; they are the only indisputable ones.", "Review the two misses: 1.2 — early writings did treat the four as genuine (True). 1.3 — “Messiah would never die…” was not in Moodle’s correct set."], "quiz": [], "essays": [], "quizSections": [{"id": "1.1", "title": "Quiz 1.1", "score": 100, "attempts": 1, "quiz": [{"q": "The Jewish Talmud mentions Jesus.", "answer": "True", "why": "The Talmud is extra evidence that Jesus was a known historical figure."}, {"q": "Chronological order in the gospels?", "answer": "They are generally chronological, but sometimes they emphasize logical order or thematic order.", "why": "Default chronology; theme or logic can take the lead."}, {"q": "Prominent cultural orientation?", "answer": "The Jewish culture of the Old Testament", "why": "OT Jewish soil, even when they write in Greek."}, {"q": "Match access to facts.", "answer": "Matthew = eyewitness / disciple. Mark = close companion of Peter. Luke = travelled with Paul and sought reliable eyewitnesses. John = eyewitness, one of the closest disciples.", "why": "Each writer’s access is different. None of them is guessing."}, {"q": "Why quote Plutarch?", "answer": "Because he shows that historians of that time paid close attention to historical detail.", "why": "Plutarch is cited as a window on first-century historical care, not as a Gospel source."}, {"q": "Candid disciple failures evidence reliability.", "answer": "True", "why": "They did not polish themselves."}, {"q": "No Greco-roman writers from first century mention Jesus.", "answer": "False", "why": "Moodle spelling kept (“Greco-roman”). First-century Greco-Roman writers do mention Him."}, {"q": "Intended audience?", "answer": "the Christian community", "why": "Written for the church."}]}, {"id": "1.2", "title": "Quiz 1.2", "score": 87.5, "attempts": 1, "quiz": [{"q": "Match unique relating style.", "answer": "Matthew = shorter stories but more of them / compendium. Mark = fewer stories but longer with more color. Luke = most teaching / more parables / more human portrait.", "why": "Same matching as the cumulative. Matthew is the compendium."}, {"q": "Majority theory?", "answer": "Mark was written first, and Matthew and Luke used Mark.", "why": "Markan priority."}, {"q": "Which is NOT a synoptic gospel?", "answer": "John", "why": "Synoptics = Matthew, Mark, Luke."}, {"q": "What does synoptic mean?", "answer": "seen together", "why": "They can be viewed side by side."}, {"q": "Similarities of the synoptics?", "answer": "They cover mostly the same material, and often use the same words for the teachings.", "why": "Shared material and often shared wording."}, {"q": "According to early writings, the four gospels were always considered by the Church as genuine documents to be included in the NT.", "answer": "True", "why": "Miss — Jay-R chose False. Moodle: True. Early writings treat the four as genuine NT documents."}, {"q": "Eusebius: who approved the synoptic gospels?", "answer": "The Apostle John", "why": "Eusebius reports John’s approval of the synoptics."}, {"q": "Eusebius: “The four Gospels...are the only _________ ones…”", "answer": "indisputable", "why": "The four are the indisputable Gospels in that line."}]}, {"id": "1.3", "title": "Quiz 1.3", "score": 90, "attempts": 1, "quiz": [{"q": "Proofs Jesus was true king (select all that apply).", "answer": "Power over demons; authority to forgive sins; power to heal and resurrect.", "why": "Kingship shown in authority over demons, sin, sickness, and death."}, {"q": "Kurios means?", "answer": "Lord", "why": "Kurios = Lord."}, {"q": "Kingdom terms are used much more frequently in the gospels than terms like gospel and evangelize.", "answer": "True", "why": "Kingdom language outweighs “gospel/evangelize.”"}, {"q": "Literal meaning of euangelion?", "answer": "good news", "why": "Euangelion = good news."}, {"q": "Jewish kingdom expectation vs Jesus (select all that apply).", "answer": "Most Jews thought the old age of sin/death would end all at once, but Jesus taught the kingdom comes in stages. Most Jews thought Messiah would overthrow Rome, but Jesus taught His kingdom was not of this world.", "why": "Partial — Jay-R also chose “Messiah would never die but Jesus taught He would die on the cross.” Moodle’s correct set is the first two only."}]}, {"id": "1.4", "title": "Quiz 1.4", "score": 100, "attempts": 1, "quiz": [{"q": "Chronology of the four gospels (select all that apply).", "answer": "Same basic timeline; they may not meet modern expectations; sometimes organized by theme or geography.", "why": "One basic timeline, not a modern diary. Theme and geography can organize a stretch."}, {"q": "Who is Jesus? Match each Gospel.", "answer": "Matthew = Messianic King. Mark = Suffering Conqueror. Luke = Compassionate Savior. John = Eternal Son of God.", "why": "Four portraits, one Lord."}, {"q": "How do we follow Jesus? Match each Gospel.", "answer": "Matthew = from the heart, not just outwardly. Mark = willing to suffer for Him. Luke = compassion on the poor and needy. John = being loved by God and showing that love to others.", "why": "Each portrait comes with a way to follow."}, {"q": "Differences among the four gospels?", "answer": "There are differences because each author has a different emphasis, but there are no contradictions.", "why": "Emphasis, not contradiction."}, {"q": "Why John omits Lord’s Supper narration?", "answer": "Possibly because it was already included in the other gospels and he wanted to emphasize other things.", "why": "John assumes you know the supper and presses other truths."}]}, {"id": "cumul", "title": "Cumulative Test", "score": 93, "attempts": 1, "quiz": [{"q": "Which of the gospels is NOT considered a \"synoptic\" gospel?", "answer": "John", "why": "Synoptics are Matthew, Mark, and Luke — seen together. John stands apart."}, {"q": "Which best describes chronological order in the gospels?", "answer": "They are generally chronological, but sometimes they emphasize logical order or thematic order.", "why": "Not a strict diary. Chronology is the default; theme can take the lead."}, {"q": "Terms related to the concept of kingdom are used much more frequently in the gospels than terms like \"gospel\" and \"evangelize.\"", "answer": "True", "why": "Kingdom language outweighs “gospel/evangelize” in the four books."}, {"q": "Match each gospel with its unique way of relating stories/teachings.", "answer": "Matthew = shorter stories but more of them / compendium. Mark = fewer stories but longer with more color / least teaching. Luke = most teaching / more parables / more human portrait.", "why": "Partial — Jay-R swapped Matthew and Mark. Moodle: Matthew is the compendium of shorter stories; Mark has fewer, longer, more colorful stories and the least teaching; Luke has the most teaching, more parables, the more human portrait."}, {"q": "The Gospel of John includes many events that are not in the other three gospels.", "answer": "True", "why": "John’s distinctive events are a feature, not a problem."}, {"q": "Candid revelation of disciples’ weaknesses/failures is evidence of reliability.", "answer": "True", "why": "They did not polish themselves. Candor supports reliability."}, {"q": "Which theory is accepted by the majority of scholars?", "answer": "Mark was written first, and Matthew and Luke used Mark.", "why": "Markan priority is the majority scholarly view in this lesson."}, {"q": "Matthew 5 mountainside vs Luke 6 level place — possible explanations (select all that apply).", "answer": "The sermon combines teachings given on several occasions; two different sermons with similar content; the “level place” may have been on top of a high place.", "why": "Partial — Jay-R had the first two. Moodle also marks: a “level place” may have been on top of a high place."}, {"q": "Anointing in a Pharisee’s house (Luke 7) vs Simon the leper (Mark 14)?", "answer": "These are two different accounts of two different but similar events.", "why": "Similar scenes, two events — not a contradiction."}, {"q": "Difference between Jewish theologians’ kingdom expectation vs Jesus (select all that apply).", "answer": "Most Jews thought the old age of sin/death would end all at once, but Jesus taught the kingdom comes in stages. Most Jews thought Messiah would overthrow Rome, but Jesus taught His kingdom was not of this world.", "why": "Both marks. Stages, not one crash; not of this world, not a Roman coup."}, {"q": "Intended audience of the gospels?", "answer": "the Christian community", "why": "Written for the church, not first as a tract to outsiders."}, {"q": "Jewish historian who mentions Jesus?", "answer": "Josephus", "why": "Josephus is the named Jewish historian here."}, {"q": "Prominent cultural orientation of gospel authors?", "answer": "The Jewish culture of the Old Testament", "why": "OT Jewish soil, even when writing in Greek."}, {"q": "Evidence of reliability (select all that apply).", "answer": "Theological conviction to record the real Jesus; corroboration from other historical sources; Holy Spirit inspired.", "why": "Partial — Jay-R also chose “writers had access to facts as disciples/eyewitnesses.” Moodle’s correct set is the three listed; that access-to-facts option is not in the marked set."}, {"q": "Differences in four gospels?", "answer": "There are differences because each author has a different emphasis, but there are no contradictions.", "why": "Emphasis, not contradiction."}, {"q": "Why John omits Lord’s Supper narration?", "answer": "Possibly because it was already included in the other gospels and he wanted to emphasize other things.", "why": "John assumes you know the supper and presses other truths."}, {"q": "Literary genre?", "answer": "They follow the Old Testament pattern of historical narratives, but also borrow some features from the Greco-roman biographies.", "why": "Moodle spelling kept (“Greco-roman”). Historical narrative first, some biography features."}, {"q": "What does \"synoptic\" mean?", "answer": "seen together", "why": "Matthew, Mark, and Luke can be seen together — they share a common view."}, {"q": "Who is Jesus? Match each Gospel.", "answer": "Matthew = Messianic King. Mark = Suffering Conqueror. Luke = Compassionate Savior. John = Eternal Son of God.", "why": "Four portraits, one Lord."}, {"q": "How do we follow Jesus? Match each Gospel.", "answer": "Matthew = not just outwardly but from the heart. Mark = willing to suffer for Him. Luke = compassion on the poor and needy. John = being loved by God and showing that love to others.", "why": "Each portrait of Jesus comes with a way to follow Him."}]}], "summary": "Four portraits of one Lord: historical Gospels with OT narrative shape, synoptic overlap, and clear answers to who Jesus is — Messianic King, Suffering Conqueror, Compassionate Savior, Eternal Son.", "bigIdeas": ["Gospels follow OT historical-narrative pattern (with some Greco-Roman biography features); generally chronological, sometimes topical or geographic.", "Audience: the Christian community. Cultural soil: OT Jewish culture.", "Reliability rests on theological conviction, corroboration, the Spirit, candid disciple failures, and distinct access (Matthew/John eyewitnesses; Mark with Peter; Luke with Paul and others).", "Synoptics = Matthew, Mark, Luke (“seen together”); majority view is Markan priority. John often includes what they omit.", "Who Jesus is: Matthew — Messianic King; Mark — Suffering Conqueror; Luke — Compassionate Savior; John — Eternal Son of God.", "Follow Him: from the heart; willing to suffer; with compassion; loved by God and loving others.", "True King: power over demons, authority to forgive, power to heal and raise. Kurios = Lord; euangelion = good news; kingdom language outweighs “gospel/evangelize.”", "Early church received the four as genuine; Eusebius: John approved the synoptics — the only indisputable ones."], "glossary": [{"term": "Synoptic", "meaning": "“Seen together” — Matthew, Mark, Luke cover mostly the same material, often with the same words."}, {"term": "Kurios", "meaning": "Greek for Lord — the title that names Jesus’ authority."}, {"term": "Euangelion", "meaning": "Greek for good news — the message of the kingdom and the King."}, {"term": "Markan priority", "meaning": "Majority theory: Mark written first; Matthew and Luke used Mark."}, {"term": "Josephus", "meaning": "Jewish historian who mentions Jesus — extra-biblical corroboration."}, {"term": "Talmud", "meaning": "Jewish writings that mention Jesus — further historical witness."}], "outline": ["Genre and chronology of the Gospels", "Audience, culture, and reliability", "Synoptics vs John; Markan priority", "Four portraits: who Jesus is and how we follow", "Kingship proofs, kurios, euangelion, kingdom language", "Early reception (Eusebius / John approving the four)"], "mustKnow": [{"label": "Genre", "value": "OT historical narrative pattern + some Greco-Roman biography features"}, {"label": "Audience", "value": "Christian community"}, {"label": "Culture", "value": "Jewish culture of the Old Testament"}, {"label": "Synoptics", "value": "Matthew, Mark, Luke (not John)"}, {"label": "Majority theory", "value": "Mark first; Matthew and Luke used Mark"}, {"label": "Four portraits", "value": "King / Suffering Conqueror / Compassionate Savior / Eternal Son"}, {"label": "Kurios / Euangelion", "value": "Lord / good news"}], "compare": [{"title": "Who Jesus is — four Gospels", "points": ["Matthew — Messianic King", "Mark — Suffering Conqueror", "Luke — Compassionate Savior", "John — Eternal Son of God"]}, {"title": "How we follow Him", "points": ["Matthew — from the heart, not just outwardly", "Mark — willing to suffer for Him", "Luke — with compassion on the needy", "John — loved by God and loving others"]}, {"title": "Story style (Matthew vs Mark)", "points": ["Matthew — shorter stories but more of them / compendium", "Mark — fewer stories but more detail / vivid"]}], "pulpit": ["Four cameras, one Lord — preach the portrait that fits today’s text without flattening the others.", "Kingdom language outweighs “gospel” talk in the four books — let people hear the King’s reign.", "Reliability is pastoral: candid failures, eyewitness access, and Spirit-guided record of the real Jesus."], "quickReview": ["Synoptics = Matthew, Mark, Luke; John is not synoptic.", "Markan priority: Mark first; Matthew and Luke used Mark.", "Kurios = Lord; euangelion = good news.", "Matthew = King; Mark = Suffering Conqueror; Luke = Compassionate Savior; John = Eternal Son.", "Early writings treated the four as genuine (True) — review Lesson 1.2 miss."]}, {"id": "fg-2", "number": 2, "title": "Matthew", "topic": "Jesus the messianic King — Israel incarnate — fulfilling the promises.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Lesson 2 is complete: Quizzes 2.1–2.3 plus the Cumulative Test, all 100%. No essays. Cumulative pack listed 20 stems (score reported 30/30).", "introCard": "Quiz 2.1 100%. Quiz 2.2 100%. Quiz 2.3 100%. Cumulative 100%. No misses.", "essayEmpty": "No essays in Lesson 2", "essayEmptyDetail": "Section quizzes and the cumulative test had no essays. Nothing is invented.", "takeaways": ["Matthew presents Jesus as the messianic King and “Israel incarnate,” fulfilling OT promises. He quotes the OT more than any other Gospel writer.", "The kingdom of heaven is already begun, not yet complete (Matt 4:17). He prefers “heaven” out of Jewish reverence for the Name.", "Written especially for Jewish Christians, to convince the Jewish people that Jesus is the Messiah King. He expects readers who know Jewish customs, and he meant to reach Jews across the Mediterranean.", "Structure: five narrative/discourse blocks marked by “When Jesus had finished saying these things,” plus an introduction and a conclusion. Most parables are about the kingdom of heaven.", "Matthew is Levi the tax collector, one of the Twelve. He probably wrote in the late 60s (temple still standing). Earliest manuscripts are not Hebrew.", "The genealogy shows Jesus as legal son of David, often traced through adoptive parents. “Son of David” is the name used more frequently. Disciples follow a humble, suffering King — not abundant material blessings.", "Miracles spread the kingdom: people were amazed, then most began to oppose Him. The Olivet Discourse gives hope about future victory. The Canaanite woman is the lesson’s case of firm belief.", "Assembly: Hebrew kahal, Greek ecclesia. “You have heard… but I say” does not nullify the OT law."], "quizSections": [{"id": "2.1", "title": "Quiz 2.1", "score": 100, "attempts": 1, "quiz": [{"q": "Matthew's other name?", "answer": "Levi", "why": "Levi the tax collector — the same man."}, {"q": "When did Matthew probably write?", "answer": "Late 60s; he refers to the temple as if still standing (destroyed AD 70).", "why": "Temple still standing in the narrative world points before AD 70."}, {"q": "Especially wrote for?", "answer": "Jewish Christians", "why": "His first readers are Jewish Christians."}, {"q": "Unique special purpose?", "answer": "To convince the Jewish people that Jesus was the Messiah King", "why": "Messiah King is Matthew’s burden."}, {"q": "Earliest manuscripts of Matthew written in Hebrew.", "answer": "False", "why": "The earliest manuscripts we have are not Hebrew."}, {"q": "Why “Kingdom of heaven” more than “Kingdom of God”?", "answer": "Out of reverence, Jews often avoided using the name of God", "why": "Heaven stands in for the Name."}, {"q": "Matthew was one of Jesus' twelve disciples.", "answer": "True", "why": "One of the Twelve — an eyewitness."}, {"q": "Match authorship statements.", "answer": "Papias — “Matthew put the logia in an ordered arrangement.” Irenaeus — “Matthew also issued a written Gospel among the Hebrews…” Tertullian — “Of the apostles, therefore, John and Matthew first instill faith into us...”", "why": "Papias: ordered logia. Irenaeus: among the Hebrews. Tertullian: John and Matthew first instill faith."}, {"q": "Matthew probably meant to reach Jews in the whole Mediterranean.", "answer": "True", "why": "Not only Judea — Jews across the Mediterranean."}]}, {"id": "2.2", "title": "Quiz 2.2", "score": 100, "attempts": 1, "quiz": [{"q": "Theme of most parables?", "answer": "The kingdom of heaven", "why": "Matthew’s parables keep circling the kingdom."}, {"q": "Reaction as the kingdom spread via miracles?", "answer": "Amazed, but most began to oppose Him", "why": "Wonder first, opposition next."}, {"q": "Meaning of Matt 4:17 “kingdom of heaven is near”?", "answer": "The kingdom has already begun, but is not yet completely fulfilled", "why": "Already inaugurated, not yet complete."}, {"q": "Main point of the Olivet Discourse?", "answer": "To give hope about future victory", "why": "Hope, not a scare chart."}, {"q": "Besides the five major sections?", "answer": "Introduction and a conclusion", "why": "Five discourses sit between intro and conclusion."}, {"q": "Genealogy / not born of a human father?", "answer": "The legal situation is important; ancestries were often traced through adoptive parents", "why": "Joseph’s line gives Jesus legal standing as son of David."}, {"q": "How do most scholars divide Matthew?", "answer": "Five main sections by phrases like “When Jesus had finished saying these things.”", "why": "That refrain marks the five blocks."}, {"q": "Only case of firm belief in Matthew is the Canaanite woman (15:21-28).", "answer": "True", "why": "Moodle: True. She is the standout case of firm belief in this lesson."}]}, {"id": "2.3", "title": "Quiz 2.3", "score": 100, "attempts": 1, "quiz": [{"q": "Jesus was \"Israel _________.\"", "answer": "Incarnate", "why": "Jesus as Israel incarnate — the true Israel in a person."}, {"q": "Matthew quotes OT more than any other gospel writer.", "answer": "True", "why": "Matthew is the heaviest OT quoter of the four."}, {"q": "Hebrew word for \"assembly\"?", "answer": "Kahal", "why": "Kahal is the Hebrew assembly-word."}, {"q": "Name used more frequently?", "answer": "\"Son of David\"", "why": "Son of David is Matthew’s frequent royal name."}, {"q": "Matthew emphasizes abundant material blessings for followers.", "answer": "False", "why": "Disciples follow a humble, suffering King — not a prosperity chart."}]}, {"id": "cumul", "title": "Cumulative Test", "score": 100, "attempts": 1, "quiz": [{"q": "Besides the five major sections?", "answer": "Introduction and a conclusion", "why": "Intro + five + conclusion."}, {"q": "Only firm belief case is the Canaanite woman.", "answer": "True", "why": "Moodle: True."}, {"q": "Jesus was \"Israel _________.\"", "answer": "Incarnate", "why": "Israel incarnate."}, {"q": "Especially wrote for?", "answer": "Jewish Christians", "why": "Jewish Christians first."}, {"q": "Name used more frequently?", "answer": "\"Son of David\"", "why": "Royal son of David."}, {"q": "Unique purpose?", "answer": "To convince the Jewish people that Jesus was the Messiah King", "why": "Messiah King."}, {"q": "Match Papias / Irenaeus / Tertullian.", "answer": "Papias — “Matthew put the logia in an ordered arrangement.” Irenaeus — “Matthew also issued a written Gospel among the Hebrews…” Tertullian — “Of the apostles, therefore, John and Matthew first instill faith into us...”", "why": "Same three authorship witnesses as Quiz 2.1."}, {"q": "Reaction to miracles/kingdom?", "answer": "Amazed, but most began to oppose Him", "why": "Amazement, then opposition."}, {"q": "Matthew did not expect readers familiar with Jewish customs.", "answer": "False", "why": "He expects Jewish familiarity. Moodle: False."}, {"q": "Genealogy legal claims answer?", "answer": "Ancestries were often traced through adoptive parents", "why": "Legal descent through Joseph."}, {"q": "Earliest manuscripts in Hebrew.", "answer": "False", "why": "Earliest manuscripts are not Hebrew."}, {"q": "Matthew's other name?", "answer": "Levi", "why": "Levi."}, {"q": "Emphasizes abundant material blessings.", "answer": "False", "why": "Not a material-blessing gospel."}, {"q": "Greek word for \"assembly\"?", "answer": "Ecclesia", "why": "Ecclesia is the Greek assembly-word (Hebrew: Kahal)."}, {"q": "Matthew's job (select all that apply).", "answer": "He was a tax collector; Jews were encouraged to lie to people of his profession.", "why": "Tax collector — and that profession was despised enough that lying to them was encouraged."}, {"q": "Quotes OT more than any other.", "answer": "True", "why": "Heaviest OT quoter."}, {"q": "\"You have heard… But I say\" nullifies OT law.", "answer": "False", "why": "He fulfills; He does not cancel."}, {"q": "Purpose of the genealogy?", "answer": "Show Jesus is legally a descendant of David", "why": "Legal son of David for messianic claim."}, {"q": "Theme of most parables?", "answer": "The kingdom of heaven", "why": "Kingdom of heaven."}, {"q": "How do scholars divide Matthew?", "answer": "By phrases like “When Jesus had finished saying these things.”", "why": "Five blocks marked by that refrain."}]}], "quiz": [], "essays": [], "summary": "Matthew presents Jesus as the messianic King and “Israel incarnate,” fulfilling OT promises for Jewish readers. Five discourse blocks sit between an introduction and conclusion; the kingdom of heaven has already begun but is not yet complete.", "bigIdeas": ["Jesus is messianic King and “Israel incarnate,” fulfilling OT promises; Matthew quotes the OT more than any other Gospel writer.", "Kingdom of heaven: already begun, not yet complete (Matt 4:17); “heaven” preferred out of Jewish reverence for the Name.", "Written especially for Jewish Christians, to convince Jews that Jesus is the Messiah King; expects Jewish customs; aims at Jews across the Mediterranean.", "Structure: five narrative/discourse blocks marked by “When Jesus had finished saying these things,” plus introduction and conclusion.", "Most parables center on the kingdom of heaven.", "Author: Matthew/Levi the tax collector, one of the Twelve; late 60s (temple still standing); earliest manuscripts not Hebrew.", "Genealogy: legal son of David (often via adoptive parents); “Son of David” used frequently; disciples follow a humble suffering King — not abundant material blessings.", "Miracles: amazement, then opposition; Olivet Discourse gives hope of future victory; Canaanite woman is the lesson’s case of firm belief.", "Assembly: Hebrew kahal, Greek ecclesia; “You have heard… but I say” does not nullify the OT law."], "glossary": [{"term": "Kingdom of heaven", "meaning": "Matthew’s preferred phrase for God’s reign — already begun, not yet complete (4:17); “heaven” shows reverence for the Name."}, {"term": "Israel incarnate", "meaning": "Jesus as the true Israel in a person — fulfilling what Israel was called to be."}, {"term": "Son of David", "meaning": "Royal messianic title Matthew uses more frequently than other names."}, {"term": "Kahal", "meaning": "Hebrew word for assembly — paired with Greek ecclesia."}, {"term": "Ecclesia", "meaning": "Greek word for assembly / church."}, {"term": "Levi", "meaning": "Matthew’s other name — the tax collector among the Twelve."}, {"term": "Canaanite woman", "meaning": "Matthew 15:21–28 — this lesson’s standout case of firm belief."}, {"term": "Olivet Discourse", "meaning": "Jesus’ teaching that gives hope about future victory, not a scare chart."}], "outline": ["Introduction (genealogy, birth, beginnings)", "Five major sections marked by “When Jesus had finished saying these things”", "Conclusion (passion, resurrection, commission)", "Within the five: narrative + discourse blocks; parables of the kingdom", "Miracles spreading the kingdom → amazement → opposition", "Olivet Discourse: hope of future victory"], "mustKnow": [{"label": "Author", "value": "Matthew / Levi — tax collector, one of the Twelve"}, {"label": "Date", "value": "Late 60s (temple referred to as still standing; destroyed AD 70)"}, {"label": "Audience", "value": "Jewish Christians (and Jews across the Mediterranean)"}, {"label": "Purpose", "value": "Convince the Jewish people that Jesus is the Messiah King"}, {"label": "Portrait", "value": "Messianic King; Jesus as “Israel incarnate”"}, {"label": "Structure", "value": "Introduction + five discourse blocks + conclusion"}, {"label": "Key refrain", "value": "“When Jesus had finished saying these things”"}, {"label": "Parable theme", "value": "The kingdom of heaven"}, {"label": "Frequent title", "value": "Son of David"}, {"label": "Manuscripts", "value": "Earliest manuscripts are not Hebrew (False that they are)"}], "compare": [{"title": "Kingdom already / not yet", "points": ["Already begun (Matt 4:17 — “near”)", "Not yet completely fulfilled"]}, {"title": "Assembly words", "points": ["Hebrew — kahal", "Greek — ecclesia"]}, {"title": "Early witnesses on Matthew", "points": ["Papias — ordered arrangement of the logia", "Irenaeus — written Gospel among the Hebrews", "Tertullian — John and Matthew first instill faith"]}], "pulpit": ["Preach the King who is Israel incarnate — OT promises land on a Person, not a program.", "Already / not yet: give hope without pretending the kingdom is finished.", "“You have heard… but I say” fulfills the law; it does not cancel it — careful with antinomian shortcuts.", "Firm belief looks like the Canaanite woman — keep that story warm for doubtful hearers."], "quickReview": ["Matthew = Levi; one of the Twelve; late 60s; Jewish Christians.", "Purpose: convince Jews Jesus is the Messiah King.", "Structure: intro + five (“When Jesus had finished…”) + conclusion.", "Kingdom of heaven: already begun, not yet complete; most parables about it.", "Son of David; Israel incarnate; kahal / ecclesia; Canaanite woman = firm belief."]}, {"id": "fg-3", "number": 3, "title": "Mark", "topic": "The suffering Messiah and victorious Son of God — servant leadership under the cross.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Lesson 3 is complete: Quizzes 3.1–3.3 plus the Cumulative Test. No essays.", "introCard": "Quiz 3.1 94.44% (partial: Rome-audience evidence is Latin words, Peter in Rome, and explaining Palestinian/Aramaic customs — not names from the Roman church). Quiz 3.2 100%. Quiz 3.3 100%. Cumulative 100%.", "essayEmpty": "No essays in Lesson 3", "essayEmptyDetail": "Section quizzes and the cumulative test had no essays. Nothing is invented.", "takeaways": ["Mark presents Jesus as the suffering Messiah and victorious Son of God. Greatest authority: He forgives sins. Greatest victory: He conquered death. Worst suffering: the Father’s wrath, the world’s sin on Him.", "Written to encourage Christians suffering in Rome around Nero’s time. Mark wants them to know their suffering is a sign they are true disciples.", "Mark is not one of the Twelve. He adapts Peter’s teaching. He was from Jerusalem (so he probably knew Jesus), helped Paul on the first journey, then left for Jerusalem. Written after Peter’s death (AD 64), probably before AD 70.", "Structure: Announcement, Power, Apostles’ Affirmation, Suffering, Victory. Centerpiece: Peter’s confession that Jesus is the Christ. Early ministry: Capernaum and Galilee.", "Leadership is serving. Deny yourself, take up the cross (Mk 8:34-35). The Son of Man came to serve (10:45). Love the Lord (12:30). With man it is impossible (10:27).", "Earliest text ends at Mark 16:8 — “they said nothing to anyone, for they were afraid.” Oldest manuscripts do not include more. Jesus did not speak clearly as Messiah from the start, lest crowds hinder the plan. He sought the collision with the authorities.", "The suffering-servant Messiah is already in the OT. His family were not first to see it. In general the Jews viewed Him as a false prophet who should be killed.", "Jewish groups: Zealots (rebellion), apocalyptic groups (supernatural intervention), nomists (obedient to the law). Most Jews lived in the diaspora; those in the land suffered persecution and foreign dominion."], "quizSections": [{"id": "3.1", "title": "Quiz 3.1", "score": 94.44, "attempts": 1, "quiz": [{"q": "Mark was one of the twelve apostles.", "answer": "False", "why": "Mark is not one of the Twelve. He writes Peter’s teaching."}, {"q": "Valid argument that Mark probably knew Jesus?", "answer": "He was from Jerusalem.", "why": "Jerusalem origin is the argument this lesson accepts."}, {"q": "Purpose of the Gospel of Mark?", "answer": "To encourage the Christians who were suffering in Rome around the time of Nero.", "why": "Rome, Nero, suffering saints — keep going."}, {"q": "According to the lesson, which of the following are legitimate evidence that Mark was probably writing his gospel especially to the Christians at Rome? Mark each correct answer.", "answer": "a. Mark uses more Latin words than any other gospel. b. Early writers indicate that he was in Rome, ministering alongside of Peter. e. In his gospel, Mark shows that he felt a need to explain Palestinian customs and Aramaic expressions.", "why": "Partial — Jay-R also chose d (“He mentions several names of people from the church in Rome”), which Moodle marked incorrect. c (“He mentions details of the Roman soldiers”) is not in the correct set. Moodle: a, b, e."}, {"q": "Whose teachings did Mark adapt?", "answer": "Peter.", "why": "Mark is Peter’s Gospel in that sense."}, {"q": "Mark assisted Paul on the first missionary journey but left to return to Jerusalem.", "answer": "True", "why": "He went with Paul, then left for Jerusalem."}]}, {"id": "3.2", "title": "Quiz 3.2", "score": 100, "attempts": 1, "quiz": [{"q": "Centerpiece of Mark?", "answer": "Peter’s recognition that Jesus was the Christ.", "why": "Caesarea Philippi is the hinge of the book."}, {"q": "Ending phrase that may have led scribes to add?", "answer": "“…and they said nothing to anyone, for they were afraid.”", "why": "That abrupt ending invited later additions."}, {"q": "Jesus’ family were first to understand He was Messiah.", "answer": "False", "why": "His family did not lead the way in recognizing Him."}, {"q": "Five main sections in order?", "answer": "Announcement, Power, Apostles’ Affirmation, Suffering, Victory of the Messiah", "why": "That is Mark’s arc: announced, powerful, confessed, suffering, victorious."}, {"q": "Kind of leadership Jesus encouraged?", "answer": "leading as a servant", "why": "Servant leadership — the Son of Man came to serve."}, {"q": "Early ministry concentrated?", "answer": "Capernaum and Galilee", "why": "North first — Capernaum and Galilee."}, {"q": "Worst part of Jesus’ suffering?", "answer": "The wrath of God the Father, with the sin of the world on Him", "why": "Worse than the nails: the Father’s wrath, our sin on Him."}, {"q": "In general Jews viewed Jesus as a false prophet who should be killed.", "answer": "True", "why": "Moodle: True. The general view was hostile."}]}, {"id": "3.3", "title": "Quiz 3.3", "score": 100, "attempts": 1, "quiz": [{"q": "Greatest show of authority?", "answer": "authority to forgive sins", "why": "Forgiving sins is the deepest claim of authority."}, {"q": "Messiah as suffering servant is absent in the OT.", "answer": "False", "why": "The suffering servant is already in the OT."}, {"q": "Match Jewish groups.", "answer": "Zealots = rebellion. Apocalyptic groups = expect God to intervene supernaturally. Nomists = obedient to the law.", "why": "Zealots fight. Apocalyptic groups wait for heaven to break in. Nomists keep the law."}, {"q": "Match references.", "answer": "Son of Man came to serve = Mark 10:45. Love the Lord = Mark 12:30. Deny self and take up the cross = Mark 8:34-35. With man it is impossible = Mark 10:27.", "why": "Serve (10:45), love God (12:30), take the cross (8:34-35), impossible with man (10:27)."}, {"q": "Life of Jews in the last centuries before Christ?", "answer": "Most lived outside Israel, but those within suffered persecution and foreign dominion", "why": "Diaspora majority; those in the land still under foreign power."}]}, {"id": "cumul", "title": "Cumulative Test", "score": 100, "attempts": 1, "quiz": [{"q": "Valid argument that Mark probably knew Jesus?", "answer": "He was from Jerusalem.", "why": "Jerusalem origin."}, {"q": "Mark assisted Paul then left for Jerusalem.", "answer": "True", "why": "First journey, then home."}, {"q": "Early ministry?", "answer": "Capernaum and Galilee", "why": "Galilee first."}, {"q": "Purpose?", "answer": "To encourage the Christians who were suffering in Rome around the time of Nero.", "why": "Suffering Rome under Nero."}, {"q": "Centerpiece?", "answer": "Peter’s recognition that Jesus was the Christ.", "why": "Peter’s confession is the hinge."}, {"q": "Response Mark wanted?", "answer": "Know their suffering was a sign they were true disciples", "why": "Suffering marks true disciples — not failure."}, {"q": "Match Mark 10:45 / 12:30 / 8:34-35 / 10:27.", "answer": "Son of Man came to serve = Mark 10:45. Love the Lord = Mark 12:30. Deny self and take up the cross = Mark 8:34-35. With man it is impossible = Mark 10:27.", "why": "Serve, love, cross, impossible with man."}, {"q": "Leadership?", "answer": "leading as a servant", "why": "Servant leadership."}, {"q": "Ending phrase that may have led scribes to add?", "answer": "“…and they said nothing to anyone, for they were afraid.”", "why": "Abrupt ending at 16:8."}, {"q": "Mark was one of the twelve apostles.", "answer": "False", "why": "Not one of the Twelve."}, {"q": "Why not speak clearly as Messiah from the beginning?", "answer": "More people flocking would hinder fulfilling His plan", "why": "Crowds would get in the way of the cross-shaped plan."}, {"q": "Messiah as suffering servant is absent in the OT.", "answer": "False", "why": "Already in the OT."}, {"q": "Why does Mark 16 end at v. 8?", "answer": "The oldest and most important manuscripts do not include more", "why": "Earliest text stops at 16:8."}, {"q": "Match Zealots / Apocalyptic groups / Nomists.", "answer": "Zealots = rebellion. Apocalyptic groups = expect God to intervene supernaturally. Nomists = obedient to the law.", "why": "Rebellion, supernatural intervention, law-obedience."}, {"q": "When written?", "answer": "After Peter was killed (AD 64), probably before the destruction of Jerusalem in AD 70", "why": "After Peter’s death, before AD 70."}, {"q": "Jesus sought opposition with Jewish authorities.", "answer": "True", "why": "He did not dodge the collision."}, {"q": "Greatest show of authority?", "answer": "authority to forgive sins", "why": "Forgiveness is the deepest authority."}, {"q": "Worst part of Jesus’ suffering?", "answer": "The wrath of God the Father, with the sin of the world on Him", "why": "The cup — the Father’s wrath."}, {"q": "Greatest victory over enemies?", "answer": "He conquered death", "why": "Resurrection is the victory."}, {"q": "Life of Jews in the last centuries BC?", "answer": "Most lived outside Israel; those within suffered persecution and foreign dominion", "why": "Diaspora plus a land under foreign rule."}]}], "quiz": [], "essays": [], "summary": "Mark presents Jesus as the suffering Messiah and victorious Son of God — written to encourage Christians suffering in Rome under Nero. Servant leadership under the cross; the earliest text ends at 16:8.", "bigIdeas": ["Jesus: suffering Messiah and victorious Son of God. Greatest authority: forgives sins. Greatest victory: conquered death. Worst suffering: the Father’s wrath with the world’s sin on Him.", "Purpose: encourage Christians suffering in Rome around Nero’s time — suffering is a sign they are true disciples.", "Mark is not one of the Twelve; adapts Peter’s teaching; from Jerusalem (likely knew Jesus); helped Paul then returned to Jerusalem; written after Peter’s death (AD 64), probably before AD 70.", "Structure: Announcement → Power → Apostles’ Affirmation → Suffering → Victory. Centerpiece: Peter’s confession that Jesus is the Christ. Early ministry: Capernaum and Galilee.", "Leadership is serving: deny yourself, take up the cross (8:34–35); Son of Man came to serve (10:45); love the Lord (12:30); with man it is impossible (10:27).", "Earliest ending: Mark 16:8 — “they said nothing to anyone, for they were afraid.” Oldest manuscripts do not include more.", "Jesus did not speak clearly as Messiah from the start (crowds would hinder the plan); He sought the collision with the authorities.", "Suffering-servant Messiah already in the OT; family were not first to see it; Jews generally viewed Him as a false prophet who should be killed.", "Jewish groups: Zealots (rebellion), apocalyptic groups (supernatural intervention), nomists (obedient to the law). Most Jews in diaspora; those in the land under foreign dominion."], "glossary": [{"term": "Suffering Messiah", "meaning": "Mark’s portrait — the conqueror who wins through the cross, not around it."}, {"term": "Peter’s confession", "meaning": "Centerpiece of Mark — recognition that Jesus is the Christ (hinge of the book)."}, {"term": "Mark 16:8", "meaning": "Earliest ending: “they said nothing to anyone, for they were afraid” — abrupt close that invited later scribal additions."}, {"term": "Servant leadership", "meaning": "Leading by serving — the Son of Man came to serve (10:45)."}, {"term": "Zealots", "meaning": "Jewish group that sought rebellion against foreign power."}, {"term": "Apocalyptic groups", "meaning": "Expected God to intervene supernaturally."}, {"term": "Nomists", "meaning": "Emphasized obedience to the law."}, {"term": "Rome / Nero", "meaning": "Mark’s pastoral setting — suffering Christians need courage under the cross."}], "outline": ["Announcement of the Messiah", "Power of the Messiah (early ministry in Capernaum and Galilee)", "Apostles’ Affirmation — Peter’s confession (centerpiece)", "Suffering of the Messiah", "Victory of the Messiah (resurrection; earliest text ends 16:8)"], "mustKnow": [{"label": "Author", "value": "Mark — not one of the Twelve; adapts Peter’s teaching; from Jerusalem"}, {"label": "Date", "value": "After Peter’s death (AD 64), probably before AD 70"}, {"label": "Audience / place", "value": "Christians suffering in Rome around Nero’s time"}, {"label": "Purpose", "value": "Encourage sufferers — suffering marks true disciples"}, {"label": "Portrait", "value": "Suffering Messiah / victorious Son of God"}, {"label": "Structure", "value": "Announcement, Power, Apostles’ Affirmation, Suffering, Victory"}, {"label": "Centerpiece", "value": "Peter’s recognition that Jesus is the Christ"}, {"label": "Early ministry", "value": "Capernaum and Galilee"}, {"label": "Ending", "value": "Earliest manuscripts end at 16:8"}, {"label": "Greatest authority / victory", "value": "Forgives sins / conquered death"}], "compare": [{"title": "Mark’s key references", "points": ["Deny self, take up the cross — Mark 8:34–35", "Son of Man came to serve — Mark 10:45", "With man it is impossible — Mark 10:27", "Love the Lord — Mark 12:30"]}, {"title": "Jewish groups in the lesson", "points": ["Zealots — rebellion", "Apocalyptic groups — expect supernatural intervention", "Nomists — obedient to the law"]}, {"title": "Rome-audience evidence (Moodle set)", "points": ["More Latin words than any other Gospel", "Early writers place Mark in Rome with Peter", "Explains Palestinian customs and Aramaic expressions", "Not: “names from the church in Rome” or “details of Roman soldiers” as Moodle’s correct set"]}], "pulpit": ["Suffering saints in Rome needed a cross-shaped King — so do we when ministry hurts.", "Greatest authority is forgiveness; greatest victory is the empty tomb; worst cup is the Father’s wrath.", "Lead as a servant (10:45) — deny yourself and take up the cross before you take a title.", "Do not sand off 16:8 — fear and silence can be the honest first response to resurrection."], "quickReview": ["Mark ≠ one of the Twelve; Peter’s teaching; Rome under Nero; after AD 64, before 70.", "Arc: Announcement → Power → Affirmation → Suffering → Victory; hinge = Peter’s confession.", "Forgives sins (authority); conquered death (victory); Father’s wrath (worst suffering).", "Earliest ending: 16:8 — said nothing, for they were afraid.", "Zealots / apocalyptic / nomists; servant leadership; Capernaum & Galilee first."]}, {"id": "fg-4", "number": 4, "title": "Luke", "topic": "Jesus the Savior — reversal for Gentiles, sinners, women, and the poor.", "quizScore": 95, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Lesson 4 is complete: Quizzes 4.1-4.3 plus the Cumulative Test. No essays.", "introCard": "Quiz 4.1 100%. Quiz 4.2 87.5% (miss: temple cleansing — Gentiles crowded out, not merely buying/selling). Quiz 4.3 80% (miss: salvation is primarily reversing people's conditions). Cumulative 95% (miss: salvation defined as deliverance from evil's tyranny and God's judgment, not \"reconciliation with God\").", "essayEmpty": "No essays in Lesson 4", "essayEmptyDetail": "Section quizzes and the cumulative test had no essays. Nothing is invented.", "takeaways": ["Luke presents Jesus as Savior. Luke is a Gentile physician and Paul's coworker. Theophilus is likely a prestigious Roman patron who supported the writing. Wider audience: Gentile Christians facing challenges to their faith.", "Date window: after Mark (~AD 65), probably before AD 67 (Acts silent on Paul's martyrdom and Jerusalem's fall). Same author as Acts: similar Greek, similar themes, same addressee. Muratorian Fragment (AD 170-180) assigns the third Gospel to Luke. Papyrus 75 (~AD 180) already titles it Gospel According to Luke.", "Luke got his information from apostles in Jerusalem and others who knew Jesus while Luke was in Rome. Evidence of authorship: Acts' author was with Paul; 2 Timothy names Luke as coworker.", "Five sections: Beginnings, Galilee, Journey to Jerusalem, Ministry in/near Jerusalem, Crucifixion and Resurrection. Smaller-scale guideline: geography.", "Salvation in this lesson: primarily reversing people's conditions (least/last/lost become first/most/found). Defined as deliverance from the tyranny of evil and from God's judgment against sin. Impossible with men. Jesus fulfilling the plan is often called \"necessary.\"", "Surprising saved: the poor, sinners, Gentiles, and women. Temple cleansing: they were leaving no room for the Gentiles. Miracles show He is the Messiah. He was baptized to identify with sinful humans as Savior.", "Review the three misses: crowding out Gentiles in the temple; salvation as reversal, not \"forgiveness\" as the primary word; salvation defined as deliverance from evil and judgment, not only reconciliation."], "quizSections": [{"id": "4.1", "title": "Quiz 4.1", "score": 100, "attempts": 1, "quiz": [{"q": "Factors for a probable date of Luke (select all that apply).", "answer": "Comparisons with Mark show Luke used Mark, so no earlier than about AD 65. Acts does not report Paul's martyrdom or the fall of Jerusalem, so probably before AD 67.", "why": "Window: after Mark (~65), before 67. Wrong: dating by Peter's martyrdom/Jerusalem to 48, or Matthew as source from 54."}, {"q": "Wider audience?", "answer": "Probably Gentile Christians", "why": "Gentile Christians are Luke's wider audience."}, {"q": "Valid facts about Luke (select all that apply).", "answer": "He was Paul's partner. He was a doctor.", "why": "Coworker and physician. Not a Jew, not an apostle."}, {"q": "Valid facts about the addressee (select all that apply).", "answer": "Possibly a Roman official; named Theophilus (\"lover of God\"); a person of much prestige; financially supported the writing.", "why": "Prestigious Roman patron named Theophilus. Not a Jewish authority, not a doctor, did not accompany Paul."}, {"q": "Same author of Luke and Acts (select all that apply).", "answer": "Similar style of Greek; similar themes; addressed to the same person.", "why": "Style, themes, and Theophilus. Not the same closing greetings, not originally Aramaic."}, {"q": "How did Luke obtain his information?", "answer": "From apostles in Jerusalem and others who knew Jesus when he was in Rome", "why": "Jerusalem apostles plus Rome witnesses."}, {"q": "Valid evidence Luke authored Luke/Acts?", "answer": "The author of Acts was with Paul; 2 Timothy mentions Luke as a coworker.", "why": "The 'we' passages in Acts plus 2 Timothy's coworker."}, {"q": "Earliest known document listing NT books and assigning the third gospel to Luke (AD 170-180)?", "answer": "Muratorian Fragment", "why": "Muratorian Fragment, about 170-180."}, {"q": "Purpose of Luke?", "answer": "To encourage Gentile Christians facing challenges to their faith", "why": "Strengthen Gentile believers under pressure."}]}, {"id": "4.2", "title": "Quiz 4.2", "score": 87.5, "attempts": 1, "quiz": [{"q": "John's disciples ask if He is the Messiah?", "answer": "Go and tell him what you see and hear", "why": "Point John to the works, not a slogan."}, {"q": "What most upset Jesus at the temple cleansing?", "answer": "They were leaving no room for the Gentiles in the temple.", "why": "Miss — Jay-R chose buying/selling in a sacred place. Moodle: the court of the Gentiles was crowded out."}, {"q": "Why was Jesus baptized by John?", "answer": "Identifying with sinful human beings as our Savior", "why": "He stands with sinners as Savior, not as one who needs repentance."}, {"q": "Main purpose of miracles?", "answer": "To show that He was the Messiah", "why": "Signs that He is the Messiah."}, {"q": "Crowd attitude at His condemnation?", "answer": "Most people were opposed to Jesus", "why": "The crowd was against Him."}, {"q": "Five major sections in order?", "answer": "Beginnings 1:5-4:13; Galilee 4:14-9:50; Journey to Jerusalem 9:51-19:27; Ministry in/near Jerusalem 19:28-21:38; Crucifixion and Resurrection 22:1-24:53", "why": "Five blocks, geography carrying the story toward the cross."}, {"q": "Smaller-scale organizing guideline?", "answer": "geography", "why": "Geography organizes the smaller stretches."}, {"q": "Angel in Daniel 9 / announcing John and Jesus?", "answer": "Gabriel", "why": "Gabriel in Daniel, and at the announcements of John and Jesus."}]}, {"id": "4.3", "title": "Quiz 4.3", "score": 80, "attempts": 1, "quiz": [{"q": "Surprising saved groups (select all that apply).", "answer": "The poor, sinners, Gentiles, and women.", "why": "Those four. Not Pharisees, not \"the Jews,\" not the rich."}, {"q": "Jesus fulfilling God's plan is often described as?", "answer": "necessary", "why": "Luke's word is \"necessary\" — the plan must happen."}, {"q": "Salvation is primarily a matter of?", "answer": "reversing peoples' conditions", "why": "Miss — Jay-R chose forgiveness of sins. Moodle: reversing people's conditions (least/last/lost become first/most/found)."}, {"q": "Salvation is impossible with men.", "answer": "True", "why": "Impossible with men — possible with God."}, {"q": "The least, the last, and the lost become?", "answer": "\"the first, the most, and the found\"", "why": "Luke's reversal in a sentence."}]}, {"id": "cumul", "title": "Cumulative Test", "score": 95, "attempts": 1, "quiz": [{"q": "Surprising saved groups (select all that apply).", "answer": "Sinners, women, the poor, and Gentiles.", "why": "The four surprising groups."}, {"q": "What most upset Jesus at the temple cleansing?", "answer": "They were leaving no room for the Gentiles in the temple.", "why": "Correct this time. Gentiles crowded out."}, {"q": "Valid facts about Luke (select all that apply).", "answer": "Paul's partner; a doctor.", "why": "Coworker and physician."}, {"q": "Angel who announced John and Jesus?", "answer": "Gabriel", "why": "Gabriel."}, {"q": "Valid facts about Theophilus (select all that apply).", "answer": "A person of prestige; financially supported the writing; named Theophilus (\"lover of God\"); possibly a Roman official.", "why": "Prestigious Roman patron."}, {"q": "Ways to date a manuscript (select all that apply).", "answer": "Chemical / carbon-14; paleography; external comments.", "why": "Those three. Not parchment thickness/color. Not paleontology."}, {"q": "Salvation is primarily a matter of?", "answer": "reversing peoples' conditions", "why": "Reversal — Moodle's primary answer."}, {"q": "How does the lesson define salvation?", "answer": "Deliverance from the tyranny of evil, and from God's judgment against sin.", "why": "Miss — Jay-R chose reconciliation with God. Moodle: deliverance from evil's tyranny and from God's judgment against sin."}, {"q": "Smaller-scale organizing guideline?", "answer": "geography", "why": "Geography."}, {"q": "Match the Luke references.", "answer": "Luke 4:18-21 — the Spirit of the Lord / good news to the poor. Luke 22:67-70 — Son of God. Luke 23:43 — paradise. Luke 23:46 — into your hands I commit my spirit.", "why": "Poor, Son of God, paradise, commit my spirit."}, {"q": "Jesus fulfilling God's plan is often described as?", "answer": "necessary", "why": "Necessary."}, {"q": "The least, the last, and the lost become?", "answer": "\"the first, the most, and the found\"", "why": "Luke's reversal."}, {"q": "Manuscript about AD 180 with the title Gospel According to Luke?", "answer": "Papyrus 75", "why": "P75 carries that title around AD 180."}, {"q": "Earliest NT canon list assigning the third gospel to Luke?", "answer": "Muratorian Fragment", "why": "Muratorian Fragment."}, {"q": "Which is NOT a topic on the journey to Jerusalem?", "answer": "True believers blessed with good health, favor, and economic prosperity", "why": "That prosperity line is not Luke's journey theme."}, {"q": "Evidence Luke authored Luke/Acts?", "answer": "The author of Acts was with Paul; 2 Timothy mentions Luke as a coworker.", "why": "Acts 'we' plus 2 Timothy."}, {"q": "Purpose of miracles?", "answer": "To show that He was the Messiah", "why": "Messiah signs."}, {"q": "John's disciples ask if He is the Messiah?", "answer": "Go and tell him what you see and hear", "why": "Show John the works."}, {"q": "Why was Jesus baptized?", "answer": "Identifying with sinful human beings as our Savior", "why": "He stands with sinners as Savior."}, {"q": "Same author of Luke and Acts (select all that apply).", "answer": "Similar themes; similar style of Greek; addressed to the same person.", "why": "Themes, Greek, Theophilus."}]}], "quiz": [], "essays": [], "summary": "Luke presents Jesus as the compassionate Savior for a wider Gentile Christian audience — orderly history for Theophilus, salvation as reversal and deliverance, with special attention to the poor, sinners, Gentiles, and women.", "bigIdeas": ["Luke: Paul’s partner and physician — not a Jew, not an apostle — writing orderly history for Theophilus and a wider Gentile Christian audience.", "Date window: after Mark (~AD 65), before about 67; comparisons show Luke used Mark.", "Structure tracks geography and salvation history: Galilee → journey to Jerusalem → ministry in/near Jerusalem → crucifixion and resurrection; smaller-scale guideline is geography.", "Salvation in this lesson: primarily reversing people’s conditions (least/last/lost become first/most/found); deliverance from tyranny of evil and God’s judgment against sin; often called “necessary.”", "Surprising saved: the poor, sinners, Gentiles, and women.", "Temple cleansing: they were leaving no room for the Gentiles — that most upset Jesus in this lesson.", "Miracles show He is the Messiah; baptized to identify with sinful humans as Savior.", "Review misses: Gentiles crowded out at the temple; salvation as reversal (not “forgiveness” as the primary word here); deliverance from evil and judgment (not only reconciliation)."], "glossary": [{"term": "Theophilus", "meaning": "Named recipient of Luke’s orderly account — “lover of God.”"}, {"term": "Salvation (Luke lesson)", "meaning": "Primarily reversing people’s conditions; deliverance from evil’s tyranny and God’s judgment against sin."}, {"term": "Necessary", "meaning": "Luke’s frequent word for Jesus fulfilling God’s plan — it must happen."}, {"term": "Temple cleansing", "meaning": "What most upset Jesus here: leaving no room for the Gentiles."}, {"term": "Muratorian Fragment / Papyrus 75", "meaning": "Early witnesses tied to Luke’s reception in the course material."}], "outline": ["Galilee ministry", "Journey to Jerusalem", "Ministry in and near Jerusalem", "Crucifixion and Resurrection", "Geographic guideline on the smaller scale"], "mustKnow": [{"label": "Author", "value": "Luke — Paul’s partner, doctor; not Jew, not apostle"}, {"label": "Audience", "value": "Probably Gentile Christians (Theophilus + wider)"}, {"label": "Date factors", "value": "Used Mark (≥~65); before ~67 in the lesson’s window"}, {"label": "Portrait", "value": "Compassionate Savior"}, {"label": "Salvation focus", "value": "Reversing conditions; deliverance from evil and judgment"}, {"label": "Surprising saved", "value": "Poor, sinners, Gentiles, women"}, {"label": "Baptism reason", "value": "Identify with sinful humans as Savior"}], "compare": [{"title": "What salvation is (this lesson)", "points": ["Primarily reversing people’s conditions", "Deliverance from tyranny of evil and God’s judgment", "Not graded here as merely “forgiveness” or only “reconciliation”"]}], "pulpit": ["Preach the reversal: least become first — Luke’s Savior finds the lost without flattering the powerful.", "Temple courts matter: when worship crowds out the nations, Jesus overturns tables.", "“Necessary” is pastoral courage — the cross was not Plan B."], "quickReview": ["Luke: physician, Paul’s partner; Gentile Christians; Theophilus.", "Arc: Galilee → Jerusalem journey → Jerusalem → cross & empty tomb.", "Salvation: reverse conditions; deliverance from evil and judgment.", "Surprising saved: poor, sinners, Gentiles, women.", "Temple miss: Gentiles crowded out; baptism = identify with sinners as Savior."]}, {"id": "fg-5", "number": 5, "title": "John", "topic": "Jesus the Christ and Son of God -- believe, and have life.", "quizScore": 95, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Lesson 5 is complete: Quizzes 5.1-5.3 plus the Cumulative Test. No essays. Moodle's 'signs' option is reported as graded, even though the wording is odd.", "introCard": "Quiz 5.1 100%. Quiz 5.2 87.5% (miss: why miracles are called signs -- Moodle: \"Because they are not meant to point to Jesus.\"). Quiz 5.3 100%. Cumulative 95% (miss: Eusebius quotes Irenaeus about John at Ephesus, not Clement of Alexandria).", "essayEmpty": "No essays in Lesson 5", "essayEmptyDetail": "Section quizzes and the cumulative test had no essays. Nothing is invented.", "takeaways": ["John emphasizes Jesus as the Christ and Son of God, belief, life, eyewitness testimony, signs, the \"I am\" sayings, and Jesus as the fulfillment of God's presence (tabernacle/temple).", "Structure: introduction, public ministry, private ministry, conclusion. Public ministry is divided by Passovers and feasts. Climax: Thomas's confession -- my Lord and my God. First sign: water to wine at Cana.", "John (son of Zebedee, Jesus' cousin, inner circle, Sons of Thunder, later exiled on Patmos) wrote from Ephesus. He is not named in the Gospel. Audience: Jewish believers outside Palestine still in the synagogue. Purpose: confirm that Jesus is both Christ and Son of God.", "Other books: 1-3 John and Revelation. P52 / Ryland's dates 100-150 AD. Authorship was not, in this lesson, a long serious debate. Eusebius quotes Irenaeus about John at Ephesus.", "Four themes: Son of God, Christ, Life, Believing. \"Believe\" appears 106 times (34 in the synoptics). Eternal life is joyful fellowship with God that already begins when we believe. \"I am\" is used 24 times as a claim of deity.", "He fulfills tabernacle/temple by showing God's presence in the world. Sanctuary decorations were modeled after Eden. Foot washing symbolized His whole earthly ministry.", "Feast of Dedication: 165 BC, Maccabees vs Antiochus Ephiphanes, purifying the temple -- today Hanukkah. Quote: John is a pool in which babes wade and elephants swim.", "Review: Moodle's graded answer for \"signs\" is \"Because they are not meant to point to Jesus.\" And Eusebius quotes Irenaeus, not Clement."], "quizSections": [{"id": "5.1", "title": "Quiz 5.1", "score": 100, "attempts": 1, "quiz": [{"q": "Vocabulary and themes are similar to first-century Palestinian Judaism.", "answer": "True", "why": "John sounds like Palestinian Judaism of that century."}, {"q": "The name of John is not mentioned in the fourth gospel.", "answer": "True", "why": "The author never names himself John in this Gospel."}, {"q": "Many references show the author was an eyewitness.", "answer": "True", "why": "Eyewitness notes run through the book."}, {"q": "John probably wrote from ________.", "answer": "Ephesus", "why": "Ephesus is the probable place of writing."}, {"q": "True about John (select all that apply).", "answer": "Jesus was his cousin; he was the son of Zebedee.", "why": "Son of Zebedee, cousin of Jesus."}, {"q": "Other NT books by John (select all that apply).", "answer": "1 John; 2 John; 3 John; Revelation", "why": "The three letters and Revelation."}, {"q": "Purpose?", "answer": "To confirm for Jewish believers that Jesus was both Christ and the Son of God", "why": "Christ and Son of God -- confirmation, not first introduction."}, {"q": "Probable audience?", "answer": "Jewish believers outside Palestine still participating in the synagogue", "why": "Diaspora synagogue believers."}, {"q": "Authorship has been seriously debated throughout history.", "answer": "False", "why": "Moodle: False. Authorship was not a long serious debate in this lesson's telling."}, {"q": "Oldest manuscript Papyrus 52 / Ryland's dates between _______.", "answer": "100 and 150 AD", "why": "Moodle spelling kept (Ryland's). P52 about 100-150."}]}, {"id": "5.2", "title": "Quiz 5.2", "score": 87.5, "attempts": 1, "quiz": [{"q": "Match John 1:10-14 ideas to the four divisions.", "answer": "Introduction = Jesus came into the world. Public Ministry = rejected by His own. Private Ministry = those who received became children of God. Conclusion = those who believed became witnesses.", "why": "Came, rejected, received as children, then witnesses."}, {"q": "Why are miracles called \"signs\"?", "answer": "Because they are not meant to point to Jesus.", "why": "Miss on 5.2 -- Jay-R chose that they point to the authority of the apostles. Moodle graded this wording correct (odd as it sounds): they are not meant to point to Jesus. Report the grade, do not invent a cleaner option."}, {"q": "Foot washing symbolized?", "answer": "His whole earthly ministry", "why": "Not a side ritual -- the whole ministry in a basin."}, {"q": "Climax of John's narrative?", "answer": "Thomas's confession that Jesus is his Lord and God", "why": "Thomas: my Lord and my God."}, {"q": "Public Ministry sections divided by?", "answer": "Passovers and religious feasts", "why": "The feasts mark the public blocks."}, {"q": "Rabbi means?", "answer": "Teacher", "why": "Rabbi = Teacher."}, {"q": "Match the John references.", "answer": "John 1:10-14 = the world / His own / children of God / glory. John 15:1-5 = the vine. John 14:26 = the Helper. John 17 = He prays for His disciples.", "why": "World/own/children/glory; vine; Helper; the prayer."}, {"q": "Greek king who massacred, desecrated the temple, and set up Zeus?", "answer": "Antiochus Ephiphanes", "why": "Moodle spelling kept (Ephiphanes). The Hanukkah villain."}]}, {"id": "5.3", "title": "Quiz 5.3", "score": 100, "attempts": 1, "quiz": [{"q": "Eternal life meaning?", "answer": "A timeless state of continual joyful fellowship with God, already beginning when we believe", "why": "Already, not only later. Fellowship with God now."}, {"q": "Phrase Jesus used 24 times claiming deity?", "answer": "\"I am\"", "why": "The I am sayings."}, {"q": "How does He fulfill tabernacle/temple?", "answer": "He showed God's presence in the world", "why": "God's presence, now in a Person."}, {"q": "Tabernacle/temple decorations modeled after?", "answer": "The Garden of Eden", "why": "Eden is the pattern behind the sanctuary art."}, {"q": "Four major themes (select all that apply).", "answer": "Son of God; Christ; Life; Believing", "why": "Those four hold the book together."}]}, {"id": "cumul", "title": "Cumulative Test", "score": 95, "attempts": 1, "quiz": [{"q": "Match the John references.", "answer": "John 1:10-14 = the world / His own / children of God / glory. John 15:1-5 = the vine. John 14:26 = the Helper. John 17 = He prays for His disciples.", "why": "Same matching as Quiz 5.2."}, {"q": "Match John 1:10-14 ideas to the four divisions.", "answer": "Introduction = Jesus came into the world. Public Ministry = rejected by His own. Private Ministry = those who received became children of God. Conclusion = those who believed became witnesses.", "why": "Came, rejected, received, witnesses."}, {"q": "Quote about John?", "answer": "\"It is a pool in which babes wade and elephants swim.\"", "why": "Simple enough for a child, deep enough for a lifetime."}, {"q": "Audience?", "answer": "Jewish believers outside Palestine still participating in the synagogue", "why": "Diaspora synagogue believers."}, {"q": "True about John (select all that apply).", "answer": "Son of Zebedee; Jesus was his cousin.", "why": "Zebedee's son, Jesus' cousin."}, {"q": "Why are miracles called \"signs\"?", "answer": "Because they are not meant to point to Jesus.", "why": "Moodle graded this wording correct here too: they are not meant to point to Jesus."}, {"q": "Life of John (select all that apply).", "answer": "Inner circle; Sons of Thunder; exiled on Patmos", "why": "Inner circle, thunder, Patmos."}, {"q": "First miracle?", "answer": "Water to wine at Cana", "why": "Cana -- the first sign."}, {"q": "Word used 106 times in John vs 34 in the synoptics?", "answer": "Believe", "why": "Believe is John's heavy word."}, {"q": "John is not named in the gospel.", "answer": "True", "why": "He does not name himself."}, {"q": "Vocabulary and themes similar to Palestinian Judaism.", "answer": "True", "why": "Palestinian Judaism of that century."}, {"q": "Purpose?", "answer": "To confirm for Jewish believers that Jesus was both Christ and the Son of God", "why": "Confirm Christ and Son of God."}, {"q": "Four major themes (select all that apply).", "answer": "Christ; Life; Believing; Son of God", "why": "The four themes."}, {"q": "Other NT books (select all that apply).", "answer": "1 John; 2 John; 3 John; Revelation", "why": "Letters plus Revelation."}, {"q": "Feast of Dedication (select all that apply).", "answer": "Began 165 BC, Maccabees vs Antiochus; purifying the temple; today Hanukkah", "why": "Moodle spelling in the lesson pack: Macabbees. Hanukkah is Dedication."}, {"q": "Wrote from?", "answer": "Ephesus", "why": "Ephesus."}, {"q": "Eternal life?", "answer": "Joyful fellowship with God, already beginning when we believe", "why": "Already, at belief."}, {"q": "Many references show the author was an eyewitness.", "answer": "True", "why": "Eyewitness."}, {"q": "Greek king?", "answer": "Antiochus Ephiphanes", "why": "Moodle spelling kept."}, {"q": "Whom does Eusebius quote about John at Ephesus?", "answer": "Irenaeus", "why": "Miss -- Jay-R chose Clement of Alexandria. Moodle: Irenaeus."}]}], "quiz": [], "essays": [], "summary": "John presents Jesus as the Christ and Son of God so that readers believe and have life — signs, “I am” sayings, tabernacle/temple fulfillment, written from Ephesus for Jewish believers still in the synagogue outside Palestine.", "bigIdeas": ["Emphases: Christ and Son of God, belief, life, eyewitness testimony, signs, “I am” sayings, fulfillment of God’s presence (tabernacle/temple).", "Structure: introduction, public ministry, private ministry, conclusion. Public ministry divided by Passovers and feasts. Climax: Thomas — “my Lord and my God.” First sign: water to wine at Cana.", "Author: John son of Zebedee (Jesus’ cousin, inner circle, Sons of Thunder, later Patmos); wrote from Ephesus; not named in the Gospel. Also 1–3 John and Revelation.", "Audience: Jewish believers outside Palestine still in the synagogue. Purpose: confirm Jesus is both Christ and Son of God.", "Four themes: Son of God, Christ, Life, Believing. “Believe” ~106× (34 in synoptics). Eternal life: joyful fellowship with God already beginning when we believe. “I am” 24× as claim of deity.", "Fulfills tabernacle/temple by showing God’s presence in the world; sanctuary decorations modeled after Eden; foot washing symbolized His whole earthly ministry.", "Feast of Dedication: 165 BC, Maccabees vs Antiochus Epiphanes, purifying the temple — today Hanukkah.", "Quote: John is a pool in which babes wade and elephants swim. P52/Rylands ~100–150 AD. Eusebius quotes Irenaeus about John at Ephesus."], "glossary": [{"term": "Signs", "meaning": "John’s word for miracles — graded Moodle answer for why: “Because they are not meant to point to Jesus” (review this miss carefully against the pack wording)."}, {"term": "I am", "meaning": "Phrase Jesus used 24 times claiming deity."}, {"term": "Eternal life", "meaning": "Timeless joyful fellowship with God, already beginning when we believe."}, {"term": "Thomas’s confession", "meaning": "Climax — “my Lord and my God.”"}, {"term": "Feast of Dedication", "meaning": "165 BC temple purification (Maccabees vs Antiochus) — Hanukkah."}, {"term": "P52 / Rylands", "meaning": "Early manuscript fragment dated roughly 100–150 AD."}, {"term": "Ephesus", "meaning": "Where John wrote; Eusebius quotes Irenaeus (not Clement) about John there."}], "outline": ["Introduction", "Public ministry (divided by Passovers and feasts; first sign at Cana)", "Private ministry", "Conclusion (Thomas’s confession as climax)"], "mustKnow": [{"label": "Author", "value": "John son of Zebedee — cousin, inner circle; from Ephesus; unnamed in the Gospel"}, {"label": "Audience", "value": "Jewish believers outside Palestine still in the synagogue"}, {"label": "Purpose", "value": "Confirm Jesus is Christ and Son of God — believe and have life"}, {"label": "Structure", "value": "Introduction, public ministry, private ministry, conclusion"}, {"label": "Four themes", "value": "Son of God, Christ, Life, Believing"}, {"label": "Believe count", "value": "~106 times (34 in the synoptics)"}, {"label": "First sign", "value": "Water to wine at Cana"}, {"label": "Climax", "value": "Thomas: my Lord and my God"}], "compare": [{"title": "John 1:10–14 mapped to structure", "points": ["Introduction — Jesus came into the world", "Public ministry — rejected by His own", "Private ministry — received as children of God", "Conclusion — witnesses of His glory"]}], "pulpit": ["Believe and live — John’s aim is faith that already tastes fellowship with God.", "Preach the “I am” sayings as deity claims, not mere metaphors.", "Babes and elephants: keep John simple enough for a child and deep enough for a lifetime."], "quickReview": ["John: Ephesus; synagogue diaspora Jews; Christ + Son of God.", "Structure: intro → public → private → conclusion; climax = Thomas.", "Themes: Son of God, Christ, Life, Believing (~106×).", "I am ×24; eternal life already begun; foot washing = whole ministry.", "Misses to review: signs wording; Eusebius quotes Irenaeus (not Clement)."]}, {"id": "fg-final", "number": "Exam", "title": "Final Exam", "topic": "Course exam covering Introduction through John -- 93.89%. Four misses to review.", "quizScore": 93.89, "quizAttempts": 1, "status": "complete", "quizWordingNote": "Attempt 101315, cmid 1177, 56.33/60 (93.89%). The 56 correct items largely repeat L1-L5 quizzes already on those pages. Full remaining stems were not in this pack, so they are not invented here. The four misses are below.", "introCard": "Course total currently 94/100. Lesson 6 Reading Reports are still open (not submitted). Four misses on this exam: Q5 Matthew/Mark story-style matching swapped; Q21 Canaanite woman as Matthew's case of firm belief is True; Q22 Matthew's extra pieces are introduction and conclusion; Q33 Mark's earliest ending is they said nothing, for they were afraid.", "essayEmpty": "No essays on the Final Exam", "essayEmptyDetail": "Nothing is invented.", "takeaways": ["Synoptics vs John, Markan priority, kingdom in stages, genre as OT historical narrative with some Greco-Roman biography -- already on Lesson 1.", "Who Jesus is and how we follow Him (the four portraits) -- already on Lessons 1-5.", "Matthew: Jewish Christians, Messiah King, kingdom of heaven, five sections plus intro and conclusion. Mark: Rome, suffering, servant. Luke: salvation, Gentiles, Theophilus, Muratorian Fragment, Papyrus 75. John: synagogue diaspora, Irenaeus, Ephesus, cousin and son of Zebedee, the four themes.", "Review the four misses: Matthew is the shorter-story compendium (not Mark). The Canaanite woman is Matthew's case of firm belief (True). Besides five major sections Matthew has an introduction and a conclusion. Mark's earliest ending (the one that invited scribal additions) is they said nothing to anyone, for they were afraid -- not the later longer ending."], "quizSections": [{"id": "final", "title": "Final Exam -- the four misses", "score": 93.89, "attempts": 1, "quiz": [{"q": "Match each gospel with its unique way of relating stories/teachings. (Q5)", "answer": "Matthew = shorter stories but more of them / compendium. Mark = fewer stories but longer with more color. Luke = most teaching / more parables / more human portrait.", "why": "Partial -- Jay-R swapped Matthew and Mark (same miss as Lesson 1 cumulative Q4). Moodle: Matthew is the compendium."}, {"q": "The only case of firm belief in Matthew is the Canaanite woman (15:21-28). (Q21)", "answer": "True", "why": "Miss -- Jay-R chose False. Moodle: True. Same item as Quiz 2.2."}, {"q": "Besides the five major sections, Matthew includes? (Q22)", "answer": "Introduction and a conclusion", "why": "Miss -- Jay-R chose interruptions of teachings with brief narratives. Moodle: introduction and a conclusion."}, {"q": "Ending phrase that may have led scribes to add to Mark? (Q33)", "answer": "...and they said nothing to anyone, for they were afraid.", "why": "Miss -- Jay-R chose the later longer ending (the Lord worked with them and confirmed the message by accompanying signs). Moodle: the abrupt 16:8 ending."}]}], "quiz": [], "essays": [], "summary": "Course exam covering Introduction through John (93.89%). Rehearse the four portraits, Matthew’s structure and firm-belief case, Mark’s ending, and the Lesson 1 story-style matching.", "bigIdeas": ["Synoptics vs John, Markan priority, kingdom in stages, genre as OT historical narrative with Greco-Roman biography features — Lesson 1.", "Four portraits and how we follow Him — Lessons 1–5.", "Matthew: Jewish Christians, Messiah King, kingdom of heaven, five sections plus intro and conclusion.", "Mark: Rome, suffering, servant; earliest ending invites scribal additions.", "Luke: salvation, Gentiles, Theophilus, Muratorian Fragment, Papyrus 75.", "John: synagogue diaspora, Irenaeus, Ephesus, son of Zebedee / cousin, four themes."], "glossary": [{"term": "Matthew story style", "meaning": "Shorter stories but more of them / compendium (do not swap with Mark)."}, {"term": "Mark story style", "meaning": "Fewer stories but more detail / vivid."}, {"term": "Canaanite woman", "meaning": "Only case of firm belief in Matthew in this course’s grading (True)."}, {"term": "Mark 16:8", "meaning": "Earliest ending that invited scribal additions — silence and fear."}], "outline": ["Intro / synoptics / portraits", "Matthew must-knows", "Mark must-knows", "Luke must-knows", "John must-knows", "Four exam misses to drill"], "mustKnow": [{"label": "Exam score", "value": "93.89%"}, {"label": "Miss Q5", "value": "Matthew = shorter/more (compendium); Mark = fewer/more detail — do not swap"}, {"label": "Miss Q21", "value": "Canaanite woman as Matthew’s firm-belief case = True"}, {"label": "Miss Q22", "value": "Besides five sections: introduction and conclusion"}, {"label": "Miss Q33", "value": "Mark’s earliest ending: said nothing… for they were afraid"}], "compare": [{"title": "Four exam misses", "points": ["Q5 — Matthew/Mark story-style matching (swapped)", "Q21 — Canaanite woman firm belief = True", "Q22 — Matthew extras = introduction and conclusion", "Q33 — Mark 16:8 earliest ending wording"]}], "pulpit": ["Use the exam misses as a review drill before you teach any of the four Gospels again.", "Synoptics vs John, Markan priority, kingdom in stages, genre as OT historical narrative with some Greco-Roman biography -- already on Lesson 1.", "Who Jesus is and how we follow Him (the four portraits) -- already on Lessons 1-5."], "quickReview": ["Matthew = compendium (shorter/more); Mark = fewer/more detail.", "Canaanite woman firm belief in Matthew = True.", "Matthew: intro + five + conclusion.", "Mark earliest ending: nothing to anyone, for they were afraid.", "Course total ~94%; Lesson 6 reading reports skipped."]}, {"id": "fg-6", "number": 6, "title": "Extra Reading", "topic": "Reading reports skipped -- not submitted.", "quizScore": null, "quizAttempts": 0, "status": "skipped", "introCard": "Skipped. Reading Reports were not submitted.", "takeaways": ["Assignment (cmid 1180) required 300+ pages of additional reading plus written reports in one combined document.", "Jay-R skipped this assignment. No report is invented. Course quizzes and the Final Exam stand as the completed work (course total 94%)."], "quiz": [], "essays": [], "quizEmpty": "Skipped -- no reading report", "quizEmptyDetail": "Not submitted. Nothing is invented.", "essayEmpty": "Skipped -- no reading report", "essayEmptyDetail": "Not submitted. Nothing is invented.", "summary": "Reading reports skipped -- not submitted. Skipped in this pack — waiting on fuller notes before dense enrichment.", "bigIdeas": ["Assignment (cmid 1180) required 300+ pages of additional reading plus written reports in one combined document.", "Jay-R skipped this assignment. No report is invented. Course quizzes and the Final Exam stand as the completed work (course total 94%)."], "quickReview": ["Assignment (cmid 1180) required 300+ pages of additional reading plus written reports in one…", "Jay-R skipped this assignment. No report is invented. Course quizzes and the Final Exam stand as…"], "glossary": null, "outline": null, "mustKnow": null, "compare": null, "pulpit": null}], "courseTotal": 94}, {"id": "apologetics-1", "code": 62, "title": "Apologetics 1", "status": "complete", "certificateUnlocked": true, "blurb": "What Is Apologetics through Logical Proof That the Bible Is God’s Word — Lessons 1–6 complete. Certificate unlocked (cmid 2109). Course total 100%.", "lessons": [{"id": "ap1-1", "number": 1, "title": "What Is Apologetics and What Is Its Purpose", "topic": "A reasoned defense of the faith — and an aid against doubt.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 1: 10/10 (100%) on attempt 1 (7m 51s). Essays not graded yet. Certificate module restricted.", "summary": "Apologetics is a reasoned defense of Christianity and an aid to faith against doubt. Left unanswered, challenges embolden scoffers. This lesson maps four functions of apologetics, Van Til’s presuppositional approach, and why evolutionist talking-points are not raw “facts.”", "bigIdeas": ["Apologetics = reasoned defense of the Christian faith and an aid to faith against doubt.", "Unanswered challenges bolster the pride of scoffers and critics — silence is not neutral.", "Four essential functions: positive confirmation, defense, refutation, and application/persuasion.", "Presuppositional apologetics (Van Til): expose non-Christian principles by reducing them to absurdity.", "Ken Ham is a well-known young-earth creationism advocate.", "Do not treat evolution claims as observed facts; natural selection is not molecules-to-man evolution.", "John Warwick Montgomery is not the one who, “in his poetic way,” defended the faith (Moodle: False).", "“Apologia” does not occur 57 times in the New Testament (Moodle: False)."], "takeaways": ["Apologetics is a reasoned defense of Christianity and an aid to faith against doubt.", "Unanswered challenges embolden scoffers.", "Four functions: positive confirmation, defense, refutation, application/persuasion.", "Van Til’s presuppositional method: reduce non-Christian principles to absurdity.", "Ken Ham advocates young-earth creationism.", "Evolution claims should not be treated as observed facts; natural selection ≠ molecules-to-man evolution."], "glossary": [{"term": "Apologetics", "meaning": "Reasoned defense of the Christian faith; also an aid to faith against doubt."}, {"term": "Apologia", "meaning": "The New Testament word-group behind “defense.” Moodle: it does not occur 57 times."}, {"term": "Cornelius Van Til", "meaning": "Presuppositional apologetics — press non-Christian starting points until they collapse into absurdity."}, {"term": "Presuppositional apologetics", "meaning": "Argue at the level of foundational assumptions, not only scattered evidences."}, {"term": "Ken Ham", "meaning": "Popular advocate of young-earth creationism."}, {"term": "Natural selection", "meaning": "A real observed process — not proof of molecules-to-man evolution as a whole."}, {"term": "John Warwick Montgomery", "meaning": "Named in a True/False item; Moodle marks the “poetic way” claim False."}], "outline": ["List and discuss the four functions of Apologetics.", "List and briefly discuss the seven aims of Apologetics as related to ministry.", "List the ten arguments that evolutionists should avoid and explain why."], "mustKnow": [{"label": "Course", "value": "Apologetics 1 · BIB 221 · course 62"}, {"label": "Quiz 1", "value": "100% (10/10), attempt 1, cmid 1083"}, {"label": "Definition", "value": "Defense of the Christian faith; aid against doubt"}, {"label": "Four functions", "value": "Confirmation, defense, refutation, application/persuasion"}, {"label": "Van Til", "value": "Reduce non-Christian principles to absurdity"}, {"label": "Certificate", "value": "Restricted / locked on Moodle"}], "compare": [{"title": "Four functions of apologetics", "points": ["Positive confirmation — show the truth of the Christian system", "Defense — answer attacks on the faith", "Refutation — expose error in opposing systems", "Application / persuasion — press truth toward faith and life"]}, {"title": "Evolutionist claims vs Moodle’s line", "points": ["“Evolution is a fact” — False on the quiz; treat as contested claim, not raw observation", "“Natural selection demonstrates evolution” — False; selection ≠ full evolutionary story", "Many “arguments evolutionists should avoid” smuggle interpretation in as if it were settled fact"]}], "pulpit": ["Faith is not allergic to reasons — apologetics serves worshipers who wake up with doubts.", "Silence under attack is not humility; unanswered scoffing hardens the scoffer and unsettles the flock.", "Start where people start: expose the hidden gods (presuppositions) before you stack loose evidences.", "Say carefully what science observes (like natural selection) without baptizing a worldview as “fact.”"], "quickReview": ["Apologetics is a reasoned defense of Christianity and an aid to faith against doubt.", "Unanswered challenges embolden scoffers.", "Four functions: positive confirmation, defense, refutation, application/persuasion.", "Van Til’s presuppositional method: reduce non-Christian principles to absurdity.", "Ken Ham advocates young-earth creationism."], "quiz": [{"q": "Apologetics is usually defines as a defense of the Christian faith.", "answer": "True", "why": "Moodle wording kept (“defines”). Defense of the faith is the usual definition."}, {"q": "\"Apologia\" occurs 57 times in the New Testament.", "answer": "False", "why": "Moodle: False. Do not memorize 57 as a fact."}, {"q": "Apologetics is an aid to faith against doubt.", "answer": "True", "why": "It serves faith under pressure, not only debates."}, {"q": "If the challenges against Christianity go unanswered, the pride of scoffers and critics is bolstered.", "answer": "True", "why": "Unanswered attacks embolden scoffers."}, {"q": "Apologetics has four essential functions.", "answer": "True", "why": "Confirmation, defense, refutation, application/persuasion."}, {"q": "In Presuppositional apologetics, Cornelius Van Til attempted to reduce the non-Christian principles to absurdity.", "answer": "True", "why": "Van Til’s method presses opposing presuppositions to collapse."}, {"q": "Ken Ham is a popular advocate of young earth creationism.", "answer": "True", "why": "Young-earth creationism advocate."}, {"q": "In his poetic way, John Warwick Montgomery defended the Christian faith.", "answer": "False", "why": "Moodle: False. Do not pair Montgomery with that “poetic way” line."}, {"q": "Evolution is a fact.", "answer": "False", "why": "Moodle: False. Do not concede evolution as uninterpreted fact."}, {"q": "Natural selection demonstrates the truth of evolution.", "answer": "False", "why": "Selection is not proof of the full evolutionary claim."}], "essays": [{"theme": "List and discuss the four functions of Apologetics.", "summary": "I understand the four functions this way:\n\n1. Positive confirmation: apologetics marshals philosophical, scientific, historical, and other evidence to make a positive case that Christianity is true and reasonable.\n\n2. Defense: it answers objections, criticisms, and questions raised against Christianity, explaining and clarifying the Christian position.\n\n3. Refutation: it exposes weaknesses in non-Christian religions and philosophies and answers the arguments offered for them. Refuting another view by itself does not prove Christianity, so this belongs alongside the positive case.\n\n4. Application and persuasion: apologetics seeks more than intellectual agreement; it persuades people to receive and apply the truth of Christianity in life, serving the gospel and ministry."}, {"theme": "List and briefly discuss the seven aims of Apologetics as related to ministry.", "summary": "The seven ministry-related aims are:\n\n1. To prepare a person for evangelistic ministry.\n2. To provide an aid to faith when doubt arises.\n3. To minister to the unsaved by answering honest intellectual and spiritual questions.\n4. To prepare the ground for sowing the seed of God's Word.\n5. To strengthen, confirm, and establish the faith of believers.\n6. To prepare the mind of the average unsaved person and motivate him or her to search for the truth.\n7. To set forth the reasonableness and coherence of the Christian system to the world."}, {"theme": "List the ten arguments that evolutionists should avoid and explain why they should be avoided.", "summary": "The ten arguments to avoid are:\n\n1. \"Evolution is a fact.\" It is a theory about the unobserved past, built on assumptions, not a directly observed fact.\n2. \"Only the educated reject evolution.\" This simply dismisses opponents by labeling them uneducated; many well-educated scholars reject it.\n3. \"Overwhelming evidence in science supports evolution.\" Evidence is interpreted through prior presuppositions; it does not settle historical origins by itself.\n4. \"Doubting evolution is like doubting gravity.\" Gravity can be observed and tested repeatedly, while molecules-to-man evolution cannot be tested in the same way.\n5. \"Doubting evolution is like believing the earth is flat.\" The earth's shape is directly observable; evolutionary stories about fossils and common descent are not direct observations.\n6. \"The evidence is clear, so it must have evolved.\" A conclusion cannot prove that the assumptions or premises behind it are true.\n7. \"Natural selection is evolution.\" Natural selection works on existing characteristics; it does not demonstrate that a lower life-form became a fundamentally higher one.\n8. \"Common design means common ancestry.\" Similar structures can reflect a common Designer just as well as, or better than, an unobserved common descent.\n9. \"Sedimentary layers show millions of years of deposition.\" Layers show that sedimentary layers exist; the millions-of-years interpretation depends on an assumed geological history.\n10. \"Mutations drive evolution.\" Mutations corrupt existing genetic information; they do not supply the kind of new information required for molecules-to-man evolution.\n\nThe common problem is treating an interpretation of evidence as if it were an observed, proven history, while overlooking the role of presuppositions."}]}, {"id": "ap1-2", "number": 2, "title": "Why Skeptics and Bible Christians Disagree", "topic": "Same facts, different glasses — presuppositions decide the interpretation.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 2: 10/10 (100%) on attempt 1 (12m 10s). Essays not graded yet.", "summary": "Skeptics and Bible Christians often look at the same evidence and reach opposite conclusions because they start with different presuppositions. Christianity begins with God, revelation, truth, logic, and observable reality. Life, matter, natural law, creation, and design press hard against purely naturalistic stories.", "bigIdeas": ["Presuppositions shape how people interpret evidence — the debate is not “facts vs no facts.”", "Christianity begins with God, revelation, truth, logic, and observable reality.", "Same facts, different interpretive “glasses.”", "Life, matter, natural law, creation, and design challenge naturalistic explanations.", "The Bible is the Christian framework for past events and the universe.", "Self-evident presuppositionalism holds to a set of assumptions.", "Dark energy is named as a great force; a force points to a force-maker.", "Created order is not random; Stephen Hawking is not always logical in observations and conclusions."], "takeaways": ["Presuppositions shape how people interpret evidence.", "Christianity begins with God, revelation, truth, logic, observable reality.", "Same facts, different interpretive glasses.", "Life, matter, natural law, creation, design challenge naturalistic explanations.", "Bible = Christian framework for past events and the universe.", "Self-evident presuppositionalism holds to a set of assumptions; dark energy as a great force; force implies force-maker; created order not random; Hawking not always logical."], "glossary": [{"term": "Presupposition", "meaning": "A starting assumption that shapes how evidence is read — worn like interpretive glasses."}, {"term": "Self-evident presuppositionalism", "meaning": "Holding to a set of foundational assumptions treated as starting points for thought."}, {"term": "Dark energy", "meaning": "Named in the lesson as one great force in the universe."}, {"term": "Force-maker", "meaning": "If a real force exists, it reasonably points beyond blind matter to a maker of that force."}, {"term": "Interpretive glasses", "meaning": "Worldview lens — same fossils, stars, and layers, different readings."}, {"term": "Stephen Hawking", "meaning": "Moodle: not always logical in his observations and conclusions."}], "outline": ["Five Christian tenets (God, law, knowledge, truth, logic)", "Five hard questions for naturalism (life, matter, law, creation, design)", "Five reasons skeptics and Bible Christians disagree", "Quiz drill on presuppositions, force, randomness, Genesis, origins, Hawking"], "mustKnow": [{"label": "Quiz 2", "value": "100% (10/10), attempt 1, cmid 1087"}, {"label": "Core claim", "value": "Same evidence, different presuppositions"}, {"label": "Christian start", "value": "God, revelation, truth, logic, observable reality"}, {"label": "Bible’s role", "value": "Framework for past events and the universe"}, {"label": "Force", "value": "Existence of a force requires a force-maker (Moodle)"}, {"label": "Universe", "value": "Could not have created itself"}], "compare": [{"title": "Bible Christian vs skeptic starting points", "points": ["Christian: begins with God and His revelation", "Skeptic/evolutionist: generally presupposes no God or no special creation", "Both sides often have the same evidence and facts", "Difference is interpretation through different glasses — no neutral ground"]}, {"title": "Five hard questions for naturalism", "points": ["Where did life come from?", "Where did matter begin, and why does it continue?", "Where do the laws of nature come from?", "What source outside the universe brought it into existence?", "What is the source of order and beauty (design)?"]}], "pulpit": ["People rarely fight only about fossils — they fight about the glasses they refuse to take off.", "Christian apologetics is honest about starting with God; the alternative still starts somewhere.", "Design, law, life, and matter are pastoral doorways — ask the hard question before you dump a bibliography.", "Same facts can preach two sermons; the Bible gives the Christian the true story of the past."], "quickReview": ["Same evidence, different presuppositions / glasses.", "Five tenets: God revealed; laws; knowledge by observation; truth consistent; mind knows logic.", "Hard questions: life, matter, law, creation, design.", "Force implies force-maker; universe did not create itself; order is not random.", "Hawking not always logical; Genesis-as-evolution claim appears among some evolutionists."], "quiz": [{"q": "Self-evident presuppositionalism holds to a set of assumptions.", "answer": "True", "why": "It begins with a held set of starting assumptions."}, {"q": "One great force in the universe is called ‘dark energy.’", "answer": "True", "why": "Dark energy is named as a great force in this lesson."}, {"q": "The existence of a force does not necessarily require the existence of a force-maker.", "answer": "False", "why": "Moodle: False. A force points to a force-maker."}, {"q": "It is logical to think that the created order just happened randomly.", "answer": "False", "why": "Random origin of the created order is not logical here."}, {"q": "Evolutionists and those who reject evolutionary theory have the same evidence and the same facts from which to draw their conclusions.", "answer": "True", "why": "Same facts — different readings."}, {"q": "Some evolutionists argue that Genesis 1 is a simplified account of evolution.", "answer": "True", "why": "That claim shows up; the lesson flags the disagreement underneath it."}, {"q": "Skeptics find it easy to explain where life comes from.", "answer": "False", "why": "Origins of life are not easy for the skeptic in this lesson."}, {"q": "Skeptics find it easy to explain where matter comes from.", "answer": "False", "why": "Matter’s origin is not easy for the skeptic here."}, {"q": "The universe could not have created itself.", "answer": "True", "why": "Self-creation is ruled out."}, {"q": "Stephen Hawking is always logical in his observations and conclusions.", "answer": "False", "why": "Moodle: False. Not always logical."}], "essays": [{"theme": "List and discuss the five tenets.", "summary": "The five tenets are these: (1) There is a God, and He has revealed Himself. (2) There are self-evident laws that control the universe. (3) Human beings can know things to the degree that they accurately observe them. (4) Truth does not contradict itself; it is self-consistent and corresponds to reality. (5) The mind can recognize what is logical and reject what is illogical."}, {"theme": "List and discuss the first five questions.", "summary": "The first five questions are: (1) the existence of life—where did life come from? It is difficult to explain how life or energy could arise from non-existence. (2) the source of matter—where did matter begin and why does it continue to exist? Saying it came from nothing is only a theory, not an explanation. (3) the source or force of law—where do the laws of nature come from? They have real force, and breaking them brings consequences, which points beyond blind matter. (4) the source of creation—what source outside the universe brought it and its details into existence? The universe cannot create itself, and thermodynamics shows it could not have existed forever. (5) design in the universe—what is the source of its order and beauty? Design reasonably points to a designer rather than to unguided chance."}, {"theme": "List five reasons for the disagreement.", "summary": "Five reasons for the disagreement are: (1) Both sides have the same evidence and facts, but they interpret them differently. (2) They begin with different presuppositions—Christians begin with God and His revelation, while evolutionists generally presuppose no God or no special creation. (3) We are trying to connect present evidence with events in the past, but neither side directly observed those past events; the Bible provides God’s revealed account of them. (4) The evidence is viewed through different “glasses,” so the same fossils, stars, and rock layers are understood within different worldviews. (5) There is no neutral ground: removing the Bible removes the Christian’s foundation for interpreting the facts, while the skeptic still retains his own presuppositions. Therefore the debate is ultimately about competing interpretations and worldviews, not merely about isolated facts."}]}, {"id": "ap1-3", "number": 3, "title": "New Attacks on Christianity from Postmodernism", "topic": "Modernism emptied the well; postmodernism reacted — and the church was not ready.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 3: 10/10 (100%) on attempt 1 (7m 24s). Essays not graded yet. Moodle uses this same section title again for Lesson 4.", "summary": "We live in a culture that is no longer Christian. Modernism treated Scripture with a liberal/humanist approach; postmodernism rose as a reaction to modernism’s emptiness. The church was not well prepared. Towns’s best response: present the true church — communicate the gospel without compromise, and distinguish cultural from hostile academic postmodernism.", "bigIdeas": ["World culture is no longer Christian.", "Modernism in doctrine = liberal/humanist approach to Scripture authority.", "Postmodernism reacted to the emptiness of modernism; the church was not well prepared.", "Postmodernism: religion as the bane of public life; only politically correct viewpoints tolerated; conviction becomes “discontent”; no need for a Savior.", "Best response (Towns): present the true church.", "Scientific demonstration order: gather info → analyze → hypothesis → test → announce (hypothesis is NOT first).", "Communicate the gospel without compromise; distinguish cultural vs hostile academic postmodernism."], "takeaways": ["World culture no longer Christian; modernism = liberal/humanist approach to scripture authority.", "Postmodernism reacted to emptiness of modernism; church was not well prepared.", "Postmodernism: religion as bane of public life; only politically correct viewpoints tolerated; conviction→discontent; no need for a Savior.", "Best response (Towns): present the true church.", "Scientific demonstration: gather info → analyze → hypothesis → test → announce (hypothesis is NOT first step).", "Communicate gospel without compromise; distinguish cultural vs hostile academic postmodernism."], "glossary": [{"term": "Modernism (doctrine)", "meaning": "Liberal or humanist approach to Scripture authority."}, {"term": "Postmodernism", "meaning": "Reaction to modernism’s emptiness; often treats religion as a public problem and denies need for a Savior."}, {"term": "Discontent", "meaning": "The new word for “conviction” in the postmodern mindset (Moodle)."}, {"term": "True church (Towns)", "meaning": "Best response to the postmodern mindset — present the true church."}, {"term": "Scientific demonstration", "meaning": "Gather → analyze → hypothesize → test → announce — hypothesis is not step one."}, {"term": "Cultural vs academic postmodernism", "meaning": "Distinguish everyday cultural mood from hostile academic theory when communicating the gospel."}], "outline": ["Modernism’s empty promises and liberal Scripture approach", "Postmodernism’s reaction and the church’s unreadiness", "Ten presuppositions of modernism", "Seven cultural expressions of postmodernism", "Five steps of scientific demonstration of truth", "Pastoral response: present the true church without compromise"], "mustKnow": [{"label": "Quiz 3", "value": "100% (10/10), attempt 1, cmid 1091"}, {"label": "Culture", "value": "No longer Christian"}, {"label": "Modernism", "value": "Liberal/humanist approach to Scripture authority"}, {"label": "Postmodernism origin", "value": "Reaction to emptiness of modernism"}, {"label": "Church readiness", "value": "Not well prepared (Moodle: False that it was)"}, {"label": "Towns’s response", "value": "Present the true church"}, {"label": "Science order", "value": "Gather → analyze → hypothesis → test → announce"}], "compare": [{"title": "Modernism’s ten presuppositions (summary)", "points": ["Naturalism, humanism, scientific method, reductionism, progress", "Nature (evolution over Creator), certainty, determinism", "Individualism and anti-authoritarianism — person as final arbiter of truth"]}, {"title": "Seven cultural expressions of postmodernism", "points": ["Denial of personal objectivity; uncertainty of knowledge", "Death of any all-inclusive explanation; denial of knowledge’s inherent goodness", "Rejection of progress; supremacy of community-based knowledge; disbelief in objective inquiry"]}, {"title": "Scientific demonstration — order matters", "points": ["NOT: create a hypothesis first", "YES: gather → analyze → hypothesize → test → announce"]}], "pulpit": ["Name the glasses: modernism emptied authority; postmodernism filled the vacuum with mood and tribe.", "Conviction is not “discontent” — the church must recover holy certainty without cruelty.", "Present the true church: holy, gospel-clear, uncompromised — not a brand-managed spirituality.", "Teach people how truth is tested: gather and analyze before you hypothesise a trendy answer."], "quickReview": ["Culture no longer Christian; modernism = liberal/humanist Scripture approach.", "Postmodernism reacted to modernism’s emptiness; church was unprepared.", "Religion as public bane; only PC views tolerated; conviction→discontent; no Savior needed.", "Towns: present the true church; gospel without compromise.", "Science: gather → analyze → hypothesis → test → announce (not hypothesis first)."], "quiz": [{"q": "We live in a world culture that is no longer Christian.", "answer": "True", "why": "The cultural default is no longer Christian."}, {"q": "Modernism in doctrine refers to a liberal or humanist approach to scripture authority.", "answer": "True", "why": "Modernism relocates authority away from Scripture toward liberal/humanist norms."}, {"q": "The first step in the scientific demonstration of truth is to create a hypothesis.", "answer": "False", "why": "First gather information, then analyze — hypothesis is third."}, {"q": "The church saw postmodernity coming and was well prepared for it.", "answer": "False", "why": "The church was not well prepared."}, {"q": "Postmodernism developed as a reaction to the emptiness of modernism.", "answer": "True", "why": "Empty modernism birthed the postmodern reaction."}, {"q": "Postmodernism argues that religion is the bane of public life.", "answer": "True", "why": "Religion treated as a public problem."}, {"q": "Postmodernism argues that only those viewpoints deemed politically correct should be tolerated.", "answer": "True", "why": "Tolerance narrows to the politically correct."}, {"q": "The new word for \"conviction\" is \"discontent.\"", "answer": "True", "why": "Conviction is rebranded as discontent."}, {"q": "Dr. Towns recommends that the best response to the postmodern mindset is to present the true church.", "answer": "True", "why": "Present the true church — Towns’s pastoral answer."}, {"q": "Postmodernism sees no need for a Savior.", "answer": "True", "why": "No felt need for a Savior in that mindset."}], "essays": [{"theme": "List and discuss the five points of scientific demonstration of truth.", "summary": "The five points move from observation to a tested conclusion:\n\n1. Gather information concerning a problem. We begin by collecting the relevant facts rather than assuming an answer.\n\n2. Analyze the facts and data. The information has to be examined carefully so that important evidence is not overlooked.\n\n3. Create a hypothesis—a proposed or suggested solution to the problem.\n\n4. Test the proposed solution. The lesson mentions testing its logic, correspondence to the reality of life, analysis of the data, consistency, comprehensiveness (whether relevant questions have been answered), and public acceptance or consensus.\n\n5. Announce a solution, principle, or law. Only after the proposed answer has been examined and tested should it be presented as a conclusion."}, {"theme": "List and discuss the ten presuppositions of modernism.", "summary": "1. Naturalism: reality is restricted to what can be observed or proved.\n2. Humanism: humanity is viewed as the pinnacle of the universe.\n3. The scientific method: knowledge is inherently good and attainable through a reliable method.\n4. Reductionism: humans are understood as highly developed animals.\n5. Progress: because knowledge is good, gaining more knowledge is expected to produce progress.\n6. Nature: evolution, rather than a Creator, is held responsible for life and its development.\n7. Certainty: because knowledge is objective, people can know things with certainty.\n8. Determinism: events happen because of fixed causes.\n9. Individualism: the individual and the individual's ability to discern truth are supreme.\n10. Anti-authoritarianism: each person is the final arbiter of truth.\n\nTogether these assumptions place confidence in observable reality, human reason, progress, and individual judgment rather than in God's revealed authority."}, {"theme": "List and discuss the seven cultural expressions of postmodernism.", "summary": "The seven cultural expressions of postmodernism are:\n\n1. Denial of personal objectivity. People say that their beliefs are shaped by their parents or background and that nobody can know for sure.\n2. Uncertainty of knowledge. Even when a government or expert makes a claim, the response is often, \"Who really knows if it is true?\"\n3. Death of any all-inclusive explanation. People resist neat explanations and believe that life does not fit one complete, orderly account.\n4. Denial of knowledge's inherent goodness. More knowledge and technology are seen as potentially making the world more dangerous, not automatically better.\n5. Rejection of progress. Having technology and material advancement does not guarantee happiness or fulfillment.\n6. Supremacy of community-based knowledge. It is considered arrogant for one individual to claim that he or she alone has discovered spiritual truth; knowledge is shaped by one's community.\n7. Disbelief in objective inquiry. Even when reading Scripture, a person may say, \"This is what I think it means, but I could be wrong—what is your interpretation?\"\n\nIn everyday life these ideas are usually expressed as attitudes rather than as a formal philosophy. They show why Christians need humility and patient conversation while still presenting the objective truth of the gospel."}]}, {"id": "ap1-4", "number": 4, "title": "New Attacks on Christianity from Postmodernism", "topic": "Five classical arguments for God — cosmological, teleological, anthropological, ontological, and congruity — plus conscience as God’s inward self-revelation.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 4: 10/10 (100%) on attempt 1 (11m 6s). Essays Complete/Not graded. cmid 1095.", "summary": "Lesson 4 surveys five classical arguments for God’s existence (cosmological, teleological, anthropological, ontological, congruity). Logical arguments do not save, but they can condemn refusal to respond; the Bible does not begin by proving God to unbelievers. Conscience (Rom 2:15) is God’s self-revelation from within man.", "bigIdeas": ["Five arguments: cosmological, teleological, anthropological, ontological, congruity.", "Logical arguments do not save but can condemn refusal to respond.", "Bible does not begin by proving God to unbelievers; arguments are not undeniable to everyone.", "Cosmological = First Cause / Uncaused Cause / Prime Mover; something ≠ nothing.", "Teleological = watchmaker/design; anthropological = human nature → personal God; ontological = mind can’t conceive a non-existent perfect Being.", "Conscience (Rom 2:15) = God’s self-revelation from within man."], "takeaways": ["Five arguments: cosmological, teleological, anthropological, ontological, congruity.", "Logical arguments do not save but can condemn refusal to respond.", "Bible does not begin by proving God to unbelievers; arguments not undeniable to everyone.", "Cosmological = First Cause / Uncaused Cause / Prime Mover; something ≠ nothing.", "Teleological = watchmaker/design; anthropological = human nature → personal God; ontological = mind can’t conceive non-existent perfect Being.", "Conscience (Rom 2:15) = God’s self-revelation from within man."], "glossary": [{"term": "Cosmological", "meaning": "First Cause / Uncaused Cause / Prime Mover argument; something does not come from nothing."}, {"term": "Teleological", "meaning": "Watchmaker/design argument — the world as created by God, as a watch proves a watchmaker."}, {"term": "Anthropological", "meaning": "Human nature reveals a personal God."}, {"term": "Ontological", "meaning": "The mind cannot conceive of that which is non-existent — concept of a perfect Being points to that Being."}, {"term": "Congruity", "meaning": "When creation, design, human nature, reason, and revelation are considered together, they fit best with the existence of God."}, {"term": "Uncaused Cause / Prime Mover", "meaning": "Equivalents in the cosmological argument for the independent First Cause of the universe."}, {"term": "Conscience (Rom 2:15)", "meaning": "God’s self-revelation from within man — the law’s work written on the heart; conscience accusing or excusing."}], "outline": ["Limits of logical arguments: not undeniable to all; do not save; can condemn refusal", "Bible does not begin by proving God to unbelievers", "Cosmological argument: First Cause / Uncaused Cause / Prime Mover", "Teleological argument: watchmaker / design", "Anthropological argument: human nature → personal God", "Ontological argument: mind cannot conceive a non-existent perfect Being", "Congruity: all facts together fit best with God’s existence", "Conscience (Rom 2:15): God’s self-revelation from within man"], "mustKnow": [{"label": "Quiz 4", "value": "100% (10/10), attempt 1, 11m 6s, cmid 1095"}, {"label": "Five arguments", "value": "Cosmological, teleological, anthropological, ontological, congruity"}, {"label": "Uncaused Cause", "value": "Also understood as the Prime Mover"}, {"label": "Logical arguments & salvation", "value": "Not sufficient to bring salvation"}, {"label": "Logical arguments & condemnation", "value": "Sufficient to condemn a person who will not respond to God"}, {"label": "Bible’s starting point", "value": "Does not begin by proving God to an unbelieving world"}, {"label": "Undeniable to everyone?", "value": "No — arguments do not demonstrate undeniable reality to everyone"}], "compare": [{"title": "Five arguments — what each starts from", "points": ["Cosmological: chain of causes/effects → First Cause / Uncaused Cause / Prime Mover (something ≠ nothing)", "Teleological: order, harmony, purposeful design → intelligent Designer (watch → watchmaker)", "Anthropological (moral): human intellect, freedom, conscience, moral awareness → personal God", "Ontological: concept of a perfect/greatest Being → that Being exists (mind can’t conceive the non-existent)", "Congruity: creation + design + human nature + reason + revelation together → best fit is God’s existence"]}, {"title": "Logical arguments — save vs condemn", "points": ["NOT sufficient to bring salvation", "ARE sufficient to condemn a person who will not respond to God"]}], "pulpit": ["Name the five paths to the same mountain: cause, design, human nature, the idea of perfection, and the fit of all the facts.", "Arguments do not save — but refusal to respond still stands condemned.", "Scripture assumes God; it does not open with a proof for the skeptic.", "Romans 2:15: conscience is God’s whisper from inside — accusing and excusing."], "quickReview": ["Five arguments: cosmological, teleological, anthropological, ontological, congruity.", "Uncaused Cause = Prime Mover; something does not come from nothing.", "Logical arguments do not save but can condemn refusal to respond.", "Bible does not begin by proving God; arguments not undeniable to everyone.", "Conscience (Rom 2:15) = God’s self-revelation from within man."], "quiz": [{"q": "The logical arguments for the existence of God demonstrate to everyone the undeniable and unquestionable reality for the existence of God.", "answer": "False", "why": "Arguments are not undeniable and unquestionable to everyone."}, {"q": "The Bible begins by attempting to prove the existence of God to an unbelieving world.", "answer": "False", "why": "The Bible does not begin by proving God to unbelievers."}, {"q": "The cosmological argument for the existence of God addresses the issue of God as the First Cause.", "answer": "True", "why": "Cosmological = First Cause / Uncaused Cause / Prime Mover."}, {"q": "The cosmological argument uses the logic that ‘something’ does not come from ‘nothing.’", "answer": "True", "why": "Something ≠ nothing — core cosmological logic."}, {"q": "The ‘Uncaused Cause’ is also understood as the ‘Prime Mover.’", "answer": "True", "why": "Uncaused Cause and Prime Mover are equivalent titles."}, {"q": "When considering the teleological argument for the existence of God, we look at the world as created by God, even as a watch is the proof of a watchmaker.", "answer": "True", "why": "Teleological = watchmaker / design analogy."}, {"q": "The anthropological argument embraces the notion that human nature reveals a personal God.", "answer": "True", "why": "Human nature points to a personal God."}, {"q": "The ontological argument embraces the notion that the mind cannot conceive of that which is non-existent.", "answer": "True", "why": "Mind cannot conceive a non-existent perfect Being."}, {"q": "Logical arguments are sufficient to bring salvation.", "answer": "False", "why": "Logical arguments do not save."}, {"q": "Logical arguments are sufficient to condemn a person who will not respond to God.", "answer": "True", "why": "They can condemn refusal to respond."}], "essays": [{"theme": "five arguments for God's existence", "summary": "1. Cosmological: The world is a chain of causes and effects, so it points to a First Cause or Uncaused Cause—God.\n2. Teleological: The order, harmony, and purposeful design in the universe point to an intelligent Designer.\n3. Anthropological (moral): Human intellect, freedom, conscience, and moral awareness are best explained by a personal God who is the source of our nature and moral standard.\n4. Ontological: Our concept of a perfect and greatest Being points to the existence of that Being, since the mind cannot conceive of what does not exist.\n5. Congruity: When all the facts—creation, design, human nature, reason, and revelation—are considered together, they fit best with the existence of God."}, {"theme": "Cosmological Argument", "summary": "The Cosmological Argument reasons from the existence of the world to a First Cause. Everything that begins or exists as an effect depends on a cause, and something cannot come from nothing. Creation exists, so it cannot explain itself; the chain of causes cannot regress endlessly without a beginning. Therefore, the universe must ultimately trace back to an uncaused, independent, all-powerful First Cause, also called the Uncaused Cause or Prime Mover. This Cause must be free, not forced by necessity, because it brought the world into existence at a point in time. It must also have intelligence and will: a timeless Cause could begin a temporal series only by freely choosing to create. Thus the order and existence of creation point beyond themselves to God as the Creator."}, {"theme": "God's self-revelation from within man / conscience", "summary": "God's self-revelation from within man is seen especially in conscience and moral awareness. Romans 2:15 says that even Gentiles who do not have the written law show that its work is written on their hearts, while their consciences accuse or excuse them. Because people are made in God's image, they naturally recognize moral absolutes and feel accountable when they do right or wrong. Laws in society also imply a Lawgiver and Judge, and our impulse to judge wrongdoing reflects this inner moral knowledge. Although sin has damaged the image of God in us, it has not erased it. This inward witness points to a personal, holy, and moral God and supports the truth of Scripture."}]}, {"id": "ap1-5", "number": 5, "title": "Logical Proof That God Created Mankind", "topic": "Doctrine of people: Image of God (immaterial), creation views, theological implications of man’s origin, and three origin theories — Bible supports special creation.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 5: 10/10 (100%) on attempt 1 (9m 26s). Essays Complete/Not graded. cmid 1099.", "summary": "Lesson 5 treats the doctrine of people where biblical revelation and human concerns converge. Humans are part of God’s creation and bear His image in an immaterial sense (rational, moral, spiritual, immortal); the Fall corrupted but did not erase that image. Creationism (ex nihilo), deistic evolution, Gap theory, and three origin theories (atheistic evolution, theistic evolution, special creation) are surveyed — Scripture best supports special creation.", "bigIdeas": ["Doctrine of people: biblical revelation and human concerns converge.", "Humans are part of God’s creation; Image of God is immaterial (rational, moral, spiritual, immortal) — not merely physical/rational capacity.", "Fall corrupted the image but did not erase it.", "Creationism: virtually everything created ex nihilo; deistic evolution: God withdrew after setting evolution in motion.", "Man does NOT have independent existence; Towns does NOT say five principal explanations for man’s origin.", "Gap theory explains apparent long age of the earth; believing the Bible’s origin of man IS important.", "Three theories: atheistic evolution, theistic evolution, special creation — Bible supports special creation."], "takeaways": ["Doctrine of people: biblical revelation and human concerns converge.", "Humans part of God’s creation; Image of God NOT merely physical/rational capacity — immaterial (rational, moral, spiritual, immortal); Fall corrupted but did not erase.", "Creationism: virtually everything ex nihilo; deistic evolution: God withdrew after setting evolution in motion.", "Man does NOT have independent existence; Towns does NOT say five principal explanations for man’s origin (False); Gap theory explains apparent long age; believing Bible’s origin of man IS important.", "Three theories: atheistic evolution, theistic evolution, special creation — Bible supports special creation."], "glossary": [{"term": "Image of God", "meaning": "Not physical resemblance or merely rational/intellectual ability; rooted in the immaterial nature God gave us — rational, moral, spiritual, and immortal aspects. Sin corrupted but did not erase it."}, {"term": "Creationism / ex nihilo", "meaning": "Virtually everything was created ex nihilo — out of nothing."}, {"term": "Deistic evolution", "meaning": "God withdrew from the process of evolution after setting it in motion."}, {"term": "Gap theory", "meaning": "One explanation for the apparent long age of the earth."}, {"term": "Atheistic evolution", "meaning": "Man as the product of blind, impersonal chemical and biological events through natural processes and survival of the fittest."}, {"term": "Theistic evolution", "meaning": "God began the creative process by bringing the first organism to life, then allowed evolution to continue, intervening at times to guide it."}, {"term": "Special creation", "meaning": "Man is a direct product of God’s hand, created from the dust and made in God’s image; Genesis as literal historical account. Biblical evidence best supports this."}], "outline": ["Doctrine of people: biblical revelation and human concerns converge", "Image of God: immaterial (rational, moral, spiritual, immortal) — not merely physical/rational; Fall corrupted but did not erase", "Creation views: creationism (ex nihilo) vs deistic evolution (God withdrew)", "Theological implications of man’s origin (8 points) — man contingent, not independent", "Three theories of man’s origin: atheistic evolution, theistic evolution, special creation — Bible supports special creation", "Gap theory as explanation for apparent long age; believing Bible’s origin of man is important"], "mustKnow": [{"label": "Quiz 5", "value": "100% (10/10), attempt 1, 9m 26s, cmid 1099"}, {"label": "Image of God", "value": "Immaterial (rational, moral, spiritual, immortal) — NOT merely physical/rational capacity"}, {"label": "Fall and the image", "value": "Corrupted humanity’s rational and moral dimensions but did not completely erase the image"}, {"label": "Towns on man’s origin", "value": "Does NOT say there are five principal explanations for man’s origin"}, {"label": "Independent existence?", "value": "No — mankind does not have independent existence; man is contingent on God"}, {"label": "Bible’s support", "value": "Supports special creation over atheistic or theistic evolution"}, {"label": "Gap theory", "value": "One explanation for the apparent long age of the earth"}], "compare": [{"title": "Three theories of man’s origin", "points": ["Atheistic evolution: man as product of blind, impersonal chemical/biological events; natural processes and survival of the fittest", "Theistic evolution: God brought first organism to life, then allowed evolution to continue, intervening at times to guide it", "Special creation: man a direct product of God’s hand from the dust, made in God’s image; Genesis literal — Bible best supports this"]}, {"title": "Creationism vs deistic evolution", "points": ["Creationism: virtually everything created ex nihilo (out of nothing)", "Deistic evolution: God withdrew from the process of evolution after setting it in motion"]}], "pulpit": ["Image of God is not a face or an IQ — it is the immaterial self: rational, moral, spiritual, immortal.", "Sin damaged the image; it did not delete it.", "Man has no independent existence — every breath is contingent on God’s provision.", "Three origin stories; only special creation matches Genesis as history."], "quickReview": ["Doctrine of people: biblical revelation and human concerns converge.", "Image of God = immaterial (rational, moral, spiritual, immortal); Fall corrupted, not erased.", "Creationism = ex nihilo; deistic evolution = God withdrew after starting evolution.", "Towns does NOT say five principal explanations; man is NOT independent of God.", "Three theories: atheistic / theistic / special creation — Bible supports special creation; Gap theory for apparent long age."], "quiz": [{"q": "The doctrine of people is important because the biblical revelation and human concerns converge at that point.", "answer": "True", "why": "Biblical revelation and human concerns converge at the doctrine of people."}, {"q": "Humans are part of God's creation process.", "answer": "True", "why": "Humans are part of God’s creation."}, {"q": "The ‘Image of God’ is humanity's physical and rational capacity.", "answer": "False", "why": "Image of God is immaterial (rational, moral, spiritual, immortal) — not merely physical/rational."}, {"q": "The Fall of Man corrupted humanity's rational and moral dimensions.", "answer": "True", "why": "Fall corrupted rational and moral dimensions (but did not erase the image)."}, {"q": "Creationism argues that virtually everything was created ex-nihilo, out of nothing.", "answer": "True", "why": "Creationism: virtually everything created ex nihilo."}, {"q": "Deistic evolution argues that God withdrew from the process of evolution after setting it in motion.", "answer": "True", "why": "Deistic evolution: God withdrew after setting evolution in motion."}, {"q": "One theological implication of man's origin is that mankind alone has independent existence.", "answer": "False", "why": "Man does NOT have independent existence; he is contingent on God."}, {"q": "Dr. Towns relates that there are five principal explanations for man's origin.", "answer": "False", "why": "Towns does NOT say there are five principal explanations."}, {"q": "One explanation for the apparent long age of the earth is the Gap theory.", "answer": "True", "why": "Gap theory explains apparent long age of the earth."}, {"q": "Believing the Bible's explanation of the origin of man is really not that important.", "answer": "False", "why": "Believing the Bible’s origin of man IS important."}], "essays": [{"theme": "Image of God (Towns)", "summary": "Dr. Towns explains that the image of God is not a physical resemblance, not merely humanity’s rational or intellectual ability, and not an unlimited ability to dominate creation. It is rooted in the immaterial nature God gave us. Animals share life and some immaterial abilities, but humans uniquely have personality and intellect. The image includes rational, moral, spiritual, and immortal aspects: we can understand truth, communicate and create, make moral choices, know and relate to God, and continue to exist eternally. Sin corrupted the image, but did not completely erase it."}, {"theme": "Theological implications of man's origin (8 points)", "summary": "1. No independent existence: man is contingent and continues to live by God’s provision, so he is never truly independent of God.\n2. Part of creation: although distinct from God, man belongs to the created order.\n3. A unique place in creation: being made in God’s image and given dominion sets humanity above the other creatures.\n4. Brotherhood among people: all humanity is related through one original pair, so every person has a common human dignity and need.\n5. Not the highest object in the universe: human value is great, but worship and ultimate glory belong to God alone.\n6. Definite limitations: as finite creatures, we cannot know everything and are subject to error.\n7. Proper adjustment in life comes from accepting our finiteness rather than pretending to be God.\n8. Man is nonetheless something wonderful: he is God’s expressly designed creation and the highest creature, made in His image."}, {"theme": "Three theories of man's origin", "summary": "The first theory is atheistic evolution: man is viewed as the product of blind, impersonal chemical and biological events, developing through natural processes and survival of the fittest. The second is theistic evolution: God began the creative process by bringing the first organism to life and then allowed evolution to continue, intervening at times to guide it. The third is special creation: man is a direct product of God’s hand, created from the dust and made in God’s image, with Genesis understood as a literal historical account. The biblical evidence best supports God’s direct creative work rather than macro-evolution."}]}, {"id": "ap1-6", "number": 6, "title": "Logical Proof That the Bible Is God’s Word", "topic": "Revelation as the truth basis that the Bible is God’s Word; Jesus’ deity; claims and prophecy; unity via dual authorship; inspiration (theopneustos) vs inerrancy; Pentateuch authorship; Jesus on Scripture.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 6: 10/10 (100%) on attempt 1 (9m 34s). Essays Complete/Not graded. cmid 1103. Course total 100% — certificate unlocked (cmid 2109).", "summary": "Lesson 6 builds the logical case that the Bible is God’s Word. Revelation is God giving knowledge about Himself we could not know otherwise — the truth basis for that claim. Jesus claimed to be God; if He is not God we cannot trust the Bible as from God. Authors claim a message from God over 1000 times; enemies do not always attack the facts of fulfilled prophecy. Unity rests on dual authorship. Inerrancy is not the Greek for God-breathed (that is inspiration / theopneustos). The course rejects a multi-writer Pentateuch (JEPD). Jesus affirmed inspiration, authority, and inerrancy.", "bigIdeas": ["Revelation = God giving knowledge about Himself we could not know otherwise; truth is the basis for arguing the Bible is God’s Word.", "Jesus claimed to be God; if Jesus is not God we cannot trust the Bible as a message from God.", "Authors claim their message is from God 1000+ times; enemies do NOT always attack the facts of fulfilled prophecy.", "Unity of Scripture is based on dual authorship; Inerrancy is NOT from the Greek for God-breathed (that is inspiration / theopneustos).", "Pentateuch was NOT written by four or more writers (course rejects JEPD); Jesus affirmed inspiration, authority, and inerrancy of Scripture."], "takeaways": ["Revelation = God giving knowledge about Himself we could not know otherwise; truth basis for Bible as Word of God.", "Jesus claimed to be God; if Jesus not God we cannot trust Bible as from God.", "Authors claim message from God 1000+ times; enemies do NOT always attack fulfilled prophecy facts.", "Unity of Scripture based on dual authorship; Inerrancy is NOT from Greek for God-breathed (that’s inspiration/theopneustos).", "Pentateuch NOT by four+ writers (rejects JEPD for this course); Jesus affirmed inspiration, authority, inerrancy."], "glossary": [{"term": "Revelation", "meaning": "The act whereby God gives us knowledge about Himself that we could not know otherwise; the truth basis for arguing that the Bible is the Word of God."}, {"term": "Inspiration / theopneustos", "meaning": "The Holy Spirit’s guidance of the human writers so they communicated God’s message accurately, while still using their own personalities and styles. The Greek idea of God-breathed (theopneustos) belongs here — not to the word Inerrancy."}, {"term": "Inerrancy", "meaning": "What God revealed and inspired is true, reliable, authoritative, and without error. The word does NOT come from the Greek for God-breathed."}, {"term": "Dual authorship", "meaning": "Scripture’s human and divine authorship together; the argument for the unity of Scripture is based on this dual authorship."}, {"term": "Pentateuch / JEPD", "meaning": "Genesis through Deuteronomy. This course rejects the claim that the Pentateuch was written by four or more writers (JEPD-style multi-writer theory)."}, {"term": "Fulfilled prophecy", "meaning": "Empirical evidence that Scripture’s message is from God. Enemies of Scripture do not always attack the facts of fulfilled prophecy."}], "outline": ["Revelation: God giving knowledge about Himself we could not know otherwise — truth basis that the Bible is God’s Word", "Jesus claimed to be God; if He is not God we cannot trust the Bible as from God", "Authors claim message from God 1000+ times; fulfilled prophecy as evidence (enemies do not always attack the facts)", "Eight arguments / evidences that Scripture is God’s Word", "Unity of Scripture based on dual authorship", "Four aspects of inspiration; Inspiration (theopneustos) vs Inerrancy", "Pentateuch authorship: course rejects four-or-more writers (JEPD)", "Jesus affirmed inspiration, authority, and inerrancy of Scripture"], "mustKnow": [{"label": "Quiz 6", "value": "100% (10/10), attempt 1, 9m 34s, cmid 1103"}, {"label": "Course / certificate", "value": "Course total 100%; certificate unlocked (cmid 2109)"}, {"label": "Revelation", "value": "God giving knowledge about Himself we could not know otherwise; truth basis for Bible as Word of God"}, {"label": "Jesus’ deity & trust", "value": "Jesus claimed to be God; if Jesus is not God we cannot trust the Bible as from God"}, {"label": "Authors’ claim", "value": "Over 1000 times authors claim their message is from God"}, {"label": "Enemies & prophecy", "value": "Enemies do NOT always attack the facts of fulfilled prophecy"}, {"label": "Unity", "value": "Argument for unity of Scripture is based on dual authorship"}, {"label": "Inerrancy ≠ theopneustos", "value": "Inerrancy does NOT come from Greek for God-breathed — that is inspiration"}, {"label": "Pentateuch", "value": "NOT written by four or more writers (course rejects JEPD)"}, {"label": "Jesus on Scripture", "value": "Affirmed inspiration, authority, and inerrancy"}], "compare": [{"title": "Revelation vs Inspiration vs Inerrancy", "points": ["Revelation: God’s act of making known what we could not otherwise know about Himself — giving of the truth", "Inspiration: Holy Spirit’s guidance of the human writers so they communicated God’s message accurately, using their own personalities and styles", "Inerrancy: what God revealed and inspired is true, reliable, authoritative, and without error — describes the resulting Scripture"]}, {"title": "Inerrancy ≠ theopneustos (God-breathed)", "points": ["Inerrancy does NOT come from the Greek words meaning God-breathed", "God-breathed / theopneustos belongs to inspiration — the Spirit’s work through the writers"]}], "pulpit": ["Revelation is God telling us what we could never invent about Himself.", "If Jesus is not God, the Bible’s claim to be from God collapses with Him.", "Over a thousand times the authors say: this message is from God.", "Inspiration is God-breathed; inerrancy is the result — true and without error.", "Jesus Himself stood for the inspiration, authority, and inerrancy of Scripture."], "quickReview": ["Revelation = God giving knowledge about Himself we could not know otherwise; truth basis for Bible as Word of God.", "Jesus claimed to be God; if not God we cannot trust Bible as from God.", "Authors claim message from God 1000+ times; enemies do NOT always attack fulfilled prophecy facts.", "Unity based on dual authorship; Inerrancy ≠ Greek God-breathed (that’s inspiration/theopneustos).", "Pentateuch NOT by four+ writers (rejects JEPD); Jesus affirmed inspiration, authority, inerrancy."], "quiz": [{"q": "Revelation is the act whereby God gives us knowledge about Himself that we could not know otherwise.", "answer": "True", "why": "Revelation = God giving knowledge about Himself we could not know otherwise."}, {"q": "Truth is the basis for argument that the Bible is the Word of God.", "answer": "True", "why": "Truth is the basis for arguing the Bible is God’s Word."}, {"q": "Jesus never claimed to be God.", "answer": "False", "why": "Jesus claimed to be God."}, {"q": "Even if Jesus is not God, we can still believe that the Bible is a message from God.", "answer": "False", "why": "If Jesus is not God we cannot trust the Bible as from God."}, {"q": "Over 1000 times in Scripture the authors claim their message is from God.", "answer": "True", "why": "Authors claim message from God 1000+ times."}, {"q": "The enemies of Scripture always attack the facts of fulfilled prophecy.", "answer": "False", "why": "Enemies do NOT always attack the facts of fulfilled prophecy."}, {"q": "The argument for the unity of Scripture is based on its dual authorship.", "answer": "True", "why": "Unity of Scripture is based on dual authorship."}, {"q": "The word \"Inerrancy\" comes from the Greek words meaning \"God breathed out.\"", "answer": "False", "why": "Inerrancy is NOT from Greek for God-breathed — that is inspiration/theopneustos."}, {"q": "The Pentateuch (Genesis through Deuteronomy) was actually written by four or more writers.", "answer": "False", "why": "Pentateuch NOT by four+ writers; course rejects JEPD."}, {"q": "Jesus affirmed the inspiration, authority and inerrancy of Scripture.", "answer": "True", "why": "Jesus affirmed inspiration, authority, and inerrancy."}], "essays": [{"theme": "Revelation / Inspiration / Inerrancy", "summary": "Revelation is God's act of making known what we could not otherwise know about Himself. Inspiration is the Holy Spirit's guidance of the human writers so they communicated God's message accurately, while still using their own personalities and styles. Inerrancy means that what God revealed and inspired is true, reliable, authoritative, and without error. In short, revelation is the giving of the truth, inspiration is the Spirit's work through the writers, and inerrancy describes the resulting Scripture."}, {"theme": "Eight arguments / evidences Scripture is God’s Word", "summary": "1. The unique revelation of the person of Christ.\n2. The Bible's extraordinary claim that its message is from God.\n3. The empirical evidence of fulfilled prophecy.\n4. The convicting, convincing, and converting power of its message.\n5. The inexhaustible infinity of revelation.\n6. The unity of the message from many human sources.\n7. The transcultural appeal of the message.\n8. The unmistakable honesty of the Scriptures."}, {"theme": "Four aspects of inspiration", "summary": "1. Inspired men: holy men of God were moved, or carried along, by the Holy Spirit, so they wrote what God wanted communicated.\n2. Inspired personalities: God used each writer's personality, background, vocabulary, and writing style rather than erasing the human author.\n3. Inspired words: the very words of Scripture were directed by the Holy Spirit, not merely the general ideas.\n4. Inspired thoughts and message: the content, thoughts, and ideas came from God, making Scripture completely accurate, authoritative, and without error."}]}], "courseTotal": 100}, {"id": "church-history-1", "code": 63, "title": "Church History 1", "status": "complete", "certificateUnlocked": true, "blurb": "HIS 402 — Lessons 1–6 complete. Certificate unlocked (cmid 2108). Course total 98%.", "lessons": [{"id": "ch1-1", "number": 1, "title": "Lesson 1", "topic": "What is history (makers, evidence, providence) and what is worship from an Old Testament perspective (face-to-face, praise, sacrifices).", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 1: 10/10 (100%), attempt 101727 (cmid 1109). Essays Complete/Not graded. Reading cmid 1108; Lesson cmid 1107.", "summary": "Lesson 1 defines history as a careful account and interpretation of past people, events, cultures, and forces — using evidence while recognizing perspective and God’s providential work. History makers make history; the Jewish view of history is not the cycle view; events, dates, and places alone do not make history come alive. Worship begins with a face-to-face encounter with God as a whole-life relationship; Old Testament praise is the most significant form, and sacrifices from the beginning pointed toward Christ.", "bigIdeas": ["History makers make history — people shaped by conviction and calling drive the story.", "The Jewish view of history is not identical to the cycle view of history.", "Events, dates, and places alone do not make history come alive.", "History is a careful account and interpretation with evidence, perspective, and God’s providence.", "Worship begins with a face-to-face encounter with God; it is a whole-life relationship.", "Music style in worship has not remained constant through church history; organs were not originally only Reformed.", "Wesley’s songs had at least as great an effect as his sermons.", "Abel, Noah, Abraham, and Moses worshipped; OT praise is the most significant form; sacrifices from the beginning pointed toward Christ."], "takeaways": ["History makers make history; Jewish view ≠ cycle view; events/dates/places alone do NOT make history come alive.", "Worship begins face-to-face with God; music style NOT constant through church history; organs not originally only Reformed.", "Wesley’s songs ≥ effect of sermons; Abel/Noah/Abraham/Moses worshipped; OT most significant form = praise; sacrifices from beginning.", "History = careful account/interpretation with evidence + God’s providence; worship = whole-life relationship; sacrifices → Christ."], "glossary": [{"term": "History (makers / providence)", "meaning": "A careful account and interpretation of past people, events, cultures, and forces, using evidence while recognizing perspective and God’s providential work. History makers make history."}, {"term": "Jewish vs cycle view of history", "meaning": "The Jewish view of history is not identical to the cycle view; treating them as the same is false."}, {"term": "Worship (face-to-face)", "meaning": "Worship begins with a face-to-face encounter with God — a whole-life relationship expressed through reverence, obedience, sacrifice, prayer, praise, thanksgiving, and service."}, {"term": "Wesley’s songs", "meaning": "Wesley’s songs had at least as great an effect as his sermons."}, {"term": "OT praise", "meaning": "The most significant form of worship in the Old Testament was praise."}, {"term": "Sacrifices", "meaning": "Part of Old Testament worship from the very beginning; expressed repentance, faith, gratitude, surrender, fellowship, and atonement, and pointed toward Christ’s sacrifice."}], "outline": ["What is history? History makers; Jewish view ≠ cycle view; events/dates/places alone do not make history come alive", "History as careful account/interpretation with evidence, perspective, and God’s providence", "Worship begins face-to-face with God; whole-life relationship", "Music style not constant in church history; organs not originally only Reformed; Wesley’s songs ≥ sermons", "OT worship: Abel, Noah, Abraham, Moses; praise most significant; sacrifices from the beginning → Christ"], "mustKnow": [{"label": "Quiz 1", "value": "100% (10/10), attempt 101727, cmid 1109"}, {"label": "History makers", "value": "History makers make history (True)"}, {"label": "Jewish vs cycle view", "value": "Jewish view is NOT identical to the cycle view (False that they are identical)"}, {"label": "Events / dates / places", "value": "Alone they do NOT make history come alive (False)"}, {"label": "Worship begins", "value": "Face-to-face encounter with God (True)"}, {"label": "Music / organ", "value": "Style NOT constant through church history; organs NOT originally only Reformed"}, {"label": "Wesley’s songs", "value": "At least as great an effect as his sermons"}, {"label": "OT worship", "value": "Abel/Noah/Abraham/Moses worshipped; praise most significant; sacrifices from the beginning"}, {"label": "What is history?", "value": "Careful account/interpretation with evidence + God’s providence"}, {"label": "What is worship (OT)?", "value": "Whole-life relationship; sacrifices → Christ"}], "compare": [{"title": "Jewish view vs cycle view of history", "points": ["Jewish view of history is NOT identical to the cycle view (quiz False that they are identical)", "Do not collapse the two into one pattern"]}, {"title": "Events/dates/places vs history that comes alive", "points": ["Events, dates, and places alone do NOT make history come alive", "History makers, careful interpretation with evidence, and God’s providence make history meaningful"]}, {"title": "Music style / organ use across church history", "points": ["Music style has NOT remained remarkably similar throughout all of church history", "Originally, Reformed churches were NOT the only ones to embrace the organ"]}], "pulpit": ["History makers make history — and God providentially works through them.", "Events and dates are not enough; interpretation with evidence brings the story alive.", "Worship begins face-to-face with God, then shapes the whole life.", "Wesley’s songs carried as much weight as his sermons — truth sung sticks.", "Old Testament sacrifices taught the seriousness of sin and pointed to Christ."], "quickReview": ["History makers make history; Jewish view ≠ cycle view; events/dates/places alone ≠ history come alive.", "History = careful account/interpretation + evidence + God’s providence.", "Worship begins face-to-face; whole-life relationship; music style not constant; organs not only Reformed.", "Wesley’s songs ≥ sermons; Abel/Noah/Abraham/Moses worshipped; OT praise most significant.", "Sacrifices from the beginning → repentance, faith, atonement → Christ."], "quiz": [{"q": "History makers make history.", "answer": "True", "why": "History makers make history."}, {"q": "The Jewish view of history is identical to the cycle view of history.", "answer": "False", "why": "Jewish view ≠ cycle view."}, {"q": "Events, dates, and places make history come alive.", "answer": "False", "why": "Events/dates/places alone do NOT make history come alive."}, {"q": "Worship begins with a face-to-face encounter with God.", "answer": "True", "why": "Worship begins face-to-face with God."}, {"q": "The music style used in worship has remained remarkably similar throughout all of church history.", "answer": "False", "why": "Music style has NOT remained constant through church history."}, {"q": "Originally, only Reformed churches embraced the use of the organ in worship.", "answer": "False", "why": "Organs were not originally only Reformed."}, {"q": "Wesley’s songs had at least as great an effect as his sermons.", "answer": "True", "why": "Wesley’s songs ≥ effect of sermons."}, {"q": "Abel, Noah, Abraham, and Moses each worshipped the Lord", "answer": "True", "why": "Abel, Noah, Abraham, and Moses each worshipped."}, {"q": "The most significant form of worship in the Old Testament was praise.", "answer": "True", "why": "OT most significant form = praise."}, {"q": "Sacrifices were part of Old Testament worship from the very beginning.", "answer": "True", "why": "Sacrifices from the beginning."}], "essays": [{"theme": "How would you answer ‘What is History?’", "summary": "History is a careful account and interpretation of past people, events, cultures, and forces, using evidence while recognizing perspective and God’s providential work."}, {"theme": "From an Old Testament perspective, what is worship?", "summary": "Whole-life relationship with the living God, expressed through reverence, obedience, sacrifice, prayer, praise, thanksgiving, and service."}, {"theme": "Explain the role of sacrifices in Old Testament worship.", "summary": "Sacrifices expressed repentance, faith, gratitude, surrender, fellowship, and atonement; the various offerings taught the seriousness of sin and pointed toward Christ’s sacrifice."}]}, {"id": "ch1-2", "number": 2, "title": "How Then Shall We Study History?", "topic": "How to study history through revival/awakening, Old Testament revival patterns (Mizpah, Asa, Josiah), and prayer — from Israel’s corporate return to the Lord to Jesus’ relationship with the Father.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 2: 10/10 (100%), 7m49s, attempt 101737 (cmid 1113). Essays Complete/Not graded.", "summary": "Lesson 2 asks how we should study history by looking at revival and awakening, Old Testament seasons of return to the Lord, and prayer. A remarkable difference between revivals and awakenings is not the framing to hold; the eternal human quest is to know and experience God, and revival can take a variety of faces. The stone of Ebenezer commemorated the great Old Testament revival at Mizpah. Asa did not lead five distinct seasons of revival, and Josiah did not first lead revival as an old man. Nothing of eternal value happens apart from prayer; prayer reflected Jesus’ relationship with the Father; self-surrender is critical in prayer; and the last thing Jesus did on the cross was pray.", "bigIdeas": ["A remarkable difference between revivals and awakenings is not the framing to hold (False as stated).", "The eternal human quest is to know and experience God.", "Revival can take a variety of faces.", "The stone of Ebenezer commemorated the great Old Testament revival at Mizpah.", "Asa did NOT lead his people through five distinct seasons of revival.", "Josiah did NOT first lead his people in a revival emphasis when he was an old man.", "Nothing of eternal value happens apart from prayer.", "Prayer reflected Jesus’ relationship with the Father; self-surrender is a critical aspect of prayer; the last thing Jesus did on the cross was pray."], "takeaways": ["Remarkable difference between revivals and awakenings = False (not as framed).", "Eternal human quest = know and experience God; revival can take variety of faces.", "Ebenezer stone commemorated revival at Mizpah; Asa did NOT lead five distinct seasons; Josiah did NOT first lead revival as old man.", "Nothing eternal apart from prayer; prayer reflected Jesus’ relationship with Father; self-surrender critical; last thing on cross was pray.", "Mizpah: repentance, confession, fasting, Samuel’s intercession, thunder vs Philistines, Ebenezer."], "glossary": [{"term": "Ebenezer", "meaning": "The stone Samuel set up between Mizpah and Shen after God’s deliverance from the Philistines; he named it Ebenezer, saying, “Thus far the Lord has helped us.” It commemorated the great Old Testament revival at Mizpah."}, {"term": "Mizpah", "meaning": "Site of Old Testament revival when Samuel gathered Israel to return to the Lord with all their hearts: putting away foreign gods, mourning, confession, fasting, sacrifice, Samuel’s intercession, thunder against the Philistines, and the Ebenezer stone."}, {"term": "Revival / awakening", "meaning": "The claim that a remarkable difference exists between revivals and awakenings is False as framed. Revival can take a variety of faces; the eternal human quest is to know and experience God."}, {"term": "Asa", "meaning": "Did NOT lead his people through five distinct seasons of revival (quiz False)."}, {"term": "Josiah", "meaning": "Did NOT first lead his people in a revival emphasis when he was an old man (quiz False)."}, {"term": "Self-surrender in prayer", "meaning": "Jesus taught that one critical aspect of prayer is self-surrender — accepting the Father’s will (“Not My will, but Yours be done”), not controlling God."}], "outline": ["How then shall we study history? Through revival/awakening and prayer patterns", "Revivals and awakenings: remarkable difference claim is False as framed; eternal quest = know and experience God; revival can take a variety of faces", "Old Testament revival markers: Ebenezer commemorated Mizpah; Asa ≠ five distinct seasons; Josiah ≠ first revival as old man", "Mizpah revival: return with all hearts, put away foreign gods, mourn/confess/fast, Samuel’s lamb and intercession, thunder vs Philistines, Ebenezer stone", "Prayer: nothing eternal apart from prayer; OT prayer as conversation/relationship; Jesus’ prayer = living relationship, surrender, trust, intercession; last act on the cross was pray"], "mustKnow": [{"label": "Quiz 2", "value": "100% (10/10), 1 attempt, 7m49s, cmid 1113, attempt 101737"}, {"label": "Revivals vs awakenings", "value": "A remarkable difference exists — False (not as framed)"}, {"label": "Eternal human quest", "value": "To know and experience God (True)"}, {"label": "Faces of revival", "value": "Revival can take a variety of faces (True)"}, {"label": "Ebenezer / Mizpah", "value": "Ebenezer stone commemorated the great OT revival at Mizpah (True)"}, {"label": "Asa", "value": "Did NOT lead five distinct seasons of revival (False)"}, {"label": "Josiah", "value": "Did NOT first lead revival as an old man (False)"}, {"label": "Prayer", "value": "Nothing of eternal value happens apart from prayer (True)"}, {"label": "Jesus and prayer", "value": "Prayer reflected Jesus’ relationship with the Father; self-surrender critical; last thing on the cross was pray"}, {"label": "Mizpah pattern", "value": "Repentance, confession, fasting, Samuel’s intercession, thunder vs Philistines, Ebenezer"}], "compare": [{"title": "Revivals vs awakenings", "points": ["Quiz: “A remarkable difference exists between revivals and awakenings” — False (not as framed)", "Hold instead: eternal human quest = know and experience God; revival can take a variety of faces"]}, {"title": "Asa and Josiah revival claims", "points": ["Asa led five distinct seasons of revival — False", "Josiah first led revival emphasis when he was an old man — False"]}, {"title": "Mizpah revival vs empty ritual", "points": ["Mizpah: return with all hearts, put away foreign gods, mourn, confess, fast", "Samuel’s sacrifice and continued intercession; God answered with thunder; Ebenezer = thankful remembrance"]}], "pulpit": ["The eternal human quest is to know and experience God — and revival can wear many faces.", "Mizpah still preaches: repentance, confession, fasting, intercession, and an Ebenezer stone of remembrance.", "Nothing of eternal value happens apart from prayer.", "Jesus’ prayer was relationship with the Father — surrender, trust, and “Not My will, but Yours.”", "The last thing Jesus did on the cross was pray — private life with God shapes who we really are."], "quickReview": ["Remarkable difference revivals/awakenings = False; quest = know/experience God; revival takes variety of faces.", "Ebenezer commemorated Mizpah; Asa ≠ five seasons; Josiah ≠ first revival as old man.", "Nothing eternal apart from prayer; prayer reflected Jesus’ relationship with Father; self-surrender critical; last on cross = pray.", "Mizpah: put away gods, mourn/confess/fast, Samuel’s intercession, thunder, Ebenezer — “Thus far the Lord has helped us.”", "OT prayer = conversation/relationship; Jesus teaches living relationship, surrender, persistence, sincerity."], "quiz": [{"q": "A remarkable difference exists between revivals and awakenings.", "answer": "False", "why": "Remarkable difference between revivals and awakenings = False (not as framed)."}, {"q": "The eternal human quest is to know and experience God.", "answer": "True", "why": "Eternal human quest = know and experience God."}, {"q": "Revival can take a variety of faces.", "answer": "True", "why": "Revival can take a variety of faces."}, {"q": "The stone of Ebenezer commemorated the great Old Testament revival at Mizpah.", "answer": "True", "why": "Ebenezer stone commemorated revival at Mizpah."}, {"q": "Asa led his people through five distinct seasons of revival.", "answer": "False", "why": "Asa did NOT lead five distinct seasons of revival."}, {"q": "Josiah first led his people in a revival emphasis when he was an old man.", "answer": "False", "why": "Josiah did NOT first lead revival as an old man."}, {"q": "Nothing of eternal value happens apart from prayer.", "answer": "True", "why": "Nothing of eternal value happens apart from prayer."}, {"q": "Prayer reflected Jesus' relationship with the Father.", "answer": "True", "why": "Prayer reflected Jesus’ relationship with the Father."}, {"q": "Jesus taught us that one critical aspect of prayer is self-surrender.", "answer": "True", "why": "Self-surrender is a critical aspect of prayer."}, {"q": "The last thing Jesus did on the cross was pray.", "answer": "True", "why": "The last thing Jesus did on the cross was pray."}], "essays": [{"theme": "Mizpah revival", "summary": "The revival at Mizpah began when Samuel gathered Israel to return to the Lord with all their hearts. The people put away their foreign gods, mourned, confessed, and fasted, showing genuine repentance. Samuel offered a lamb and cried out to God for them. When the Philistines came to attack, Israel was afraid, but Samuel kept praying and interceding. God answered with a mighty thunder and threw the Philistines into confusion, giving Israel victory. Samuel then set up a stone between Mizpah and Shen and named it Ebenezer, saying, “Thus far the Lord has helped us.” The revival therefore joined repentance, confession, prayer, sacrifice, and thankful remembrance of God’s deliverance."}, {"theme": "OT prayer", "summary": "In the Old Testament, prayer was a real conversation and relationship with God, beginning with Adam and Eve and continuing through people such as Noah, Abraham, Isaac, Jacob, Moses, Joshua, David, Ezra, and Nehemiah. People called on the Lord, built altars, offered sacrifices, made vows, worshiped, confessed sin, sought forgiveness and purity, and asked for guidance and help. Prayer was also corporate, as Israel prayed and repented together, and it included intercession for others and for the nation. The Old Testament shows that prayer could change how people faced circumstances and opposition, but its deepest purpose was spiritual: intimacy with God, pardon, holiness, and dependence on his promises and will."}, {"theme": "Jesus and prayer", "summary": "Jesus teaches me that prayer must be a living relationship with the Father, not just words. He made time to pray alone, prayed with humility and earnestness, and accepted the Father’s will: “Not My will, but Yours be done.” His prayers show surrender, trust, intercession, thanksgiving, and compassion—even forgiveness for those who crucified him. He prayed in both ordinary ministry and deep suffering, so prayer helps us discover and follow God’s will rather than trying to control God. Jesus also teaches that prayer should be persistent and sincere, and that a believer’s private life with God shapes the person he or she really is."}]}, {"id": "ch1-3", "number": 3, "title": "How Shall We Divide Church History?", "topic": "Dividing church history by the seven churches of Revelation as seven epochs — from Apostolic Ephesus through Liberal Laodicea — with prophecy as history pre-written, Reformation and missionary ages, and the end of history as the beginning of eternity.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 3: 9/10 (90%), 9m21s, attempt 101741 (cmid 1117). Essays Complete/Not graded. Miss: Q5 (chose False; Moodle True).", "summary": "Lesson 3 asks how we should divide church history by reading the seven letters to the seven churches in Revelation as seven epochs. Prophecy is history pre-written. The seven letters do not follow a traveler’s path through Asia Minor. Ephesus represents the early Apostolic church; Smyrna the age of persecution (including attempts to destroy the Scriptures); Pergamos the state/political church; Thyatira the Medieval church (Christianity modified by medieval civilization; no vast Charlemagne revival); Sardis the Protestant/Reformation period (capitalizing on nationalism); Philadelphia the Missionary church; and Laodicea the Liberal age (liberalism does not free evangelistic zeal). The end of history is the beginning of eternity.", "bigIdeas": ["Prophecy is history pre-written.", "The seven letters to the seven churches do NOT follow a traveler’s path visiting the churches in Asia Minor.", "Ephesus = early Apostolic church (to ~100).", "Smyrna = Persecuted church (100–312); a major tragedy was the attempt to destroy all copies of the Scriptures.", "Pergamos = State/Political church (~316–800).", "Thyatira = Medieval church (800–1517); Christianity was modified with medieval civilization; did NOT see a vast revival under Charlemagne.", "Sardis = Protestant/Reformation (1517–1750); the Reformation capitalized on the spirit of nationalism.", "Philadelphia = Missionary church (1750–1900).", "Laodicea = Liberal church (1900+); liberalism does NOT free evangelistic zeal for unparalleled progress.", "The end of history is the beginning of eternity."], "takeaways": ["Prophecy = history pre-written.", "Seven letters do NOT follow traveler path in Asia Minor (False is correct for that stem).", "Ephesus = early Apostolic; Smyrna persecution + attempt to destroy Scriptures; medieval civilization modified Christianity (True).", "Thyatira Medieval did NOT see vast revival under Charlemagne; Reformation capitalized on nationalism; Philadelphia = Missionary; liberalism does NOT free evangelistic zeal; end of history = beginning of eternity.", "Seven epochs: Ephesus Apostolic–100; Smyrna Persecuted 100–312; Pergamos State/Political ~316–800; Thyatira Medieval 800–1517; Sardis Protestant/Reformation 1517–1750; Philadelphia Missionary 1750–1900; Laodicea Liberal 1900+."], "glossary": [{"term": "Prophecy", "meaning": "History pre-written — God’s foretelling that unfolds as church history epochs."}, {"term": "Ephesus", "meaning": "Early Apostolic church; epoch roughly to AD 100."}, {"term": "Smyrna", "meaning": "Persecuted church, AD 100–312. One major tragedy: the attempt to destroy all copies of the Scriptures."}, {"term": "Pergamos", "meaning": "State/Political church, roughly AD 316–800."}, {"term": "Thyatira", "meaning": "Medieval church, AD 800–1517. Christianity was modified with the introduction of medieval civilization; did NOT see a vast revival under Charlemagne."}, {"term": "Sardis", "meaning": "Protestant/Reformation church, AD 1517–1750. The Reformation Period capitalized on the spirit of nationalism."}, {"term": "Philadelphia", "meaning": "Missionary church, AD 1750–1900."}, {"term": "Laodicea", "meaning": "Liberal church, AD 1900+. Liberalism does NOT free evangelistic zeal so that Christianity sees unparalleled progress."}, {"term": "Seven churches / seven epochs", "meaning": "Revelation’s seven letters mapped as church-history epochs: Ephesus → Smyrna → Pergamos → Thyatira → Sardis → Philadelphia → Laodicea. They do NOT follow a traveler’s path through Asia Minor."}, {"term": "End of history", "meaning": "The end of history is the beginning of eternity."}], "outline": ["How shall we divide church history? — prophecy as history pre-written; seven churches as seven epochs", "Ephesus — Apostolic church (to ~100)", "Smyrna — Persecuted church (100–312); attempt to destroy Scriptures", "Pergamos — State/Political church (~316–800)", "Thyatira — Medieval church (800–1517); Christianity modified by medieval civilization; no vast Charlemagne revival", "Sardis — Protestant/Reformation (1517–1750); capitalized on nationalism", "Philadelphia — Missionary church (1750–1900)", "Laodicea — Liberal church (1900+); liberalism does not free evangelistic zeal", "The end of history is the beginning of eternity"], "mustKnow": [{"label": "Quiz 3", "value": "90% (9/10), 1 attempt, 9m21s, cmid 1117, attempt 101741 — Miss Q5"}, {"label": "Prophecy", "value": "History pre-written (True)"}, {"label": "Traveler path", "value": "Seven letters follow a traveler’s path in Asia Minor — False"}, {"label": "Ephesus", "value": "Early Apostolic church (True); epoch to ~100"}, {"label": "Smyrna", "value": "Persecution age 100–312; attempt to destroy Scriptures (True)"}, {"label": "Medieval civilization (Q5 Miss)", "value": "Christianity was modified with medieval civilization — True (chose False)"}, {"label": "Thyatira / Charlemagne", "value": "Vast revival under Charlemagne — False"}, {"label": "Reformation / Sardis", "value": "Capitalized on nationalism (True); 1517–1750"}, {"label": "Philadelphia", "value": "Missionary Church (True); 1750–1900"}, {"label": "Liberalism / Laodicea", "value": "Frees evangelistic zeal / unparalleled progress — False; 1900+"}, {"label": "End of history", "value": "Beginning of eternity (True)"}], "compare": [{"title": "Seven epochs (church → age → dates)", "points": ["Ephesus — Apostolic — to ~100", "Smyrna — Persecuted — 100–312", "Pergamos — State/Political — ~316–800", "Thyatira — Medieval — 800–1517", "Sardis — Protestant/Reformation — 1517–1750", "Philadelphia — Missionary — 1750–1900", "Laodicea — Liberal — 1900+"]}, {"title": "Traveler path vs epoch map", "points": ["The seven letters do NOT follow a path a traveler might follow visiting the churches in Asia Minor (False)", "Hold instead: seven churches as prophetic epochs dividing church history"]}, {"title": "Missionary zeal vs liberalism", "points": ["Philadelphia = Missionary Church — evangelistic advance (1750–1900)", "Liberalism does NOT free evangelistic zeal for unparalleled progress (Laodicea, 1900+)"]}, {"title": "Medieval / Thyatira claims", "points": ["Christianity was modified with the introduction of medieval civilization — True", "Thyatira saw a vast revival under Charlemagne — False"]}], "pulpit": ["Prophecy is history pre-written — God maps the ages before they unfold.", "From Apostolic fire to persecution, state church, medieval modification, Reformation, missions, and liberalism — each epoch still speaks.", "The Reformation rode the spirit of nationalism; Philadelphia carried the missionary church.", "Liberalism does not free evangelistic zeal — do not confuse cultural accommodation with gospel advance.", "The end of history is the beginning of eternity — live toward that horizon."], "quickReview": ["Prophecy = history pre-written; seven letters ≠ traveler path in Asia Minor.", "Ephesus Apostolic–100; Smyrna Persecuted 100–312 (Scriptures targeted); Pergamos State ~316–800.", "Thyatira Medieval 800–1517: civilization modified Christianity (True); Charlemagne vast revival = False.", "Sardis Reformation 1517–1750 capitalized on nationalism; Philadelphia Missionary 1750–1900; Laodicea Liberal 1900+.", "Liberalism ≠ frees evangelistic zeal; end of history = beginning of eternity. Miss Q5: medieval modification = True."], "quiz": [{"q": "Prophecy is history pre-written.", "answer": "True", "why": "Prophecy = history pre-written."}, {"q": "The seven letters to the seven churches in Revelation follow a path that a traveler might follow visiting the churches in Asia Minor.", "answer": "False", "why": "Seven letters do NOT follow a traveler path in Asia Minor (False is correct)."}, {"q": "Ephesus represents the early Apostolic church.", "answer": "True", "why": "Ephesus = early Apostolic church."}, {"q": "One major tragedy during the age of persecution (Smyrna), was the attempt to destroy all copies of the Scriptures.", "answer": "True", "why": "Smyrna persecution included the attempt to destroy all copies of the Scriptures."}, {"q": "Christianity was modified with the introduction of medieval civilization.", "answer": "True", "why": "Miss: chose False; Moodle True — medieval civilization modified Christianity."}, {"q": "Thyatira, representing the Medieval Church, saw a vast revival under the leadership of Charlemagne.", "answer": "False", "why": "Thyatira Medieval did NOT see a vast revival under Charlemagne."}, {"q": "The Reformation Period capitalized on the spirit of nationalism.", "answer": "True", "why": "Reformation capitalized on nationalism."}, {"q": "Philadelphia marked the period of the Missionary Church.", "answer": "True", "why": "Philadelphia = Missionary Church."}, {"q": "Liberalism frees evangelistic zeal so that Christianity sees unparalleled progress.", "answer": "False", "why": "Liberalism does NOT free evangelistic zeal / unparalleled progress."}, {"q": "The end of history is the beginning of eternity.", "answer": "True", "why": "The end of history is the beginning of eternity."}], "essays": [{"theme": "List the seven churches of Revelation and the historic epochs they represent.", "summary": "The seven churches represent seven broad epochs of church history: Ephesus, the Apostolic Church (Pentecost–AD 100); Smyrna, the Persecuted Church (AD 100–312); Pergamos, the State or Political Church (about AD 316–800); Thyatira, the Medieval Church (AD 800–1517); Sardis, the Protestant or Reformation Church (AD 1517–1750); Philadelphia, the Missionary Church (AD 1750–1900); and Laodicea, the Liberal Church (AD 1900 onward)."}, {"theme": "From the perspective of Sardis, explain factors and personalities which contributed to the birth and development of the state church, the Period of Reformation.", "summary": "From Sardis, the Reformation grew out of serious spiritual and moral problems in the medieval church, but also from several movements and personalities God used to prepare the way. The Albigenses and Waldensians, John Wycliffe, John Huss, and Jerome Savonarola challenged corruption and called people back to Scripture; the Renaissance, the printing press, nationalism, and widespread discontent also helped the reform spread. Wycliffe translated the New Testament into English, Huss was burned in 1415, and Savonarola was tortured and executed. Martin Luther then rediscovered that salvation rests on faith in God's grace rather than works, opposed Tetzel's indulgences, posted the Ninety-five Theses, and refused to recant. Zwingli led reform in Switzerland, Calvin's Institutes shaped Reformed theology, and John Knox established the Scottish Reformation. Together, these influences broke the monopoly of the papacy and helped form Protestant and national/state churches, with the Bible as the authority for faith and practice and with personal, living faith."}, {"theme": "What characteristics marked the Missionary Church, depicted in the Church of Philadelphia?", "summary": "Philadelphia was a faithful and persevering church with only limited strength, yet Christ gave it an open door for ministry. It kept His word and did not deny His name, so its defining marks were endurance, evangelistic zeal, revival, and worldwide missions. After about 1780, spiritual vitality spread through men and movements, especially John Wesley and the Methodist movement in Britain. Mission societies carried the gospel to every continent and many islands, while other religious groups and evangelists grew outside the established church. This period also showed the church's social influence in opposing the slave trade and improving living conditions and education for ordinary people. Philadelphia therefore represents a church that remained faithful and used its opportunity to proclaim Christ broadly."}]}, {"id": "ch1-4", "number": 4, "title": "The Apostolic Church, Pentecost to 100 AD", "topic": "The Apostolic Church from Pentecost to AD 100 — Jerusalem Council welcoming Gentiles, Pentecost as Christianity’s foundation and new worship model (preaching, lifestyle, spiritual life), Peter’s Joel 2:28–32 sermon, and the early church’s missionary-pastoral prayer life.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 4: 10/10 (100%), 9m58s, attempt 101750 (cmid 1121). Essays Complete/Not graded. 1 attempt.", "summary": "Lesson 4 covers the Apostolic Church from Pentecost to AD 100. The Jerusalem Council welcomed Gentiles into the church. Pentecost is Christianity’s foundation, separating it from its Jewish roots, and established a new worship model centered on the Holy Spirit and Christ — preaching, lifestyle (believers as the temple), and spiritual life — so worship could take place anywhere. Peter’s Pentecost sermon used Joel 2:28–32; about three thousand believed and were baptized. Paul did not attend John’s funeral. The early church prayed with missionary and pastoral focus: when they prayed, things began to happen; prayer is a privilege for all believers; they prayed for sinners’ salvation (not “no need because predetermined”) and for Gospel effectiveness.", "bigIdeas": ["Jerusalem Council welcomed Gentiles into the church.", "Paul did NOT attend John’s funeral (stem “Paul may have attended” = False).", "Peter’s Pentecost sermon used Joel 2:28–32.", "Pentecost worship included preaching, lifestyle, and spiritual life.", "Pentecost was Christianity’s foundation, separating it from Jewish roots.", "Pray for sinners — salvation is not “no need because predetermined.”", "When the early church prayed, things began to happen.", "Prayer is a privilege for all believers.", "Pray for Gospel effectiveness (it is NOT unnecessary).", "Believers may worship God anywhere."], "takeaways": ["Jerusalem Council welcomed Gentiles; Paul did NOT attend John’s funeral; Peter’s Pentecost sermon used Joel 2:28–32.", "Pentecost worship = preaching, lifestyle, spiritual life; Pentecost = Christianity’s foundation separating from Jewish roots.", "Pray for sinners (salvation not “no need because predetermined”); when early church prayed, things happened; prayer privilege for all; pray for Gospel effectiveness; worship anywhere."], "glossary": [{"term": "Jerusalem Council", "meaning": "Early church council that welcomed Gentiles into the church (True on Quiz 4)."}, {"term": "Pentecost", "meaning": "Christianity’s foundation, separating it from Jewish roots; Spirit’s empowering presence, birth of the church’s public witness, beginning of ongoing revival."}, {"term": "Joel 2:28–32", "meaning": "Scripture Peter used in his Pentecost sermon to explain the Spirit’s outpouring."}, {"term": "Pentecost worship", "meaning": "New model: preaching the good news alongside Scripture, singing, prayer, and adoration; lifestyle (believers as the temple); spiritual life — personal, participatory, congregational; worship anywhere."}, {"term": "Believers as temple", "meaning": "Because God dwells with His people, a clean and sanctified life matters; worship is not tied to a sacred building or fixed ritual."}, {"term": "Early church prayer", "meaning": "Missionary and pastoral focus — when they prayed, things began to happen; privilege for all believers; includes praying for sinners and Gospel effectiveness."}, {"term": "Apostolic Church", "meaning": "Epoch from Pentecost to about AD 100 (Ephesus in the seven-epoch map)."}, {"term": "Gentiles welcomed", "meaning": "Jerusalem Council decision: Gentiles welcomed into the church without requiring full Jewish ritual boundary as the door."}, {"term": "Gospel effectiveness", "meaning": "A standing prayer request of the early church — it is NOT unnecessary to pray for it."}, {"term": "Worship anywhere", "meaning": "Because God dwells with His people, believers may worship God anywhere — not limited to a sacred building."}], "outline": ["The Apostolic Church — Pentecost to AD 100", "Jerusalem Council — Gentiles welcomed", "Pentecost Sunday — wind, tongues of fire, Spirit filling, other languages, Peter’s Joel 2 sermon, ~3,000 added", "Pentecost as foundation — separating Christianity from Jewish roots", "New worship model — preaching, lifestyle (temple-people), spiritual life; worship anywhere", "Paul and John’s funeral — Paul did NOT attend", "Early church prayer — eight missionary/pastoral requests; things happened when they prayed", "Pray for sinners and Gospel effectiveness; prayer privilege for all"], "mustKnow": [{"label": "Quiz 4", "value": "100% (10/10), 1 attempt, 9m58s, cmid 1121, attempt 101750"}, {"label": "Jerusalem Council", "value": "Welcomed Gentiles — True"}, {"label": "Paul / John’s funeral", "value": "Paul may have attended John’s funeral — False"}, {"label": "Peter’s sermon", "value": "Used Joel 2:28–32 — True"}, {"label": "Pentecost worship", "value": "Preaching, lifestyle, and spiritual life — True"}, {"label": "Pentecost foundation", "value": "Christianity’s foundation, separating from Jewish roots — True"}, {"label": "Pray for sinners", "value": "No need because salvation predetermined — False (do pray)"}, {"label": "Early church prayed", "value": "Things began to happen — True"}, {"label": "Prayer privilege", "value": "Privilege for all believers — True"}, {"label": "Gospel effectiveness", "value": "Unnecessary to pray for it — False (do pray)"}, {"label": "Worship anywhere", "value": "Believers may worship God anywhere — True"}], "compare": [{"title": "Jewish roots vs Pentecost foundation", "points": ["Pentecost = Christianity’s foundation, separating it from Jewish roots", "Worship no longer centered on a sacred building or fixed ritual alone — Spirit and Christ at the center"]}, {"title": "Temple building vs temple people", "points": ["Old pattern: sacred building / fixed ritual focus", "Pentecost model: believers are the temple; clean sanctified lifestyle; worship anywhere"]}, {"title": "Prayer: predetermined vs petition", "points": ["False: no need to pray for sinners because salvation is predetermined", "True: pray for sinners’ salvation; pray for Gospel effectiveness; when early church prayed, things happened"]}, {"title": "Quiz True vs False stems", "points": ["True: Jerusalem Council / Gentiles; Joel 2:28–32; worship triad; Pentecost foundation; prayer works; privilege for all; worship anywhere", "False: Paul may have attended John’s funeral; no need to pray for sinners (predetermined); unnecessary to pray for Gospel effectiveness"]}], "pulpit": ["Pentecost founded the church’s public witness — Spirit-filled people, not a building, became God’s dwelling.", "Welcome the nations: the Jerusalem Council opened the door to Gentiles.", "Worship is preaching, life offered to God, and Spirit-led participation — and it can happen anywhere.", "When the church prays, things begin to happen — pray for sinners, workers, boldness, healing, and Gospel advance.", "Prayer is a privilege for every believer; do not let fatalism silence petitions for salvation or Gospel effectiveness."], "quickReview": ["Jerusalem Council welcomed Gentiles (True); Paul may have attended John’s funeral (False); Peter used Joel 2:28–32 (True).", "Pentecost worship = preaching + lifestyle + spiritual life; Pentecost = foundation separating from Jewish roots; worship anywhere.", "Pray for sinners (not “predetermined = no need”); early church prayer → things happened; privilege for all; pray for Gospel effectiveness.", "Pentecost Sunday: ~120 praying; wind; tongues of fire; filled with Spirit; other languages; Peter’s sermon; ~3,000 baptized.", "Eight prayer themes: leaders, Spirit power, sinners, workers, Gospel spread, boldness, healing, protection/deliverance."], "quiz": [{"q": "Jerusalem Council welcomed Gentiles", "answer": "True", "why": "Jerusalem Council welcomed Gentiles into the church."}, {"q": "Paul may have attended John’s funeral", "answer": "False", "why": "Paul did NOT attend John’s funeral."}, {"q": "Peter’s Pentecost sermon used Joel 2:28–32", "answer": "True", "why": "Peter explained Pentecost from Joel 2:28–32."}, {"q": "Pentecost worship included preaching, lifestyle, and spiritual life", "answer": "True", "why": "Pentecost worship = preaching, lifestyle, and spiritual life."}, {"q": "Pentecost was Christianity’s foundation, separating it from Jewish roots", "answer": "True", "why": "Pentecost = Christianity’s foundation separating from Jewish roots."}, {"q": "No need to pray for sinners because salvation is predetermined", "answer": "False", "why": "Do pray for sinners — not “no need because predetermined.”"}, {"q": "When the early church prayed, things began to happen", "answer": "True", "why": "When the early church prayed, things began to happen."}, {"q": "Prayer is a privilege for all believers", "answer": "True", "why": "Prayer is a privilege for all believers."}, {"q": "It is unnecessary to pray for Gospel effectiveness", "answer": "False", "why": "Do pray for Gospel effectiveness — it is NOT unnecessary."}, {"q": "Believers may worship God anywhere", "answer": "True", "why": "Because God dwells with His people, worship can take place anywhere."}], "essays": [{"theme": "Pentecost worship model", "summary": "Pentecost brought a new model of worship centered on the Holy Spirit and on Christ rather than on a sacred building or fixed ritual. Preaching the good news became as important as Scripture reading, singing, prayer, and adoration. Worship also meant offering our whole lives to God; believers were now the temple, so a clean and sanctified life mattered. The service was personal, participatory, and congregational, with lay believers sharing in hymns, Scripture, exhortation and teaching, fellowship, breaking bread, and prayer. Because God dwells with His people, worship could take place anywhere."}, {"theme": "early church prayer requests — 8", "summary": "The early church prayed with a missionary and pastoral focus. Eight clear requests were: (1) guidance and discernment for choosing leaders, (2) that the Holy Spirit would work powerfully in believers, (3) the salvation of sinners, (4) that God would send workers into the harvest, (5) the Gospel’s spread and effectiveness, (6) boldness for pastors and missionaries to speak, (7) healing for the sick, and (8) protection and deliverance for His servants. Their prayer was not centered on comfort or buildings, but on God’s will, spiritual power, salvation, the advance of the Gospel, the needs of people, and faithful ministry."}, {"theme": "Pentecost Sunday events", "summary": "On Pentecost Sunday about 120 disciples were gathered in Jerusalem, continuing in prayer as Jesus had commanded. Suddenly there was a sound like a rushing mighty wind that filled the house. Tongues like fire appeared and rested on each person, and all were filled with the Holy Spirit. They began speaking in other languages, so Jewish pilgrims from many nations heard God’s works in their own tongues. Peter explained the event from Joel 2 and proclaimed Jesus. About three thousand people believed, were baptized, and were added to the church. Pentecost therefore marked the Spirit’s empowering presence, the birth of the church’s public witness, and the beginning of an ongoing revival."}]}, {"id": "ch1-5", "number": 5, "title": "Smyrna & Pergamos: The Persecuted and Worldly Church (100–800)", "topic": "Smyrna the Persecuted Church (100–313) and Pergamos the Worldly Church (313–800) — John the last Apostle (~100), early learning and worship, Justin Martyr’s order of worship, Ambrose’s doctrinally pure hymns, desert refuge under persecution (to Diocletian), Jesus’ word to Pergamos (Balaam/Nicolaitans), Augustine (Confessions & City of God; not first to use Trinity), and Patrick of Ireland.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 5: 10/10 (100%), 7m35s, attempt 101753 (cmid 1125). Essays Complete/Not graded. 1 attempt.", "summary": "Lesson 5 covers Smyrna (the Persecuted Church, 100–313) and Pergamos (the Worldly Church, 313–800). Around AD 100 John, the last surviving Apostle, dies. By 150 the Bible is not yet translated into German. Augustine was not the first theologian to use the term Trinity. Early Christians were committed to learning and advancement; dancing, drama, and instrumental music were not heavily embraced. In Justin Martyr’s early order of worship, the cup was not reserved only for presiding ministers. Ambrose of Milan wrote doctrinally pure hymns. Under Roman persecution the desert became a refuge for many seeking inner peace; persecution peaked under Diocletian. Jesus commended Pergamos for holding fast His name yet rebuked tolerance of Balaam and the Nicolaitans. Augustine of Hippo’s best-known works are Confessions and The City of God. Patrick is the patron saint of Ireland.", "bigIdeas": ["Around AD 100 John, the last surviving Apostle, dies.", "By 150 AD the Bible is NOT translated into German.", "Augustine was NOT the first theologian to use the term \"Trinity.\"", "Early Christians were committed to learning and advancement.", "Dancing, drama, and instrumental music were NOT heavily embraced by the early church.", "Justin Martyr’s order of worship: the cup was NOT given only to presiding ministers.", "Ambrose of Milan was known for writing doctrinally pure hymns.", "Because of Roman persecution, the desert became home for many searching for inner peace; severity peaked under Diocletian.", "Jesus to Pergamos: held fast His name where Satan’s throne was, yet rebuked Balaam/Nicolaitan compromise; repent.", "Augustine’s best-known works: Confessions and The City of God; Patrick is the patron saint of Ireland."], "takeaways": ["~100 AD John last Apostle dies; Bible NOT translated into German by 150 AD; Augustine NOT first to use Trinity.", "Early Christians committed to learning; dancing/drama/instrumental music NOT heavily embraced.", "Justin Martyr order: cup NOT only for ministers (False that only ministers got cup).", "Ambrose = doctrinally pure hymns; desert refuge under persecution; Augustine Confessions + City of God; Patrick = Ireland."], "glossary": [{"term": "Smyrna", "meaning": "The Persecuted Church epoch (100–313) — era of Roman persecution after the Apostolic age; refusal to sacrifice to Roman gods / emperor as divine fed hostility."}, {"term": "Pergamos", "meaning": "The Worldly / State Church epoch (313–800). Jesus commended holding fast His name where Satan’s throne was, yet rebuked Balaam and Nicolaitan tolerance."}, {"term": "John (last Apostle)", "meaning": "Around AD 100, John — the last surviving Apostle — dies (Quiz 5 True)."}, {"term": "Justin Martyr", "meaning": "Early Christian apologist whose order of worship shows bread and cup given to worshippers — not cup only to ministers."}, {"term": "Ambrose of Milan", "meaning": "Known for writing doctrinally pure hymns; his influence and Scripture reading helped lead Augustine to conversion."}, {"term": "Desert refuge", "meaning": "Under Roman persecution, the desert became home for many searching for inner peace."}, {"term": "Diocletian", "meaning": "Emperor under whom official persecution of the church reached its most severe form (essay on persecution 100–313)."}, {"term": "Balaam / Nicolaitans", "meaning": "False teachings Jesus rebuked at Pergamos — led toward idolatry, compromise, and immoral practices; He warned He would fight them with the sword of His mouth."}, {"term": "Augustine of Hippo", "meaning": "North African bishop (baptized 387); Confessions and The City of God; NOT the first to use the term Trinity; shaped church teaching for centuries."}, {"term": "Patrick", "meaning": "Patron saint of Ireland (Quiz 5 True)."}], "outline": ["Smyrna — The Persecuted Church (100–313)", "Why persecution — refusal of emperor cult; rumors; poor classes; faithful lives; decrees to Diocletian", "Pergamos — The Worldly Church (313–800)", "Jesus to Pergamos — hold fast His name; rebuke Balaam/Nicolaitans; repent; promise to overcomers", "~100 AD — John, last surviving Apostle, dies", "By 150 AD — Bible NOT yet translated into German", "Early Christians — committed to learning; cautious about dancing, drama, instrumental music", "Justin Martyr — early order of worship; bread and cup to worshippers", "Ambrose — doctrinally pure hymns; influence on Augustine", "Augustine — conversion 387; Confessions & City of God; Patrick — Ireland"], "mustKnow": [{"label": "Quiz 5", "value": "100% (10/10), 1 attempt, 7m35s, cmid 1125, attempt 101753"}, {"label": "John ~100 AD", "value": "Last surviving Apostle dies — True"}, {"label": "Bible / German by 150", "value": "Translated into German by 150 AD — False"}, {"label": "Augustine / Trinity", "value": "First to use term \"Trinity\" — False"}, {"label": "Learning", "value": "Early Christians committed to learning and advancement — True"}, {"label": "Dancing / drama / instruments", "value": "Heavily embraced by early church — False"}, {"label": "Justin Martyr cup", "value": "Cup only to presiding ministers — False"}, {"label": "Ambrose", "value": "Doctrinally pure hymns — True"}, {"label": "Desert / Diocletian", "value": "Desert refuge under persecution — True; most severe official form under Diocletian"}, {"label": "Augustine works", "value": "Confessions and The City of God — True; baptized 387; bishop of Hippo"}, {"label": "Patrick", "value": "Patron saint of Ireland — True"}], "compare": [{"title": "Smyrna vs Pergamos", "points": ["Smyrna (100–313): Persecuted Church — emperor cult refusal, rumors, decrees; desert refuge; peak under Diocletian", "Pergamos (313–800): Worldly / State Church — hold fast His name where Satan’s throne was, yet rebuke for Balaam/Nicolaitan compromise"]}, {"title": "Early worship practices", "points": ["Embraced: learning and advancement; doctrinally pure hymnody (Ambrose); Justin’s shared bread and cup", "Not heavily embraced: dancing, drama, instrumental music; separation from pagan entertainment fed pagan hostility"]}, {"title": "Augustine — what he is / is not", "points": ["Is: North African leader; baptized 387; Confessions and The City of God; shaped teaching for centuries", "Is NOT: the first theologian to use the term \"Trinity\""]}, {"title": "Quiz True vs False stems", "points": ["True: John dies ~100; committed to learning; Ambrose hymns; desert refuge; Augustine’s two great works; Patrick / Ireland", "False: German Bible by 150; Augustine first to say Trinity; dancing/drama/instruments heavily embraced; cup only to ministers"]}], "pulpit": ["Smyrna: the church was hated for confessing Jesus as Lord instead of the emperor — faithfulness under pressure shaped identity.", "Pergamos: hold fast His name where Satan’s throne is, yet repent of Balaam/Nicolaitan compromise — Jesus fights false teachers with the sword of His mouth.", "Worship that forms disciples: learning, shared table (Justin), and doctrinally pure song (Ambrose) — not spectacle.", "Augustine’s Confessions and City of God still preach grace and the two cities — without claiming he invented the Trinity.", "Patrick’s Ireland shows Gospel advance beyond the old empire’s center."], "quickReview": ["John dies ~100 (True); German Bible by 150 (False); Augustine first to use Trinity (False).", "Early Christians committed to learning (True); dancing/drama/instruments heavily embraced (False).", "Justin Martyr: cup only to ministers (False); Ambrose doctrinally pure hymns (True).", "Desert refuge under persecution (True); Diocletian = most severe; Augustine = Confessions + City of God (True); Patrick = Ireland (True).", "Epochs: Smyrna Persecuted 100–313; Pergamos Worldly 313–800 — Jesus rebuked Balaam/Nicolaitans; overcomers get manna, white stone, new name."], "quiz": [{"q": "Around 100 AD, John, the last surviving Apostle dies.", "answer": "True", "why": "Around AD 100 John, the last surviving Apostle, dies."}, {"q": "By 150 AD, the Bible is translated into German.", "answer": "False", "why": "By 150 AD the Bible is NOT translated into German."}, {"q": "Augustine was the first theologian to use the term, \"Trinity.\"", "answer": "False", "why": "Augustine was NOT the first theologian to use the term Trinity."}, {"q": "In the early church, those who became Christians were committed to learning and advancement.", "answer": "True", "why": "Early Christians were committed to learning and advancement."}, {"q": "Dancing, drama, and instrumental music were heavily embraced by the early church.", "answer": "False", "why": "Dancing, drama, and instrumental music were NOT heavily embraced."}, {"q": "In an early order of worship penned by Justin Martyr, the bread was given to the worshippers, but the cup was given only to the presiding ministers.", "answer": "False", "why": "The cup was NOT reserved only for ministers — False that only ministers got the cup."}, {"q": "Ambrose of Milan was known for writing doctrinally pure hymns.", "answer": "True", "why": "Ambrose of Milan wrote doctrinally pure hymns."}, {"q": "Because of the persecution by the Roman Emperor, the desert became home for many searching for inner peace.", "answer": "True", "why": "Under Roman persecution the desert became a refuge for many seeking inner peace."}, {"q": "Augustine of Hippo's best known works are probably his Confessions and The City of God.", "answer": "True", "why": "Augustine’s best-known works are Confessions and The City of God."}, {"q": "The patron saint of Ireland is Patrick.", "answer": "True", "why": "Patrick is the patron saint of Ireland."}], "essays": [{"theme": "Explain why the church was severely persecuted between 100 and 313 AD.", "summary": "The church was persecuted for several reasons. Christians refused to sacrifice to the Roman gods or honor the emperor as divine, and they confessed Jesus as Lord, which made Rome see them as a rival and an unlawful society. Their separation from pagan entertainment and practices also made them seem antisocial. Because believers met at night and called one another brothers and sisters, false rumors accused them of immorality, cannibalism, and other crimes. Many Christians came from the poor and dispossessed classes, so critics dismissed Christianity as a movement of the ignorant. Their faithful lives also convicted pagans of sin. These pressures, along with official hostility and repeated imperial decrees, led to persecution that reached its most severe official form under Diocletian."}, {"theme": "Explain what Jesus said to the church at Pergamos.", "summary": "Jesus commended the church at Pergamos for holding fast to His name even though it lived where Satan's throne was and where Antipas had been killed. However, He rebuked the church for tolerating people who followed the teaching of Balaam and the Nicolaitans. Those teachings led believers toward idolatry, compromise, and immoral practices. Jesus therefore called them to repent and warned that He would fight against the false teachers with the sword of His mouth. He promised hidden manna, a white stone, and a new name to those who overcame."}, {"theme": "Who was Augustine of Hippo and why was he important?", "summary": "Augustine of Hippo was a North African Christian leader, born to a Christian mother and a pagan father. He was highly educated in philosophy and rhetoric and taught rhetoric in Carthage, Rome, and Milan. The influence of Ambrose of Milan and his reading of Scripture led to his conversion; he was baptized in 387. He later became a priest and then bishop. Augustine was important because his Confessions and The City of God shaped Christian thinking and helped establish the direction of church teaching and practice for centuries. His writings also gave the church a deep testimony of grace and conversion."}]}, {"id": "ch1-6", "number": 6, "title": "Thyatira: The Medieval Church (800–1517)", "topic": "Thyatira the Medieval Church (800–1517) — Middle Ages from Rome’s fall (476); East/West split not immediately after the First Crusade; minimized Bible preaching (poor priest training); congregational singing not critically important (yet Francis emphasized it); Waldo, Wycliffe, Huss, and Savonarola as Reformation forerunners; by 1500 four of five original Christian stronghold cities under Islam.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 6: 9/10 (90%), 8m33s, attempt 101762 (cmid 1129). Essays Complete/Not graded. 1 attempt.", "summary": "Lesson 6 covers Thyatira — the Medieval Church (800–1517). The East/West split did not happen immediately after the First Crusade. Many date the Middle Ages from Rome’s fall in 476 and the collapse of the Roman Empire. Medieval preaching of the Bible was minimized because priests were poorly trained, and congregational singing was not a critically important part of worship — though Francis of Assisi did emphasize it. Peter Waldo was forbidden to preach by the Pope; John Wycliffe lived to see the Lollard revival; John Huss was burned for preaching the Bible; Savonarola was not burned like Huss. By 1500, four of the five original stronghold cities of Christianity were under Islam.", "bigIdeas": ["East/West Church split did NOT happen immediately after the First Crusade.", "Many consider the Middle Ages to begin when Rome fell in 476 (collapse of the Roman Empire).", "During the Medieval Period, Bible preaching was minimized due to poor priest training.", "Congregational singing was NOT a critically important part of Medieval worship.", "Francis of Assisi DID emphasize congregational singing (Quiz 6 miss if marked False).", "Peter Waldo, a committed layman, was forbidden to preach by the Pope.", "John Wycliffe lived to see the Lollard revival in England.", "John Huss was burned at the stake for preaching the Bible.", "Savonarola was NOT burned at the stake like Huss.", "By 1500, four of the five original stronghold cities of Christianity were controlled by Islam."], "takeaways": ["East/West split NOT immediately after First Crusade; Middle Ages begin with Rome fall 476.", "Medieval preaching minimized (poor priest training); congregational singing NOT critically important then.", "Francis DID emphasize congregational singing; Waldo forbidden to preach by Pope; Wycliffe lived to see Lollard revival.", "Huss burned for preaching Bible; Savonarola NOT burned like Huss; by 1500 four of five original stronghold cities under Islam."], "glossary": [{"term": "Thyatira", "meaning": "The Medieval Church epoch (800–1517) — era of Roman Catholic dominance, monastery/order revivals, and pre-Reformation reformers."}, {"term": "Middle Ages / 476", "meaning": "Many mark the beginning of the Middle Ages with Rome’s fall in 476 and the collapse of the Roman Empire (Quiz 6 True)."}, {"term": "East/West split", "meaning": "Division of Eastern and Western Churches — NOT immediately after the First Crusade (Quiz 6 False)."}, {"term": "Medieval preaching", "meaning": "Bible preaching minimized in the Medieval Period largely because priests were poorly trained (Quiz 6 True)."}, {"term": "Congregational singing", "meaning": "NOT critically important in Medieval worship overall (Quiz 6 False) — yet Francis of Assisi emphasized it (Quiz 6 True; common miss)."}, {"term": "Francis of Assisi", "meaning": "Founder of the Franciscans; emphasized congregational singing (Quiz 6 True — Moodle; miss if chose False)."}, {"term": "Peter Waldo", "meaning": "Committed layman forbidden by the Pope to preach; forerunner path toward Reformation (Quiz 6 True)."}, {"term": "John Wycliffe / Lollards", "meaning": "English reformer who lived to see the Lollard revival in England (Quiz 6 True)."}, {"term": "John Huss", "meaning": "Burned at the stake for preaching the Bible (Quiz 6 True); Reformation forerunner."}, {"term": "Savonarola", "meaning": "Florentine reformer — NOT burned at the stake like Huss (Quiz 6 False that he was burned like Huss)."}, {"term": "Stronghold cities / Islam by 1500", "meaning": "By 1500, four of the five original stronghold cities of Christianity were controlled by Islam (Quiz 6 True)."}], "outline": ["Thyatira — The Medieval Church (800–1517)", "Dating the Middle Ages — Rome falls 476; collapse of the Roman Empire", "East and West — split NOT immediately after the First Crusade", "Medieval worship — Bible preaching minimized (poor priest training)", "Congregational singing — not critically important overall; Francis emphasized it", "Francis of Assisi — congregational singing emphasis", "Peter Waldo — committed layman; forbidden to preach by the Pope", "John Wycliffe — lived to see the Lollard revival in England", "John Huss — burned at the stake for preaching the Bible", "Savonarola — NOT burned like Huss; by 1500 four of five stronghold cities under Islam"], "mustKnow": [{"label": "Quiz 6", "value": "90% (9/10), 1 attempt, 8m33s, cmid 1129, attempt 101762"}, {"label": "East/West after First Crusade", "value": "Split immediately after First Crusade — False"}, {"label": "Middle Ages begin", "value": "Rome fell 476 / Roman Empire collapse — True"}, {"label": "Medieval preaching", "value": "Minimized due to poor priest training — True"}, {"label": "Congregational singing (era)", "value": "Critically important in Medieval worship — False"}, {"label": "Francis of Assisi", "value": "Emphasized congregational singing — True (MISS if False)"}, {"label": "Peter Waldo", "value": "Forbidden to preach by the Pope — True"}, {"label": "John Wycliffe", "value": "Lived to see Lollard revival in England — True"}, {"label": "John Huss", "value": "Burned at the stake for preaching the Bible — True"}, {"label": "Savonarola", "value": "Burned at the stake like Huss — False"}, {"label": "Strongholds by 1500", "value": "Four of five original Christian stronghold cities under Islam — True"}], "compare": [{"title": "Congregational singing — era vs Francis", "points": ["Medieval period overall: congregational singing NOT critically important in worship (False stem)", "Francis of Assisi: DID emphasize congregational singing (True — Quiz 6 miss if chose False)"]}, {"title": "Huss vs Savonarola", "points": ["Huss: burned at the stake for preaching the Bible — True", "Savonarola: NOT burned like Huss — False that he was burned at the stake like Huss"]}, {"title": "Pre-Reformation forerunners", "points": ["Waldo: committed layman forbidden by the Pope to preach", "Wycliffe: lived to see Lollard revival; Huss burned for Bible preaching; Savonarola prepared the way without Huss’s same death"]}, {"title": "Quiz True vs False stems", "points": ["True: Middle Ages / 476; preaching minimized; Francis singing; Waldo forbidden; Wycliffe/Lollards; Huss burned; four of five cities under Islam", "False: East/West immediately after First Crusade; congregational singing critically important; Savonarola burned like Huss"]}], "pulpit": ["Thyatira / Medieval Church: when priest training fails, Bible preaching shrinks — recovery starts with the Word again.", "Francis and song: one reformer’s emphasis on congregational singing can outrun the era’s general neglect of the people’s voice in worship.", "Waldo: a committed layman forbidden by the Pope still shows that Gospel urgency will not stay locked in the clergy alone.", "Wycliffe and the Lollards: reformers sometimes live to see fruit; Huss shows the cost when Scripture is preached against power.", "By 1500 four of five original strongholds under Islam — church history is not only Western triumph; geography and fidelity both matter."], "quickReview": ["East/West split immediately after First Crusade (False); Middle Ages begin with Rome 476 (True).", "Medieval preaching minimized — poor priest training (True); congregational singing critically important (False).", "Francis emphasized congregational singing (True — MISS if False); Waldo forbidden by Pope (True).", "Wycliffe saw Lollard revival (True); Huss burned for Bible preaching (True); Savonarola burned like Huss (False).", "By 1500: four of five original Christian stronghold cities controlled by Islam (True). Epoch: Thyatira Medieval 800–1517."], "quiz": [{"q": "Immediately after the First Crusade, the Eastern and Western Churches split.", "answer": "False", "why": "The East/West split did NOT happen immediately after the First Crusade."}, {"q": "Many consider the beginning of the Middle Ages to be when Rome fell in 476 marking the collapse of the Roman Empire.", "answer": "True", "why": "Many date the Middle Ages from Rome’s fall in 476 and the collapse of the Roman Empire."}, {"q": "During the Medieval Period, the preaching of the Bible was minimized due to the poor training of the priests.", "answer": "True", "why": "Medieval Bible preaching was minimized because priests were poorly trained."}, {"q": "During the Medieval period, congregational singing became a critically important part of worship.", "answer": "False", "why": "Congregational singing was NOT a critically important part of Medieval worship."}, {"q": "Francis of Assisi emphasized congregational singing.", "answer": "True", "why": "Miss — Jay-R chose False. Moodle: True. Francis of Assisi emphasized congregational singing."}, {"q": "Peter Waldo, a committed layman, was forbidden to preach by the Pope.", "answer": "True", "why": "Peter Waldo was forbidden to preach by the Pope."}, {"q": "John Wycliffe lived to see the Lollard revival in England.", "answer": "True", "why": "John Wycliffe lived to see the Lollard revival in England."}, {"q": "John Huss was burned at the stake for preaching the Bible.", "answer": "True", "why": "John Huss was burned at the stake for preaching the Bible."}, {"q": "Savonarola, like Huss, was burned at the stake.", "answer": "False", "why": "Savonarola was NOT burned at the stake like Huss."}, {"q": "By 1500, four of the five original stronghold cities of Christianity were controlled by Islam.", "answer": "True", "why": "By 1500, four of the five original stronghold cities of Christianity were under Islam."}], "essays": [{"theme": "Describe the development of worship in the Roman Catholic Church during in Medieval times.", "summary": "Worship began with the simple services of the early Christians but gradually became a complex ceremony led by priests. Bible preaching was minimized because many priests were poorly trained, and services were conducted in Latin rather than the language of the people. Communion became mainly a priestly function; only the officiating priest received the bread and cup, and the emphasis was on Christ's death rather than the resurrection and Second Coming. Prayers increasingly asked God to receive help from the saints, while congregational singing was nearly eliminated. Gregorian chant, cantillation, antiphons, and hymns remained, but ordinary believers had little active participation."}, {"theme": "Describe the attempts to revive the Roman Catholic Church through the monasteries and religious orders?", "summary": "The Benedictine reform at Cluny was a major attempt to renew the Catholic Church. In 909 Duke William of Aquitaine gave Abbot Berno a charter for a monastery at Cluny that was free from outside control. Other Benedictine monasteries were reorganized on this model, and Cluny became known for financial integrity, discipline, and social reform. Francis of Assisi also sought renewal after his conversion, abandoning a pleasure-seeking life and embracing poverty and the gospel. The Franciscan order was formally established in 1210, and its brothers preached widely, even beyond Italy. These communities brought spiritual seriousness, reform, and gospel preaching back into the church."}, {"theme": "Who were Waldo, Wycliffe, Hus, and Savonarola? In what ways did they prepare the church for the coming Reformation?", "summary": "Peter Waldo was a wealthy merchant who gave up much of his wealth, wanted to preach the gospel, and helped form the Waldensian movement. The Waldensians valued the Bible in the people's own language, lay preaching, and the priesthood of all believers. John Wycliffe called the English church back to its biblical foundations, translated the Scriptures into English, and sent the Lollards to preach among the villages. John Hus preached a similar message in Bohemia, led reform, and was martyred for Christ. Girolamo Savonarola preached boldly against corruption in Florence, challenged both church and political leaders, and was eventually executed. Together they kept Scripture, gospel preaching, vernacular Bible translation, lay ministry, and moral reform before the church. Their witness exposed the need for renewal and prepared the way for the Reformation."}]}], "courseTotal": 98}, {"id": "theology-3", "code": 57, "title": "Survey of Theology 3", "status": "complete", "certificateUnlocked": true, "blurb": "BIB 205 — Lessons 1–6 complete. Certificate unlocked (cmid 2158). Course total 98%. Block 3 complete.", "lessons": [{"id": "th3-1", "number": 1, "title": "Prolegomena: Theologizing, Presuppositions, and Soteriology", "topic": "Theology starts with Prolegomena — how we gather truth, test it, and name our presuppositions before we speak of salvation.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 1: 10/10 (100%), 9m 30s, cmid 943 / attempt 101765. Essays Complete/Not graded. Certificate restricted (cmid 2158).", "summary": "Collecting data comes first in theologizing. The scientific method begins with a problem and is not identical to deduction. Everyone brings presuppositions; the Bible believer starts with God who has revealed Himself, while the liberal starts with mankind as pinnacle. Theology begins with Prolegomena. Salvation is not eschatology — it is both an instantaneous event and a progressive experience, studied as soteriology.", "bigIdeas": ["Collecting all data is the first step in theologizing / arriving at a doctrinal statement.", "The scientific method is not identical to the deductive method; it begins with a problem.", "The first verification test of theological truth is not cohesiveness.", "Everyone interprets with presuppositions.", "Bible believer’s first presupposition: there is a God who has revealed Himself to mankind.", "Theological liberal’s first presupposition: mankind is the pinnacle; reject higher beings including God.", "Theology begins with Prolegomena.", "Salvation is not called Eschatology — soteriology studies salvation as instantaneous event and progressive experience."], "takeaways": ["Collecting all data first step in theologizing; scientific method ≠ deductive; begins with a problem.", "First verification test is NOT cohesiveness; everyone has presuppositions.", "Bible believer first presupp: God revealed Himself; liberal first: mankind pinnacle, reject God.", "Theology begins with Prolegomena; Salvation is NOT Eschatology; salvation = instantaneous + progressive."], "glossary": [{"term": "Prolegomena", "meaning": "The starting point of theology — preliminary questions about method and how we know."}, {"term": "Scientific method (in theologizing)", "meaning": "Begins with a problem; not identical to the deductive method."}, {"term": "Presuppositions", "meaning": "Assumptions everyone brings when interpreting the Bible or the universe."}, {"term": "Bible believer’s first presupposition", "meaning": "There is a God, and He has revealed Himself to mankind."}, {"term": "Liberal’s first presupposition", "meaning": "Mankind is the pinnacle of the universe; rejects higher beings including God."}, {"term": "Soteriology", "meaning": "Doctrine of salvation (soteria + logos) — not eschatology."}, {"term": "Five verification tests", "meaning": "Consistency, practicality, relevance, adequacy, comprehensiveness."}, {"term": "Four aspects of salvation", "meaning": "Atonement, conversion, justification, sanctification — with past/present/future tenses."}], "outline": ["Theologizing: collect data first; scientific method begins with a problem", "Verifying theological truth (first test is not cohesiveness)", "Presuppositions: Bible believer vs theological liberal", "Theology begins with Prolegomena", "Soteriology defined: not eschatology; instantaneous + progressive", "Five tests; five biblical presuppositions; four aspects and three tenses of salvation"], "mustKnow": [{"label": "Quiz 1", "value": "100% (10/10), cmid 943, attempt 101765"}, {"label": "First step in theologizing", "value": "Collecting all data"}, {"label": "Scientific method", "value": "Begins with a problem; ≠ deductive method"}, {"label": "First verification test", "value": "Not cohesiveness"}, {"label": "Theology begins with", "value": "Prolegomena"}, {"label": "Salvation study", "value": "Soteriology (not Eschatology)"}, {"label": "Salvation shape", "value": "Instantaneous event + progressive experience"}, {"label": "Cert", "value": "Restricted (cmid 2158)"}], "compare": [{"title": "Bible believer vs theological liberal (first presupposition)", "points": ["Believer: God exists and has revealed Himself to mankind", "Liberal: mankind is the pinnacle; reject higher beings including God"]}, {"title": "Scientific method vs deductive method", "points": ["Scientific method begins with a problem", "Not identical to the deductive method of thinking"]}, {"title": "Soteriology vs Eschatology", "points": ["Soteriology = doctrine of salvation", "Salvation is not called Eschatology (Moodle False)"]}], "pulpit": ["Name your glasses before you preach your text — everyone starts with presuppositions.", "Collect the data first: doctrine is not a slogan race; it is patient gathering under Scripture.", "Salvation is both crisis and pilgrimage — justified in a moment, becoming like Christ over a lifetime.", "Start where theology starts: Prolegomena — how we know God has spoken."], "quickReview": ["Theologizing starts by collecting all data; scientific method begins with a problem (≠ deduction).", "First verification test is not cohesiveness; everyone has presuppositions.", "Believer: God revealed Himself; liberal: mankind pinnacle, reject God.", "Theology begins with Prolegomena; salvation = soteriology, not eschatology.", "Salvation: instantaneous + progressive; atonement, conversion, justification, sanctification."], "quiz": [{"q": "Collecting all data is the first step in the process of theologizing or arriving at a doctrinal statement.", "answer": "True", "why": "Data collection comes first in theologizing."}, {"q": "The scientific method is identical to the deductive method of thinking.", "answer": "False", "why": "Scientific method is not identical to deduction."}, {"q": "The scientific method begins with a problem.", "answer": "True", "why": "It begins with a problem."}, {"q": "The first test used to verify theological truth is cohesiveness.", "answer": "False", "why": "Cohesiveness is not the first verification test."}, {"q": "Everyone begins with assumptions or presuppositions when they interpret the Bible or universe.", "answer": "True", "why": "Everyone brings presuppositions."}, {"q": "The first presupposition of a Bible believer is that there is a God and that He has revealed Himself to mankind.", "answer": "True", "why": "God exists and has revealed Himself."}, {"q": "The first presupposition of a theological liberal is that mankind is the pinnacle of the universe. They reject the notion of any higher order of beings, including God.", "answer": "True", "why": "Liberal starts with mankind as pinnacle and rejects God."}, {"q": "Theology begins with Prolegomena.", "answer": "True", "why": "Prolegomena is the starting point."}, {"q": "The theology of Salvation is called Eschatology.", "answer": "False", "why": "Salvation is soteriology, not eschatology."}, {"q": "Salvation is both an instantaneous event progressive experience in the life of the believer.", "answer": "True", "why": "Instantaneous event and progressive experience (Moodle stem as given)."}], "essays": [{"theme": "Five tests used to verify theological truth", "summary": "The five tests I would use are consistency, practicality, relevance, adequacy, and comprehensiveness. Consistency asks whether the claims fit together without contradiction. Practicality asks whether the truth corresponds to reality and speaks meaningfully to life. Relevance distinguishes what is essential from what is incidental. Adequacy recognizes that theology has a firm center in God's historical and supernatural revelation in Christ, while not pretending to draw a rigid boundary around every question. Comprehensiveness requires a careful examination of all questions related to the subject, so that nothing important is ignored."}, {"theme": "Five presuppositions of the biblical believer", "summary": "The five presuppositions of the biblical believer are: (1) There is a God, and He has revealed Himself in the Bible. (2) There are laws that are absolute. (3) People can know things to the degree that they directly observe them. (4) Truth is not relative; it is consistent with itself and corresponds to reality. (5) The mind accepts what is logical and rejects what is illogical."}, {"theme": "Soteriology: definition, four aspects, and three tenses", "summary": "Soteriology is the doctrine or study of salvation, from the Greek words soteria (salvation) and logos (word, study, or doctrine). Its four aspects are atonement—the historical work Christ accomplished on the cross; conversion—the human experience of turning from sin to faith; justification—the non-experiential, legal declaration of righteousness before God; and sanctification—the continuing growth into Christlikeness in the new life with Christ. Salvation has three tenses: past, we have been saved from the guilt and penalty of sin; present, we are being saved from the habit and dominion of sin; and future, we will be saved from bodily infirmity and the effects of sin at Christ's return."}]}, {"id": "th3-2", "number": 2, "title": "What We Believe About Salvation", "topic": "Conversion and regeneration meet — human turning and divine new birth, with repentance, justification, adoption, and union with Christ.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 2: 10/10 (100%), 13m 18s, cmid 947 / attempt 101766. Essays Complete/Not graded.", "summary": "The plan of salvation does not begin with knowledge of God’s provision. Conversion is the human side; regeneration is the divine side. You must know both Bible content and the Person of the gospel. Emotional intensity does not make anyone “more saved.” Repentance is a change of mind; justification changes standing; regeneration uses the Spirit as agent and the Bible as instrument; adoption legally introduces sons; Paul’s “together” teaches union with Christ. Noah was not the first justified by faith.", "bigIdeas": ["First step in the plan of salvation is NOT knowledge of God’s provision.", "Conversion = human side; regeneration = divine side.", "Must know Bible content (doctrine) and the Person (Jesus Christ) of the gospel to be converted.", "Emotional experience does not make some people more saved than others.", "Repentance is essentially a change of mind.", "Justification changes position/standing before God.", "Noah was not the first person described as justified by faith.", "In regeneration: Holy Spirit = agent; Bible = instrument.", "Adoption is God’s legal introduction of sons into His family.", "Pauline “together” teaches union with Christ."], "takeaways": ["First step in plan of salvation is NOT knowledge of God’s provision; conversion = human side, regeneration = divine.", "Must know Bible content + Person of gospel; emotional experience doesn’t make some “more saved”.", "Repentance = change of mind; justification changes standing; Noah NOT first justified by faith; regeneration: Spirit agent, Bible instrument; adoption legal introduction of sons; Pauline “together” = union with Christ."], "glossary": [{"term": "Conversion", "meaning": "Human side of the salvation experience."}, {"term": "Regeneration", "meaning": "Divine side; Spirit is the agent, Bible the instrument."}, {"term": "Repentance", "meaning": "Essentially a change of mind."}, {"term": "Justification", "meaning": "Act changing standing/position before God."}, {"term": "Adoption", "meaning": "God’s method of legally introducing sons into His family."}, {"term": "“Together” (Pauline)", "meaning": "Expression teaching union with Christ."}], "outline": ["Plan of salvation — what is not the first step", "Conversion (human) and regeneration (divine)", "Doctrine + Person of the gospel; emotions and “more saved”", "Repentance, justification, regeneration’s agent/instrument", "Adoption and union with Christ (“together”)"], "mustKnow": [{"label": "Quiz 2", "value": "100% (10/10), cmid 947, attempt 101766"}, {"label": "First step?", "value": "Not knowledge of God’s provision"}, {"label": "Conversion / regeneration", "value": "Human side / divine side"}, {"label": "Gospel knowledge", "value": "Bible content + Person (Christ)"}, {"label": "Repentance", "value": "Change of mind"}, {"label": "Regeneration means", "value": "Spirit agent; Bible instrument"}, {"label": "Adoption", "value": "Legal introduction of sons"}, {"label": "“Together”", "value": "Union with Christ"}], "compare": [{"title": "Conversion vs regeneration", "points": ["Conversion: human side", "Regeneration: divine side"]}, {"title": "Emotional experience vs salvation status", "points": ["Emotions vary", "Nobody is “more saved” by emotional intensity"]}], "pulpit": ["Preach both the content and the Christ of the gospel — doctrine without a Person won’t convert.", "Repentance is a mind turned — not a mood managed.", "Hold justification and adoption together: new standing and a legal place in the family.", "Paul’s “together” words: salvation is union with Christ, not a private self-help project."], "quickReview": ["First step ≠ knowledge of God’s provision; conversion human, regeneration divine.", "Need Bible content + Person; emotions don’t make you more saved.", "Repentance = change of mind; justification changes standing.", "Regeneration: Spirit agent, Bible instrument; adoption legal; “together” = union.", "Noah was not the first justified by faith."], "quiz": [{"q": "The first step in the plan of salvation is the knowledge of God's provision.", "answer": "False", "why": "That is not the first step."}, {"q": "Conversion is the human side of that experience in which regeneration is the Divine side.", "answer": "True", "why": "Human conversion; divine regeneration."}, {"q": "It is imperative to know both the Bible content (doctrine) and the Person (Jesus Christ) of the gospel to be converted.", "answer": "True", "why": "Doctrine and Person both required."}, {"q": "Some people are more saved than others based upon their emotional experience.", "answer": "False", "why": "Emotions do not create degrees of being saved."}, {"q": "Repentance is essentially a change of mind.", "answer": "True", "why": "Change of mind."}, {"q": "Justification is an act whereby our position in a Heaven is changed and a man is given a new standing before God.", "answer": "True", "why": "New standing before God (Moodle stem as given)."}, {"q": "Noah was the first person in the Bible described as having been justified by faith.", "answer": "False", "why": "Noah was not the first so described."}, {"q": "In regeneration, the Holy Spirit is the agent, and the Bible is the instrument.", "answer": "True", "why": "Spirit agent; Bible instrument."}, {"q": "Adoption is the method of God for legally introducing sons into His family.", "answer": "True", "why": "Legal introduction of sons."}, {"q": "A Pauline expression teaching the doctrine of union with Christ is the word \"together.\"", "answer": "True", "why": "“Together” teaches union with Christ."}], "essays": [{"theme": "Explain the concept of repentance.", "summary": "Repentance is a genuine change of mind about sin that results in a change of heart and will. It means turning away from sin and turning toward God in faith and obedience. It is necessary for salvation, but repentance itself does not save; it prepares the sinner to receive Christ, and its reality is shown by a changed life."}, {"theme": "List and explain the seven \"together\" statements in Paul's writings concerning our union with Christ.", "summary": "Paul describes seven aspects of our union with Christ: (1) crucified together with Christ (Galatians 2:20)—my old life is judged and Christ lives in me; (2) died together with Christ (Colossians 2:20)—I have died to the world’s controlling principles; (3) buried together with Christ (Romans 6:4)—the old life is put away; (4) made alive together with Christ (Ephesians 2:5)—God gives spiritual life by grace; (5) raised together with Christ (Colossians 3:1)—I share His resurrection life and seek the things above; (6) suffer together with Christ (Romans 8:17)—I share His sufferings as an heir; and (7) glorified together with Christ (Romans 8:17)—I will share His future glory."}, {"theme": "Outline the four-fold plan of salvation.", "summary": "The four-fold plan of salvation is: (1) knowledge of the need for salvation—we recognize that all have sinned and fall short of God’s glory; (2) knowledge of the penalty of sin—sin deserves death; (3) knowledge of God’s provision—Christ took the sinner's punishment and died in our place; and (4) a personal response to the good news—we confess Jesus as Lord and believe in Him, receiving salvation by faith."}]}, {"id": "th3-3", "number": 3, "title": "Looking at Two Extremes", "topic": "Calvinism and Arminianism — TULIP, conditional salvation, and how Dort framed the debate.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 3: 10/10 (100%), 3m 37s, cmid 2398 / attempt 101768. Multi-choice only — no essays.", "summary": "Calvinism’s essential belief is summarized by TULIP; Arminians hold conditional salvation. The image of God grounds moral choice—repenting, turning, and believing. Total depravity means inability to please God. “Elect” refers to the corporate church or all believers. Dort condemned Arminius for conditional salvation (among other charges). Arminius taught a person becomes a sinner only when consciously and voluntarily sinning; salvation can be lost if the believer denies Calvary; confusing salvation and sanctification yields a “second work of grace.” Regeneration is God’s work.", "bigIdeas": ["Calvinism acronym: TULIP.", "Arminian belief about salvation: conditional salvation.", "Image of God → moral choice (repent, turn, believe).", "Total depravity = inability to please God.", "Elect = corporate church / all believers.", "Dort condemned Arminius for conditional salvation (plus experiential neglect of Calvary and wrong perfection).", "Arminius: man becomes a sinner only when he consciously and voluntarily sins.", "Arminian loss of salvation: if the believer denies the work of Calvary.", "Salvation/Sanctification confusion = second work of grace.", "Regeneration is God’s work."], "takeaways": ["Calvinism acronym TULIP; Arminian = conditional salvation.", "Image of God → moral choice (repent, turn, believe).", "Total depravity = inability to please God; elect = corporate church / all believers.", "Dort condemned Arminius for conditional salvation (+ experiential neglect of Calvary, wrong perfection).", "Arminius: man becomes sinner only when consciously/voluntarily sins; salvation lost if believer denies Calvary; Salvation/Sanctification confusion = second work of grace; Regeneration = God’s work."], "glossary": [{"term": "TULIP", "meaning": "Acronym expressing the essential belief of Calvinism."}, {"term": "Conditional salvation", "meaning": "Arminian view of salvation; also the other charge Dort condemned in Arminius."}, {"term": "Moral choice", "meaning": "Image-of-God power reflected in repenting, turning from sin, and believing."}, {"term": "Total depravity", "meaning": "Inability to please God."}, {"term": "Elect", "meaning": "Corporate church or all believers."}, {"term": "Council of Dort", "meaning": "Condemned Arminius (conditional salvation; experiential neglect of Calvary; wrong perfection)."}, {"term": "Second work of grace", "meaning": "Confusion of salvation and sanctification as sequential experiences."}, {"term": "Regeneration", "meaning": "God’s work."}], "outline": ["Two extremes: Calvinism (TULIP) and Arminianism (conditional salvation)", "Image of God and moral choice", "Total depravity and the meaning of elect", "Dort’s condemnation of Arminius", "Arminian anthropology, security, second work of grace", "Regeneration as God’s work"], "mustKnow": [{"label": "Quiz 3", "value": "100% (10/10), cmid 2398, attempt 101768 — multi-choice, no essays"}, {"label": "Calvinism", "value": "TULIP"}, {"label": "Arminian salvation", "value": "Conditional salvation"}, {"label": "Moral choice", "value": "Repent, turn, believe (image of God)"}, {"label": "Total depravity", "value": "Inability to please God"}, {"label": "Elect", "value": "Corporate church / all believers"}, {"label": "Dort", "value": "Condemned Arminius for conditional salvation (among others)"}, {"label": "Regeneration", "value": "God did the work"}], "compare": [{"title": "Calvinism vs Arminianism (as framed in this lesson)", "points": ["Calvinism: TULIP", "Arminian: conditional salvation; sinner only when consciously/voluntarily sins", "Loss: if believer denies Calvary; second work of grace when salvation/sanctification confused"]}, {"title": "Dort’s charges against Arminius", "points": ["Conditional salvation", "Experiential focus neglecting Calvary’s non-experiential accomplishment", "Wrong interpretation of perfection"]}], "pulpit": ["Name the extremes without caricaturing people — TULIP and conditional salvation are maps, not insults.", "Preach moral choice under the image of God: repent, turn, believe.", "Hold regeneration as God’s work even while calling sinners to respond.", "Don’t confuse being saved with growing holy — “second work” talk often mixes salvation and sanctification."], "quickReview": ["Calvinism = TULIP; Arminian = conditional salvation.", "Image of God → moral choice; total depravity = inability to please God.", "Elect = corporate church / all believers.", "Dort condemned Arminius for conditional salvation (+ other charges).", "Regeneration = God’s work; second work of grace = salvation/sanctification confusion."], "quiz": [{"q": "What acronym expresses the essential belief of Calvinism?", "answer": "TULIP", "why": "TULIP summarizes Calvinism’s essential belief."}, {"q": "What does the Arminian believe about salvation?", "answer": "Conditional salvation", "why": "Arminian view: conditional salvation."}, {"q": "The image of God gives people the power of choice. What kind of choice does reflect the repenting heart, turning from sin, and believing in God’s work of salvation?", "answer": "Moral Choice", "why": "Moral choice: repent, turn, believe."}, {"q": "What is the proper definition of total depravity?", "answer": "Inability to please God.", "why": "Total depravity = inability to please God."}, {"q": "What does the word “elect” mean refer to?", "answer": "Corporate Church or to all believers", "why": "Elect = corporate church / all believers (Moodle stem as given)."}, {"q": "Arminius was condemned by the council of Dort because he taught on the experiential aspect of salvation but neglected the non-experiential accomplishment of Calvary and wrong interpretation of perfection. What is the other one that Arminius taught?", "answer": "Conditional Salvation", "why": "Dort also condemned conditional salvation."}, {"q": "According to Arminius, a man becomes a sinner only when,", "answer": "He consciously and voluntarily sins", "why": "Only when he consciously and voluntarily sins."}, {"q": "One of the beliefs of the Arminian why salvation is lost?", "answer": "If the believer denies the work of Calvary", "why": "Lost if the believer denies Calvary."}, {"q": "Arminius confused between Salvation and Sanctification. It looks like one will go first and the other will follow. This experience is known as,", "answer": "Second work of grace", "why": "Called a second work of grace."}, {"q": "Who did the work of “Regeneration?”", "answer": "God", "why": "Regeneration is God’s work."}], "essays": []}, {"id": "th3-4", "number": 4, "title": "What We Believe About Sin", "topic": "The fall, imputed sin, and the three lusts — and why sin’s ruin meets the gospel’s remedy.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 4: 9/10 (90%), 7m 42s, cmid 955 / attempt 101769. Essays Complete/Not graded. Miss: Q6 (chose True; Moodle False — “cruse of Christ” stem).", "summary": "Adam was not unclear about God’s expectation. Eve was tempted in the lust of the flesh, eyes, and pride of life. The fall affected more than Adam and Eve alone; God is not powerless for allowing sin. All are involved with sin nature, imputation, and personal sin (Moodle: False that some only have nature/imputation without personal sin). Sin is act or attitude; Adam’s disobedience imputes sin, Christ’s death imputes righteousness to believers; sin’s influence reaches every part of human nature.", "bigIdeas": ["Adam was not unclear what God expected — that is not why he sinned.", "Eve was tempted in lust of the flesh, lust of the eyes, and pride of life.", "The garden was harmonious until they sinned; the fall did not affect only them.", "God was not shown to be less than all-powerful by allowing sin.", "Q6 miss: from God’s perspective stem about penalty evidenced by “cruse of Christ” is False (Moodle).", "False that some have nature + imputation but never commit personal sin.", "Sin can be defined as an act or an attitude.", "In Adam sin is imputed; in Christ righteousness is imputed to believers.", "Sin’s influence extends to every part of man’s nature.", "Gospel hope restores spiritually and promises resurrection."], "takeaways": ["Adam clear on expectation; Eve tempted in three lusts; garden harmony until sin; fall affects more than the first pair.", "God not less powerful for allowing sin; Q6 Moodle False on “cruse of Christ” penalty stem.", "Sin = act or attitude; imputation in Adam / righteousness in Christ; influence on every part of nature."], "glossary": [{"term": "Lust of the flesh", "meaning": "Good bodily desire turned against God’s command; remedy: self-control and submission."}, {"term": "Lust of the eyes", "meaning": "Attraction/ambition turned to coveting or control; remedy: contentment and obedience."}, {"term": "Pride of life", "meaning": "Self as center, wanting to be like God; remedy: humility and dependence on grace."}, {"term": "Imputed sin", "meaning": "In Adam’s disobedience, sin is imputed to all people."}, {"term": "Imputed righteousness", "meaning": "In Christ’s death, righteousness is imputed to all who believe."}, {"term": "Sin nature", "meaning": "All are born with a sin nature; Moodle rejects that some never commit personal sin."}], "outline": ["Eden’s clarity and harmony before the fall", "Eve’s three temptation areas", "Scope of the fall — not the first pair only", "God’s power, penalty, imputation, and definition of sin", "Physical and spiritual consequences; gospel hope", "Three lusts with results and remedies"], "mustKnow": [{"label": "Quiz 4", "value": "90% (9/10), cmid 955 — miss Q6"}, {"label": "Three lusts", "value": "Flesh, eyes, pride of life"}, {"label": "Fall’s scope", "value": "Not Adam and Eve only"}, {"label": "Sin defined", "value": "Act or attitude"}, {"label": "Imputation", "value": "Sin in Adam; righteousness in Christ to believers"}, {"label": "Influence", "value": "Every part of man’s nature"}, {"label": "Q6", "value": "Miss: chose True; Moodle False"}], "compare": [{"title": "In Adam vs in Christ (imputation)", "points": ["Adam’s disobedience: sin imputed to all", "Christ’s death: righteousness imputed to believers"]}, {"title": "Three lusts — desire, result, remedy", "points": ["Flesh → self-gratification → self-control / submission", "Eyes → coveting/control → contentment / obedience", "Pride of life → self-rule / alienation → humility / grace"]}], "pulpit": ["Sin is not only what we do — it is also what we want and how we posture before God.", "Preach both imputation stories: ruin in Adam, righteousness in Christ.", "Name the three lusts with their gospel remedies, not just their diagnoses.", "Flag the miss: the “cruse of Christ” stem is False on Moodle — study the exact wording."], "quickReview": ["Adam not unclear; Eve: flesh, eyes, pride of life; fall wider than the first pair.", "God not powerless for allowing sin; Q6 Moodle False.", "Sin = act or attitude; all sin nature + imputation + personal sin (Moodle).", "Adam imputes sin; Christ imputes righteousness to believers.", "Sin touches every part of nature; gospel restores and promises resurrection."], "quiz": [{"q": "Adam was unclear what God expected of him, therefore he sinned.", "answer": "False", "why": "Adam was not unclear about God’s expectation."}, {"q": "Eve was tempted in three areas, the lust of the flesh, the lust of the eyes and the pride of life.", "answer": "True", "why": "Three temptation areas."}, {"q": "God planted a beautiful garden where Adam and Eve lived in harmonious community with nature, God and each other: until they sinned.", "answer": "True", "why": "Harmony until the fall."}, {"q": "The fall of Adam and Eve only effectively influenced them, each a new child must face the temptation of sin to determine if they will live forever with God or be lost in punishment.", "answer": "False", "why": "The fall’s influence is not limited to Adam and Eve alone."}, {"q": "God was not all-powerful because He allowed sin to occur.", "answer": "False", "why": "Allowing sin does not mean God lacks all-power."}, {"q": "When view the fall of man from God’s perspective, sin demands a terrible penalty as evidenced by the cruse of Christ.", "answer": "False", "why": "Miss: chose True; Moodle False (stem as given, including “cruse”)."}, {"q": "All are born with a sin nature and have sin imputed to them, but not all commit personal sin.", "answer": "False", "why": "Moodle False — not a class that skips personal sin."}, {"q": "Sin can be defined as an act, or an attitude.", "answer": "True", "why": "Act or attitude."}, {"q": "In Adam’s disobedience, sin is imputed to all people, in Christ death, righteousness is imputed to all who believe on Him.", "answer": "True", "why": "Imputation in Adam and in Christ."}, {"q": "The influence of sin extends to every part of man’s nature.", "answer": "True", "why": "Every part of human nature."}], "essays": [{"theme": "How we can see sin in ordinary human life", "summary": "We can see sin in ordinary human life: everyone faces physical death, and people experience suffering and sickness. Even babies show an unlearned selfish desire. People are inclined to lie and can be motivated to harm one another. Sin also shows itself in guilt and shame, alienation from God, and a depraved desire that draws us toward further sin."}, {"theme": "Physical and spiritual consequences of the fall", "summary": "The fall brought physical and spiritual consequences to both Adam and Eve. Physically, death entered, the man would labor over a cursed ground and rule the creation with difficulty, while the woman would experience multiplied sorrow and pain in childbirth and a troubled relationship with her husband. Spiritually, both felt guilt and shame, were alienated from God, lost their positive inclination toward Him, and developed a depraved desire that drew them toward sin. The earth and animal world were also affected by divine judgment. The hope is God's grace and the gospel, which restore the spiritual condition and ultimately promise resurrection."}, {"theme": "Lust of the flesh, lust of the eyes, and pride of life", "summary": "The three expressions are the lust of the flesh, the lust of the eyes, and the pride of life. The lust of the flesh is a good bodily desire turned against God's command; its result is sinful self-gratification, and it is answered by self-control and submission to God's will. The lust of the eyes turns attraction and ambition into coveting, power-seeking, or control; its remedy is contentment, disciplined desire, and obedience. The pride of life makes the self the center, seeking independence and wanting to be like God; its result is self-rule and alienation, and its remedy is humility, dependence on God, and trust in His grace. Ultimately, the gospel is God's remedy for the ruin caused by sin."}]}, {"id": "th3-5", "number": 5, "title": "What We Believe About The Doctrine Of The Church", "topic": "The church as Christ’s body and stewardship — organism, assembly, and Great Commission.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 5: 10/10 (100%), 10m 56s, cmid 959 / attempt 101771. Essays Complete/Not graded.", "summary": "The church is an organism — the body of Christ — belonging to Christ, with embryonic truth in Scripture’s first reference. “Binding and loosing” are not uniformly understood by all believers. Dispensation means stewardship. “Church” has many popular meanings; the building analogy is not the most used; fold and flock are not identical. Theologically the church is an assembly of professing believers, and it ceases to be a church when it ceases the Great Commission.", "bigIdeas": ["Church is an organism (body of Christ), above business/social agencies.", "First Scripture reference contains embryonic truth of its development.", "The church belongs to Christ.", "“Binding and loosing” are not clearly understood the same way by all believers.", "Dispensation means stewardship.", "“Church” has many popular/generic meanings.", "Building is not the most used analogy for the church.", "Fold and flock are not identical in meaning in Scripture.", "Theologically: assembly of professing believers.", "Ceases to be a church when it ceases the Great Commission."], "takeaways": ["Organism / body of Christ; belongs to Christ; first reference embryonic.", "Binding/loosing not uniformly understood; dispensation = stewardship.", "Many popular meanings; building not top analogy; fold ≠ flock; assembly of professing believers; Great Commission essential."], "glossary": [{"term": "Organism (body of Christ)", "meaning": "Elevates the church above business and social agencies."}, {"term": "Dispensation", "meaning": "Means stewardship."}, {"term": "Binding and loosing", "meaning": "Not clearly understood the same way by all believers."}, {"term": "Fold vs flock", "meaning": "Not identical in meaning in Scripture."}, {"term": "Church (theological)", "meaning": "Assembly of professing believers."}, {"term": "Great Commission", "meaning": "A church ceases to be a church when it ceases to carry this out."}], "outline": ["Church as organism belonging to Christ", "First biblical reference and embryonic development", "Disputed and clarified terms: binding/loosing, dispensation, analogies", "Theological definition and Great Commission"], "mustKnow": [{"label": "Quiz 5", "value": "100% (10/10), cmid 959, attempt 101771"}, {"label": "Church nature", "value": "Organism — body of Christ; belongs to Christ"}, {"label": "Dispensation", "value": "Stewardship"}, {"label": "Theological definition", "value": "Assembly of professing believers"}, {"label": "Great Commission", "value": "Ceases to be a church without it"}, {"label": "Analogies", "value": "Building not most used; fold ≠ flock"}], "compare": [{"title": "Organism vs agencies", "points": ["Body of Christ", "Elevated above business and social agencies"]}, {"title": "Fold vs flock", "points": ["Not identical in meaning in Scripture"]}], "pulpit": ["Preach the church as Christ’s body, not a brand or club.", "Stewardship (dispensation) keeps the church accountable under Christ.", "A church without the Great Commission has lost what makes it a church.", "Don’t force “binding and loosing” into a consensus that Scripture and history don’t share uniformly."], "quickReview": ["Organism / body of Christ; belongs to Christ; first reference embryonic.", "Binding/loosing not uniform; dispensation = stewardship.", "Many meanings; building not top analogy; fold ≠ flock.", "Assembly of professing believers; cease Great Commission → cease being a church."], "quiz": [{"q": "The church is an organism (the body of Christ) which elevates it above the business and social agencies of our day.", "answer": "True", "why": "Organism — body of Christ."}, {"q": "The first reference to the church in Scripture contains the embryonic truth of its development.", "answer": "True", "why": "Embryonic truth in the first reference."}, {"q": "The church belongs to Christ.", "answer": "True", "why": "Belongs to Christ."}, {"q": "The terms, “binding and loosing,” are clearly understood truths embraced in the same way by all believers.", "answer": "False", "why": "Not uniformly understood by all believers."}, {"q": "The term “dispensation” means “stewardship.”", "answer": "True", "why": "Dispensation = stewardship."}, {"q": "The word “church” has many popular or generic meanings.", "answer": "True", "why": "Many popular meanings."}, {"q": "The picture of a building is the most used analogy for the church.", "answer": "False", "why": "Building is not the most used analogy."}, {"q": "The terms “fold” and “flock” are identical in meaning in the Scriptures.", "answer": "False", "why": "Fold and flock are not identical."}, {"q": "From the theological perspective, the church is an assembly of professing believers.", "answer": "True", "why": "Assembly of professing believers."}, {"q": "A church ceases to be a church when it ceases to carry out the Great Commission.", "answer": "True", "why": "Great Commission is essential."}], "essays": [{"theme": "Explain the meaning of the word, ‘church.’", "summary": "The word “church” comes from the Greek ekklesia, meaning an assembly of people who are called out. In the New Testament, believers are called out from the world and called together for God’s purpose. The word can refer to a local congregation, and in a broader sense to the universal body of all true believers in Christ. It is therefore not merely a building or a social organization, but a gathered people who belong to Jesus."}, {"theme": "What is meant in Scripture by the term, ‘keys?’", "summary": "The “keys” refer to the authority and responsibility Christ gives His servants to proclaim the gospel and open the way of salvation to people. Peter used these keys first among the Jews at Pentecost and then among the Gentiles in Cornelius’s house. They do not mean that a human leader controls heaven or forgives sins. The church announces God’s revealed truth; binding and loosing concern declaring what God forbids or permits according to Scripture, and proclaiming the result of the gospel."}, {"theme": "Define the church’s six functions, and explain each.", "summary": "The church has six main functions. First, it is an assembly of professing believers: Christians gather as a visible fellowship, while the church must also seek genuine faith in those who profess Christ. Second, it is the place where the unique presence of Jesus Christ dwells; He is the church’s life and light. Third, it lives under the authority of God’s Word, continuing in apostolic doctrine and accepting the discipline and correction of Scripture. Fourth, it is organized to carry out the Great Commission by preaching Christ, making disciples, baptizing, and teaching believers to obey Him. Fifth, it administers the two ordinances, baptism and the Lord’s Table; baptism pictures identification with Christ’s death, burial, and resurrection, while the Lord’s Table brings edification, fellowship, and self-examination. Sixth, it reflects spiritual gifts, with members and leaders serving one another and the mission of the church through the gifts God gives them."}]}, {"id": "th3-6", "number": 6, "title": "What We Believe About Church Function", "topic": "When the church began, how it is ordered, and what pastoral titles and Spirit-baptism views mean for church life.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 6: 9/10 (90%), 8m 45s, cmid 963 / attempt 101774. Essays Complete/Not graded. Course total 98%; certificate unlocked (cmid 2158). Miss: Q5 Jerusalem Council as embryonic denomination seed.", "summary": "Augustine articulated the universal church in The City of God; multiple views exist on when the church began. Towns does not review five kinds of church authority. Episcopal comes from “bishop.” Some see Acts 15 as the embryonic seed of a denomination (Q5 True — miss if False). NT churches were independent; the church is both organization and organism; elders are spiritually mature; seven pastoral titles; deacons do not run the church.", "bigIdeas": ["Universal church first articulated by Augustine in The City of God.", "Multiple views on when the church began.", "Towns does NOT review 5 kinds of church authority.", "Episcopal comes from the word meaning bishop.", "Jerusalem Council (Acts 15) seen by some as embryonic seed of a denomination (Q5 True).", "NT churches were independent.", "Church is both organization and organism.", "Elder = man of spiritual maturity.", "NT includes seven words describing a pastor.", "Bible does not teach that deacons run the church."], "takeaways": ["Augustine / City of God; multiple start-of-church views; Towns ≠ five authority kinds; episcopal = bishop.", "Acts 15 as denomination seed (Moodle True); NT independent churches; organization + organism.", "Elder maturity; seven pastoral titles; deacons do not run the church; five Spirit-baptism views."], "glossary": [{"term": "Universal church (Augustine)", "meaning": "First articulated in The City of God."}, {"term": "Episcopal", "meaning": "From the word meaning bishop."}, {"term": "Jerusalem Council (Acts 15)", "meaning": "Seen by some as embryonic seed of a denomination."}, {"term": "Elder", "meaning": "Man of spiritual maturity."}, {"term": "Organization and organism", "meaning": "The church is both."}, {"term": "Five Spirit-baptism views", "meaning": "Wesleyan; Keswick; Scofield/universal church; local-church/water baptism; Calvary/atonement."}], "outline": ["When the church began and the universal church", "Authority structures: episcopal, Acts 15, independence", "Organization and organism; elder maturity", "Seven pastoral titles; deacons’ role", "Five views of Spirit baptism"], "mustKnow": [{"label": "Quiz 6", "value": "90% (9/10), cmid 963 — miss Q5 Acts 15 denomination seed"}, {"label": "Course total", "value": "98%; certificate unlocked (cmid 2158)"}, {"label": "Universal church", "value": "Augustine, The City of God"}, {"label": "Episcopal", "value": "From “bishop”"}, {"label": "NT churches", "value": "Independent; organization + organism"}, {"label": "Deacons", "value": "Do not run the church"}, {"label": "Pastoral titles", "value": "Seven words in the NT"}], "compare": [{"title": "Five Spirit-baptism views", "points": ["Wesleyan: second work of grace / holy living (strong form: removes sin nature)", "Keswick (Rice/Torrey): distinct post-conversion power for holy living and service", "Scofield: at salvation into universal church / body of Christ", "Local-church / water baptism: Spirit baptism when placed into local church by baptism", "Calvary / atonement: identification with Christ’s death, burial, resurrection"]}, {"title": "Organization vs organism", "points": ["Church is both an organization and an organism"]}], "pulpit": ["Hold both: the church is living body and ordered household.", "Pastoral titles are one ministry seen from seven angles — maturity, oversight, shepherding, preaching, teaching, service, messenger.", "Name Spirit-baptism views carefully so people don’t fight straw men.", "Flag the miss: some do see Acts 15 as the embryonic seed of a denomination."], "quickReview": ["Augustine / City of God; multiple start views; Towns ≠ five authority kinds.", "Episcopal = bishop; Acts 15 denomination seed (True); NT churches independent.", "Organization + organism; elder maturity; seven pastoral titles; deacons don’t run the church.", "Five Spirit-baptism views; course 98%, cert unlocked."], "quiz": [{"q": "The concept of the universal church was first articulated by Augustine in his book, The City of God.", "answer": "True", "why": "Augustine in The City of God."}, {"q": "Multiple views exist concerning just when the church began.", "answer": "True", "why": "Multiple views on the church’s beginning."}, {"q": "Dr. Towns reviews 5 kinds of church authority.", "answer": "False", "why": "Towns does not review five kinds of church authority."}, {"q": "The title ‘episcopal’ comes from the word meaning ‘bishop.’", "answer": "True", "why": "Episcopal from bishop."}, {"q": "The Jerusalem Council (Acts 15) is seen by some as the embryonic seed of a denomination.", "answer": "True", "why": "Miss: chose False; Moodle True — some see Acts 15 as embryonic denomination seed."}, {"q": "Churches in the New Testament were independent.", "answer": "True", "why": "NT churches were independent."}, {"q": "The church is both an organization and an organism.", "answer": "True", "why": "Both organization and organism."}, {"q": "The ‘elder’ was to be a man of spiritual maturity.", "answer": "True", "why": "Elder = spiritual maturity."}, {"q": "The New Testament includes seven words describing a pastor.", "answer": "True", "why": "Seven pastoral words/titles."}, {"q": "The Bible teaches that Deacons are to run the church.", "answer": "False", "why": "Deacons are not taught to run the church."}], "essays": [{"theme": "Five views of Spirit baptism", "summary": "The lesson presents five main views. First, the Wesleyan view treats Spirit baptism as a second work of grace after salvation, setting the believer apart for holy living and, in its strongest form, removing the sin nature. Second, the Keswick view, associated with J. R. Rice and R. A. Torrey, also sees a distinct post-conversion work that gives the believer power for holy living and service. Third, the Scofield Reference Bible view says that at salvation the Holy Spirit places the believer positionally into the universal church, the body of Christ. Fourth, the local-church or water-baptism view says that Spirit baptism takes place when a believer is placed into a local church through water baptism. Fifth, the Calvary or atonement view sees Spirit baptism as identification with Christ’s body on the cross, including His death, burial, and resurrection."}, {"theme": "Five views of Spirit baptism (Moodle duplicate of Essay 11)", "summary": "The lesson presents five main views. First, the Wesleyan view treats Spirit baptism as a second work of grace after salvation, setting the believer apart for holy living and, in its strongest form, removing the sin nature. Second, the Keswick view, associated with J. R. Rice and R. A. Torrey, also sees a distinct post-conversion work that gives the believer power for holy living and service. Third, the Scofield Reference Bible view says that at salvation the Holy Spirit places the believer positionally into the universal church, the body of Christ. Fourth, the local-church or water-baptism view says that Spirit baptism takes place when a believer is placed into a local church through water baptism. Fifth, the Calvary or atonement view sees Spirit baptism as identification with Christ’s body on the cross, including His death, burial, and resurrection."}, {"theme": "Seven words/titles describing a pastor", "summary": "As an elder, the pastor must be spiritually mature and provide wise rule and care for the church. As a bishop, he is an overseer who carries chief responsibility for the church’s spiritual and administrative direction, without becoming authoritarian. As a pastor or shepherd, he cares for, feeds, guides, corrects, and protects Christ’s flock. As a preacher, he heralds God’s Word so that people are educated, exhorted, and comforted. As a teacher, he explains Scripture and feeds the flock with sound doctrine. As a servant, he leads humbly by serving the people rather than seeking status or control. As a messenger, he faithfully receives and delivers God’s message to the church. These titles describe one pastoral ministry from different angles: mature leadership, oversight, shepherding, proclamation, teaching, humble service, and faithful communication."}]}], "courseTotal": 98}, {"id": "acts", "code": 60, "title": "The Book of Acts", "status": "complete", "certificateUnlocked": false, "blurb": "BIB 304 / course 60 — Lessons 1–3 + Final Exam complete (exam 93.33%). Reading Reports & Written Project skipped. Course total 98%. Certificate not unlocked.", "lessons": [{"id": "acts-1", "number": 1, "title": "Introduction: Luke and the Book of Acts", "topic": "Luke’s two-volume work — authorship evidence, setting (~60–62), and the kingdom advancing through the gospel.", "quizScore": 95, "quizAttempts": 1, "status": "complete", "introCard": "Lesson 1: Quiz 1.1 90% · 1.2 100% · 1.3 100% · Cumulative 95% (19/20). One attempt each. No essays. Misses: 1.1 Q2 (Muratorian Fragment); Cumulative Q2 (kingdom comes slowly/in stages).", "quizWordingNote": "Some stems summarized from Jaira’s attempt-review notes when full Moodle wording was abbreviated in the pack.", "summary": "Acts is Luke’s second volume to Theophilus (and a wider church), written about 60–62 AD. Early testimony, manuscripts (including Papyrus 75), and we-passages support Lukan authorship even though Luke was not an apostle or eyewitness of Jesus’ earthly ministry. The kingdom expands as God grants salvation through the gospel — including Gentile blessing promised to Abraham.", "bigIdeas": ["Luke–Acts is a two-volume work (Theophilus + Acts as second document).", "Early writers attribute Luke/Acts to Luke; nobody seriously suggests another author.", "Evidence includes Anti-Marcionite Prologue, Muratorian Fragment, Papyrus 75, and first-person plural “we” passages.", "Luke was not an apostle / not an eyewitness of Jesus’ ministry; converted after the ascension; physician; sophisticated Greek.", "Acts written ~60–62 AD into the Roman Empire’s complex tolerance/oppression of Jews and Christians.", "Kingdom expands as God grants salvation to believers in Jesus; apostles spread the kingdom by preaching the gospel.", "OT prophecy: Gentiles blessed through Abraham — Acts records fulfillment."], "takeaways": ["Luke authorship (two-volume, early testimony, manuscripts, we-passages).", "Acts ~60–62; Theophilus + wider church.", "Kingdom advances via gospel/salvation including Gentiles."], "glossary": [{"term": "Muratorian Fragment", "meaning": "Early canon list supporting Lukan authorship (Quiz 1.1 Q2 correct answer)."}, {"term": "Papyrus 75", "meaning": "Important early manuscript witness connected to Luke in this lesson’s evidence set."}, {"term": "Anti-Marcionite Prologue", "meaning": "Early prologue evidence for Luke’s authorship."}, {"term": "We-passages", "meaning": "First-person plural sections suggesting the author traveled with Paul."}, {"term": "Theophilus", "meaning": "Named recipient; Acts is the second document in Luke’s two-volume project."}, {"term": "Kingdom of God (Acts)", "meaning": "Expands as God grants salvation; spread by gospel preaching."}], "outline": ["Authorship evidence for Luke–Acts", "Date, audience, and Roman setting (~60–62)", "Moses, creation, and kingdom themes connecting OT and Acts", "Cumulative review of Lesson 1"], "mustKnow": [{"label": "Quiz 1.1", "value": "90% — miss Q2 Muratorian Fragment (chose Papyrus 75)"}, {"label": "Quiz 1.2 / 1.3", "value": "100% / 100%"}, {"label": "Cumulative", "value": "95% (19/20) — miss Q2 kingdom comes slowly/in stages"}, {"label": "Date", "value": "~60–62 AD"}, {"label": "Audience", "value": "Theophilus + broader church"}, {"label": "Author", "value": "Luke — physician; not apostle/eyewitness; after ascension"}], "compare": [{"title": "Authorship evidence (Lesson 1.1)", "points": ["Anti-Marcionite Prologue", "Muratorian Fragment", "Papyrus 75", "We-passages / first-person plural", "Key writers attribute Luke; no rival author tradition"]}, {"title": "Kingdom timing (Cumulative miss)", "points": ["Missed: “When it begins, it will come quickly… distant future”", "Correct: “It will come slowly and in stages.”"]}], "pulpit": ["Preach Acts as volume two — same author, same Theophilus, same gospel advancing.", "The kingdom grows by salvation granted and gospel preached, not by political conquest alone.", "Gentile inclusion fulfills Abraham’s promise — Acts is OT hope arriving.", "Flag the misses: Muratorian Fragment for authorship evidence; kingdom comes slowly and in stages."], "quickReview": ["Luke–Acts two volumes; ~60–62; Theophilus + church.", "Evidence: prologues, Muratorian Fragment, P75, we-passages.", "Luke not apostle/eyewitness; physician; sophisticated Greek.", "Kingdom expands by gospel/salvation; Gentiles via Abraham promise.", "Misses: 1.1 Q2 Muratorian Fragment; Cumul Q2 slowly/in stages."], "quiz": [], "quizSections": [{"id": "1.1", "title": "Quiz 1.1", "score": 90, "attempts": 1, "quiz": [{"q": "Luke openly names himself as the author inside the text of Acts.", "answer": "False", "why": "Authorship is established by testimony and evidence, not a self-naming line in Acts (stem summarized from review; Moodle False)."}, {"q": "Which early witness is especially cited for Lukan authorship in this item?", "answer": "Muratorian Fragment", "why": "Miss: chose Papyrus 75; Moodle Muratorian Fragment."}, {"q": "Select early evidence connected to Luke’s authorship (as graded).", "answer": "Anti-Marcionite Prologue; Muratorian Fragment; Papyrus 75", "why": "Multi-select authorship evidence from the attempt review."}, {"q": "What narrative feature supports the author’s presence with Paul?", "answer": "First-person plural (“we”) passages", "why": "We-passages."}, {"q": "Which manuscript is named among the authorship/text witnesses in this quiz?", "answer": "Papyrus 75", "why": "Papyrus 75."}, {"q": "How do early writers treat Luke’s authorship?", "answer": "Several key writers attribute Luke and nobody suggests another author", "why": "Strong early attribution to Luke."}, {"q": "How does Acts relate to Luke’s first volume?", "answer": "Theophilus plus Acts as the second document", "why": "Two-volume project to Theophilus."}, {"q": "What similarities support Luke–Acts as a pair?", "answer": "Similar order, length, and years", "why": "Paired volumes."}, {"q": "What limitation of Luke is affirmed?", "answer": "Luke was not an apostle / not an eyewitness", "why": "Not an apostle or eyewitness of Jesus’ ministry."}, {"q": "When does Luke’s story connection to Jesus’ earthly ministry sit relative to the ascension?", "answer": "After Jesus’ ascension", "why": "Luke’s conversion/connection after the ascension (as graded)."}]}, {"id": "1.2", "title": "Quiz 1.2", "score": 100, "attempts": 1, "quiz": [{"q": "How did the Roman Empire relate to Judaism and Christianity in Acts’ setting?", "answer": "Tolerated Judaism and Christianity but oppressed believers", "why": "Tolerance mixed with oppression of believers."}, {"q": "To whom was Acts written?", "answer": "Written specifically to Theophilus and also a broader audience", "why": "Theophilus + wider church."}, {"q": "Acts addresses real pressures facing the early church.", "answer": "True", "why": "True (as graded)."}, {"q": "How did Christians relate to Jewish leaders’ commands?", "answer": "Christians respected Jewish leaders but would not obey commands contrary to God", "why": "Respect with God-first obedience."}, {"q": "Approximate date of Acts?", "answer": "60–62 AD", "why": "~60–62 AD."}, {"q": "Select challenges reflected in Acts (as graded).", "answer": "Persecution and imprisonment; Strife between Church and government; Doctrinal errors of false teachers", "why": "Multi-select pressures."}, {"q": "Acts is useful for understanding the church’s public witness under empire.", "answer": "True", "why": "True (as graded)."}, {"q": "Which Jewish historian is referenced in this lesson’s background?", "answer": "Josephus", "why": "Josephus."}, {"q": "What was a central Jewish response to Jesus in this framing?", "answer": "Jews rejected Jesus as Messiah", "why": "Messiah rejected."}, {"q": "The historical setting of Acts matters for reading its narrative.", "answer": "True", "why": "True (as graded)."}]}, {"id": "1.3", "title": "Quiz 1.3", "score": 100, "attempts": 1, "quiz": [{"q": "Moses’ promise of a coming figure is phrased as…", "answer": "“prophet like me”", "why": "Prophet like Moses."}, {"q": "How does Acts treat Moses in argumentation?", "answer": "Moses as a source of authority", "why": "Mosaic authority."}, {"q": "What doctrine is taught from the beginning of Scripture in this lesson’s link?", "answer": "Creation", "why": "Creation."}, {"q": "What do Luke–Acts and the OT share in the big story?", "answer": "Both teach creation, Fall, and redemption", "why": "Creation, Fall, redemption."}, {"q": "Messianic hope is tied to…", "answer": "David’s son", "why": "Davidic son."}, {"q": "A false claim about the kingdom (as graded False item).", "answer": "False", "why": "False item in the attempt review (exact stem abbreviated in pack)."}, {"q": "How does the kingdom expand in Acts?", "answer": "Kingdom expands as God grants salvation to believers in Jesus", "why": "Salvation granted → kingdom expands."}, {"q": "What kingdom is in view?", "answer": "Kingdom of God", "why": "Kingdom of God."}, {"q": "How do the apostles spread the kingdom?", "answer": "Apostles spread the kingdom by preaching the gospel", "why": "Gospel preaching."}, {"q": "How do Abraham’s promise and Acts relate?", "answer": "OT prophecy that Gentiles would be blessed through Abraham and Acts records fulfillment", "why": "Gentile blessing fulfilled."}]}, {"id": "cumul", "title": "Cumulative Lesson 1", "score": 95, "attempts": 1, "quiz": [{"q": "Groups with different Messiah expectations (as matched/reviewed).", "answer": "Zealots; Pharisees & Sadducees; Apocalyptic", "why": "Messiah-expectation groups from the attempt review."}, {"q": "How will the kingdom come (timing/manner)?", "answer": "It will come slowly and in stages.", "why": "Miss: chose “When it begins, it will come quickly, but will not begin until a date in the distant future”; Moodle “It will come slowly and in stages.”"}, {"q": "Moses functions as…", "answer": "A source of authority", "why": "Moses authority."}, {"q": "Athens / creation theme (as graded).", "answer": "Creation", "why": "Creation preaching link (Athens)."}, {"q": "When did Luke join Paul’s story?", "answer": "Luke joined Paul later", "why": "Joined later (we-passages)."}, {"q": "Background streams compared (as graded).", "answer": "Jewish theology / Early Christian / John the Baptist", "why": "Background comparison from review."}, {"q": "When was Luke converted relative to Jesus’ ministry?", "answer": "Luke converted after ascension", "why": "After the ascension."}, {"q": "Luke’s vocation?", "answer": "Physician", "why": "Physician."}, {"q": "Luke’s Greek style?", "answer": "Sophisticated Greek", "why": "Sophisticated Greek."}, {"q": "How do apostles spread the kingdom?", "answer": "Apostles spread the kingdom through the gospel", "why": "Gospel preaching."}, {"q": "A True item affirming Lesson 1 teaching (as graded).", "answer": "True", "why": "True (stem abbreviated in pack)."}, {"q": "How is David’s kingdom related to the Church’s expansion?", "answer": "David’s kingdom restored through Church expansion", "why": "Davidic hope and church expansion."}, {"q": "Does early Church evidence support Luke?", "answer": "Early Church evidence supports Luke", "why": "Supports Lukan authorship."}, {"q": "Select pressures on the church (as graded).", "answer": "Doctrinal errors; persecution; strife", "why": "Multi-select from review."}, {"q": "Kingdom expansion is tied to…", "answer": "Salvation of believers", "why": "Salvation of believers."}, {"q": "Luke’s addressee and volume structure?", "answer": "Theophilus + second document", "why": "Two volumes."}, {"q": "Key OT figures in the lesson’s argument?", "answer": "Abraham / David / Moses", "why": "Abraham, David, Moses."}, {"q": "Jewish response to Jesus as Messiah?", "answer": "Jews rejected Jesus", "why": "Rejection of Jesus as Messiah."}, {"q": "Shared biblical storyline?", "answer": "Both teach creation, Fall, and redemption", "why": "Creation, Fall, redemption."}, {"q": "Final True/affirmation item in the cumulative (as graded).", "answer": "True", "why": "True (stem abbreviated in pack)."}]}], "essays": [], "essayEmpty": "No essays", "essayEmptyDetail": "Acts Lesson 1 uses section quizzes + cumulative only (no Moodle essays)."}, {"id": "acts-2", "number": 2, "title": "Structure and Strategy in Acts", "topic": "Six geographic expansion periods — internal growth and external opposition — and Luke as a reliable, selective, teaching narrator.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Lesson 2: Quiz 2.1 100% · 2.2 100% · 2.3 90% · Cumulative 90% (18/20). Misses: 2.3 Q1 property sharing; Cumul Q14 70% not 90%; Q15 NT apostleship only.", "quizWordingNote": "Stems from Jaira attempt reviews for Quiz 2.1–2.3 and Cumulative Lesson 2.", "summary": "Acts Lesson 2 traces six geographical periods of expansion. Internal growth/tension and external growth/opposition reinforce each other. Luke writes a reliable, selective, episodic narrative that teaches implicitly. Pentecost is unique equipping; historical details are corroborated. Watch the misses: property-sharing context in other Acts homes; narrative percentage ~70% not 90%; apostleship limited to NT apostles who saw the risen Lord with a direct calling.", "bigIdeas": ["Six geographical periods of expansion structure Acts movement.", "Internal growth/tension and external growth/opposition reinforce one another.", "Luke = reliable, selective, episodic, implicitly teaching narrative.", "Pentecost is special/unique equipping.", "Historical details in Acts are corroborated.", "Miss 2.3 Q1: other Acts accounts show believers meeting in wealthy homes without sharing resources (not merely a persecution/famine exception).", "Cumul miss Q14: narrative percentage is 70%, not 90%.", "Cumul miss Q15: apostleship = only NT apostles who saw the risen Lord + direct calling (not a broader modern apostleship).", "Acts 1:8 order: Jerusalem → Judea → Samaria → ends of the earth; six geographical periods divided by summaries."], "takeaways": ["Six geographic expansion periods.", "Internal growth/tension + external growth/opposition reinforce.", "Luke = reliable selective episodic implicitly teaching narrative; Pentecost unique equipping; historical details corroborated."], "glossary": [{"term": "Six geographical periods", "meaning": "Expansion map of Acts used in this lesson."}, {"term": "Internal vs external growth", "meaning": "Growth/tension inside and growth/opposition outside reinforce each other."}, {"term": "Episodic selective narrative", "meaning": "Luke chooses episodes that teach implicitly while remaining historically reliable."}, {"term": "Pentecost (unique equipping)", "meaning": "Special equipping event in Acts opening movement."}, {"term": "Apostleship (NT)", "meaning": "Those who saw the risen Lord and received a direct calling — not a broader modern category (Cumul Q15)."}], "outline": ["Catechetical / didactic history and the role of speeches", "Six geographical expansion periods", "Internal growth/tension and external growth/opposition", "Luke narrative style: episodic, selective, implicit teaching", "Pentecost unique equipping; corroborated historical detail", "Misses to lock: property sharing; 70% narrative; NT apostleship"], "mustKnow": [{"label": "Quiz 2.1 / 2.2", "value": "100% / 100%"}, {"label": "Quiz 2.3", "value": "90% — miss Q1 property sharing / wealthy homes"}, {"label": "Cumulative L2", "value": "90% (18/20) — miss Q14 70% not 90%; Q15 NT apostleship only"}, {"label": "Geography", "value": "Six expansion periods"}, {"label": "Luke narrative", "value": "Reliable, selective, episodic, implicitly teaching"}], "compare": [{"title": "Internal vs external pressures", "points": ["Internal: growth and tension", "External: growth and opposition", "Together they reinforce the story of advance"]}, {"title": "Misses to remember", "points": ["2.3 Q1: wealthy homes without resource-sharing (not only persecution/famine exception)", "Cumul Q14: ~70% narrative, not 90%", "Cumul Q15: NT apostles who saw risen Lord + direct calling"]}], "pulpit": ["Map the six geographies so Acts does not feel like random travel stories.", "Preach both insides and outsides of growth — tension and opposition belong in the advance.", "Luke selects episodes that teach; preach the implicit lesson, not only the plot.", "Keep apostleship tethered to the risen Lord eyewitnesses and calling."], "quickReview": ["Six geographic periods; internal + external reinforce.", "Luke: reliable, selective, episodic, teaching narrative.", "Pentecost unique equipping; details corroborated.", "Misses: property sharing; 70% not 90%; NT apostleship only.", "Full quiz drill pending exact Moodle stems from Jaira."], "quiz": [], "quizSections": [{"id": "2.1", "title": "Quiz 2.1", "score": 100, "attempts": 1, "quiz": [{"q": "Which deed in Acts 13:7–12 supports the authority of the gospel?", "answer": "Elymas was blinded and the proconsul was convinced.", "why": "Miracle and conversion support gospel authority."}, {"q": "When was Paul allowed to speak as a prisoner?", "answer": "He was allowed when the ship was in danger.", "why": "Allowed to speak when the ship was in danger."}, {"q": "True or false? Luke edited the style and content of the speeches.", "answer": "False", "why": "He retained the speakers’ unique styles and content."}, {"q": "Acts is “_____ or didactic history.”", "answer": "catechetical", "why": "Catechetical or didactic history."}, {"q": "What authority did Luke include in Acts?", "answer": "speeches of apostles/prophets", "why": "Apostolic/prophetic speeches."}, {"q": "What was Luke’s purpose?", "answer": "reliable history plus gospel/kingdom teaching to Theophilus", "why": "History + teaching for Theophilus."}, {"q": "True or false? First-century writers often gave inaccurate speech reports.", "answer": "True", "why": "Often inaccurate speech reports in the century — Luke’s care stands out."}, {"q": "True or false? The title “first of the island” was used only by Luke.", "answer": "False", "why": "Not used only by Luke."}, {"q": "True or false? There are about 24 speeches in Acts, mostly by apostles, prophets, and leaders.", "answer": "True", "why": "About 24 speeches."}, {"q": "What is Acts’ focus?", "answer": "internal and external growth with tension and opposition", "why": "Internal/external growth with tension and opposition."}]}, {"id": "2.2", "title": "Quiz 2.2", "score": 100, "attempts": 1, "quiz": [{"q": "What marked Jerusalem’s internal growth?", "answer": "Holy Spirit outpouring at Pentecost", "why": "Pentecost outpouring."}, {"q": "What marked Judea/Samaria’s external growth?", "answer": "Paul’s conversion", "why": "Paul’s conversion."}, {"q": "What was Antioch’s internal tension?", "answer": "resistance to loosening dietary restrictions", "why": "Dietary restrictions tension."}, {"q": "Who evangelized Judea and Samaria?", "answer": "Philip", "why": "Philip."}, {"q": "How many were converted at Pentecost?", "answer": "3,000", "why": "3,000 converted."}, {"q": "What was Jerusalem’s internal tension?", "answer": "discrimination against Hellenistic widows", "why": "Hellenistic widows."}, {"q": "Who was the Gentile in Acts 10?", "answer": "Cornelius", "why": "Cornelius."}, {"q": "Which region was not evangelized by Paul?", "answer": "Egypt", "why": "Egypt not by Paul."}, {"q": "What internal growth came from Acts 15?", "answer": "Jerusalem Council removed the circumcision requirement", "why": "Circumcision requirement removed."}, {"q": "True or false? There was a rumor that Paul required Gentiles to keep Jewish laws.", "answer": "False", "why": "The rumor concerned Jewish believers abandoning traditions."}]}, {"id": "2.3", "title": "Quiz 2.3", "score": 90, "attempts": 1, "quiz": [{"q": "Why is sharing property not necessarily normative for the church?", "answer": "Other Acts accounts had believers meeting in wealthy homes without sharing resources.", "why": "Miss: chose special persecution/famine/poverty exception; Moodle: wealthy homes without sharing resources."}, {"q": "Meeting in homes — is it necessarily normative?", "answer": "Not necessarily normative; it was a custom related to persecution.", "why": "Persecution-related custom."}, {"q": "What does “episodic” mean?", "answer": "successive selection of smaller accounts", "why": "Episodic = successive smaller accounts."}, {"q": "Luke’s selectivity means…", "answer": "he selected history to fit his purposes", "why": "Selective for his purposes."}, {"q": "Feeding widows — normative for every church?", "answer": "good practice, not required for every church; special circumstances", "why": "Special circumstances, not universal requirement."}, {"q": "Pentecost — required manifestations today?", "answer": "special event equipping early believers; the same manifestations are not required today", "why": "Unique equipping event."}, {"q": "Argumentative vs narrative discourse", "answer": "direct vs indirect communication", "why": "Direct vs indirect."}, {"q": "Which has more argumentative discourse?", "answer": "epistles", "why": "Epistles."}, {"q": "Which has more narrative discourse?", "answer": "Gospels and Acts", "why": "Gospels and Acts."}, {"q": "Mark each correct about Luke’s narrative.", "answer": "The author is selective; It narrates in episodes; It teaches implicitly, not directly", "why": "All three correct."}]}, {"id": "cumul", "title": "Cumulative Lesson 2", "score": 90, "attempts": 1, "quiz": [{"q": "True or false? Paul was unable to preach freely in Rome.", "answer": "False", "why": "He was able to preach freely in Rome (False that he was unable)."}, {"q": "Acts is “_____ or didactic history.”", "answer": "catechetical", "why": "Catechetical."}, {"q": "Whom did Priscilla and Aquila instruct?", "answer": "Apollos", "why": "Apollos."}, {"q": "Meeting in homes — normative?", "answer": "Not necessarily normative; persecution custom", "why": "Persecution custom."}, {"q": "Acts 1:8 order", "answer": "Jerusalem → Judea → Samaria → “The ends of the earth”", "why": "1:8 expansion order."}, {"q": "True or false? First-century speech reports were inaccurate.", "answer": "True", "why": "Often inaccurate in the century."}, {"q": "What authority did Luke add?", "answer": "speeches of apostles/prophets", "why": "Speeches."}, {"q": "Rumor about Paul and Gentile laws", "answer": "False", "why": "Not that Paul required Gentiles to keep Jewish laws."}, {"q": "Critics’ view of Acts", "answer": "religious sentiment / “pious fiction”", "why": "Pious fiction charge."}, {"q": "Argumentative vs narrative", "answer": "direct vs indirect", "why": "Direct vs indirect."}, {"q": "Implicit teaching", "answer": "stories allowing indirect inference", "why": "Indirect inference from stories."}, {"q": "Structure of Acts", "answer": "six geographical periods divided by summaries", "why": "Six periods + summaries."}, {"q": "Acts 15 internal growth", "answer": "Council removed circumcision requirement", "why": "Circumcision requirement removed."}, {"q": "What percentage of Acts is narrative?", "answer": "70%", "why": "Miss: chose 90%; Moodle 70%."}, {"q": "Who are apostles?", "answer": "Only New Testament apostles existed, requiring seeing the resurrected Lord and direct calling", "why": "Miss: chose broader modern apostleship; Moodle NT apostles only (risen Lord + direct calling)."}, {"q": "Paul speaking as prisoner", "answer": "allowed when the ship was in danger", "why": "Ship in danger."}, {"q": "“First of the island” used only by Luke", "answer": "False", "why": "Not only by Luke."}, {"q": "More argumentative discourse", "answer": "epistles", "why": "Epistles."}, {"q": "Continuity in Acts", "answer": "same God, goal, gospel", "why": "Same God, goal, gospel."}, {"q": "Jerusalem internal growth", "answer": "Pentecost outpouring", "why": "Pentecost."}]}], "essays": [], "essayEmpty": "No essays", "essayEmptyDetail": "Acts uses section quizzes + cumulative (no Moodle essays)."}, {"id": "acts-3", "number": 3, "title": "Pentecost, Apostles, and Church Leadership", "topic": "Spirit power at Pentecost, what makes an apostle, and how the church learns to lead and delegate.", "quizScore": 95, "quizAttempts": 1, "status": "complete", "introCard": "Lesson 3: Quiz 3.1 100% · 3.2 100% · 3.3 100% (9/9) · Cumulative 95% (19/20). Miss: Cumul Q6 — James as Jerusalem church leader (chose True; Moodle False).", "quizWordingNote": "Stems from Jaira attempt reviews for Quiz 3.1–3.3 and Cumulative Lesson 3.", "summary": "Pentecost brings Spirit power for God’s will, miracles, and witness — tongues as known human languages — and begins a great harvest of salvation under Jeremiah’s new-covenant promise. Apostolic identity is tightly defined (risen Lord, divine appointment, taught by Jesus); there are no apostles today in that foundational sense. Church leadership includes elders/deacons without universal agreement on the offices, and the Jerusalem Council was not apostles-only.", "bigIdeas": ["OT Spirit power: bring God’s will to pass, miracles, witness.", "Pentecost tongues = unknown human languages; begins great harvest of salvation.", "Jeremiah: new covenant — law in minds and hearts.", "Kingdom comes as a long process in stages (not all at once).", "Apostolos = one who is sent; marks include signs/wonders/miracles; requirements: seen risen Lord, appointed by God, taught by Jesus.", "No apostles today — unique foundational role.", "Gospel channels: public speeches, dialogue, households, personal evangelism.", "Jerusalem Council not apostles-only; Acts 6 = daily food distribution; apostles/prophets = church foundation.", "Enter the kingdom through many hardships; false teachers would arise from Ephesians.", "Cumul miss: James was not the Jerusalem church leader (Moodle False)."], "takeaways": ["Pentecost: Spirit power, tongues as languages, harvest of salvation, new covenant.", "Apostleship tightly defined; no perpetual modern apostleship.", "Leadership: delegate, elders/deacons varied practice, Council shared decision; hardships and false teachers warned."], "glossary": [{"term": "Pentecost tongues", "meaning": "Miraculous ability to speak in an unknown human language."}, {"term": "Apostolos", "meaning": "One who is sent."}, {"term": "Apostolic requirements", "meaning": "Seen the risen Lord; appointed by God; taught by Jesus."}, {"term": "Mark of an apostle", "meaning": "Signs, wonders, and miracles."}, {"term": "Jerusalem Council", "meaning": "Decision not by apostles only."}, {"term": "Acts 6", "meaning": "Daily distribution of food — delegated service."}, {"term": "Tyrannus hall", "meaning": "Ephesus preaching location."}], "outline": ["Spirit power, Pentecost, and kingdom timing", "Jewish expectation vs progressive kingdom", "What an apostle is — and is not", "Confirming strategies and gospel channels", "Church offices, Council, hardships, and false teachers"], "mustKnow": [{"label": "Quiz 3.1 / 3.2 / 3.3", "value": "100% / 100% / 100% (9/9)"}, {"label": "Cumulative", "value": "95% — miss Q6 James as Jerusalem leader (False)"}, {"label": "Tongues", "value": "Unknown human language"}, {"label": "Apostles today", "value": "No — unique foundational role"}, {"label": "Acts 6", "value": "Daily food distribution"}, {"label": "Kingdom entry", "value": "Through many hardships"}], "compare": [{"title": "Kingdom timing", "points": ["Not: Messiah all at once and suddenly", "Yes: long process in stages"]}, {"title": "Apostles then vs now", "points": ["Then: seen risen Lord, appointed by God, taught by Jesus; signs/wonders", "Now: no longer have apostles in that foundational sense"]}], "pulpit": ["Preach Pentecost as harvest beginning under a new-covenant heart, not a circus of phenomena.", "Keep apostleship historical and foundational — Christ still sends workers without reinventing the Twelve.", "Delegation in Acts 6 protects the Word and the widows.", "Flag the miss: James’s death wakes the church; he is not framed as Jerusalem’s standing leader on that item."], "quickReview": ["Spirit power: will, miracles, witness; tongues = human languages; harvest begins.", "Apostle = sent; requirements + signs; none today in that sense.", "Council not apostles-only; Acts 6 food; foundation = apostles/prophets.", "Hardships; false teachers from Ephesus; Cumul miss: James ≠ Jerusalem leader."], "quiz": [], "quizSections": [{"id": "3.1", "title": "Quiz 3.1", "score": 100, "attempts": 1, "quiz": [{"q": "Spirit power in the OT includes…", "answer": "power to bring God's will to pass, power to perform miracles, and power to witness", "why": "Will, miracles, witness."}, {"q": "Tongues at Pentecost", "answer": "miraculous ability to speak in an unknown human language", "why": "Unknown human language."}, {"q": "Pentecost began the…", "answer": "great harvest of salvation", "why": "Harvest of salvation."}, {"q": "Jeremiah’s promise", "answer": "new covenant when the law would be in the minds and hearts of God's people", "why": "New covenant — law in mind and heart."}, {"q": "Kingdom timing correction", "answer": "Not all at once and suddenly — a long process in stages", "why": "Progressive kingdom in stages."}, {"q": "Peter modified Joel slightly", "answer": "True", "why": "Peter modified Joel slightly."}, {"q": "Jewish Messiah expectation", "answer": "restore Israel politically…center of God's kingdom…spiritual blessings of eternal life", "why": "Political restoration + spiritual blessings."}, {"q": "Ephesus believers (Acts 19 setting in this lesson)", "answer": "only followers of John the Baptist…needed to become followers of Christ", "why": "John’s followers needing Christ."}, {"q": "Peter was not educated / a great speaker", "answer": "True", "why": "True as graded."}, {"q": "Samaria/Caesarea significance", "answer": "first time Gentiles were converted in significant numbers…expansion across ethnic borders", "why": "Gentile expansion across ethnic borders."}]}, {"id": "3.2", "title": "Quiz 3.2", "score": 100, "attempts": 1, "quiz": [{"q": "Paul considered himself the…", "answer": "least", "why": "Least of the apostles."}, {"q": "Mark of an apostle", "answer": "signs, wonders and miracles", "why": "Signs, wonders, miracles."}, {"q": "Confirming strategies (select all)", "answer": "history; nature and things observed even by pagans; Scripture; personal experience; signs and wonders; their loyalty to Christ", "why": "All listed strategies."}, {"q": "Paul did not meet apostolic requirements", "answer": "False", "why": "Paul did meet the requirements."}, {"q": "Gamaliel’s advice", "answer": "Leave them alone; if this is of man, it will fail, and if it is of God, we cannot stop it", "why": "Gamaliel’s counsel."}, {"q": "Ephesus preaching location", "answer": "The lecture hall of Tyrannus", "why": "Tyrannus hall."}, {"q": "Apostolic requirements (select all)", "answer": "seen the risen Lord; appointed by God; taught by Jesus", "why": "All three."}, {"q": "Apostolos means…", "answer": "one who is sent", "why": "Sent one."}, {"q": "Apostles today", "answer": "no longer have apostles…taught by Jesus…unique foundational role", "why": "No apostles today in that sense."}, {"q": "Gospel channels (select all)", "answer": "public speeches; dialogue; households; personal evangelism", "why": "All four channels."}]}, {"id": "3.3", "title": "Quiz 3.3", "score": 100, "attempts": 1, "quiz": [{"q": "Jerusalem Council decision only by apostles", "answer": "False", "why": "Not apostles-only."}, {"q": "Acts 6 task", "answer": "daily distribution of food", "why": "Daily food distribution."}, {"q": "All churches agree on elders/deacons", "answer": "False", "why": "Not universal agreement."}, {"q": "Apostles/prophets are the Church’s…", "answer": "foundation", "why": "Foundation."}, {"q": "Event making apostles aware some would die", "answer": "Herod killed the apostle James", "why": "James killed by Herod."}, {"q": "Enter the kingdom through many…", "answer": "hardships", "why": "Many hardships."}, {"q": "False teachers would arise from the Ephesians", "answer": "True", "why": "From among them."}, {"q": "Why delegate gospel preaching", "answer": "not enough people and they would not live long enough", "why": "Capacity and mortality."}, {"q": "Apostles’ primary ongoing emphasis in this item", "answer": "teaching", "why": "Apostles’ teaching."}]}, {"id": "cumul", "title": "Cumulative Lesson 3", "score": 95, "attempts": 1, "quiz": [{"q": "Apostles/prophets are the Church’s…", "answer": "foundation", "why": "Foundation."}, {"q": "Jewish Messiah expectation", "answer": "restore Israel politically; center of God’s kingdom; spiritual blessings of eternal life", "why": "Political + spiritual hope."}, {"q": "Paul/Barnabas and elders", "answer": "Paul/Barnabas appointed elders", "why": "Appointed elders."}, {"q": "Tongues at Pentecost", "answer": "unknown human language", "why": "Human language."}, {"q": "Why delegate preaching", "answer": "not enough people / would not live long enough", "why": "Capacity and mortality."}, {"q": "James was Jerusalem church leader", "answer": "False", "why": "Miss: chose True; Moodle False."}, {"q": "Acts 6 task", "answer": "daily distribution of food", "why": "Food distribution."}, {"q": "Council decision apostles-only?", "answer": "False", "why": "Not apostles-only."}, {"q": "Apostles today?", "answer": "no apostles today (foundational / taught by Jesus)", "why": "No longer have apostles in that sense."}, {"q": "Two offices (elders/deacons) universal agreement?", "answer": "False", "why": "Not all churches agree."}, {"q": "Kingdom timing", "answer": "progressive — long process in stages", "why": "In stages."}, {"q": "How apostles are distinguished", "answer": "perpetual office / special authority (unique foundational role)", "why": "Special foundational authority."}, {"q": "Ephesus believers", "answer": "followers of John the Baptist needing Christ", "why": "John’s followers."}, {"q": "Jeremiah promise", "answer": "new covenant — law in minds and hearts", "why": "New covenant."}, {"q": "Gamaliel’s advice", "answer": "Leave them alone; if of man it fails, if of God cannot stop it", "why": "Gamaliel."}, {"q": "Apostolic mark", "answer": "signs, wonders and miracles", "why": "Signs and wonders."}, {"q": "Pentecost associations", "answer": "Passover / harvest / law themes as taught", "why": "Harvest/salvation framing."}, {"q": "Confirming strategies", "answer": "history; nature; Scripture; experience; signs; loyalty to Christ", "why": "All strategies."}, {"q": "Samaria / Caesarea / Ephesus unique notes", "answer": "Gentile expansion / ethnic borders; Ephesus John’s followers", "why": "Unique expansion moments."}, {"q": "Enter the kingdom through many…", "answer": "hardships", "why": "Hardships."}]}], "essays": [], "essayEmpty": "No essays", "essayEmptyDetail": "Acts uses section quizzes + cumulative (no Moodle essays)."}, {"id": "acts-final", "number": 4, "title": "Final Exam", "topic": "Course-wide review of Luke–Acts authorship, structure, Pentecost, apostleship, and church life — with the five flagged misses locked in.", "quizScore": 93.33, "quizAttempts": 1, "status": "complete", "introCard": "Final Exam: 56/60 (93.33%), 33m 11s, attempt 101816 / cmid 1046. Course total 98%. Reading Reports & Written Project: no attempt — course not marked complete; cert not unlocked. Folded misses only (other 55 stems not invented).", "quizWordingNote": "Only miss/flagged items folded from Jaira’s review. Remaining correct items overlap L1–L3 packs — open those lesson drills for full stems. Score 56/60; five items flagged below (multi-select/partial may explain count).", "summary": "Final exam 93.33% (56/60). Course total sits at 98% with Reading Reports and Written Project still untouched. Study the flagged misses: early-church problem set; Luke did not merely edit speech style while keeping content; James did not lead the Jerusalem church on that item; confirming strategies include loyalty to Christ (not logic/debate); apostles distinguished by perpetual office and special Church authority.", "bigIdeas": ["Final: 56/60 (93.33%); course total 98% with Reports/Project open.", "Early Church problems (Moodle): Strife between Church and government; Persecution and imprisonment; Doctrinal errors of false teachers.", "Luke did NOT merely edit speeches’ style without major content changes (False).", "James did NOT lead the Jerusalem church (False) — same miss pattern as Lesson 3 cumulative.", "Message-confirming strategies: loyalty to Christ, personal experience, nature, signs, Scripture, history — not logic/reasoned debate.", "Apostles distinguished: appointed to perpetual office and given special Church authority."], "takeaways": ["Final 93.33%; course 98%; Reports/Project undecided.", "Lock the five flagged Moodle answers before any retake mindset.", "Overlap with L1–L3: authorship, structure, Pentecost, apostleship, leadership."], "glossary": [{"term": "Early Church problems (final)", "meaning": "Strife with government; persecution/imprisonment; doctrinal errors of false teachers."}, {"term": "Speech reports (Luke)", "meaning": "Moodle False that Luke only edited style without major content changes."}, {"term": "Confirming strategies", "meaning": "Loyalty to Christ; personal experience; nature; signs; Scripture; history."}, {"term": "Apostolic distinction (final wording)", "meaning": "Appointed to perpetual office and given special Church authority."}], "outline": ["Score and open assignments", "Flagged misses Q3, Q36, Q46, Q50, Q60", "Review path: Lesson 1–3 drills for the other 55"], "mustKnow": [{"label": "Final", "value": "93.33% (56/60), cmid 1046, attempt 101816"}, {"label": "Course total", "value": "98% — Reports/Project not attempted; cert locked"}, {"label": "Q3", "value": "Strife / persecution & imprisonment / doctrinal errors"}, {"label": "Q36", "value": "False — Luke did not only edit speech style"}, {"label": "Q46", "value": "False — James did not lead Jerusalem church"}, {"label": "Q50", "value": "Loyalty to Christ (not logic) + experience + nature + signs + Scripture + history"}, {"label": "Q60", "value": "Perpetual office + special Church authority"}], "compare": [{"title": "Chosen vs Moodle — early Church problems", "points": ["Chose: Famine + Persecution + Doctrinal errors", "Moodle: Strife between Church and government; Persecution and imprisonment; Doctrinal errors of false teachers"]}, {"title": "Chosen vs Moodle — apostles distinguished", "points": ["Chose: taught by Jesus and saw risen Lord", "Moodle: appointed to perpetual office and given special Church authority"]}], "pulpit": ["Use the miss list as a short catechism drill before you preach Acts’ church-under-pressure themes.", "Hold Luke’s speech fidelity carefully — he is not a modern paraphraser in Moodle’s framing.", "Apostleship language on the final emphasizes office and authority, not only eyewitness credentials."], "quickReview": ["Final 56/60; course 98%; Reports/Project open.", "Problems: strife, persecution/imprisonment, false teachers’ doctrine.", "Speeches: not “style-only” edit (False).", "James ≠ Jerusalem leader (False).", "Confirm with loyalty to Christ — not logic debate.", "Apostles: perpetual office + special authority."], "quiz": [], "quizSections": [{"id": "final", "title": "Final Exam — flagged misses", "score": 93.33, "attempts": 1, "quiz": [{"q": "Early Church problems (select all that apply). (Q3)", "answer": "Strife between Church and government; Persecution and imprisonment; Doctrinal errors of false teachers", "why": "Miss: chose Famine + Persecution + Doctrinal errors; Moodle wants strife with government, persecution/imprisonment, and doctrinal errors of false teachers."}, {"q": "Luke edited the speeches’ style without major content changes. (Q36)", "answer": "False", "why": "Miss: chose True; Moodle False."}, {"q": "James led the Jerusalem church. (Q46)", "answer": "False", "why": "Miss: chose True; Moodle False — same miss theme as Lesson 3 cumulative."}, {"q": "Message-confirming strategies (select all that apply). (Q50)", "answer": "loyalty to Christ; personal experience; nature; signs and wonders; Scripture; history", "why": "Miss/partial: included logic/reasoned debate; Moodle wants loyalty to Christ (not logic) plus personal experience, nature, signs, Scripture, and history."}, {"q": "How are apostles distinguished? (Q60)", "answer": "appointed to perpetual office and given special Church authority", "why": "Miss: chose taught by Jesus and saw risen Lord; Moodle: perpetual office + special Church authority."}]}], "essays": [], "essayEmpty": "No essays", "essayEmptyDetail": "Final exam only — no Moodle essays."}, {"id": "acts-reading", "number": 5, "title": "Reading Reports", "topic": "Skipped — no report content.", "quizScore": null, "quizAttempts": 0, "status": "skipped", "introCard": "Skipped permanently per Jay-R — no Reading Reports invented or submitted (cmid 1049).", "summary": "Reading Reports assignment skipped. Quizzes and Final Exam stand as the completed Acts study path.", "bigIdeas": [], "takeaways": ["Assignment cmid 1049 (instructions 1048) — Reading Reports not attempted on Moodle.", "Jay-R skipped permanently. No reports invented. Quizzes + Final Exam stand as completed work (course total 98%)."], "glossary": [], "outline": [], "mustKnow": [], "compare": [], "pulpit": [], "quickReview": [], "quiz": [], "quizSections": [], "essays": [], "essayEmpty": "Skipped", "essayEmptyDetail": "No reading reports invented.", "quizEmpty": "Skipped", "quizEmptyDetail": "Reading Reports left unattempted on Moodle; marked skipped on the study site by Jay-R’s decision."}, {"id": "acts-project", "number": 6, "title": "Written Project", "topic": "Skipped — no project content.", "quizScore": null, "quizAttempts": 0, "status": "skipped", "introCard": "Skipped permanently per Jay-R — no Written Project invented or submitted (cmid 1052).", "summary": "Written Project assignment skipped. Quizzes and Final Exam stand as the completed Acts study path.", "bigIdeas": [], "takeaways": ["Assignment cmid 1052 (instructions 1051) — Written Project not attempted on Moodle.", "Jay-R skipped permanently. No project invented. Quizzes + Final Exam stand as completed work (course total 98%)."], "glossary": [], "outline": [], "mustKnow": [], "compare": [], "pulpit": [], "quickReview": [], "quiz": [], "quizSections": [], "essays": [], "essayEmpty": "Skipped", "essayEmptyDetail": "No written project invented.", "quizEmpty": "Skipped", "quizEmptyDetail": "Written Project left unattempted on Moodle; marked skipped on the study site by Jay-R’s decision."}], "courseTotal": 98}, {"id": "apologetics-2", "code": 65, "title": "Apologetics 2", "status": "complete", "certificateUnlocked": true, "blurb": "BIB 222 / course 65 — Continues Apologetics 1 as Lessons 7–12. Complete: L7–L12 full Q&A + essays. Course total 98%; certificate unlocked (cmid 2164). DOCX workbooks.", "lessons": [{"id": "ap2-7", "number": 7, "title": "Logical Proofs That Jesus Is God", "topic": "Jesus’ claims, worship, messianic fulfillment, and the virgin birth — proofs of deity that do not make a claim true merely by being spoken.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 7: 10/10 (100%), cmid 1185 / attempt 101991. Essays Complete/Not graded. Certificate restricted (cmid 2164). DOCX workbooks.", "summary": "A claim to be God is not true merely because it is claimed. Jesus claimed to forgive sins; NT authors ascribe creation to Him; worship given to and accepted by Him demonstrates deity. He saw Himself as OT Messiah fulfillment; He fills the offices of prophet, priest, and king; the virgin birth demonstrates deity (Matthew calls Mary a virgin; Luke also identifies virgin birth). A Christophany is not defined as a post-incarnation bodily manifestation of Christ as God.", "bigIdeas": ["Claiming to be God does not by itself make the claim true.", "Jesus claimed to forgive sins.", "NT authors ascribe creation to Jesus.", "Worship given to and accepted by Jesus demonstrates His deity.", "Jesus believed Himself the fulfillment of OT Messiah prophecies.", "Christophany is NOT “manifestation of Christ as God in visible bodily form after the incarnation” (Moodle False).", "Christ fulfilled prophet, priest, and king.", "Virgin birth demonstrates His deity; Matthew calls Mary a virgin; Luke is not the Gospel that fails to identify virgin birth."], "takeaways": ["Claim ≠ proof by itself; forgive sins; creation ascribed to Jesus; worship accepted.", "Messiah fulfillment; prophet/priest/king; virgin birth (Matthew + Luke).", "Christophany definition False as stated on Moodle."], "glossary": [{"term": "Christophany", "meaning": "Moodle: False that it is Christ as God in visible bodily form after the incarnation (as graded)."}, {"term": "Threefold office", "meaning": "Prophet, priest, and king — fulfilled by Christ."}, {"term": "Virgin birth", "meaning": "Demonstrates deity; Matthew calls Mary a virgin; Luke also identifies virgin birth."}, {"term": "Worship of Jesus", "meaning": "Given to and accepted by Him — demonstrates deity."}], "outline": ["Claims and why a claim alone is not enough", "Forgiveness, creation, and worship", "Messiah fulfillment and threefold office", "Christophany (correct the False definition)", "Virgin birth in Matthew and Luke"], "mustKnow": [{"label": "Quiz 7", "value": "100% (10/10), cmid 1185"}, {"label": "Claim alone", "value": "Does not make deity true"}, {"label": "Threefold office", "value": "Prophet, priest, king"}, {"label": "Christophany item", "value": "False as worded on Moodle"}, {"label": "Virgin birth", "value": "Matthew yes; Luke also identifies (not the exception)"}], "compare": [{"title": "Claim vs demonstration", "points": ["Mere claim to be God ≠ automatic truth", "Forgiveness, creation, worship, messianic fulfillment, virgin birth demonstrate deity"]}], "pulpit": ["Preach Jesus’ deity from what He does and receives — forgiveness, creation, worship — not from volume of claims alone.", "Hold prophet, priest, and king together in one Christ.", "Teach the virgin birth as Matthew and Luke both identify it."], "quickReview": ["Claim alone ≠ true; forgive sins; creation; worship accepted.", "Messiah fulfillment; prophet/priest/king.", "Christophany item False as worded; virgin birth Matthew + Luke."], "quiz": [{"q": "Because Jesus claimed to be God makes His claim true.", "answer": "False", "why": "A claim alone does not make it true."}, {"q": "Jesus claimed to forgive sins.", "answer": "True", "why": "He claimed to forgive sins."}, {"q": "The New Testament authors ascribed the work of creation to Jesus.", "answer": "True", "why": "Creation ascribed to Jesus."}, {"q": "The fact that worship was given to and accepted by Jesus demonstrates His Deity.", "answer": "True", "why": "Worship accepted demonstrates deity."}, {"q": "Jesus clearly believed Himself to be the fulfillment of the Old Testament prophecies of the Messiah.", "answer": "True", "why": "Messiah fulfillment."}, {"q": "A Christophany is the manifestation of Christ as God in visible and bodily form after the incarnation.", "answer": "False", "why": "False as worded on Moodle."}, {"q": "Christ fulfilled the threefold offices of prophet, priest, and king.", "answer": "True", "why": "Prophet, priest, king."}, {"q": "The virgin birth of Christ demonstrates His Deity.", "answer": "True", "why": "Virgin birth demonstrates deity."}, {"q": "Matthew called Mary a virgin.", "answer": "True", "why": "Matthew calls Mary a virgin."}, {"q": "Luke is the one Gospel not identifying Jesus as virgin born.", "answer": "False", "why": "Luke also identifies virgin birth."}], "essays": [{"theme": "Give nine reasons why we can believe in the Deity of Jesus Christ.", "summary": "1. Jesus openly claimed deity, using the divine “I AM” language and saying, “I and my Father are one.”\n2. The Old and New Testament Scriptures testify that Jesus is God—the Word was God, Isaiah called Him Mighty God, and Paul called Him great God and Savior.\n3. The triune nature of God places the Son fully within the one divine life of Father, Son, and Holy Spirit.\n4. Jesus’ heavenly origin and eternal preexistence show that He did not begin at Bethlehem; He came down from heaven.\n5. Scripture gives Jesus the work of creation: all things were made by Him.\n6. The New Testament ascribes divine attributes to Him, including sustaining creation, eternal life, and authority beyond ordinary human limits.\n7. Jesus received and accepted worship, something appropriate for God alone.\n8. Scripture gives Him divine titles such as Jehovah, Son of God, Son of man, Word, and Christ/Messiah.\n9. His virgin birth and sinless life demonstrate a unique, holy divine-human identity, while His prophetic, priestly, and kingly offices fulfill God’s redemptive work."}, {"theme": "Discuss Jesus’ own claims to be Deity.", "summary": "Jesus did not leave His deity as an abstract claim; He spoke and acted in ways that put the claim plainly before His hearers. He used the divine “I AM” language, including “I am the way,” “I am the resurrection,” and “I am the door.” He said, “I and my Father are one,” and called God “my Father,” which His opponents understood as making Himself equal with God. He claimed authority to forgive sins, an authority they recognized belongs to God. He identified Himself with the Old Testament Lord and Messiah, claimed a unique oneness with the Father, and spoke of heavenly origin and authority. He also accepted worship rather than refusing it. Taken together—His words, His works, His holiness, His authority over sin, and His acceptance of worship—show that Jesus understood Himself to be the divine Son, not merely a teacher or prophet."}, {"theme": "What five titles given to Christ in Scripture demonstrate His Deity?", "summary": "Five titles that point to Christ’s deity are:\n1. Jehovah—the Lord of the Old Testament, identifying Jesus with the divine Lord.\n2. Son of God—the title expressing His divine nature and unique relationship with the Father.\n3. Son of Man—the Daniel 7 title of the heavenly figure who receives everlasting dominion.\n4. The Word—the eternal Word who was with God and was God, and through whom God revealed Himself.\n5. Christ or Messiah—the Anointed One who fulfills the divine offices of Prophet, Priest, and King."}]}, {"id": "ap2-8", "number": 8, "title": "Logical Proofs That Jesus Was Raised From The Dead", "topic": "Christianity as a religion of resurrection — historical proofs, failed opposing theories, and the lesson’s creationist side notes.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 8: 10/10 (100%), 5m 27s, cmid 1190 / attempt 101992. Essays Complete/Not graded. Certificate restricted (cmid 2164).", "summary": "Christianity is ultimately a religion of resurrection. Real scholarship does not treat the resurrection as a mere fabrication; history is a chief demonstration of Christianity’s validity. Jewish leaders could not disprove it though they tried; Jesus predicted His death and resurrection; results include shared spiritual life and living in two worlds. The quiz also marks False that earth’s magnetic field is increasing and that the sun’s diameter is increasing five feet an hour (the essay’s anti-evolution list uses related claims as the course framed them).", "bigIdeas": ["Christianity is ultimately a religion of resurrection.", "The resurrection was not merely a scholarly fabrication.", "History is the greatest demonstration of Christianity’s validity.", "Jewish leaders could not disprove the resurrection though they tried.", "Jesus predicted both death and resurrection.", "Result: sharing spiritual life with believers; Christian lives in two worlds.", "Quiz: moon dust argument against evolution as fact (True as graded); magnetic field increasing = False; sun diameter increasing 5 ft/hour = False.", "Opposing theories (stolen body, swoon, Passover Plot, wrong tomb, demythologizing, hallucination, mystical) fail the empty tomb, witnesses, and church rise."], "takeaways": ["Resurrection at the center; history validates; opponents could not disprove; Jesus predicted it.", "Spiritual life shared; two worlds; ten historical proofs; ten anti-evolution evidences as the lesson listed."], "glossary": [{"term": "Swoon theory", "meaning": "Jesus only appeared dead, revived, and escaped."}, {"term": "Passover Plot (Schonfield)", "meaning": "Drug-signal / wrong-tomb style non-resurrection theory."}, {"term": "Wrong-tomb theory (Lake)", "meaning": "Women and disciples went to the wrong burial place."}, {"term": "Demythologizing (Bultmann)", "meaning": "Appearances reduced to subjective visions."}, {"term": "Two worlds", "meaning": "The Christian is said to live in two worlds."}], "outline": ["Resurrection as the heart of Christianity", "Historical demonstration and failed opposing theories", "Ten proofs of the resurrection", "Quiz side notes on creationist evidences vs evolution"], "mustKnow": [{"label": "Quiz 8", "value": "100% (10/10), cmid 1190, attempt 101992"}, {"label": "Core claim", "value": "Christianity = religion of resurrection"}, {"label": "History", "value": "Greatest demonstration of Christianity’s validity"}, {"label": "Magnetic field / sun diameter items", "value": "Increasing magnetic field = False; sun +5 ft/hr = False"}, {"label": "Opposing theories", "value": "Stolen body, swoon, Passover Plot, wrong tomb, visions/hallucinations, mystical"}], "compare": [{"title": "Historical resurrection vs opposing theories", "points": ["Stolen body / swoon / Passover Plot / wrong tomb / demythologizing / hallucination / mystical message", "Fail to explain empty tomb, grave clothes, witnesses, transformed disciples, rise of the church"]}], "pulpit": ["Preach Christianity as a resurrection faith — empty tomb and living witnesses, not a private myth.", "Name the failed alternatives briefly so people hear why the church rose.", "Hold both worlds: life now in Christ and life with Him forever."], "quickReview": ["Religion of resurrection; not a fabrication; history demonstrates.", "Leaders could not disprove; Jesus predicted death and rising.", "Spiritual life shared; two worlds.", "Ten proofs; opposing theories fail; quiz False on magnetic increase and sun expanding."], "quiz": [{"q": "Christianity is ultimately a religion of resurrection.", "answer": "True", "why": "Resurrection is ultimate."}, {"q": "The real scholars know that the resurrection of Jesus was simply a fabrication.", "answer": "False", "why": "Not merely a fabrication."}, {"q": "History is the greatest demonstration of the validity of Christianity.", "answer": "True", "why": "History demonstrates validity."}, {"q": "One argument for the resurrection was the inability of the Jewish leaders to disprove it even though they tried to do so.", "answer": "True", "why": "Opponents could not disprove it."}, {"q": "Jesus predicted both His death and resurrection.", "answer": "True", "why": "He predicted both."}, {"q": "One of the obvious results of the resurrection of Christ is the sharing of spiritual life with believers.", "answer": "True", "why": "Shared spiritual life."}, {"q": "The Christian is said to live in two worlds.", "answer": "True", "why": "Two worlds."}, {"q": "One fact that argues against evolution as a fact is the relatively small amount of dust on the moon.", "answer": "True", "why": "Moon dust item True as graded in this course."}, {"q": "The strength of earth's magnetic field is increasing at an alarming rate.", "answer": "False", "why": "Not increasing at an alarming rate (False as graded)."}, {"q": "The sun's diameter is increasing on an average of 5 feet an hour.", "answer": "False", "why": "Not increasing 5 ft/hour (False as graded)."}], "essays": [{"theme": "Main historical theories opposing the resurrection", "summary": "The main historical theories opposing the resurrection begin with the claim that the disciples stole Jesus’ body, which was the report the guards were told to give. The swoon theory says Jesus only appeared dead, revived in the cool tomb, and escaped. Hugh Schonfield’s Passover Plot presents a similar idea, saying Jesus arranged a drug signal and that the body was mistakenly placed in another tomb. Kirsopp Lake’s wrong-tomb theory argues that the women and disciples went to the wrong burial place. Other views redefine the resurrection as something non-historical or eschatological rather than a bodily event. Rudolf Bultmann’s demythologizing approach reduces the appearances to subjective visions, and George Hanson describes them as hallucinations caused by excited imagination. Keim’s view treats the resurrection as a spiritual or mystical message rather than a physical rising. These alternatives fail because they do not adequately explain the empty tomb, the grave clothes, the many witnesses, the transformed disciples, and the rise of the church."}, {"theme": "Ten proofs of the resurrection", "summary": "Here are ten proofs of the resurrection: (1) history accurately records the events; (2) the empty tomb and the grave cloths left together and unwrapped; (3) the agreement of the eyewitnesses; (4) the sudden change of frightened disciples into bold witnesses; (5) the rapid emergence of the growing church, which claimed the risen Christ as its foundation; (6) the testimony of individuals and groups who said they saw Jesus alive; (7) the transformation of Saul of Tarsus into Paul, a fervent preacher; (8) Paul’s testimony, shared by believers through the ages, that the resurrected Christ lives in them; (9) the church’s connection of Christ’s death, burial, and resurrection with Old Testament prophecy; and (10) the New Testament’s coherent historical explanation of the purpose and results of the resurrection. Additional evidence includes the inability of Jesus’ opponents to produce His body, the change from Sabbath worship to Sunday, James’s conversion, and Ignatius’s testimony."}, {"theme": "Ten evidences presented against evolution (as the lesson framed them)", "summary": "Ten evidences presented against evolution are: (1) meteoritic dust and the small amount of dust on the moon, which is used to argue for a young moon; (2) the rapid decay of the earth’s magnetic field; (3) the fossil record, which has no genuine missing link or gradual series of intermediate forms; (4) the problem of probability, since the chance formation of even a simple cell or protein is unimaginably small; (5) the second law of thermodynamics, which points toward degeneration rather than increasing order; (6) so-called vestigial organs, many of which have proved to have useful functions; (7) the rapid burial required for fossils and fossil fuels, consistent with a catastrophic flood; (8) homology and molecular comparisons, which do not consistently support a common ancestor; (9) the sun’s diameter shrinking about five feet per hour; and (10) the earth’s rotation slowing over time. Together these observations raise serious questions about an old earth and naturalistic evolutionary progression, and they support the lesson’s creationist argument."}]}, {"id": "ap2-9", "number": 9, "title": "10 Questions Every Christian Must Answer", "topic": "Absolute truth, origins, and whether the heathen are lost — with the reading Are the Heathen Really Lost?", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 9: 9/10 (90%), 7m 17s, cmid 1193 / attempt 101995. Essays Complete/Not graded. Reading: Are the Heathen Really Lost? Miss: Q8 Universalists “most people” (chose True; Moodle False).", "summary": "Start with absolute truth and “why something rather than nothing.” Creationism’s critics say it is untestable/unobservable/unpredictable; the past is not infinite; whatever begins has a cause; the universe’s size and complexity argue against accident. Darwinian theory is not specific, guided, and unified in purpose as the False stem claimed. Universalists do not merely believe “most” eventually go to heaven (Moodle False). Barth embraced “biblical universalism.” Conscience is an inborn sense of right and wrong from inward awareness of God.", "bigIdeas": ["First question: Is there absolute truth?", "Origins: Why is there something rather than nothing?", "Critics of Creationism: not scientific because not testable, observable, predictable.", "The past is not infinite; whatever begins to exist has a cause.", "Universe too large/complex to be accident.", "Darwinian theory is NOT specific, guided, with strict unity of purpose (False).", "Universalists do NOT believe merely that most people eventually go to heaven (False — miss if True).", "Karl Barth embraced “biblical universalism.”", "Conscience = inborn right/wrong from inward awareness of God.", "Scripture: outside Christ people are lost; salvation only in Jesus."], "takeaways": ["Ten must-answer questions for Christians; absolute truth and origins first.", "Cause of the universe; anti-accident; Darwinian stem False.", "Heathen lost apart from Christ; universalism vs Barth; conscience."], "glossary": [{"term": "Absolute truth", "meaning": "First question every Christian should ask and answer."}, {"term": "Universalism", "meaning": "All eventually saved; Moodle False that they believe only “most” go to heaven."}, {"term": "Biblical universalism (Barth)", "meaning": "Karl Barth’s phrasing embraced in this lesson’s True item."}, {"term": "Conscience", "meaning": "Inborn sense of right and wrong from inward awareness of God."}, {"term": "Are the heathen really lost?", "meaning": "Reading focus — Scripture answers yes apart from Christ."}], "outline": ["Absolute truth and origins questions", "Creationism vs critics; causality and complexity", "Darwinian claim corrected", "Universalism, Barth, conscience", "Ten questions list; Scripture on the lost"], "mustKnow": [{"label": "Quiz 9", "value": "90% (9/10), cmid 1193 — miss Q8 Universalists “most”"}, {"label": "First question", "value": "Is there absolute truth?"}, {"label": "Origins", "value": "Why something rather than nothing?"}, {"label": "Past infinite?", "value": "False"}, {"label": "Universalists Q8", "value": "False that “most” eventually go to heaven"}, {"label": "Barth", "value": "Embraced biblical universalism"}], "compare": [{"title": "Universalist hope vs Scripture’s answer", "points": ["Universalist: all (or, wrongly on the miss stem, “most”) eventually heaven; other standards/opportunities", "Scripture: lost apart from Christ; John 14:6; Acts 4:12; conscience suppressed"]}], "pulpit": ["Start with absolute truth before you argue origins or ethics.", "Preach the ten questions as a discipleship checklist, not a trivia list.", "Hold the lostness of those without Christ with tears and clarity — sincerity is not a substitute for the Son.", "Flag the miss: universalism is “all,” not “most.”"], "quickReview": ["Absolute truth first; why something rather than nothing.", "Past not infinite; begins → cause; universe not accident.", "Darwinian stem False; Universalists “most” False; Barth biblical universalism; conscience.", "Ten questions; heathen lost apart from Christ."], "quiz": [{"q": "The first question that a Christian should ask (and answer) is: Is there such a thing as absolute truth?", "answer": "True", "why": "Absolute truth is first."}, {"q": "With respect to the origin of the universe, a critical question is: Why is there something rather than nothing?", "answer": "True", "why": "Something rather than nothing."}, {"q": "Critics of Creationism argue that it is not scientific because it is not testable, does not use an observable entity, and is not predictable.", "answer": "True", "why": "Critics’ three charges."}, {"q": "The past is infinite.", "answer": "False", "why": "The past is not infinite."}, {"q": "Whatever begins to exist has a cause to its existence.", "answer": "True", "why": "Begins → cause."}, {"q": "Because the universe is so large and so complex it could not have come into existence by accident.", "answer": "True", "why": "Not by accident."}, {"q": "Darwinian evolutionary theory is specific, guided, and maintains that all living things have a strict unity of purpose.", "answer": "False", "why": "Not specific/guided/unity of purpose as stated."}, {"q": "Universalists believe that eventually most people will go to heaven.", "answer": "False", "why": "Miss: chose True; Moodle False — not “most.”"}, {"q": "Karl Barth embraced what he called a ‘biblical universalism.’", "answer": "True", "why": "Barth’s biblical universalism."}, {"q": "Conscience is an inborn sense of right and wrong that comes from an inward awareness of God.", "answer": "True", "why": "Inborn conscience from awareness of God."}], "essays": [{"theme": "From the skeptic or universalist perspective, are the heathen really lost?", "summary": "From the skeptic or universalist perspective, the heathen are not necessarily lost. Universalists believe all people will eventually go to heaven, including those who have never heard of Jesus, because God is loving and fair. They argue that such people may be judged by a different standard, given another opportunity after death, or accepted because of sincere worship. Some even minimize the severity of God’s judgment or deny hell."}, {"theme": "List the ten questions every Christian must answer", "summary": "1. Is there such a thing as absolute truth?\n2. How can I know there is a God?\n3. Where did the universe come from?\n4. Is the Bible reliable?\n5. Is Jesus the only way?\n6. Are the claims of Jesus’ physical resurrection from the dead valid?\n7. Are the heathen really lost?\n8. Is hell a real place that lasts for eternity?\n9. Must a person believe in Jesus or make Him Lord of his life to be saved?\n10. How detailed is God’s wonderful plan for each individual life?"}, {"theme": "Scripture’s answer: are people outside the church lost?", "summary": "Scripture answers that people outside the church are lost because salvation is found only in Jesus Christ. He is the way, the truth, and the life, and no one comes to the Father except through Him (John 14:6; Acts 4:12). All people are sinners, and those who have not heard still have an inborn knowledge of God and a conscience witnessing to right and wrong, yet they suppress and reject that knowledge. Sincerity, sacrifice, or religious practice cannot substitute for Christ; only those who believe in Him receive eternal life."}]}, {"id": "ap2-10", "number": 10, "title": "10 Questions About Prayer", "topic": "Prayer as relationship talk with God — miracles, nature’s laws, and guidance through open doors.", "quizScore": 90, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 10: 9/10 (90%), 5m 4s, cmid 1197 / attempt 101996. Essays Complete/Not graded (Q11–Q13 verbatim). Miss: Q10 greater miracle than Jesus (chose True; Moodle False).", "summary": "Prayer is relationship talk with God. God can override natural laws; He does not answer prayer for our purposes instead of His. Critics call miracles myths and Bible writers embellishers; Intelligent Design fits observable facts. Not all miracles are repeatable. God often leads through open doors. Moodle False that no one will ever do a greater miracle than those done by Jesus.", "bigIdeas": ["Prayer = relationship talk with God.", "False that God will never override natural laws; True that He can override whenever He chooses.", "Critics: miracles as myths; Bible writers embellished.", "Intelligent Designer fits observable universe.", "God does not answer prayer to do the miraculous for our purposes, not His.", "Not all miracles are repeatable.", "God often leads through open doors: opportunities, friends, common sense.", "Miss Q10: False that no one will ever do a greater miracle than Jesus’."], "takeaways": ["Prayer as relationship; God can override nature; answers for His purposes.", "Critics vs ID; miracles not all repeatable; open doors.", "Q10 miss: greater-than-Jesus miracle claim is False on Moodle."], "glossary": [{"term": "Prayer", "meaning": "Based on relationship — simply talk with God."}, {"term": "Open doors", "meaning": "Opportunities, friends, even common sense as guidance."}, {"term": "Intelligent Designer", "meaning": "Fits the facts of the observable universe (as graded)."}, {"term": "Miracles (repeatability)", "meaning": "Not all miracles are repeatable."}], "outline": ["Prayer as relationship", "Nature’s laws and God’s freedom to override", "Critics of miracles and Scripture", "Intelligent Design; purpose of answered prayer", "Open doors; Q10 miss on greater miracles"], "mustKnow": [{"label": "Quiz 10", "value": "90% (9/10), cmid 1197 — miss Q10"}, {"label": "Prayer", "value": "Relationship talk with God"}, {"label": "Natural laws", "value": "God can override; not “never”"}, {"label": "Answered prayer", "value": "For His purposes, not merely ours"}, {"label": "Q10", "value": "False — someone may do a greater miracle than Jesus’ (as graded)"}], "compare": [{"title": "Never override vs can override", "points": ["False: God will never override natural laws", "True: God can interfere/override whenever He chooses"]}], "pulpit": ["Preach prayer as conversation in a relationship, not a vending machine.", "Hold miracles under God’s purpose — not our wish list.", "Teach open doors without making them fatalism.", "Flag the miss: Moodle says False that no one will ever do a greater miracle than Jesus’."], "quickReview": ["Prayer = talk with God; God can override nature.", "Critics: myths/embellishment; ID fits facts.", "Not for our purposes alone; miracles not all repeatable; open doors.", "Q10: False that none greater than Jesus’ miracles."], "quiz": [{"q": "Prayer is based on a relationship to God where you simply talk with God.", "answer": "True", "why": "Relationship talk."}, {"q": "God will never override His natural laws of nature.", "answer": "False", "why": "He can override."}, {"q": "Critics argue that miracles are only myths used to perpetuate Christianity.", "answer": "True", "why": "Critics’ myth charge."}, {"q": "Critics argue that the Bible writers embellished the truth to further their cause.", "answer": "True", "why": "Critics’ embellishment charge."}, {"q": "The idea that God is the Intelligent Designer of the universe fits the facts of the observable universe.", "answer": "True", "why": "ID fits observable facts."}, {"q": "God can interfere with or override the laws of nature whenever He chooses.", "answer": "True", "why": "He can override."}, {"q": "God answers prayer to do the miraculous for our purposes, not His.", "answer": "False", "why": "Not for our purposes instead of His."}, {"q": "All miracles are repeatable.", "answer": "False", "why": "Not all are repeatable."}, {"q": "God often leads through open doors: opportunities, friends, and even common sense.", "answer": "True", "why": "Open doors."}, {"q": "No one will ever do a greater miracle than those done by Jesus.", "answer": "False", "why": "Miss: chose True; Moodle False."}], "essays": [{"theme": "According to Dr. Towns, what is prayer?", "summary": "According to Dr. Towns, prayer is based on a relationship with God in which we simply talk with Him. It is communication and conversation with the Father, not a mechanical formula or a way of manipulating Him. Through Christ, a believer who has a relationship with God can bring requests, worship, and thanksgiving to Him."}, {"theme": "With respect to prayer's effectiveness in bringing change in the natural world, what is the critics' (skeptics') argument, and how can we respond?", "summary": "Skeptics argue that the universe is a closed mechanical system controlled by fixed scientific laws. If prayer could change events in the natural world, they say it would interrupt cause and effect and produce chaos, so miracles and answers to prayer must be myths or mistaken interpretations. We can respond that God is the Creator and the Source and Lawgiver of nature. He is not trapped inside the naturalist's box; He can work through providence, bring natural forces together, or answer by a higher law and perform a miracle for His divine purpose. This does not mean prayer controls God. We pray in submission to His will and according to His Word."}, {"theme": "Why would we believe that prayer could override God's plans for the universe?", "summary": "I would not say that prayer overrides God's plans as though God were surprised or forced to change His mind. God is omniscient and sovereign, and He already knows the requests we will bring. Rather, prayer is one of the means God uses within His plan, and He may include our prayers in the way He accomplishes His will. When He answers with providence or a miracle, He is not abandoning His purposes; He is carrying out a divine purpose through the prayer of His people. Therefore we pray with faith, but also with submission to God's will."}]}, {"id": "ap2-11", "number": 11, "title": "Why Can’t We Hear The Actual Voice Of God?", "topic": "Why God may be silent — and how He still speaks through Word, Son, nature, and standing orders.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 11: 10/10 (100%), 6m 2s, cmid 1201 / attempt 101997. Essays Complete/Not graded (Q11–Q13 verbatim).", "summary": "God may be silent for many reasons, but He always speaks through His Word and spoke most clearly through His Son. Silence can be a test; His last orders are standing orders. Claims of hearing God’s voice must be tested. We are not responsible for what God keeps secret, and He never promised to always explain what He is doing.", "bigIdeas": ["Many reasons God might be silent — silence can be a test.", "False that God never speaks through the natural world; True that He always speaks through His Word.", "God spoke most clearly through His Son.", "When silent: last orders are standing orders.", "God can do whatever He wants because He is God.", "A claim to hear God’s voice must be questioned — not automatic truth.", "God never promised always to explain what He is doing; we are not responsible for His secrets."], "takeaways": ["Word + Son are primary; nature also used; silence can test.", "Standing orders until further word; test voice claims.", "Essays: ways God speaks; seven silence situations; why audible is not the norm today."], "glossary": [{"term": "Standing orders", "meaning": "His last orders remain what we should do until He tells us otherwise."}, {"term": "Silence as a test", "meaning": "God’s silence can itself be a test of faith and obedience."}, {"term": "Clearest speech", "meaning": "God spoke most clearly through His Son."}, {"term": "Test the spirits", "meaning": "Claims of hearing God must be questioned and measured by Scripture."}], "outline": ["Why God may be silent", "How God speaks (Word, Son, nature, Spirit, providence)", "Standing orders when silent", "Testing claims of an audible voice", "Secrets and unexplained providence"], "mustKnow": [{"label": "Quiz 11", "value": "100% (10/10), cmid 1201"}, {"label": "Always speaks", "value": "Through His Word"}, {"label": "Most clearly", "value": "Through His Son"}, {"label": "When silent", "value": "Last orders = standing orders"}, {"label": "Voice claims", "value": "Must be questioned / tested"}], "compare": [{"title": "Normal speech vs claimed audible voice", "points": ["Normal: Word, Son, Spirit, providence, believers", "Audible claim: not automatic; may be mistake, deception, illness, lie, or demonic — test by Scripture"]}], "pulpit": ["Preach the Word as God’s normal, reliable voice for every believer.", "Comfort the silent season: last orders still stand; hope in God like David.", "Warn against untested “God told me” claims without crushing genuine guidance.", "Hold sovereignty: God need not explain every secret."], "quickReview": ["Many reasons for silence; silence can test.", "Word always; Son most clearly; nature yes.", "Standing orders; voice claims must be tested.", "No promise of full explanation; secrets are His."], "quiz": [{"q": "There are many reasons why God might be silent.", "answer": "True", "why": "Many reasons."}, {"q": "God never speaks through the natural world.", "answer": "False", "why": "He can speak through nature."}, {"q": "God always speaks through His Word.", "answer": "True", "why": "Always through Scripture."}, {"q": "God spoke most clearly through His Son.", "answer": "True", "why": "Clearest revelation."}, {"q": "The silence of God can be a test.", "answer": "True", "why": "Silence as test."}, {"q": "When God is silent remember that His last orders are standing orders. That is what we should do until He tells us otherwise.", "answer": "True", "why": "Standing orders."}, {"q": "God can choose to do whatever He wants to do because He is God.", "answer": "True", "why": "Sovereignty."}, {"q": "Because a person says they have heard the voice of God means they have, and this should never be questioned.", "answer": "False", "why": "Claims must be tested."}, {"q": "God never promised that He would always explain what He is doing in our life.", "answer": "True", "why": "No promise of full explanation."}, {"q": "We are not responsible for the things God chooses to keep secret.", "answer": "True", "why": "Secrets remain His."}], "essays": [{"theme": "Ways God has spoken / how we hear today", "summary": "God has spoken in many ways: through creation and the natural world; through Scripture, His breathed-out Word; through judgment and the Holy Spirit’s conviction; through miracles and signs; and at times through an audible voice. He has also guided people without words, through His Spirit, through circumstances or providence, and ultimately through Jesus Christ, the clearest and fullest revelation of God. The Bible and the life of Christ remain the reliable message we are to hear today."}, {"theme": "Seven situations when God seems silent — and how to respond", "summary": "The seven situations are: God is not ready to speak; He is testing me; He has already talked to me; He wants me to make an important decision; He knows I will not listen; I have forgotten what He said; or something is hindering my ability to listen. I should not panic or invent a new message. I should treat His last orders as standing orders, remember clearly what He has already said, stay in prayer and Scripture, examine what may be blocking my hearing, and wait faithfully. Like David, I should hope in God and learn to listen through the sounds of silence."}, {"theme": "Why audible voice is not God’s normal way today (Towns)", "summary": "Dr. Towns says God can speak audibly because He is God, but He has chosen not to make that His normal way of speaking today. During the age of grace, God does not show partiality: Christ has made access to God available to all, so a private audible message to one person would raise the question of why not everyone. God has already spoken fully through His Son, Jesus, and has recorded everything necessary in the Bible. The written Word is consistent, reliable, and available to every believer; the Holy Spirit helps us understand it, and Christians should study it together and test claims against Scripture. People who claim an audible message may be mistaken, self-deceived, mentally ill, lying, or hearing something demonic, so the spirits must be tested. Even an audible voice would not guarantee faithfulness, guidance, character growth, or doctrinal truth. God is not silent—He speaks through His Word, prayer, circumstances, and other believers."}]}, {"id": "ap2-12", "number": 12, "title": "Seeing God, Miracles, and Suffering for Service", "topic": "Why we cannot see the Father physically; how God works miracles; leaders without signs; suffering that prepares for service.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 12: 10/10 (100%), 5m 51s, cmid 1205 / attempt 101998. Essays Complete/Not graded (Q11–Q13 verbatim). Course total 98%; certificate unlocked (cmid 2164).", "summary": "God the Father is Spirit — not limited to a physical form or to time and space. To see God, look at Jesus; in Heaven we shall actually see God. Miracles always have a purpose and do not automatically produce faith in all who see them. John the Baptist was not known for miracle-working powers. Sometimes God allows suffering to prepare a person for special service.", "bigIdeas": ["Universal desire to see God; Moses saw a manifestation of His glory.", "Father is Spirit — not limited to physical form; False that He has restricted Himself to time and space.", "Want to see God? Look at Jesus; in Heaven we shall actually see God.", "Jesus’ public miracles did not produce faith in all who saw them.", "God’s miracles always have a purpose.", "John the Baptist was not known for miracle-working powers.", "Suffering can prepare a person for special service."], "takeaways": ["God is Spirit beyond physical time and space; Jesus reveals the Father.", "Miracles have divine purposes and do not automatically produce faith.", "God can use suffering to prepare believers for service."], "glossary": [{"term": "God as Spirit", "meaning": "Father is not limited to a physical form or to matter; invisible Creator."}, {"term": "See God", "meaning": "Look at Jesus now; in Heaven we shall actually see God."}, {"term": "Miracle purpose", "meaning": "God’s miracles always have a purpose — not spectacle for its own sake."}, {"term": "Suffering for service", "meaning": "Sometimes God allows suffering to prepare someone for special service."}], "outline": ["Desire to see God; Moses and glory", "Father as Spirit beyond time and space", "Jesus as the image; Heaven’s sight", "Miracles: purpose, limits on producing faith", "Leaders without signs; suffering that prepares"], "mustKnow": [{"label": "Quiz 12", "value": "100% (10/10), cmid 1205"}, {"label": "Course total", "value": "98%; cert 2164 unlocked"}, {"label": "See God now", "value": "Look at Jesus"}, {"label": "Miracles", "value": "Always purposeful; not automatic faith"}, {"label": "John the Baptist", "value": "Not known for miracle powers"}], "compare": [{"title": "Seeing God now vs in Heaven", "points": ["Now: look at Jesus (image of the invisible God)", "Heaven: we shall actually see God"]}, {"title": "Miracle workers vs great leaders without signs", "points": ["Jesus’ miracles: purposeful, not universal faith-producers", "Adam, Isaac, Joseph, David, Isaiah, Jeremiah, John the Baptist — great without recorded miracle-working fame"]}], "pulpit": ["Preach Jesus as the visible revelation of the invisible God.", "Hold miracles under purpose — not a faith vending machine.", "Honor leaders who served without signs; greatness is not spectacle.", "Redeem suffering as preparation for service, not only punishment."], "quickReview": ["Father is Spirit; not boxed in time/space.", "See God: Jesus now; Heaven later.", "Miracles purposeful; not automatic faith; John no signs.", "Suffering can prepare for special service."], "quiz": [{"q": "Throughout the ages people have had a universal desire to see God.", "answer": "True", "why": "Universal desire."}, {"q": "Moses saw a manifestation of God, His glory.", "answer": "True", "why": "Glory manifestation."}, {"q": "God the Father is Spirit and not limited to a physical form.", "answer": "True", "why": "Father is Spirit."}, {"q": "God has restricted Himself to time and space.", "answer": "False", "why": "Not restricted to time/space."}, {"q": "If we want to see God, we should look at Jesus.", "answer": "True", "why": "Look at Jesus."}, {"q": "In Heaven, we shall actually see God.", "answer": "True", "why": "Heaven’s sight."}, {"q": "The miracles performed by Jesus in His public ministry produced faith in all who saw them.", "answer": "False", "why": "Not faith in all."}, {"q": "God's miracles always have a purpose.", "answer": "True", "why": "Always purposeful."}, {"q": "John the Baptist was known for his miracle working powers.", "answer": "False", "why": "Not known for miracles."}, {"q": "Sometimes God allows a person to suffer to prepare them for some special service.", "answer": "True", "why": "Suffering can prepare."}], "essays": [{"theme": "Why I cannot see God physically — and how I still know Him", "summary": "I cannot see God physically because God is Spirit; He is not limited to a bodily form or to matter. As the eternal, infinite, and omnipresent Creator, He exists beyond time and space, so there is no physical object for human eyes to see. Scripture calls Him invisible and points us to Jesus, the image of the invisible God. I can still know Him through Christ, Scripture, faith, obedience, and the ways He works in creation and in my life."}, {"theme": "Six ways God accomplishes miracles", "summary": "God accomplishes miracles in six ways: (1) by superseding and transcending all known laws of the universe, as in creation and Christ’s resurrection; (2) by superseding and transcending natural laws, as when He sent a raven to Elijah; (3) by suspending the usual laws of nature; (4) by intensifying His natural laws, as when He changed water into wine; (5) by redirecting natural laws, as in the parting of the Red Sea; and (6) by neutralizing the usual consequences of sin, such as in healing."}, {"theme": "Great leaders and prophets without miracle-working fame", "summary": "Adam, Isaac, Joseph, and David are described as great leaders who performed no recorded miracles. Prophets such as Isaiah and Jeremiah saw God’s work but were not known as miracle workers. John the Baptist also performed no sign, even though Jesus called him the greatest born of women."}]}], "courseTotal": 98}, {"id": "church-history-2", "title": "Church History 2", "code": 66, "status": "in-progress", "courseTotal": 88, "certificateUnlocked": false, "blurb": "HIS / course 66 — Continues Church History 1 as Lessons 7–12. L7–L11 live; L12 placeholder. Course total 88%; certificate locked (cmid 2165) until final quiz.", "lessons": [{"id": "ch2-7", "number": 7, "title": "Renaissance and Reformation — Luther, Zwingli, Calvin, and Church Music", "topic": "Italy’s Renaissance; Luther’s 1517 challenge to indulgences; Zwingli in Zurich; Calvin’s Christian society and Servetus; congregational singing.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 7: 10/10 (100%), 6m 28s, cmid 1211 / attempt 101999. Essays Complete/Not graded (Q11–Q13 verbatim). Course total 50%. Cert cmid 2165 locked.", "summary": "The Renaissance began in Italy. The Reformation was sparked by Luther’s opposition to the sale of indulgences (Ninety-Five Theses, 1517). Luther was Augustinian, not Dominican. Calvin’s Institutes were not published in 1517. Zwingli led in Zurich, taught a symbolic Lord’s Supper, wanted civil government under Christ, and died in battle in 1531. Calvin sought a Christian society, valued music (did not disdain it), and was responsible for Servetus’s burning. Isaac Watts later championed congregational singing.", "bigIdeas": ["Renaissance began in Italy.", "Reformation spark: Luther vs sale of indulgences (1517 Theses).", "Luther = Augustinian monk (not Dominican).", "Calvin’s Institutes ≠ 1517.", "Zwingli: Zurich; civil gov under Christ; symbolic Lord’s Supper; killed 1531.", "Calvin: Christian socioeconomic/political life; valued church music; Servetus burned for heresy.", "Isaac Watts: great proponent of congregational singing."], "takeaways": ["Renaissance in Italy; Reformation sparked by Luther vs indulgences (1517).", "Luther Augustinian not Dominican; Calvin’s Institutes not 1517.", "Zwingli Zurich / killed 1531 / symbolic Lord’s Supper; Calvin sought Christian society, valued music, Servetus; congregational singing / Watts."], "glossary": [{"term": "Ninety-Five Theses (1517)", "meaning": "Luther’s Wittenberg challenge to the sale of indulgences — sparked the Reformation."}, {"term": "Ulrich Zwingli", "meaning": "Zurich reformer; Bible sole authority; symbolic Lord’s Supper; killed in battle 1531."}, {"term": "John Calvin", "meaning": "Sought Christian society/government; Institutes; valued music; Servetus burned for heresy."}, {"term": "Indulgences", "meaning": "Sale opposed by Luther — the big issue sparking the Reformation."}, {"term": "Isaac Watts", "meaning": "Great proponent of congregational singing."}], "outline": ["Renaissance begins in Italy", "Luther: Augustinian, 1517 Theses, grace through faith", "Zwingli in Zurich: Scripture alone, symbolic Supper, death 1531", "Calvin: Institutes, Christian society, music, Servetus", "Church music: chorales, Psalter, congregational singing / Watts"], "mustKnow": [{"label": "Quiz 7", "value": "100% (10/10), cmid 1211"}, {"label": "Course total", "value": "50%; cert 2165 locked"}, {"label": "Reformation spark", "value": "Luther vs indulgences (1517)"}, {"label": "Luther’s order", "value": "Augustinian (not Dominican)"}, {"label": "Zwingli death", "value": "Battle, 1531"}, {"label": "Servetus", "value": "Calvin responsible for burning for heresy"}], "compare": [{"title": "Luther / Zwingli / Calvin", "points": ["Luther: Wittenberg, Augustinian, faith/grace, German Bible, chorales", "Zwingli: Zurich, Scripture alone, symbolic Lord’s Supper, civil gov under Christ, died 1531", "Calvin: Christian society, Institutes (not 1517), valued music, Servetus"]}, {"title": "Church music streams", "points": ["Luther: German chorales teaching doctrine; singing in the people’s language", "Calvin: Psalter; congregational singing generally in unison; instruments less direct"]}], "pulpit": ["Preach grace through faith against any “buy your way” spirituality.", "Hold Scripture as sole religious authority (Zwingli’s Zurich lesson).", "Recover congregational singing as the people’s praise, not a show.", "Name the hard history honestly (Servetus) while teaching Calvin’s larger vision."], "quickReview": ["Renaissance: Italy. Reformation spark: indulgences / 1517.", "Luther Augustinian; Institutes ≠ 1517.", "Zwingli Zurich, symbolic Supper, 1531; Calvin society + music + Servetus.", "Watts / congregational singing."], "quiz": [{"q": "The Renaissance began in Italy.", "answer": "True", "why": "Italy."}, {"q": "John Calvin's Institutes of the Christian Religion was published in 1517.", "answer": "False", "why": "Not 1517."}, {"q": "The big issue sparking the Reformation was Luther's opposition to the sale of Indulgences.", "answer": "True", "why": "Indulgences spark."}, {"q": "Zwingli believed that the civil government should be under the leadership of Christ.", "answer": "True", "why": "Civil gov under Christ."}, {"q": "Zwingli was killed in battle in 1531.", "answer": "True", "why": "Died 1531."}, {"q": "Calvin sought to establish a Christian socioeconomic and political way of life and government.", "answer": "True", "why": "Christian society."}, {"q": "Calvin disdained the use of music in the church as vulgar and undignified.", "answer": "False", "why": "He valued music."}, {"q": "Luther was a Dominican monk.", "answer": "False", "why": "Augustinian, not Dominican."}, {"q": "John Calvin was responsible for burning Michael Servetus at the stake for heresy.", "answer": "True", "why": "Servetus."}, {"q": "Isaac Watts was a great proponent of Congregational singing.", "answer": "True", "why": "Congregational singing."}], "essays": [{"theme": "Summarize the life of Martin Luther", "summary": "Martin Luther (1483–1546) was an Augustinian monk and teacher in Wittenberg. Through studying Galatians and Romans, he came to emphasize salvation by grace through faith in Jesus Christ rather than indulgences or the merits of the church. In 1517 he posted his Ninety-Five Theses, challenging the sale of indulgences and sparking the Protestant Reformation. At the Diet of Worms he stood by his conscience and the Scriptures, and Frederick protected him afterward. Luther translated the Bible into German and helped bring the Word of God to ordinary people. His teaching and example shaped Protestant Christianity."}, {"theme": "Summarize the impact of Ulrich Zwingli on the Reformation", "summary": "Ulrich Zwingli was the Swiss preacher in Zurich who helped lead the Reformation alongside Luther. He opposed the traditional fast during Lent and other practices that lacked scriptural support, and he taught that the Bible—not the Pope or church government—was the sole religious authority. He supported civil government being submitted to Christ and helped establish Reformed churches in Zurich and other Swiss cities. He taught that the Lord’s Supper was symbolic rather than the actual physical presence of Christ in the elements. His influence spread the Reformation through Switzerland until his death in battle in 1531."}, {"theme": "What do we know about church music during the Reformation?", "summary": "Church music became an important part of the Reformation because the reformers believed the whole congregation should praise God, not only a professional choir or priest. Luther encouraged singing in the language of the people and wrote German chorales to teach biblical truth and doctrine. Calvin emphasized the Psalter, with congregational singing generally in unison. Protestant worship music therefore included Lutheran chorales and Calvinist psalm singing, while instruments were used less directly during congregational hymn singing. The result was active participation by ordinary believers in worship."}]}, {"id": "ch2-8", "number": 8, "title": "Philadelphia: The Missionary Church 1750 – 1900 AD", "topic": "Moravian Herrnhut prayer; Edwards and the First Great Awakening; Wesleys, Whitefield, open-air; Haystack missions; circuit riders; Cane Ridge.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 8: 10/10 (100%), 6m 23s, cmid 1215 / attempt 102001. Essays Complete/Not graded (Q11–Q13 verbatim). Course total 60%. Cert cmid 2165 locked.", "summary": "The Moravian community at Herrnhut (“the Lord’s watch”) began a prayer meeting lasting over a hundred years from August 13, 1727. John Newton wrote Amazing Grace. Jonathan Edwards issued a call to prayer and preached “Sinners in the Hands of an Angry God,” marking the beginning of the First Great Awakening in America. The Wesleys and Whitefield were in Oxford’s Holy Club; Wesley did not immediately embrace open-air preaching when Whitefield first invited him. The Haystack Prayer Meeting of 1806 helped birth modern U.S. missions. Methodist circuit riders typically covered 200–500 miles a month. Cane Ridge was not marked by somber, quiet dignity.", "bigIdeas": ["Herrnhut = “the Lord’s watch”; 100+ year prayer meeting from Aug 13, 1727.", "John Newton authored Amazing Grace.", "Edwards: call to prayer + “Sinners…” sermon began First Great Awakening in America.", "Holy Club: Wesleys + Whitefield at Oxford.", "Wesley hesitated at first open-air invite from Whitefield.", "Haystack 1806 helped birth modern U.S. missions.", "Circuit riders: 200–500 miles/month on horseback.", "Cane Ridge was NOT somber and quiet."], "takeaways": ["Moravian Herrnhut prayer; Newton Amazing Grace; Edwards awakening.", "Holy Club; Whitefield open-air; Wesley hesitated at first.", "Haystack 1806; circuit riders 200–500 mi/month; Cane Ridge not somber/quiet."], "glossary": [{"term": "Herrnhut", "meaning": "“the Lord’s watch” — Moravian refuge; continuous prayer from Aug 13, 1727 for 100 years."}, {"term": "First Great Awakening", "meaning": "Marked in America by Edwards’ “Sinners in the Hands of an Angry God.”"}, {"term": "Holy Club", "meaning": "Oxford group including the Wesleys and George Whitefield."}, {"term": "Haystack Prayer Meeting (1806)", "meaning": "Helped birth the modern missions movement in the United States."}, {"term": "Circuit riders", "meaning": "Methodist itinerants traveling 200–500 miles/month on horseback."}, {"term": "Cane Ridge", "meaning": "Revival — graded False that it was somber and quiet."}], "outline": ["Moravian Revival at Herrnhut", "Newton / Amazing Grace", "Edwards: prayer call and First Great Awakening", "Holy Club; Whitefield open-air; Wesley’s hesitation", "Haystack missions; circuit riders; Cane Ridge"], "mustKnow": [{"label": "Quiz 8", "value": "100% (10/10), cmid 1215"}, {"label": "Course total", "value": "60%; cert 2165 locked"}, {"label": "Herrnhut", "value": "Lord’s watch; 100-year prayer"}, {"label": "Edwards sermon", "value": "Began First Great Awakening (as graded)"}, {"label": "Haystack", "value": "1806 — modern U.S. missions"}, {"label": "Circuit riders", "value": "200–500 mi/month"}], "compare": [{"title": "Whitefield vs Wesley on open-air", "points": ["Whitefield pioneered outdoor preaching when pulpits closed", "Wesley did not immediately and whole-heartedly embrace the first invite"]}, {"title": "Quiet dignity vs Cane Ridge", "points": ["False: Cane Ridge marked by somber and quiet dignity", "Revival characterized otherwise (as graded)"]}], "pulpit": ["Preach prayer that outlasts a generation (Herrnhut’s watch).", "Hold open-air courage without romanticizing every first invitation (Wesley’s hesitation).", "Honor ordinary itinerants who rode hard for remote souls.", "Recover Amazing Grace’s story in Newton’s own conversion and calling."], "quickReview": ["Herrnhut = Lord’s watch; 100-year prayer from 1727.", "Newton Amazing Grace; Edwards Sinners / First Awakening.", "Holy Club; Wesley hesitated on open-air; Haystack 1806.", "Circuit 200–500 mi; Cane Ridge not quiet."], "quiz": [{"q": "The author of \"Amazing Grace,\" was John Newton.", "answer": "True", "why": "Newton."}, {"q": "Herrnhut means \"the Lord's watch.\"", "answer": "True", "why": "Lord’s watch."}, {"q": "The prayer meeting at Herrnhut lasted for over a hundred years.", "answer": "True", "why": "100+ years."}, {"q": "Jonathan Edwards published a call to prayer encouraging Christians to unite in intercession for revival.", "answer": "True", "why": "Call to prayer."}, {"q": "Edwards' sermon, \"Sinners in the Hands of an Angry God,\" marked the beginning of the First Great Awakening in America.", "answer": "True", "why": "First Great Awakening marker."}, {"q": "John Wesley immediately and whole-heartedly embraced open air preaching the first time he was invited to do so by George Whitefield.", "answer": "False", "why": "He hesitated at first."}, {"q": "The Wesley's and Whitefield were members of Oxford University's Holy Club.", "answer": "True", "why": "Holy Club."}, {"q": "The Haystack Prayer Meeting of 1806 helped birth the modern missions movement in the United States.", "answer": "True", "why": "Haystack 1806."}, {"q": "Methodist Circuit Riders typically traveled 200 to 500 miles on horseback each month.", "answer": "True", "why": "200–500 mi/month."}, {"q": "The Cane Ridge Revival was marked by it somber and quiet dignity.", "answer": "False", "why": "Not somber/quiet."}], "essays": [{"theme": "Describe the Moravian Revival", "summary": "The Moravian Revival began among persecuted believers who found refuge on Count Nicolaus von Zinzendorf’s estate at Herrnhut, Germany. After division and criticism, the community covenanted to serve the Lord and experienced a powerful visitation of God while gathering for the Lord’s Supper on August 13, 1727. They began a continuous twenty-four-hour prayer meeting that continued for one hundred years. From this prayer movement, the Moravians sent hundreds of missionaries around the world."}, {"theme": "Describe the ministry of George Whitefield", "summary": "George Whitefield was a gifted evangelist who preached repentance, holy living, and personal conversion through faith in Christ. When church pulpits closed to him, he preached outdoors, first to coal miners near Bristol, where crowds grew from about 200 to more than 20,000 and thousands were converted. In America he preached throughout the colonies in fields, orchards, barns, and other open places, often drawing thousands. His biblical, energetic preaching and use of open-air meetings helped spread the Great Awakening and encouraged the Methodist movement."}, {"theme": "Describe the work of the Methodist Circuit Riders", "summary": "Methodist Circuit Riders were itinerant preachers who traveled roughly 200 to 500 miles each month on horseback, serving thirty to fifty preaching points. They were often not college educated and came from ordinary trades, but they were trained and empowered by the Holy Spirit. They slept in homes, inns, or the open air, received little pay, preached passionately from the Bible without reading a manuscript, and used everyday illustrations. They organized converts into societies and churches, helping carry the gospel into remote communities and laying foundations for Methodist growth."}]}, {"id": "ch2-9", "number": 9, "title": "I. The Philadelphia Church, The Missionary Church: 1750 – 1900 AD", "topic": "Second Great Awakening West; McGready camp meetings; Finney’s new measures; Raikes Sunday School; Layman’s Prayer Revival; Moody and Sankey.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 9: 10/10 (100%), 4m 38s, cmid 1219 / attempt 102003. Essays Complete/Not graded (Q11–Q13 verbatim). Course total 70%. Cert cmid 2165 locked.", "summary": "Before the Second Great Awakening in the West, public morals were non-existent. James McGready catalyzed revival in Logan County, Kentucky; camp meetings introduced public emotion in worship. Baptists did not nearly disappear. Finney’s altar call was not welcomed by all denominations; his sermons often ran in next-day papers. Robert Raikes fathered the Sunday School movement. The Layman’s Prayer Revival was not birthed in Chicago (Fulton Street, NYC / Lamphier). Moody regretted giving no invitation the Sunday before the Chicago Fire; Ira Sankey was his music leader.", "bigIdeas": ["Pre–2nd Awakening West: public morals non-existent.", "McGready = catalyst in Logan County, KY; camp meetings = public emotion in worship.", "False that Baptists almost went out of existence during the 2nd Awakening.", "Finney altar call NOT well received by all denominations; sermons often in next-day papers.", "Robert Raikes = father of Sunday School.", "Layman’s Prayer Revival NOT birthed in Chicago (Fulton St NYC / Lamphier).", "Moody regretted no invitation before Chicago Fire; Sankey = music leader."], "takeaways": ["West morals collapsed; McGready / camp meetings / emotion in worship.", "Baptists did not nearly disappear; Finney altar call contested; sermons in papers.", "Raikes Sunday School; Layman’s Prayer Revival NYC not Chicago; Moody/Sankey."], "glossary": [{"term": "James McGready", "meaning": "Catalyst for revival in Logan County, Kentucky — fasting, prayer, communion meetings."}, {"term": "Camp meetings", "meaning": "Open-air gatherings (e.g. Cane Ridge) introducing public emotional display in worship."}, {"term": "Charles Finney", "meaning": "New measures: altar call / anxious seat; sermons printed next day; not universally welcomed."}, {"term": "Robert Raikes", "meaning": "Father of the Sunday School movement."}, {"term": "Layman’s Prayer Revival", "meaning": "Began Fulton Street NYC under Jeremiah Lamphier — not Chicago."}, {"term": "Ira Sankey", "meaning": "Moody’s music leader."}], "outline": ["Moral collapse before 2nd Awakening in the West", "McGready and Camp Meeting Awakenings (1780–1820)", "Finney and the General Awakening (1830–1840)", "Raikes / Sunday School", "Layman’s Prayer Revival; Moody and Sankey"], "mustKnow": [{"label": "Quiz 9", "value": "100% (10/10), cmid 1219"}, {"label": "Course total", "value": "70%; cert 2165 locked"}, {"label": "McGready", "value": "Logan County, KY catalyst"}, {"label": "Finney", "value": "Altar call contested; next-day papers"}, {"label": "Prayer Revival", "value": "Fulton St NYC / Lamphier — not Chicago"}, {"label": "Moody regret", "value": "No invitation before Chicago Fire"}], "compare": [{"title": "Methodist growth vs Baptist myth", "points": ["Methodists grew considerably in the 2nd Awakening", "False that Baptists almost went out of existence"]}, {"title": "Where the Layman’s Prayer Revival began", "points": ["True origin: Fulton Street Church, New York City (Lamphier)", "False: birthed in Chicago"]}], "pulpit": ["Preach camp-meeting urgency without confusing emotion with empty hype.", "Hold Finney’s invitation as a tool — not every church welcomed it then either.", "Recover lay-led noon prayer (Lamphier) as a model for ordinary believers.", "Learn from Moody’s regret: give the invitation while there is still a tonight."], "quickReview": ["West morals collapsed; McGready → camp meetings.", "Baptists did not vanish; Finney altar call contested; papers printed sermons.", "Raikes Sunday School; Prayer Revival = NYC not Chicago.", "Moody regretted no invite; Sankey led music."], "quiz": [{"q": "Prior to the Second Great Awakening in the West, public morals were non-existent", "answer": "True", "why": "Morals collapsed."}, {"q": "The catalyst for revival in Logan County, Kentucky was James McGready", "answer": "True", "why": "McGready."}, {"q": "The camp meetings introduced a public display of emotions in worship.", "answer": "True", "why": "Public emotion."}, {"q": "During the Second Great Awakening, the Methodist church experienced considerable growth, but Baptist churches almost went out of existence.", "answer": "False", "why": "Baptists did not nearly disappear."}, {"q": "Charles Finney's introduction of the alter call was well received by all Christian denominations.", "answer": "False", "why": "Not welcomed by all."}, {"q": "Finney's sermons were often printed in the newspaper the day after he preached them.", "answer": "True", "why": "Next-day papers."}, {"q": "The father of the Sunday School movement was Robert Raikes.", "answer": "True", "why": "Raikes."}, {"q": "The Layman's Prayer Revival was birthed in Chicago.", "answer": "False", "why": "Fulton St NYC / Lamphier."}, {"q": "DL Moody always regretted not giving an invitation the Sunday night before the Great Chicago Fire.", "answer": "True", "why": "Moody’s regret."}, {"q": "Moody's music leader was Ira Sankey.", "answer": "True", "why": "Sankey."}], "essays": [{"theme": "Describe the Camp Meeting Awakenings (1780-1820)", "summary": "The Camp Meeting Awakenings grew out of the moral and spiritual decline that followed the American Revolution. In Logan County, Kentucky, Presbyterian preacher James McGready called people to regular fasting and prayer, and the communion meetings he led became too large for church buildings. At Cane Ridge in 1801, an estimated 10,000–20,000 people gathered, with many arriving in wagons and staying for days. Preachers proclaimed repentance, salvation, heaven, and hell in the open air, and people responded with deep emotion—weeping, shouting, trembling, and coming to Christ. These gatherings became known as camp meetings. They combined fellowship, heartfelt singing, long sermons, and evangelism, and later became more organized. Baptists and Methodists embraced them, while circuit-riding preachers carried the gospel and planted churches across the frontier."}, {"theme": "Describe the General Awakening (1830-1840), and the paradigm shifts and innovations that it introduced", "summary": "The General Awakening of 1830–1840 was closely associated with Charles Grandison Finney. After his conversion, Finney left the law and preached revival, especially in Rochester. His “new measures” included the public invitation or altar call and the anxious seat, asking hearers to make an immediate, personal response to the gospel. Protracted meetings, lay participation, carrying revival results into nearby communities, organized evangelistic music, and the deliberate creation of a worship atmosphere also became important. The movement emphasized a practical Arminian appeal rather than relying on older Calvinistic assumptions. Print media helped spread the message, since Finney’s sermons were published in newspapers soon after preaching. These innovations connected worship and evangelism and helped revival spread widely."}, {"theme": "Explain the inception and expansion of the Layman's Prayer Revival", "summary": "The revival began during a time of economic growth and then the severe financial panic of 1857. At Fulton Street Church in New York City, missionary Jeremiah Lamphier organized a noon prayer meeting. Only a few attended at first, but the meeting grew rapidly as workers left their shops to pray. Newspapers reported the meetings, and prayer gatherings spread to other cities. Where factories were far from churches, owners provided tents. The movement was driven by ordinary laymen rather than a famous evangelist or a major crusade. Meetings were open and orderly but participatory: people prayed, exhorted, sang, or testified, usually within a five-minute limit. Conversions multiplied across the country, with prayer meetings in many cities and rural communities. The Civil War later disrupted the movement, but the revival showed how God used simple, faithful prayer by lay people."}]}, {"id": "ch2-10", "number": 10, "title": "The Laodicea Church – The Apostate Church: 1900 – Present", "topic": "Twentieth-century upheaval; Welsh Revival; Azusa/Pentecostalism; Billy Sunday; Scofield; Depression/war; Billy Graham.", "quizScore": 80, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 10: 8/10 (80%), 6m 2s, cmid 1223 / attempt 102004. Essays Complete/Not graded (Q11–Q13 verbatim). Misses: Q2 colonialism after WWII (chose False; Moodle True); Q5 Welsh Revival five million (chose False; Moodle True). Course total 78%. Cert cmid 2165 locked.", "summary": "2001 marked the beginning of the Age of Terrorism. Colonialism’s global collapse began after WWII; third-world countries often received humanitarian aid. The Welsh Revival’s leader was not J. Edwin Orr (Evan Roberts per essay). Moodle grades True that over five million came to faith in two years (Jay-R missed). Azusa Street birthed modern Pentecostalism. Billy Sunday was an MLB player before evangelism. C.I. Scofield was a great Bible teacher. Depression and war did not drive people away from God. Billy Graham is known for “the Bible says.”", "bigIdeas": ["2001 = beginning of the Age of Terrorism.", "Colonialism’s global collapse began after WWII (miss Q2).", "Third world often object of humanitarian aid/development.", "Welsh Revival leader ≠ J. Edwin Orr (Evan Roberts).", "Miss Q5: Moodle True that over five million came to faith in two years (essay text says more than 100,000 — keep both as given).", "Azusa Street → modern Pentecostal movement.", "Billy Sunday: MLB then evangelist; Scofield in Bible Teaching movement.", "Depression/war did NOT drive people from God; Graham: “the Bible says.”"], "takeaways": ["Age of Terrorism 2001; postcolonial third-world aid.", "Welsh Revival leader not Orr (Evan Roberts); Azusa → Pentecostalism.", "Billy Sunday MLB then evangelist; Scofield; Depression/war not from God; Graham “the Bible says.”"], "glossary": [{"term": "Age of Terrorism", "meaning": "2001 marked its beginning (as graded)."}, {"term": "Welsh Revival (1904–1906)", "meaning": "Led by Evan Roberts (not J. Edwin Orr); prayer, repentance, transformed community."}, {"term": "Azusa Street", "meaning": "Birthed the modern Pentecostal movement."}, {"term": "Billy Sunday", "meaning": "Former MLB player; major U.S. revivalist; tabernacles; Rodeheaver music."}, {"term": "C.I. Scofield", "meaning": "Great and effective teacher in the Bible Teaching movement."}, {"term": "Billy Graham", "meaning": "Known for the phrase “the Bible says.”"}], "outline": ["World at the start of the twentieth century", "Colonial collapse, third world, Cold War, liberal theology", "Welsh Revival (1904–1906)", "Azusa / Pentecostalism; Bible Teaching / Scofield", "Billy Sunday; Depression/war; Billy Graham"], "mustKnow": [{"label": "Quiz 10", "value": "80% (8/10), cmid 1223 — miss Q2, Q5"}, {"label": "Course total", "value": "78%; cert 2165 locked"}, {"label": "Welsh leader", "value": "Evan Roberts (not J. Edwin Orr)"}, {"label": "Azusa", "value": "Modern Pentecostal birth"}, {"label": "Billy Sunday", "value": "MLB → evangelist"}, {"label": "Graham phrase", "value": "“the Bible says”"}], "compare": [{"title": "Welsh Revival numbers (quiz vs essay)", "points": ["Quiz Q5 (graded True): over five million came to faith in two years", "Essay Q12 text: more than 100,000 came to faith within two years — keep both as pack gave them"]}, {"title": "Who led the Welsh Revival", "points": ["False: J. Edwin Orr", "Essay: Evan Roberts"]}], "pulpit": ["Preach Welsh Revival as prayer and repentance that changes streets, not only pews.", "Hold Azusa’s Pentecostal birth without rewriting history’s hard edges.", "Recover Sunday’s public invitation and moral courage — and Moody/Graham’s Bible-centered call.", "Flag the two misses: colonialism after WWII; Welsh five-million quiz item."], "quickReview": ["2001 Age of Terrorism; colonialism collapses after WWII.", "Welsh: Evan Roberts not Orr; Azusa → Pentecostalism.", "Sunday MLB→evangelist; Scofield; Depression/war ≠ from God.", "Graham: “the Bible says.” Miss Q2 & Q5."], "quiz": [{"q": "2001 marked the beginning of the ‘Age of Terrorism.’", "answer": "True", "why": "Age of Terrorism."}, {"q": "The global collapse of colonialism began after World War 2.", "answer": "True", "why": "Miss: chose False; Moodle True."}, {"q": "Third world countries were often the object of humanitarian aid and development.", "answer": "True", "why": "Humanitarian aid."}, {"q": "The leader of the Welch Revival was J Edwin Orr.", "answer": "False", "why": "Not Orr (Evan Roberts)."}, {"q": "In what was known as the Welsh Revival, over five million people came to faith in Christ in two years.", "answer": "True", "why": "Miss: chose False; Moodle True."}, {"q": "The Azusa Street Revival birthed the modern Pentecostal movement.", "answer": "True", "why": "Azusa → Pentecostalism."}, {"q": "Billy Sunday was a Major League Baseball player before he became an evangelist.", "answer": "True", "why": "MLB then evangelist."}, {"q": "In the Bible Teaching movement, one of the great and effective teachers was CI Scofield.", "answer": "True", "why": "Scofield."}, {"q": "The Great Depression and the horrors of war drove people away from God.", "answer": "False", "why": "Did not drive people from God."}, {"q": "Billy Graham is known for the phrase, ‘the Bible says.’", "answer": "True", "why": "“the Bible says.”"}], "essays": [{"theme": "Describe the world condition at the beginning of the twentieth century", "summary": "At the beginning of the twentieth century, the world was being reshaped by rapid political, social, economic, and technological change. After World War I, the great empires began to lose control of their colonial possessions, while nationalism grew among the nations of the third world and indigenous leadership replaced foreign influence. Commerce then carried Western products and habits into those societies. World War II multiplied mass-produced goods, new technologies, communication, transportation, and conveniences, turning people's attention toward material and worldly concerns. The church struggled to keep pace with the changing society. The First World and the Communist Second World were divided by the Cold War, while the Third World became a focus of humanitarian aid. Rationalism and evolutionism also weakened confidence in divine revelation and helped spread liberal theology. Yet this troubled and changing world became a setting in which God brought revival and renewed people’s hunger for biblical truth."}, {"theme": "Explain the initiation, expansion, and the significance of the Welsh Revival (1904-1906)", "summary": "The Welsh Revival began in 1904 in Wales through Evan Roberts, a young evangelist who believed God was calling the church to prayer and revival. After intense personal prayer, he asked his pastor for permission to speak, and although only a small group first gathered, the meetings quickly grew. People prayed, worshiped, confessed sin, repented, reconciled relationships, and openly responded to the call to follow Christ. The meetings were often long and spontaneous, and the whole congregation seemed conscious of the Holy Spirit’s presence. Within two years, more than 100,000 people came to faith. Drunkenness and crime declined, taverns went bankrupt, and even judges reported that there were few cases. The revival spread beyond Wales across Europe and encouraged many young people to become student volunteer missionaries. Its significance was that it was a powerful, largely spontaneous work of prayer, repentance, evangelism, and transformed community life, preparing the way for further revival movements."}, {"theme": "Discuss the evangelistic ministry of Billy Sunday", "summary": "Billy Sunday was a former Major League Baseball player who was converted at the Pacific Garden Mission in Chicago in 1886. He became one of America’s leading revivalists, preaching more than 300 evangelistic campaigns in major cities and seeing more than 593,000 people make decisions for Christ. Because ordinary buildings were too small, businessmen built large temporary structures called ‘Billy Sunday Tabernacles.’ His 1917 New York campaign recorded 98,264 professions of faith and involved more than 50,000 volunteers. Sunday was a forceful, colorful preacher whose voice could be heard by thousands without electronic amplification, and he urged people to come forward and publicly commit themselves to Christ. He preached against sin and championed moral reform, including opposition to child labor, support for women’s suffrage, opposition to alcohol, and resistance to evolution and other social evils. Working with Homer Rodeheaver, he used enthusiastic singing and very large choirs to prepare people for the invitation. His ministry combined evangelistic preaching, public decisions, music, and social reform, and it helped shape revivalism in the United States."}]}, {"id": "ch2-11", "number": 11, "title": "The Laodicean Church – The Apostate Church: 1900 – Present", "topic": "Postwar missions; Graham LA/Seoul; Hebrides; China house churches; SCOTUS & morals; Jesus movement; Towns Sunday Schools; Prairie restitution.", "quizScore": 100, "quizAttempts": 1, "status": "complete", "introCard": "Quiz 11: 10/10 (100%), 4m 58s, cmid 1227 / attempt 102006. Essays Complete/Not graded (Q11–Q13 verbatim). Course total 88%. Cert cmid 2165 locked until final quiz.", "summary": "After WWII, over 20,000 veterans went to Christian colleges/seminary then overseas as missionaries. Stuart Hamblin promoted Graham’s LA crusade; in Seoul over a million heard Graham in person. The Hebrides lead evangelist was not James Murray McKay (MacKay was pastor; Duncan Campbell preached). China house churches are hard to locate; Communists did not invite Western missionaries. SCOTUS did affect U.S. moral values. Chuck Smith was used greatly in the Jesus movement. Towns’ 1969 study: 7 of 10 largest Sunday Schools were Independent Baptist. Western Canadian Prairie revival was known for restitution.", "bigIdeas": ["Postwar: 20,000+ veterans → Christian colleges/seminary → overseas missions.", "Stuart Hamblin promoted Billy Graham LA crusade; Seoul: million+ heard in person.", "Hebrides lead evangelist ≠ James Murray McKay (Campbell preached; MacKay pastor/prayer).", "China house churches hard to locate; Communists did NOT invite Western missionaries.", "SCOTUS affected changing U.S. moral values (False that it had nothing to do).", "Chuck Smith / Jesus movement (Baby Boom revival).", "Towns 1969: 7/10 largest Sunday Schools Independent Baptist.", "Western Canadian Prairie revival known for restitution."], "takeaways": ["Postwar missionary veterans; Hamblin LA; Seoul million+.", "Hebrides: Campbell not McKay as lead evangelist; China house churches hard to find.", "SCOTUS & morals; Chuck Smith / Jesus movement; Towns 7/10 IB; Prairie restitution."], "glossary": [{"term": "Stuart Hamblin", "meaning": "Radio personality who promoted Graham’s Los Angeles Crusade; later converted."}, {"term": "Hebrides Revival", "meaning": "Duncan Campbell preached; Pastor James Murray MacKay led prayer — MacKay not “the” lead evangelist."}, {"term": "Chinese house church", "meaning": "Hard to locate; grew without buildings/foreign missionaries; Communists expelled missionaries."}, {"term": "Chuck Smith", "meaning": "Pastor used greatly in the Baby Boom revival / Jesus movement."}, {"term": "Restitution (Prairie)", "meaning": "Western Canadian Prairie revival known for the extent of restitution."}], "outline": ["Postwar missionary surge from veterans", "Graham: LA 1949 crusade; Seoul crowds", "Hebrides Revival: prayer, MacKay, Campbell", "China underground / house churches", "SCOTUS, Jesus movement, Sunday Schools, Prairie restitution"], "mustKnow": [{"label": "Quiz 11", "value": "100% (10/10), cmid 1227"}, {"label": "Course total", "value": "88%; cert 2165 locked"}, {"label": "LA radio push", "value": "Stuart Hamblin"}, {"label": "Hebrides evangelist", "value": "Duncan Campbell (not McKay)"}, {"label": "Jesus movement pastor", "value": "Chuck Smith"}, {"label": "Towns 1969", "value": "7/10 Independent Baptist"}], "compare": [{"title": "Hebrides roles", "points": ["James Murray MacKay: pastor; led leaders in prayer; invited Campbell", "Duncan Campbell: lead evangelist whose preaching brought conviction", "Quiz False: McKay as “the lead evangelist”"]}, {"title": "China church under Communism", "points": ["House churches hard to locate; no public structure", "False that Communists invited Western missionaries"]}], "pulpit": ["Preach Graham’s LA urgency — invite broadly, raise the tent, watch for God’s sign.", "Hold Hebrides: aged prayer warriors + clean hands before the crowd.", "Learn from China’s house churches: the church is people in Christ, not buildings.", "Name restitution as revival fruit (Prairie) and Chuck Smith’s Jesus-movement pastoral role."], "quickReview": ["20k+ postwar missionary veterans; Hamblin → LA; Seoul million+.", "Hebrides: Campbell not McKay; China houses hard to find; no missionary invite.", "SCOTUS shaped morals; Chuck Smith / Jesus movement.", "Towns 7/10 IB; Prairie restitution."], "quiz": [{"q": "After World War Two, over 20,000 veterans would attend Christian colleges or seminary and then go overseas as foreign missionaries.", "answer": "True", "why": "Postwar missionary veterans."}, {"q": "The radio personality who promoted the Billy Graham Los Angeles Crusade was Stuart Hamblin.", "answer": "True", "why": "Hamblin."}, {"q": "When Billy Graham preached in Seoul, Korea, over a million people heard him preach in person.", "answer": "True", "why": "Seoul million+."}, {"q": "The lead evangelist in the Hebrides Revival was James Murray McKay.", "answer": "False", "why": "Campbell preached; MacKay pastor."}, {"q": "The house churches in China are easy to locate.", "answer": "False", "why": "Hard to locate."}, {"q": "The Communist government in China invited western missionaries to come and preach,", "answer": "False", "why": "Did not invite."}, {"q": "The Supreme Court had nothing to do with the changing moral values of the United States.", "answer": "False", "why": "SCOTUS did affect morals."}, {"q": "The pastor used greatly in the Baby Boom revival, also known as the Jesus movement, was Chuck Smith.", "answer": "True", "why": "Chuck Smith."}, {"q": "In Dr. Towns' study of the ten largest Sunday Schools in 1969, he discovered that 7 out of 10 were Independent Baptists.", "answer": "True", "why": "7/10 Independent Baptist."}, {"q": "The Western Canadian Prairie revival was known for the extent of ‘restitution.’", "answer": "True", "why": "Restitution."}], "essays": [{"theme": "1949 Los Angeles Crusade", "summary": "The 1949 Los Angeles Crusade began through the invitation of Christ for Greater Los Angeles, a fellowship of about 200 churches. Billy Graham approached it with urgency, believing that revival in Los Angeles could have repercussions around the world. He asked that all churches be included, the budget be raised from $7,000 to $25,000, and a tent seating 5,000 be built. Stuart Hamblin, a popular radio personality, urged listeners to attend and was later converted, which Graham viewed as God's sign to continue. William Randolph Hearst then ordered his newspapers to ‘Puff Graham,’ and the media attention expanded the meetings. Jim Vaus, a wire-tapper for the Mob, was also converted. The meetings continued for 72 nights, thousands professed faith, and 82 percent had never made a profession before. The crusade launched Graham's worldwide citywide evangelistic ministry."}, {"theme": "Hebrides Revival", "summary": "The Hebrides Islands had declined spiritually after World War II; no church could point to a single young person attending, while young people went to dances, films, and drinking houses. Peggy Smith, an 84-year-old blind prayer warrior, and her sister Christine prayed for revival. Peggy's vision of crowded churches was confirmed by Pastor James Murray MacKay, who led his leaders in prayer for three months. A young deacon's question, ‘O God, are my hands clean? Is my heart pure?’ was followed by deep conviction. MacKay invited Duncan Campbell, who first declined but later came when circumstances changed. Campbell's preaching brought a solemn awareness of God's presence, repentance, and salvation. More than 600 gathered outside one church, and the revival spread rapidly to neighboring districts. People prayed through the night, homes experienced salvation, and drinking houses closed for a generation. The revival showed me the importance of persistent, honest prayer and repentance."}, {"theme": "Chinese Organic House Church / underground church", "summary": "The Chinese Organic House Church, or underground church, developed almost everywhere in China but is difficult to locate because it has no public structure. Estimates place the movement at about 130 million believers, alongside roughly 23.5 million registered members of the official Three-Self Church. It grew without church buildings, programs, denominational support, foreign missionaries, or a formal organizational network. When the Communists took power, missionaries were expelled, pastors and believers were imprisoned, and many outward professors abandoned the faith. Yet the gospel continued to spread through believers meeting in homes, apartments, restaurants, and other ordinary places. Its strength came from committed disciples, prayer, witness, and dependence on God rather than buildings or institutions. For me as a pastor, this movement is a reminder that the church is people gathered in Christ and that persecution cannot extinguish the true light of the gospel."}]}, {"id": "ch2-12", "number": 12, "title": "Lesson 12", "topic": "", "status": "empty", "quizScore": null, "quizAttempts": 0, "introCard": "Placeholder — waiting on Lesson 12 pack.", "summary": "", "bigIdeas": [], "takeaways": [], "glossary": [], "outline": [], "mustKnow": [], "compare": [], "pulpit": [], "quickReview": [], "quiz": [], "essays": []}]}]};
